  --ds-select-error-border: #ef4444;
  --ds-select-warning-border: #f59e0b;
  --ds-select-success-border: #22c55e;

  /* Select Filled Variant */

  /* Select Dropdown */
  --ds-select-dropdown-border: #e5e5e5;
  --ds-select-dropdown-radius: var(--ds-radius-md);

  /* Select Option */

  /* Select Tag (multiple mode) */
  --ds-select-tag-radius: var(--ds-radius-sm);

  /* Select Arrow/Icon */
  --ds-select-check-color: #171717;

  /* ─────────────────────────────────────────────────────────────────────────────
     DATEPICKER
     ───────────────────────────────────────────────────────────────────────────── */

  /* DatePicker Base */
  --ds-datepicker-bg: #ffffff;
  --ds-datepicker-bg-disabled: #fafafa;
  --ds-datepicker-color: #171717;
  --ds-datepicker-color-placeholder: #a3a3a3;
  --ds-datepicker-border: #e5e5e5;
  --ds-datepicker-border-hover: #d4d4d4;
  --ds-datepicker-border-focus: #171717;
  --ds-datepicker-radius: var(--ds-radius-md);
  --ds-datepicker-shadow-focus: 0 0 0 1px #171717;
  --ds-datepicker-transition: var(--ds-transition-fast);

  /* DatePicker Status */
  --ds-datepicker-error-border: #ef4444;
  --ds-datepicker-warning-border: #f59e0b;

  /* DatePicker Sizes */
  --ds-datepicker-sm-padding: 0.25rem 0.5rem;
  --ds-datepicker-sm-font-size: var(--ds-font-size-xs);
  --ds-datepicker-md-padding: 0.5rem 0.75rem;
  --ds-datepicker-md-font-size: var(--ds-font-size-sm);
  --ds-datepicker-lg-padding: 0.75rem 1rem;
  --ds-datepicker-lg-font-size: var(--ds-font-size-base);

  /* DatePicker Icon */
  --ds-datepicker-icon-color: #a3a3a3;
  --ds-datepicker-clear-color: #a3a3a3;
  --ds-datepicker-clear-color-hover: #525252;

  /* DatePicker Separator */
  --ds-datepicker-separator-color: #a3a3a3;

  /* ─────────────────────────────────────────────────────────────────────────────
     INPUTNUMBER
     ───────────────────────────────────────────────────────────────────────────── */

  /* InputNumber Base */
  --ds-inputnumber-bg: #ffffff;
  --ds-inputnumber-bg-disabled: #fafafa;
  --ds-inputnumber-color: #171717;
  --ds-inputnumber-border: #e5e5e5;
  --ds-inputnumber-border-hover: #d4d4d4;
  --ds-inputnumber-border-focus: #171717;
  --ds-inputnumber-radius: var(--ds-radius-md);
  --ds-inputnumber-shadow-focus: 0 0 0 1px #171717;
  --ds-inputnumber-transition: var(--ds-transition-fast);

  /* InputNumber Status */
  --ds-inputnumber-error-border: #ef4444;
  --ds-inputnumber-warning-border: #f59e0b;

  /* InputNumber Sizes */
  --ds-inputnumber-sm-padding: 0.25rem 0.5rem;
  --ds-inputnumber-sm-font-size: var(--ds-font-size-xs);
  --ds-inputnumber-sm-width: 100px;
  --ds-inputnumber-md-padding: 0.5rem 0.75rem;
  --ds-inputnumber-md-font-size: var(--ds-font-size-sm);
  --ds-inputnumber-md-width: 120px;
  --ds-inputnumber-lg-padding: 0.75rem 1rem;
  --ds-inputnumber-lg-font-size: var(--ds-font-size-base);
  --ds-inputnumber-lg-width: 140px;

  /* InputNumber Controls */
  --ds-inputnumber-control-bg: transparent;
  --ds-inputnumber-control-color: #737373;
  --ds-inputnumber-control-color-hover: #171717;

  /* InputNumber Addon */
  --ds-inputnumber-addon-bg: #fafafa;
  --ds-inputnumber-addon-border: #e5e5e5;
  --ds-inputnumber-addon-color: #525252;

  /* InputNumber Prefix/Suffix */
  --ds-inputnumber-affix-color: #a3a3a3;

  /* ─────────────────────────────────────────────────────────────────────────────
     TEXTAREA
     ───────────────────────────────────────────────────────────────────────────── */

  /* Textarea Base */
  --ds-textarea-bg: #ffffff;
  --ds-textarea-bg-disabled: #fafafa;
  --ds-textarea-color: #171717;
  --ds-textarea-color-placeholder: #a3a3a3;
  --ds-textarea-border: #e5e5e5;
  --ds-textarea-border-hover: #d4d4d4;
  --ds-textarea-border-focus: #171717;
  --ds-textarea-shadow-focus: 0 0 0 1px #171717;
  --ds-textarea-transition: var(--ds-transition-fast);

  /* Textarea Status */
  --ds-textarea-error-border: #ef4444;
  --ds-textarea-warning-border: #f59e0b;
  --ds-textarea-success-border: #22c55e;

  /* Textarea Sizes */
  --ds-textarea-sm-padding: 0.375rem 0.5rem;
  --ds-textarea-sm-font-size: var(--ds-font-size-xs);
  --ds-textarea-md-padding: 0.5rem 0.75rem;
  --ds-textarea-md-font-size: var(--ds-font-size-sm);
  --ds-textarea-lg-padding: 0.75rem 1rem;
  --ds-textarea-lg-font-size: var(--ds-font-size-base);

  /* Textarea Filled Variant */
  --ds-textarea-filled-bg: #f5f5f5;

  /* Textarea Count */
  /* AA floor on light surfaces: #a3a3a3 measured 2.8:1 on white (Axe R0).
     #6B6B72 converges with the rottay light-section value and clears 4.5:1
     on white (5.29), #F4F8FB (4.83) and #FBF6EC (4.78). The dark section
     below keeps #a3a3a3, whose dark-surface pairing already passes (7.0:1). */
  --ds-textarea-count-color: #6B6B72;
  --ds-textarea-count-font-size: var(--ds-font-size-xs);

  /* ─────────────────────────────────────────────────────────────────────────────
     TIMEPICKER
     ───────────────────────────────────────────────────────────────────────────── */

  /* TimePicker Base */
  --ds-timepicker-bg: #ffffff;
  --ds-timepicker-bg-disabled: #fafafa;
  --ds-timepicker-color: #171717;
  --ds-timepicker-border: #e5e5e5;
  --ds-timepicker-border-focus: #171717;
  --ds-timepicker-radius: var(--ds-radius-md);
  --ds-timepicker-shadow-focus: 0 0 0 1px #171717;
  --ds-timepicker-transition: var(--ds-transition-fast);

  /* TimePicker Status */
