     COMMAND PALETTE
     ───────────────────────────────────────────────────────────────────────────── */
  --ds-command-palette-backdrop: var(--ds-color-bg-overlay);
  --ds-command-palette-bg: var(--ds-color-bg-elevated);
  --ds-command-palette-shadow: var(--ds-shadow-dialog);
  --ds-command-palette-border: var(--ds-color-border);
  --ds-command-palette-item-hover-bg: var(--ds-color-bg-hover);
  --ds-command-palette-group-color: var(--ds-color-text-muted);
  --ds-command-palette-empty-color: var(--ds-color-text-muted);
  --ds-command-palette-shortcut-border: var(--ds-color-border);

  /* ─────────────────────────────────────────────────────────────────────────────
     LIVE FEED
     ───────────────────────────────────────────────────────────────────────────── */
  --ds-live-feed-bg: var(--ds-color-bg-elevated);
  --ds-live-feed-border: var(--ds-color-border);
  --ds-live-feed-refresh-color: var(--ds-color-text-secondary);
  --ds-live-feed-new-bg: var(--ds-color-info-bg);
  --ds-live-feed-new-border: var(--ds-color-info-border);
  --ds-live-feed-new-color: var(--ds-color-info);
  --ds-live-feed-badge-bg: var(--ds-color-primary);
  --ds-live-feed-badge-color: var(--ds-color-text-on-primary);
  --ds-live-feed-empty-color: var(--ds-color-text-muted);
  --ds-live-feed-load-more-color: var(--ds-color-primary);
  --ds-live-feed-skeleton-bg: var(--ds-color-bg-tertiary);

  /* ─────────────────────────────────────────────────────────────────────────────
     STATS GRID
     ───────────────────────────────────────────────────────────────────────────── */
  --ds-stats-grid-card-bg: var(--ds-color-bg-elevated);
  --ds-stats-grid-card-border: var(--ds-color-border);
  --ds-stats-grid-card-filled-bg: var(--ds-color-bg-secondary);
  --ds-stats-grid-card-glass-bg: var(--ds-color-alpha-white-50);
  --ds-stats-grid-card-glass-border: var(--ds-color-alpha-white-20);
  --ds-stats-grid-hover-shadow: var(--ds-shadow-md);
  --ds-stats-grid-label-color: var(--ds-color-text-secondary);
  --ds-stats-grid-value-color: var(--ds-color-text-primary);
  --ds-stats-grid-description-color: var(--ds-color-text-muted);
  --ds-stats-grid-trend-positive: var(--ds-color-success);
  --ds-stats-grid-trend-negative: var(--ds-color-error);
  --ds-stats-grid-trend-neutral: var(--ds-color-text-muted);
  --ds-stats-grid-skeleton-bg: var(--ds-color-bg-tertiary);
  --ds-stats-grid-skeleton-wave-gradient:
    linear-gradient(
      90deg,
      var(--ds-color-alpha-black-10) 25%,
      var(--ds-color-alpha-black-20) 37%,
      var(--ds-color-alpha-black-10) 63%
    );

