/**
 * Premium Effect Tokens - Rottay Design System
 *
 * The gradient / glass / glow layer for the modern engine's Quiet Premium
 * signature. Every effect below is scaled by --ds-effect-intensity so a tenant
 * collapses the whole layer to flat by setting the dial to 0 (BitHire's
 * Evidence-Ledger zero-decoration law); the DS/rottay default (1) showcases the
 * full treatment.
 *
 * Sanctioned roles (engines/modern spec section 5):
 *   surface-tint  --ds-gradient-surface  -> cards, hero surfaces, metric tiles
 *   accent        --ds-gradient-primary  -> primary buttons, selected states
 *   signal-glow   --ds-shadow-glow-*     -> live/AI moments + data-viz ONLY
 *   glass         --ds-glass-*           -> overlay backdrops ONLY (modal/palette/drawer)
 *   mesh          --ds-gradient-mesh     -> marketing/showcase ONLY (never product chrome)
 */

:root {
  /* ========================================================================
     EFFECT INTENSITY DIAL
     Tenant/vertical-tunable multiplier. 1 = full Quiet Premium (DS/rottay
     default); 0 = flat (no gradient/glass/glow). Every effect multiplies its
     alpha/length by this, so intensity 0 collapses each effect to none while
     keeping valid CSS (blur(0px), transparent stops, 0-alpha shadow).
     Emitted per tenant by infrastructure/compilers/kernel/runtime/brand-theme from surfaces.effectIntensity.
     ======================================================================== */
  --ds-effect-intensity: 1;

  /* ========================================================================
     GLASSMORPHISM (overlay backdrops ONLY: modal, command palette, drawer)
     Base palette tokens are read by the glass-card effect and exposed through
     the useTokens() catalog; blur/bg/border scale with --ds-effect-intensity so
     a zero-intensity tenant (bithire) collapses them without needing a per-token
     'none' override. The two composed backdrop tokens are the wired overlay
     values and likewise collapse to a plain scrim at intensity 0.
     ======================================================================== */
  --ds-glass-blur: calc(12px * var(--ds-effect-intensity));
  --ds-glass-blur-sm: 8px;
  --ds-glass-blur-lg: 20px;
  --ds-glass-blur-xl: 32px;
  --ds-glass-bg: rgba(255, 255, 255, calc(0.05 * var(--ds-effect-intensity)));
  --ds-glass-bg-light: var(--ds-color-alpha-white-10);
  --ds-glass-bg-heavy: var(--ds-color-alpha-white-20);
  --ds-glass-border: rgba(255, 255, 255, calc(0.10 * var(--ds-effect-intensity)));
  --ds-glass-border-light: var(--ds-color-alpha-white-5);
  --ds-glass-border-heavy: var(--ds-color-alpha-white-20);

  /* Wired overlay-backdrop values. Intensity 0 -> blur(0px) + transparent tint,
     i.e. the backdrop falls back to its plain scrim. The 12px/0.05 literals are
     inlined (not var(--ds-glass-blur)) so a tenant hard-nulling --ds-glass-blur
     cannot turn this into the invalid blur(none). */
  --ds-glass-backdrop-filter: blur(calc(12px * var(--ds-effect-intensity)));
  --ds-glass-scrim-tint: rgba(255, 255, 255, calc(0.05 * var(--ds-effect-intensity)));

  /* ========================================================================
     SIGNAL-GLOW (live/AI moments + data-viz emphasis ONLY, never static chrome)
     ======================================================================== */
  --ds-shadow-glow-primary: 0 0 calc(40px * var(--ds-effect-intensity)) rgba(var(--ds-color-primary-rgb), calc(0.18 * var(--ds-effect-intensity)));

  /* ========================================================================
     GRADIENTS
     ======================================================================== */
  /* surface-tint: barely-there ~2-3% vertical luminance tint that replaces flat
     fills on cards, hero surfaces and metric tiles. */
  --ds-gradient-surface: linear-gradient(
    180deg,
    rgba(255, 255, 255, calc(0.025 * var(--ds-effect-intensity))) 0%,
    rgba(255, 255, 255, calc(0.004 * var(--ds-effect-intensity))) 52%,
    rgba(0, 0, 0, calc(0.02 * var(--ds-effect-intensity))) 100%
  );
  /* accent: subtle top-light sheen on primary buttons and selected states. */
  --ds-gradient-primary: linear-gradient(
    180deg,
    rgba(255, 255, 255, calc(0.16 * var(--ds-effect-intensity))) 0%,
    rgba(255, 255, 255, 0) 46%,
    rgba(0, 0, 0, calc(0.06 * var(--ds-effect-intensity))) 100%
  );
  /* Catalog-only gradients (exposed via useTokens(); not wired into chrome). */
  --ds-gradient-primary-soft: linear-gradient(135deg, var(--ds-color-primary-50), var(--ds-color-secondary-50));
  --ds-gradient-dark: linear-gradient(135deg, var(--ds-color-neutral-900), var(--ds-color-neutral-800));
  /* mesh: marketing/showcase ONLY (never wired into product chrome). */
  --ds-gradient-mesh: radial-gradient(at 40% 20%, var(--ds-color-primary-100) 0px, transparent 50%),
                      radial-gradient(at 80% 0%, var(--ds-color-secondary-100) 0px, transparent 50%),
                      radial-gradient(at 0% 50%, var(--ds-color-primary-50) 0px, transparent 50%);

  /* ========================================================================
     PREMIUM EASING
     Additional cubic-bezier curves for premium animations
     ======================================================================== */
  --ds-ease-premium: cubic-bezier(0.16, 1, 0.3, 1);
  --ds-ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
  --ds-ease-smooth: cubic-bezier(0.25, 0.1, 0.25, 1);
  --ds-ease-out-expo: cubic-bezier(0.19, 1, 0.22, 1);
  --ds-ease-in-out-expo: cubic-bezier(0.87, 0, 0.13, 1);
}

/* Reduced motion: disable the blur/glow effects that may cause discomfort. */
@media (prefers-reduced-motion: reduce) {
  :root {
    --ds-glass-blur: 0px;
    --ds-glass-blur-sm: 0px;
    --ds-glass-blur-lg: 0px;
    --ds-glass-blur-xl: 0px;
    --ds-glass-backdrop-filter: none;
    --ds-shadow-glow-primary: none;
  }
}

/**
 * Collection insert stagger preset — Rottay Design System.
 *
 * The CSS half of the `collection.insert` motion recipe
 * (infrastructure/runtime/foundation/motion/policy/recipes: staggerStepMs 30,
 * staggerMaxMs 240, both capped by MAX_TOTAL_STAGGER_MS 320). A collection
 * surface stamps `.ds-collection-stagger` on a freshly mounted batch and sets
 * `--ds-stagger-index` on each row/card; every item reveals with a
 * compositor-only opacity+transform entrance whose start is delayed by
 * `index * step`, clamped to `max`, so a large batch never staggers longer than
 * the cap (150-300ms total by design). The `useCollectionStagger` hook
 * (ui/patterns/foundation/motion) resolves the SAME recipe through the active
 * motion policy, stamps the class only when the policy animates, and writes
 * `--ds-stagger-step`/`--ds-stagger-max` from the resolved recipe so a tenant's
 * durationScale moves the CSS and the JS in lockstep.
 *
 * Compositor-only (modern engine spec section 2, WO-CRA-06): opacity + transform
 * only, never a layout property. Under reduced motion every item resolves to its
 * final state with no delay -- the media guard below is load-bearing because the
 * step/max tokens are not zeroed by the foundation reduced-motion block (a bare
 * duration zero would still leave each item delayed and briefly hidden).
 */

:root {
  /* collection.insert recipe bounds. A stamping container overrides these inline
     from the resolved recipe; these defaults keep the class self-sufficient when
     stamped without the hook (e.g. a static server-rendered batch). */
  --ds-stagger-step: 30ms;
  --ds-stagger-max: 240ms;
}

@keyframes ds-collection-insert {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.99);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.ds-collection-stagger [data-ds-stagger-item] {
  animation-name: ds-collection-insert;
  animation-duration: var(--ds-motion-normal);
  animation-timing-function: var(--ds-motion-ease-out);
  /* `both` holds the from-state through the delay so an item stays hidden until
     its turn instead of flashing in and then animating out. */
  animation-fill-mode: both;
  animation-delay: min(
    var(--ds-stagger-index, 0) * var(--ds-stagger-step),
    var(--ds-stagger-max)
  );
}

@media (prefers-reduced-motion: reduce) {
  .ds-collection-stagger [data-ds-stagger-item] {
    animation: none;
  }
}


}

/* Layer 2: Component tokens */
@layer rottay-components {
/**
 * Avatar Component Tokens - Rottay Design System
 *
 * Design tokens specific to the Avatar component.
 * Includes sizes, shapes, variants, status indicators, and group settings.
 */

:root {
  /* ========================================================================
     SIZES - Avatar Dimensions
     Seven size variants from xs to 3xl with corresponding properties
     ======================================================================== */

  /* XS - Extra Small (24px) */
  --ds-avatar-xs-size: 1.5rem;           /* 24px */
  --ds-avatar-xs-font-size: 0.625rem;    /* 10px */
  --ds-avatar-xs-status-size: 0.375rem;  /* 6px */
  --ds-avatar-xs-border-width: 1px;

  /* SM - Small (32px) */
  --ds-avatar-sm-size: 2rem;             /* 32px */
  --ds-avatar-sm-font-size: 0.75rem;     /* 12px */
  --ds-avatar-sm-status-size: 0.5rem;    /* 8px */
  --ds-avatar-sm-border-width: 1.5px;

  /* MD - Medium (40px - Default) */
  --ds-avatar-md-size: 2.5rem;           /* 40px */
  --ds-avatar-md-font-size: 0.875rem;    /* 14px */
  --ds-avatar-md-status-size: 0.625rem;  /* 10px */
  --ds-avatar-md-border-width: 2px;

  /* LG - Large (48px) */
  --ds-avatar-lg-size: 3rem;             /* 48px */
  --ds-avatar-lg-font-size: 1rem;        /* 16px */
  --ds-avatar-lg-status-size: 0.75rem;   /* 12px */
  --ds-avatar-lg-border-width: 2px;

  /* XL - Extra Large (56px) */
  --ds-avatar-xl-size: 3.5rem;           /* 56px */
  --ds-avatar-xl-font-size: 1.125rem;    /* 18px */
  --ds-avatar-xl-status-size: 0.875rem;  /* 14px */
  --ds-avatar-xl-border-width: 2.5px;

  /* 2XL - 2x Extra Large (64px) */
  --ds-avatar-2xl-size: 4rem;            /* 64px */
  --ds-avatar-2xl-font-size: 1.25rem;    /* 20px */
  --ds-avatar-2xl-status-size: 1rem;     /* 16px */
  --ds-avatar-2xl-border-width: 3px;

  /* 3XL - 3x Extra Large (96px) */
  --ds-avatar-3xl-size: 6rem;            /* 96px */
  --ds-avatar-3xl-font-size: 1.75rem;    /* 28px */
  --ds-avatar-3xl-status-size: 1.25rem;  /* 20px */
  --ds-avatar-3xl-border-width: 4px;

  /* Default size (can be overridden) */
  --ds-avatar-default-size: var(--ds-avatar-md-size);
  --ds-avatar-default-font-size: var(--ds-avatar-md-font-size);
  --ds-avatar-default-status-size: var(--ds-avatar-md-status-size);
  --ds-avatar-default-border-width: var(--ds-avatar-md-border-width);

  /* ========================================================================
     SHAPES - Avatar Border Radius
     Three shape variants: circle, square, rounded
     ======================================================================== */
  --ds-avatar-circle-radius: 50%;                          /* Fully rounded */
  --ds-avatar-square-radius: 0;                            /* No rounding */
  --ds-avatar-rounded-radius: var(--ds-radius-md, 0.5rem);    /* 8px rounded corners */

  /* Default shape */
  --ds-avatar-default-shape: var(--ds-avatar-circle-radius);

  /* ========================================================================
     VARIANTS - Avatar Color Variants
     Different visual styles for avatars
     ======================================================================== */

  /* Default variant (neutral) */
  --ds-avatar-default-bg: var(--ds-color-neutral-100);
  --ds-avatar-default-color: var(--ds-color-neutral-600);
  --ds-avatar-default-border-color: var(--ds-color-neutral-200);
  --ds-avatar-default-shadow: none;

  /* Primary variant */
  --ds-avatar-primary-bg: var(--ds-color-primary-100);
  --ds-avatar-primary-color: var(--ds-color-primary-700);
  --ds-avatar-primary-border-color: var(--ds-color-primary-200);
  --ds-avatar-primary-shadow: 0 2px 8px rgba(0, 102, 204, 0.15);

  /* Secondary variant */
  --ds-avatar-secondary-bg: var(--ds-color-secondary-100);
  --ds-avatar-secondary-color: var(--ds-color-secondary-700);
  --ds-avatar-secondary-border-color: var(--ds-color-secondary-200);
  --ds-avatar-secondary-shadow: 0 2px 8px rgba(107, 107, 212, 0.15);

  /* Success variant */
  --ds-avatar-success-bg: var(--ds-color-success-100);
  --ds-avatar-success-color: var(--ds-color-success-700);
  --ds-avatar-success-border-color: var(--ds-color-success-200);
  --ds-avatar-success-shadow: 0 2px 8px rgba(34, 197, 94, 0.15);

  /* Warning variant */
  --ds-avatar-warning-bg: var(--ds-color-warning-100);
  --ds-avatar-warning-color: var(--ds-color-warning-700);
  --ds-avatar-warning-border-color: var(--ds-color-warning-200);
  --ds-avatar-warning-shadow: 0 2px 8px rgba(245, 158, 11, 0.15);

  /* Error variant */
  --ds-avatar-error-bg: var(--ds-color-error-100);
  --ds-avatar-error-color: var(--ds-color-error-700);
  --ds-avatar-error-border-color: var(--ds-color-error-200);
  --ds-avatar-error-shadow: 0 2px 8px rgba(239, 68, 68, 0.15);

  /* Gradient variant */
  --ds-avatar-gradient-bg: linear-gradient(135deg, var(--ds-color-primary-400) 0%, var(--ds-color-secondary-500) 100%);
  --ds-avatar-gradient-color: var(--ds-color-white);
  --ds-avatar-gradient-border-color: transparent;
  --ds-avatar-gradient-shadow: 0 4px 12px rgba(0, 102, 204, 0.2);

  /* ========================================================================
     STATUS INDICATORS
     Color indicators for online/offline/away/busy states
     ======================================================================== */
  --ds-avatar-status-online-color: var(--ds-color-success-500);
  --ds-avatar-status-offline-color: var(--ds-color-neutral-400);
  --ds-avatar-status-away-color: var(--ds-color-warning-500);
  --ds-avatar-status-busy-color: var(--ds-color-error-500);

  /* Status indicator position and sizing */
  --ds-avatar-status-offset: 0;          /* Distance from edge */
  --ds-avatar-status-border-width: 2px;  /* White border around status */
  --ds-avatar-status-border-color: var(--ds-color-white);

  /* ========================================================================
     AVATAR GROUP
     Settings for overlapping avatar groups
     ======================================================================== */
  --ds-avatar-group-compact-spacing: -0.5rem;   /* -8px overlap */
  --ds-avatar-group-normal-spacing: -0.25rem;   /* -4px overlap */
  --ds-avatar-group-loose-spacing: 0.25rem;     /* 4px gap */

  /* Default group spacing */
  --ds-avatar-group-default-spacing: var(--ds-avatar-group-normal-spacing);

  /* Group max count settings */
  --ds-avatar-group-max-count: 5;                /* Max avatars before showing +N */
  --ds-avatar-group-overflow-bg: var(--ds-color-neutral-200);
  --ds-avatar-group-overflow-color: var(--ds-color-neutral-700);
  --ds-avatar-group-overflow-font-weight: var(--ds-font-weight-medium);

  /* ========================================================================
     INTERACTIONS
     Hover, focus, and active states
     ======================================================================== */
  --ds-avatar-hover-scale: 1.05;
  --ds-avatar-hover-shadow: 0 4px 12px rgba(0, 0, 0, 0.1);
  --ds-avatar-hover-border-color: var(--ds-color-primary-300);

  --ds-avatar-focus-ring-width: 2px;
  --ds-avatar-focus-ring-color: var(--ds-color-primary-500);
  --ds-avatar-focus-ring-offset: 2px;

  --ds-avatar-active-scale: 0.98;

  /* ========================================================================
     BADGE/NOTIFICATION
     For notification badges on avatars
     ======================================================================== */
  --ds-avatar-badge-size: 1rem;                  /* 16px */
  --ds-avatar-badge-font-size: 0.625rem;         /* 10px */
  --ds-avatar-badge-bg: var(--ds-color-error-500);
  --ds-avatar-badge-color: var(--ds-color-white);
  --ds-avatar-badge-border-width: 2px;
  --ds-avatar-badge-border-color: var(--ds-color-white);
  --ds-avatar-badge-offset-top: 0;
  --ds-avatar-badge-offset-right: 0;

  /* ========================================================================
     LOADING STATE
     Skeleton/loading appearance
     ======================================================================== */
  --ds-avatar-loading-bg: var(--ds-color-neutral-100);
  --ds-avatar-loading-animation: ds-foundation-pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;

  /* ========================================================================
     TOUCH TARGETS
     Minimum touch target size for accessibility
     ======================================================================== */
  --ds-avatar-touch-target-min: 2.75rem;  /* 44px - WCAG AAA minimum */

  /* ========================================================================
     TRANSITIONS
     Animation timing for state changes
     ======================================================================== */
  --ds-avatar-transition-duration: 0.2s;
  --ds-avatar-transition-timing: ease-in-out;
  --ds-avatar-transition: all var(--ds-avatar-transition-duration) var(--ds-avatar-transition-timing);

  /* ========================================================================
     IMAGE SETTINGS
     Settings for image rendering within avatars
     ======================================================================== */
  --ds-avatar-image-object-fit: cover;
  --ds-avatar-image-object-position: center;

  /* ========================================================================
     FALLBACK ICON
     Settings for icon fallback when no image is provided
     ======================================================================== */
  --ds-avatar-fallback-icon-size: 60%;  /* Icon size relative to avatar */
  --ds-avatar-fallback-icon-color: currentColor;
}

}
@layer rottay-components {
/**
 * VisuallyHidden — canonical screen-reader-only rule.
 *
 * LAYER: rottay-components (single owner for every engine and consumer).
 * SCOPE: `.ds-visually-hidden` applied by the `VisuallyHidden` primitive;
 *   no data-part, no states, no theming axes — the geometry is universal
 *   and must never change per tenant.
 * SPECIFICITY: single class, no repetition, no `!important`, logical
 *   properties. Content stays in the accessibility tree and in the tab
 *   order's source position; it is only clipped from paint.
 */
.ds-visually-hidden {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* Reveal-on-focus (skip-link pattern): the content stays clipped until it
 * or a descendant receives keyboard focus, then it re-enters the layout.
 * Interactive content must become visible to keyboard users — clipping a
 * focused control would hide the focus ring itself. */
.ds-visually-hidden--focusable:focus,
.ds-visually-hidden--focusable:focus-within {
  position: static;
  inline-size: auto;
  block-size: auto;
  margin: 0;
  overflow: visible;
  clip: auto;
  clip-path: none;
  white-space: normal;
}

}
@layer rottay-components {
/**
 * IconFrame — canonical paint for the engine-independent medallion primitive.
 *
 * LAYER: rottay-components (single owner for every engine and consumer).
 * SCOPE: `.ds-icon-frame` applied by the `IconFrame` primitive. All axes
 *   arrive as data attributes stamped by the TSX: `data-size`, `data-shape`,
 *   `data-variant`, `data-tone`, `data-loading`, `data-disabled`. Anatomy
 *   parts: `icon`, `badge`.
 * SPECIFICITY: single class + attribute selectors, no repetition, no
 *   `!important`, logical properties throughout (RTL-safe by construction;
 *   the badge anchors to the logical end corner, no translate mirroring).
 *
 * GEOMETRY: sizes ride the density-effective spacing scale (already
 *   multiplied by `--ds-density-effective-scale` in foundation/base/spacing),
 *   so compact/comfortable/spacious and the tenant density dial reshape every
 *   frame without a single fixed pixel. The inner icon size rides the
 *   canonical `--ds-icon-*` scale via the TSX token mapping.
 *
 * MATERIAL: every variant derives from existing semantic channels — subtle
 *   (color-mix tone wash, button.css/card.css precedent), outline (tone
 *   edge), filled (tone solid; its ink is the per-tone
 *   `--ds-color-on-<tone>` authority both theme paths emit, so contrast
 *   follows every tenant's own tones) and glass (the governed frost recipe
 *   of semantic-surface.css: blur scaled by the tenant effect intensity,
 *   collapsing to solid when the channel is opaque). Tenants reshape
 *   radically through radius-scale/effect-intensity/type/density; there is
 *   no parallel color system here.
 *
 * STATES: presentation only — the frame is never a control, so it paints no
 *   hover, focus or active chrome (icon-only actions are `Button.Icon`).
 *   `disabled` pairs the governed opacity floor with the muted cursor;
 *   `loading` is the icon's governed busy motion (never color-only).
 *
 * MOTION: transitions ride `--ds-motion-fast` / `--ds-motion-ease-out`,
 *   which the foundation zeroes under reduced motion — every frame ends in
 *   its final state immediately.
 */

/* ---- private experimental axes (prototype ledger; fallbacks canonical) ---- */

.ds-icon-frame {
  /* geometry axis: outer frame size, per-size values from the spacing scale */
  --_ds-proto-icon-frame-size: var(--ds-spacing-10);
  /* material axis: subtle wash strength inside color-mix */
  --_ds-proto-icon-frame-subtle-strength: 12%;
  /* material axis: glass wash (tenant alpha channel) */
  --_ds-proto-icon-frame-glass-bg: var(--ds-color-alpha-white-10);

  position: relative;
  display: inline-grid;
  place-items: center;
  flex: none;
  inline-size: var(--_ds-proto-icon-frame-size);
  block-size: var(--_ds-proto-icon-frame-size);
  padding: 0;
  margin: 0;
  border: 1px solid transparent;
  border-radius: var(--ds-radius-lg);
  background: transparent;
  color: var(--ds-color-text-secondary);
  vertical-align: middle;
  transition:
    background-color var(--ds-motion-fast) var(--ds-motion-ease-out),
    border-color var(--ds-motion-fast) var(--ds-motion-ease-out),
    color var(--ds-motion-fast) var(--ds-motion-ease-out);
}

/* ---- size (geometry × density-effective spacing scale) ---- */

.ds-icon-frame[data-size='xs'] {
  --_ds-proto-icon-frame-size: var(--ds-spacing-6);
}
.ds-icon-frame[data-size='sm'] {
  --_ds-proto-icon-frame-size: var(--ds-spacing-8);
}
.ds-icon-frame[data-size='md'] {
  --_ds-proto-icon-frame-size: var(--ds-spacing-10);
}
.ds-icon-frame[data-size='lg'] {
  --_ds-proto-icon-frame-size: var(--ds-spacing-12);
}
.ds-icon-frame[data-size='xl'] {
  --_ds-proto-icon-frame-size: var(--ds-spacing-16);
}

/* ---- shape (tenant radius scale; square is the deliberate sharp pole) ---- */

.ds-icon-frame[data-shape='circle'] {
  border-radius: var(--ds-radius-full);
}
.ds-icon-frame[data-shape='square'] {
  border-radius: var(--ds-radius-none);
}
.ds-icon-frame[data-shape='rounded'] {
  border-radius: var(--ds-radius-lg);
}

/* ---- tone ink (per-tone ink channel consumed by every variant) ---- */

.ds-icon-frame[data-tone='neutral'] {
  --_icon-frame-ink: var(--ds-color-text-secondary);
  /* Solid neutral inverts against the page: the canvas is the readable ink
     over the secondary-text fill in both schemes. */
  --_icon-frame-on-ink: var(--ds-surface-canvas, var(--ds-color-bg-primary));
}
.ds-icon-frame[data-tone='primary'] {
  --_icon-frame-ink: var(--ds-color-primary);
  --_icon-frame-on-ink: var(--ds-color-on-primary, var(--ds-color-text-on-primary));
}
.ds-icon-frame[data-tone='success'] {
  --_icon-frame-ink: var(--ds-color-success);
  --_icon-frame-on-ink: var(--ds-color-on-success);
}
.ds-icon-frame[data-tone='warning'] {
  --_icon-frame-ink: var(--ds-color-warning);
  --_icon-frame-on-ink: var(--ds-color-on-warning);
}
.ds-icon-frame[data-tone='error'] {
  --_icon-frame-ink: var(--ds-color-error);
  --_icon-frame-on-ink: var(--ds-color-on-error);
}
.ds-icon-frame[data-tone='info'] {
  --_icon-frame-ink: var(--ds-color-info);
  --_icon-frame-on-ink: var(--ds-color-on-info);
}

/* ---- variants (material recipes over the tone ink) ---- */

.ds-icon-frame[data-variant='subtle'] {
  background: color-mix(
    in srgb,
    var(--_icon-frame-ink) var(--_ds-proto-icon-frame-subtle-strength),
    transparent
  );
  color: var(--_icon-frame-ink);
}

.ds-icon-frame[data-variant='outline'] {
  background: transparent;
  border-color: color-mix(in srgb, var(--_icon-frame-ink) 45%, transparent);
  color: var(--_icon-frame-ink);
}

.ds-icon-frame[data-variant='filled'] {
  background: var(--_icon-frame-ink);
  color: var(--_icon-frame-on-ink);
}

.ds-icon-frame[data-variant='glass'] {
  background: var(--_ds-proto-icon-frame-glass-bg);
  border-color: var(--ds-color-alpha-white-20);
  color: var(--_icon-frame-ink);
  backdrop-filter: blur(calc(var(--ds-glass-blur-sm) * var(--ds-effect-intensity, 1)))
    saturate(1.08);
  -webkit-backdrop-filter: blur(calc(var(--ds-glass-blur-sm) * var(--ds-effect-intensity, 1)))
    saturate(1.08);
}

/* ---- badge anchor (logical end corner; no translate, no RTL mirror) ---- */

.ds-icon-frame > [data-part='badge'] {
  position: absolute;
  inset-block-start: calc(-1 * var(--ds-spacing-1));
  inset-inline-end: calc(-1 * var(--ds-spacing-1));
  display: inline-flex;
}

/* ---- disabled (opacity floor + muted cursor; aria-disabled carries the rest) ---- */

.ds-icon-frame[data-disabled='true'] {
  opacity: var(--ds-state-disabled-opacity);
  cursor: not-allowed;
}

/* ---- forced colors: system palette, no frost ---- */

@media (forced-colors: active) {
  .ds-icon-frame {
    background: Canvas;
    color: CanvasText;
    border-color: CanvasText;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
  }
  .ds-icon-frame[data-variant='filled'] {
    background: ButtonFace;
    color: ButtonText;
  }
  .ds-icon-frame[data-disabled='true'] {
    opacity: 1;
    color: GrayText;
    border-color: GrayText;
  }
}

}
@layer rottay-components {
/**
 * Arc — shared circular-gauge substrate (conic sweep, ring mask, rounded cap).
 *
 * LAYER: rottay-components (single owner of the arc recipe for every gauge
 *   consumer). `Meter` and Modern `Progress` both compose it; each consumer
 *   maps its own contract onto the private substrate channels below.
 * SCOPE: `.ds-arc` on the gauge element. All inputs are private composition
 *   channels set by the consuming skin — never tenant tokens:
 *     --_ds-arc-value      0..100 sweep (stamped per instance by the owner TSX)
 *     --_ds-arc-size       outer diameter (consumer maps its sizing channel)
 *     --_ds-arc-thickness  ring thickness (defaults to size/10, progress parity)
 *     --_ds-arc-fill       sweep color (consumer maps its resolved fill)
 *     --_ds-arc-track      remainder color
 *   `data-arc-mirror='true'` opts into the RTL horizontal flip (Progress's
 *   determinate posture); `data-arc-cap='false'` suppresses the cap for a
 *   spinning arc. Without either flag the sweep is direction-neutral.
 * SPECIFICITY: single class (+ one attribute opt-in), no `!important`, logical
 *   properties; the `#0000`/`#000` stops below are mask alpha, not paint.
 * MOTION: the sweep transition rides `--ds-motion-normal`/`--ds-motion-ease-out`,
 *   zeroed by the foundation under reduced motion.
 *
 * REGISTRATION: `--_ds-arc-value` is registered exactly once in
 * foundation/base/properties.css. Component skins must never register typed
 * custom properties locally because @property is document-global.
 */

.ds-arc {
  --_ds-arc-size: 6rem;
  --_ds-arc-thickness: calc(var(--_ds-arc-size) / 10);
  --_ds-arc-fill: var(--ds-color-primary);
  --_ds-arc-track: var(--ds-color-border-secondary);

  position: relative;
  display: inline-grid;
  place-items: center;
  inline-size: var(--_ds-arc-size);
  block-size: var(--_ds-arc-size);
  border-radius: 50%;
  transition: --_ds-arc-value var(--ds-motion-normal) var(--ds-motion-ease-out);
}

/* Sweep over the full disc, masked down to the ring thickness. */
.ds-arc::before {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  content: '';
  background: conic-gradient(
    var(--_ds-arc-fill) calc(var(--_ds-arc-value) * 1%),
    var(--_ds-arc-track) 0
  );
  -webkit-mask: radial-gradient(
    farthest-side,
    #0000 calc(100% - var(--_ds-arc-thickness)),
    #000 calc(100% + 0.5px - var(--_ds-arc-thickness))
  );
  mask: radial-gradient(
    farthest-side,
    #0000 calc(100% - var(--_ds-arc-thickness)),
    #000 calc(100% + 0.5px - var(--_ds-arc-thickness))
  );
}

/* Rounded cap at the sweep tip. */
.ds-arc::after {
  position: absolute;
  inset: calc(50% - var(--_ds-arc-thickness) / 2);
  border-radius: 50%;
  content: '';
  background: var(--_ds-arc-fill);
  transform: rotate(calc(var(--_ds-arc-value) * 3.6deg - 90deg))
    translate(calc(var(--_ds-arc-size) / 2 - 50%));
}

.ds-arc[data-arc-cap='false']::after {
  content: none;
}

/* RTL flip is an explicit consumer opt-in: a mirrored gauge reverses the
   sweep and the cap together so the arc still meets its own tip. */
.ds-arc[data-arc-mirror='true']:dir(rtl)::before {
  transform: scaleX(-1);
}

.ds-arc[data-arc-mirror='true']:dir(rtl)::after {
  transform: scaleX(-1) rotate(calc(var(--_ds-arc-value) * 3.6deg - 90deg))
    translate(calc(var(--_ds-arc-size) / 2 - 50%));
}

/* Forced colors: the system palette feeds the same channels, so both the
   sweep and the cap remap without touching the recipe. */
@media (forced-colors: active) {
  .ds-arc {
    --_ds-arc-fill: Highlight;
    --_ds-arc-track: Canvas;
  }
}

}
@layer rottay-components {
/**
 * Meter — canonical paint for the engine-independent scalar-gauge primitive.
 *
 * LAYER: rottay-components (single owner for every engine and consumer).
 * SCOPE: `.ds-meter` applied by the `Meter` primitive. Axes arrive as data
 *   attributes stamped by the TSX: `data-variant` (bar|compact|ring),
 *   `data-size`, `data-tone` (only when the caller sets an explicit tone),
 *   `data-threshold` (none|optimal|suboptimal|critical, resolved with the
 *   WHATWG region algorithm over sanitized bounds). Anatomy parts: header,
 *   label, value, track, fill, tick, ring, description.
 * SPECIFICITY: single class + attribute selectors, no repetition, no
 *   `!important`, logical properties throughout. The bar fill and the ticks
 *   anchor to the inline-start edge, so RTL flows them from the reading
 *   side with zero mirroring code; the fill's scaleX origin flips under
 *   `:dir(rtl)`. The ring arc is gauge semantics (a clockwise sweep from
 *   12 o'clock), deliberately direction-neutral: it does not opt into the
 *   substrate's `data-arc-mirror` flip.
 * GEOMETRY: track thickness and ring diameter ride the density-effective
 *   spacing scale (already multiplied by `--ds-density-effective-scale`),
 *   so the tenant density dial and compact/comfortable/spacious reshape every
 *   meter without a fixed pixel. The only per-instance geometry is truly
 *   dynamic: the fill ratio custom property, the tick positions and the
 *   registered arc sweep, all stamped inline by the TSX (contract instance
 *   geometry — never a tenant token).
 * THRESHOLDS: on bar/compact, never color-only — shape (track tick marks at
 *   the low/high boundaries), label (the localized value text plus the
 *   screen-reader threshold status in `aria-valuetext`) and pattern (static
 *   governed stripes on the fill, graduated by severity). On the ring the
 *   threshold reaches users through TEXT — `aria-valuetext` and the center
 *   reading — not through shape. An explicit `data-tone` always wins over
 *   threshold-derived fill color: its rules sort after the threshold ones at
 *   equal specificity.
 * RING: composes the shared `.ds-arc` substrate
 *   (presentation/components/arc.css) — this skin only maps its own channels
 *   (`--_ds-arc-size/fill/track`) onto it and sizes the textual center.
 * MOTION: fill and arc transitions ride `--ds-motion-normal` /
 *   `--ds-motion-ease-out`, which the foundation zeroes under reduced
 *   motion — every meter settles in its final state immediately. Stripes are
 *   static, so the non-color threshold cue survives motion-off.
 */

/* ---- private experimental axes (prototype ledger; fallbacks canonical) ---- */

.ds-meter {
  /* material axis: track substrate */
  --_ds-proto-meter-track-bg: var(--ds-color-border-secondary);
  /* geometry axis: bar/compact track thickness */
  --_ds-proto-meter-track-size: var(--ds-spacing-2);
  /* geometry axis: ring diameter */
  --_ds-proto-meter-ring-size: var(--ds-spacing-16);

  /* internal composition hatch: resolved fill color (threshold < tone) */
  --_meter-fill: var(--ds-color-primary);

  display: flex;
  flex-direction: column;
  gap: var(--ds-spacing-1);
  inline-size: 100%;
  color: var(--ds-color-text-primary);
}

/* ---- size (geometry × density-effective spacing scale) ---- */

.ds-meter[data-size='sm'] {
  --_ds-proto-meter-track-size: var(--ds-spacing-1);
  --_ds-proto-meter-ring-size: var(--ds-spacing-10);
}
.ds-meter[data-size='md'] {
  --_ds-proto-meter-track-size: var(--ds-spacing-2);
  --_ds-proto-meter-ring-size: var(--ds-spacing-16);
}
.ds-meter[data-size='lg'] {
  --_ds-proto-meter-track-size: var(--ds-spacing-3);
  --_ds-proto-meter-ring-size: var(--ds-spacing-24);
}

/* ---- header / label / value / description ---- */

.ds-meter > [data-part='header'] {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--ds-spacing-2);
  min-inline-size: 0;
}

.ds-meter [data-part='label'] {
  min-inline-size: 0;
  overflow: hidden;
  color: var(--ds-color-text-secondary);
  font-size: var(--ds-font-size-sm);
  line-height: var(--ds-line-height-normal);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ds-meter [data-part='value'] {
  flex: none;
  color: var(--ds-color-text-primary);
  font-size: var(--ds-font-size-sm);
  font-variant-numeric: tabular-nums;
  font-weight: var(--ds-font-weight-semibold);
  line-height: var(--ds-line-height-normal);
}

.ds-meter > [data-part='description'] {
  color: var(--ds-color-text-muted);
  font-size: var(--ds-font-size-xs);
  line-height: var(--ds-line-height-normal);
  overflow-wrap: anywhere;
}

/* ---- bar / compact track, fill, ticks ---- */

.ds-meter > [data-part='track'] {
  position: relative;
  display: block;
  flex: none;
  inline-size: 100%;
  block-size: var(--_ds-proto-meter-track-size);
  border-radius: var(--ds-radius-full);
  background: var(--_ds-proto-meter-track-bg);
}

.ds-meter [data-part='fill'] {
  position: absolute;
  inset-block: 0;
  inset-inline-start: 0;
  inline-size: 100%;
  border-radius: var(--ds-radius-full);
  background: var(--_meter-fill);
  transform: scaleX(var(--_meter-ratio, 0));
  transform-origin: 0 50%;
  transition: transform var(--ds-motion-normal) var(--ds-motion-ease-out);
}

.ds-meter:dir(rtl) [data-part='fill'] {
  transform-origin: 100% 50%;
}

/* threshold boundary marks: hairlines overshooting the track pill (shape cue) */
.ds-meter [data-part='tick'] {
  position: absolute;
  inset-block: calc(-1 * var(--ds-spacing-1));
  border-inline-start: 1px solid var(--ds-color-text-muted);
}

/* ---- compact: single-row micro meter (label · track · value) ---- */

.ds-meter[data-variant='compact'] {
  flex-flow: row wrap;
  align-items: center;
  gap: var(--ds-spacing-2);
  inline-size: auto;
  min-inline-size: var(--ds-spacing-20);
}

.ds-meter[data-variant='compact'] > [data-part='header'] {
  display: contents;
}

.ds-meter[data-variant='compact'] [data-part='label'] {
  order: 1;
  flex: 0 1 auto;
}

.ds-meter[data-variant='compact'] > [data-part='track'] {
  order: 2;
  flex: 1 1 0;
  min-inline-size: 0;
}

.ds-meter[data-variant='compact'] [data-part='value'] {
  order: 3;
}

.ds-meter[data-variant='compact'] > [data-part='description'] {
  flex: 1 1 100%;
  order: 4;
}

/* ---- ring: the shared arc substrate, fed by this skin's channels ---- */

.ds-meter[data-variant='ring'] {
  align-items: center;
  inline-size: auto;
}

.ds-meter [data-part='ring'] {
  --_ds-arc-size: var(--_ds-proto-meter-ring-size);
  --_ds-arc-fill: var(--_meter-fill);
  --_ds-arc-track: var(--_ds-proto-meter-track-bg);

  flex: none;
}

/* center reading: the textual alternative, sized off the arc */
.ds-meter [data-part='ring'] > [data-part='value'] {
  position: relative;
  font-size: calc(var(--_ds-arc-size) * 0.22);
  line-height: 1;
}

/* ---- threshold signaling (color + static pattern; tone overrides below) ---- */

.ds-meter[data-threshold='optimal'] {
  --_meter-fill: var(--ds-color-success);
}

.ds-meter[data-threshold='suboptimal'] {
  --_meter-fill: var(--ds-color-warning);
}

.ds-meter[data-threshold='suboptimal'] [data-part='fill'] {
  /* Stripe ink rides the on-tone authority, so the pattern stays visible on
     ANY tenant's warning fill instead of assuming a dark one. */
  background-image: linear-gradient(
    45deg,
    color-mix(in srgb, var(--ds-color-on-warning) 14%, transparent) 25%,
    transparent 25%,
    transparent 50%,
    color-mix(in srgb, var(--ds-color-on-warning) 14%, transparent) 50%,
    color-mix(in srgb, var(--ds-color-on-warning) 14%, transparent) 75%,
    transparent 75%
  );
  background-size: var(--ds-spacing-2) var(--ds-spacing-2);
}

.ds-meter[data-threshold='critical'] {
  --_meter-fill: var(--ds-color-error);
}

.ds-meter[data-threshold='critical'] [data-part='fill'] {
  background-image: linear-gradient(
    45deg,
    color-mix(in srgb, var(--ds-color-on-error) 26%, transparent) 25%,
    transparent 25%,
    transparent 50%,
    color-mix(in srgb, var(--ds-color-on-error) 26%, transparent) 50%,
    color-mix(in srgb, var(--ds-color-on-error) 26%, transparent) 75%,
    transparent 75%
  );
  background-size: var(--ds-spacing-2) var(--ds-spacing-2);
}

/* ---- explicit tone (sorted after thresholds at equal specificity: it wins) ---- */

.ds-meter[data-tone='neutral'] {
  --_meter-fill: var(--ds-color-text-secondary);
}
.ds-meter[data-tone='primary'] {
  --_meter-fill: var(--ds-color-primary);
}
.ds-meter[data-tone='success'] {
  --_meter-fill: var(--ds-color-success);
}
.ds-meter[data-tone='warning'] {
  --_meter-fill: var(--ds-color-warning);
}
.ds-meter[data-tone='error'] {
  --_meter-fill: var(--ds-color-error);
}
.ds-meter[data-tone='info'] {
  --_meter-fill: var(--ds-color-info);
}

/* ---- forced colors: system palette, patterns flattened, ticks kept.
        The ring remaps through the arc substrate's own forced-colors block. */

@media (forced-colors: active) {
  .ds-meter > [data-part='track'] {
    border: 1px solid CanvasText;
    background: Canvas;
  }
  .ds-meter [data-part='fill'] {
    background: Highlight;
  }
  .ds-meter [data-part='tick'] {
    border-color: CanvasText;
  }
}

