@layer rottay-components {
/**
 * Badge Component Tokens - Rottay Design System
 *
 * Design tokens specific to the Badge component.
 * Includes sizes, dot sizes, variants, and styling properties.
 */

:root {
  /* ========================================================================
     SIZES - Badge Dimensions
     Five size variants from xs to xl with corresponding properties
     ======================================================================== */

  /* XS - Extra Small */
  --ds-badge-xs-min-width: 0.875rem;       /* 14px */
  --ds-badge-xs-height: 0.875rem;          /* 14px */
  --ds-badge-xs-font-size: 0.5625rem;      /* 9px */
  --ds-badge-xs-padding-x: 0.375rem;

  /* SM - Small */
  --ds-badge-sm-min-width: 1rem;           /* 16px */
  --ds-badge-sm-height: 1rem;              /* 16px */
  --ds-badge-sm-font-size: 0.625rem;       /* 10px */
  --ds-badge-sm-padding-x: 0.5rem;

  /* MD - Medium (Default) */
  --ds-badge-md-min-width: 1.25rem;        /* 20px */
  --ds-badge-md-height: 1.25rem;           /* 20px */
  --ds-badge-md-font-size: 0.75rem;        /* 12px */
  --ds-badge-md-padding-x: 0.625rem;

  /* LG - Large */
  --ds-badge-lg-min-width: 1.5rem;         /* 24px */
  --ds-badge-lg-height: 1.5rem;            /* 24px */
  --ds-badge-lg-font-size: 0.875rem;       /* 14px */
  --ds-badge-lg-padding-x: 0.75rem;

  /* XL - Extra Large */
  --ds-badge-xl-min-width: 1.75rem;        /* 28px */
  --ds-badge-xl-height: 1.75rem;           /* 28px */
  --ds-badge-xl-font-size: 1rem;           /* 16px */
  --ds-badge-xl-padding-x: 0.875rem;

  /* Default size (can be overridden) */
  --ds-badge-default-min-width: var(--ds-badge-md-min-width);
  --ds-badge-default-height: var(--ds-badge-md-height);
  --ds-badge-default-font-size: var(--ds-badge-md-font-size);

  /* ========================================================================
     DOT SIZES - Badge Dot Indicator Dimensions
     Diameter of dot badges for each size variant
     ======================================================================== */

  --ds-badge-dot-xs-size: 0.25rem;         /* 4px */
  --ds-badge-dot-sm-size: 0.375rem;        /* 6px */
  --ds-badge-dot-md-size: 0.5rem;          /* 8px */
  --ds-badge-dot-lg-size: 0.625rem;        /* 10px */
  --ds-badge-dot-xl-size: 0.75rem;         /* 12px */

  /* Default dot size */
  --ds-badge-dot-default-size: var(--ds-badge-dot-md-size);

  /* ========================================================================
     VARIANTS - Badge Color Variants
     Different visual styles for badges
     ======================================================================== */

  /* Default variant (neutral) */
  --ds-badge-default-bg: #d9d9d9;
  --ds-badge-default-color: var(--ds-color-white, #ffffff);
  --ds-badge-default-border: var(--ds-badge-border-color);

  /* Primary variant */
  --ds-badge-primary-bg: #1890ff;
  --ds-badge-primary-color: var(--ds-color-white, #ffffff);
  --ds-badge-primary-border: var(--ds-badge-primary-bg);

  /* Secondary variant */
  --ds-badge-secondary-bg: #722ed1;
  --ds-badge-secondary-color: var(--ds-color-white, #ffffff);
  --ds-badge-secondary-border: var(--ds-badge-secondary-bg);

  /* Success variant */
  --ds-badge-success-bg: #52c41a;
  --ds-badge-success-color: var(--ds-color-white, #ffffff);
  --ds-badge-success-border: var(--ds-badge-success-bg);

  /* Warning variant */
  --ds-badge-warning-bg: #faad14;
  --ds-badge-warning-color: var(--ds-color-white, #ffffff);
  --ds-badge-warning-border: var(--ds-badge-warning-bg);

  /* Error variant */
  --ds-badge-error-bg: #ff4d4f;
  --ds-badge-error-color: var(--ds-color-white, #ffffff);
  --ds-badge-error-border: var(--ds-badge-error-bg);

  /* Info variant */
  --ds-badge-info-bg: #1890ff;
  --ds-badge-info-color: var(--ds-color-white, #ffffff);
  --ds-badge-info-border: var(--ds-badge-info-bg);

  /* ========================================================================
     STATUS INDICATORS
     Color indicators for processing/default/success/error/warning states
     ======================================================================== */

  --ds-badge-status-processing-color: #1890ff;
  --ds-badge-status-default-color: #d9d9d9;
  --ds-badge-status-success-color: #52c41a;
  --ds-badge-status-error-color: #ff4d4f;
  --ds-badge-status-warning-color: #faad14;

  /* ========================================================================
     BORDER RADIUS
     Border radius options for badges
     ======================================================================== */

  --ds-badge-radius-none: 0;
  --ds-badge-radius-sm: 0.125rem;          /* 2px */
  --ds-badge-radius-md: 0.25rem;           /* 4px */
  --ds-badge-radius-lg: 0.5rem;            /* 8px */
  --ds-badge-radius-full: 9999px;

  /* Default border radius */
  --ds-badge-default-radius: var(--ds-badge-radius-full);

  /* ========================================================================
     SPACING
     Padding and spacing for badges
     ======================================================================== */

  --ds-badge-padding-x: 0.375rem;          /* 6px */
  --ds-badge-padding-y: 0;
  --ds-badge-icon-gap: 0.25rem;            /* 4px */
  --ds-badge-close-gap: 0.25rem;           /* 4px */

  /* ========================================================================
     BORDER
     Border settings for bordered badges
     ======================================================================== */

  --ds-badge-border-width: 2px;
  --ds-badge-border-color: var(--ds-color-white, #ffffff);

  /* ========================================================================
     TRANSITIONS
     Animation timing for state changes
     ======================================================================== */

  --ds-badge-transition-duration: 0.2s;
  --ds-badge-transition-timing: ease-in-out;
  --ds-badge-transition: var(--ds-badge-transition-duration) var(--ds-badge-transition-timing);

  /* ========================================================================
     PULSE ANIMATION
     Settings for attention-grabbing pulse animation
     ======================================================================== */

  --ds-badge-pulse-duration: 1.5s;
  --ds-badge-pulse-timing: ease-in-out;
  --ds-badge-pulse-opacity: 0.6;
  --ds-badge-pulse-scale: 1.05;

  /* ========================================================================
     TYPOGRAPHY
     Font settings for badge content
     ======================================================================== */

  --ds-badge-font-weight: 500;
  --ds-badge-line-height: 1;

  /* ========================================================================
     COMPACT LABEL FAMILY — Badge / Chip / Pill
     Tenant compilers may override these channels without changing anatomy.
     ======================================================================== */

  --ds-badge-font-family: var(--ds-font-family-base);
  --ds-badge-letter-spacing: var(--ds-letter-spacing-body, -0.01em);
  --ds-badge-gap: 0.25rem;
  --ds-badge-max-inline-size: 18rem;
  --ds-badge-chip-max-inline-size: 22rem;
  --ds-badge-pill-max-inline-size: 22rem;
  --ds-badge-frame-width: 1px;
  --ds-badge-icon-size: 1em;
  --ds-badge-avatar-bleed: 0.125rem;
  --ds-badge-count-min-size: 1rem;
  --ds-badge-count-size: 1rem;
  --ds-badge-count-padding-inline: 0.25rem;
  --ds-badge-remove-size: 1.125rem;
  --ds-badge-remove-bleed: 0.1875rem;
  --ds-badge-disabled-opacity: 0.48;
  --ds-badge-loading-opacity: 0.76;
  --ds-badge-motion-duration: var(--ds-motion-fast);
  --ds-badge-motion-easing: var(--ds-motion-ease-out, ease-out);
  --ds-badge-touch-target: 2.75rem;

  /* ========================================================================
     Z-INDEX
     Stacking context for positioned badges
     ======================================================================== */

  --ds-badge-z-index: 1;
}

