    var(--ds-motion-ease-out);
}

.ds-semantic-surface[data-emphasis="strong"] {
  border-color: var(--_surface-border-strong, var(--_surface-border));
}

.ds-semantic-surface[data-interactive="true"] {
  cursor: pointer;
}

.ds-semantic-surface > .ds-semantic-surface__support {
  color: var(--_surface-foreground-muted, var(--ds-color-text-secondary));
  font-size: var(--ds-font-size-sm);
  line-height: var(--ds-line-height-normal);
