.ds-semantic-surface[data-finish="glass"][data-surface-role="overlay"] {
  backdrop-filter: blur(calc(var(--ds-glass-blur-sm) * var(--ds-effect-intensity))) saturate(1.08);
  -webkit-backdrop-filter: blur(calc(var(--ds-glass-blur-sm) * var(--ds-effect-intensity))) saturate(1.08);
}

@media (hover: hover) {
