    border-color: var(--_surface-border-hover, var(--_surface-border));
    box-shadow: var(--_surface-shadow-hover, var(--_surface-shadow));
  }
}

.ds-semantic-surface[data-interactive="true"]:not([data-loading="true"]):active {
  background: var(--_surface-texture, none),
    var(--_surface-background-active, var(--_surface-background));
  border-color: var(--_surface-border-active, var(--_surface-border));
  box-shadow: var(--_surface-shadow-active, var(--_surface-shadow));
}

.ds-semantic-surface[data-interactive="true"]:focus-visible {
  outline: none;
}

.ds-semantic-surface[data-interactive="true"]:focus-visible::after {
  opacity: 1;
}

.ds-semantic-surface[data-selected="true"] {
  background: var(--_surface-texture, none),
    var(--_surface-background-selected, var(--_surface-background));
  border-color: var(--_surface-border-selected, var(--_surface-border-strong));
  box-shadow: var(--_surface-shadow-selected, var(--_surface-shadow));
