  --ds-button-success-shadow-hover: var(--ds-button-success-shadow);
  --ds-button-success-shadow-active: var(--ds-button-success-shadow);
  --ds-button-success-border-color: var(--ds-button-success-border);

  /* WARNING */
  --ds-button-warning-bg: var(--ds-color-warning-500);
  --ds-button-warning-bg-hover: var(--ds-color-warning-600);
  --ds-button-warning-bg-active: var(--ds-color-warning-700);
  --ds-button-warning-color: var(--ds-color-white);
  --ds-button-warning-color-hover: var(--ds-button-warning-color);
  --ds-button-warning-color-active: var(--ds-button-warning-color);
  --ds-button-warning-border: var(--ds-color-warning-600);
  --ds-button-warning-border-hover: var(--ds-color-warning-700);
  --ds-button-warning-border-active: var(--ds-color-warning-800);
  --ds-button-warning-shadow: var(--ds-shadow-warning-sm);
  --ds-button-warning-shadow-hover: var(--ds-button-warning-shadow);
  --ds-button-warning-shadow-active: var(--ds-button-warning-shadow);
  --ds-button-warning-border-color: var(--ds-button-warning-border);

  /* ERROR/DANGER */
  --ds-button-error-bg: var(--ds-color-error-500);
  --ds-button-error-bg-hover: var(--ds-color-error-600);
  --ds-button-error-bg-active: var(--ds-color-error-700);
  --ds-button-error-color: var(--ds-color-white);
  --ds-button-error-color-hover: var(--ds-button-error-color);
  --ds-button-error-color-active: var(--ds-button-error-color);
  --ds-button-error-border: var(--ds-color-error-600);
  --ds-button-error-border-hover: var(--ds-color-error-700);
  --ds-button-error-border-active: var(--ds-color-error-800);
  --ds-button-error-shadow: var(--ds-shadow-error-sm);
  --ds-button-error-shadow-hover: var(--ds-shadow-error-sm);
  --ds-button-error-shadow-active: var(--ds-shadow-error-sm);
  --ds-button-error-border-color: var(--ds-button-error-border);

  /* INFO */
  --ds-button-info-bg: var(--ds-color-info-500);
  --ds-button-info-bg-hover: var(--ds-color-info-600);
  --ds-button-info-bg-active: var(--ds-color-info-700);
  --ds-button-info-color: var(--ds-color-white);
  --ds-button-info-color-hover: var(--ds-button-info-color);
  --ds-button-info-color-active: var(--ds-button-info-color);
  --ds-button-info-border: var(--ds-color-info-600);
  --ds-button-info-border-hover: var(--ds-color-info-700);
  --ds-button-info-border-active: var(--ds-color-info-800);
  --ds-button-info-shadow: var(--ds-shadow-button-rest);
  --ds-button-info-shadow-hover: var(--ds-button-info-shadow);
  --ds-button-info-shadow-active: var(--ds-button-info-shadow);

  /* AI - Assisted/generative actions; every channel remains brand-authored. */
  --ds-button-ai-bg: var(--ds-color-primary-600);
  --ds-button-ai-bg-hover: var(--ds-color-primary-700);
  --ds-button-ai-bg-active: var(--ds-color-primary-800);
  --ds-button-ai-color: var(--ds-color-text-on-primary);
  --ds-button-ai-color-hover: var(--ds-button-ai-color);
  --ds-button-ai-color-active: var(--ds-button-ai-color);
  --ds-button-ai-border: var(--ds-color-primary-500);
  --ds-button-ai-border-hover: var(--ds-color-primary-600);
  --ds-button-ai-border-active: var(--ds-color-primary-700);
  --ds-button-ai-shadow: var(--ds-shadow-button-rest);
  --ds-button-ai-shadow-hover: var(--ds-shadow-button-hover);
  --ds-button-ai-shadow-active: var(--ds-shadow-button-rest);
  --ds-button-ai-texture: var(--ds-material-control-texture);

  /* ========================================================================
     STATES - Interactive States
     Disabled, loading, and focus states
     ======================================================================== */

  /* Disabled state */
  --ds-button-disabled-bg: var(--ds-color-neutral-100);
  --ds-button-disabled-color: var(--ds-color-neutral-400);
  --ds-button-disabled-border-color: var(--ds-color-neutral-200);
  --ds-button-disabled-opacity: 0.58;
  --ds-button-disabled-cursor: not-allowed;
  --ds-button-disabled-shadow: none;

  /* Loading state */
  --ds-button-loading-opacity: 0.7;
  --ds-button-loading-cursor: wait;

  /* Focus state — the canonical WO-ENG-04 double ring (page-ground gap +
     >=3:1 ring) so the indicator survives saturated fills cross-family; the
     old single-layer --ds-shadow-focus-ring measured ~1.3-1.8:1 (W8). */
  --ds-button-focus-ring: var(--ds-focus-ring);
  --ds-button-focus-ring-offset: 2px;
  --ds-button-focus-outline: none;

  /* ========================================================================
     SHAPES
     Border radius variants
     ======================================================================== */
  --ds-button-shape-square: 0;
  --ds-button-shape-rounded: var(--ds-radius-md);
  --ds-button-shape-pill: var(--ds-radius-full);
  --ds-button-shape-circle: 50%;

  /* ========================================================================
     ICON BUTTONS
     Special settings for icon-only buttons
     ======================================================================== */
  --ds-button-icon-only-padding: 0.5rem;
  --ds-button-icon-only-xs-size: var(--ds-button-xs-height);
  --ds-button-icon-only-sm-size: var(--ds-button-sm-height);
  --ds-button-icon-only-md-size: var(--ds-button-md-height);
  --ds-button-icon-only-lg-size: var(--ds-button-lg-height);
  --ds-button-icon-only-xl-size: var(--ds-button-xl-height);

  /* ========================================================================
     BUTTON GROUP
     Settings for button groups
     ======================================================================== */
  --ds-button-group-gap: var(--ds-spacing-2);
  --ds-button-group-mobile-direction: column;
  --ds-button-group-mobile-gap: var(--ds-spacing-2);
  --ds-button-group-mobile-width: 100%;
  --ds-button-group-border-radius-first: var(--ds-radius-md) 0 0 var(--ds-radius-md);
  --ds-button-group-border-radius-last: 0 var(--ds-radius-md) var(--ds-radius-md) 0;
  --ds-button-group-border-radius-middle: 0;
  --ds-button-group-divider-color: var(--ds-color-neutral-300);

  /* ========================================================================
     TRANSITIONS
     Animation timing for state changes
     ======================================================================== */
  --ds-button-transition-duration: var(--ds-motion-feedback);
  --ds-button-transition-timing: var(--ds-motion-ease-out);
  --ds-button-transition: all var(--ds-button-transition-duration) var(--ds-button-transition-timing);

  /* ========================================================================
     TYPOGRAPHY
     Font settings for button text
     ======================================================================== */
  --ds-button-font-family: var(--ds-font-family-base);
  --ds-button-font-weight: var(--ds-font-weight-semibold);
  --ds-button-letter-spacing: -0.006em;
  --ds-button-text-transform: none;
  --ds-button-hover-transform: translateY(-1px);
  --ds-button-active-transform: scale(var(--ds-state-press-scale));
  --ds-button-icon-hover-transform: translateY(-0.03125rem);
  --ds-button-icon-active-transform: scale(var(--ds-state-press-scale));
  --ds-button-label-offset-y: -0.015em;
  --ds-button-hover-filter: saturate(1.025);
  --ds-button-active-filter: saturate(0.985);
  --ds-button-surface-highlight: linear-gradient(
    180deg,
    rgb(255 255 255 / 0.22),
    transparent 58%
  );
  --ds-button-surface-highlight-opacity: 0.52;
  --ds-button-surface-highlight-hover-opacity: 0.72;
  --ds-button-surface-highlight-active-opacity: 0.26;
  --ds-button-gradient: var(--ds-gradient-primary);
  --ds-button-bordered-border: var(--ds-color-border);
  --ds-button-elevated-shadow: var(--ds-elevation-1);
  --ds-button-elevated-shadow-hover: var(--ds-elevation-2);
  --ds-button-pulse-ring-color: color-mix(in srgb, var(--ds-color-primary-500) 36%, transparent);
  --ds-button-pulse-shadow-start: 0 0 0 0 var(--ds-button-pulse-ring-color);
  --ds-button-pulse-shadow-end: 0 0 0 0.5rem transparent;
  --ds-button-attention-iteration-count: 1;

  /* ========================================================================
     TOUCH TARGETS
     Minimum touch target size for accessibility
     ======================================================================== */
  --ds-button-touch-target-min: 2.75rem;  /* 44px - WCAG AAA minimum */

  /* ========================================================================
     BORDERS
     Border width for different variants
     ======================================================================== */
  --ds-button-border-width: 1px;
  --ds-button-border-width-focus: 2px;

  /* ========================================================================
     SPINNER/LOADER
     Loading spinner settings
     ======================================================================== */
  --ds-button-spinner-size-xs: 0.75rem;
  --ds-button-spinner-size-sm: 1rem;
  --ds-button-spinner-size-md: 1.25rem;
  --ds-button-spinner-size-lg: 1.5rem;
  --ds-button-spinner-size-xl: 1.75rem;
  --ds-button-spinner-color: currentColor;
  --ds-button-spinner-track-opacity: 0.2;
  --ds-button-spinner-stroke-width: 2.5;
  --ds-button-spinner-duration: var(--ds-motion-attention);
}

}
@layer rottay-components {
/**
 * Input Component Tokens - Rottay Design System
 *
 * Design tokens specific to Input components (text inputs, textareas, etc).
 * Includes sizes, variants, states, and interactive properties.
 */

:root {
  /* ========================================================================
     SIZES - Input Dimensions
     Five size variants from xs to xl with corresponding properties
     ======================================================================== */

  /* XS - Extra Small */
  --ds-input-xs-height: 1.5rem;            /* 24px */
  --ds-input-xs-padding-x: 0.5rem;         /* 8px */
  --ds-input-xs-padding-y: 0.125rem;       /* 2px */
  --ds-input-xs-font-size: 0.75rem;        /* 12px */
  --ds-input-xs-line-height: 1.25rem;      /* 20px */
  --ds-input-xs-icon-size: 0.875rem;       /* 14px */
  --ds-input-xs-border-radius: var(--ds-radius-sm);

  /* SM - Small */
  --ds-input-sm-height: 2rem;              /* 32px */
  --ds-input-sm-padding-x: 0.625rem;       /* 10px */
  --ds-input-sm-padding-y: 0.25rem;        /* 4px */
  --ds-input-sm-font-size: 0.8125rem;      /* 13px */
  --ds-input-sm-line-height: 1.5rem;       /* 24px */
  --ds-input-sm-icon-size: 1rem;           /* 16px */
  --ds-input-sm-border-radius: var(--ds-radius-md);

  /* MD - Medium (Default) */
  --ds-input-md-height: 2.5rem;            /* 40px */
  --ds-input-md-padding-x: 0.75rem;        /* 12px */
  --ds-input-md-padding-y: 0.5rem;         /* 8px */
  --ds-input-md-font-size: 0.875rem;       /* 14px */
  --ds-input-md-line-height: 1.5rem;       /* 24px */
  --ds-input-md-icon-size: 1.25rem;        /* 20px */
  --ds-input-md-border-radius: var(--ds-radius-md);

  /* LG - Large */
  --ds-input-lg-height: 3rem;              /* 48px */
  --ds-input-lg-padding-x: 0.875rem;       /* 14px */
  --ds-input-lg-padding-y: 0.75rem;        /* 12px */
  --ds-input-lg-font-size: 1rem;           /* 16px */
  --ds-input-lg-line-height: 1.75rem;      /* 28px */
  --ds-input-lg-icon-size: 1.5rem;         /* 24px */
  --ds-input-lg-border-radius: var(--ds-radius-lg);

  /* XL - Extra Large */
  --ds-input-xl-height: 3.5rem;            /* 56px */
  --ds-input-xl-padding-x: 1rem;           /* 16px */
  --ds-input-xl-padding-y: 1rem;           /* 16px */
  --ds-input-xl-font-size: 1.125rem;       /* 18px */
  --ds-input-xl-line-height: 2rem;         /* 32px */
  --ds-input-xl-icon-size: 1.75rem;        /* 28px */
  --ds-input-xl-border-radius: var(--ds-radius-lg);

  /* Default size */
  --ds-input-default-height: var(--ds-input-md-height);
  --ds-input-default-padding-x: var(--ds-input-md-padding-x);
  --ds-input-default-padding-y: var(--ds-input-md-padding-y);
  --ds-input-default-font-size: var(--ds-input-md-font-size);

  /* Textarea specific */
  --ds-textarea-min-height: 6rem;       /* 96px */
  --ds-textarea-max-height: 24rem;      /* 384px */
  --textarea-min-height: var(--ds-textarea-min-height);
  --textarea-max-height: var(--ds-textarea-max-height);

  /* ========================================================================
     DEFAULT STATE - Base Appearance
     Default input styling
     ======================================================================== */
  --ds-input-bg: var(--ds-color-white);
  --ds-input-bg-hover: var(--ds-color-white);
  --ds-input-bg-focus: var(--ds-color-white);
  --ds-input-bg-disabled: var(--ds-color-neutral-50);

  --ds-input-color: var(--ds-color-neutral-900);
  --ds-input-color-placeholder: var(--ds-color-neutral-400);
  --ds-input-color-disabled: var(--ds-color-neutral-400);

  --ds-input-border-color: var(--ds-color-neutral-300);
  --ds-input-border-color-hover: var(--ds-color-neutral-400);
  --ds-input-border-color-focus: var(--ds-color-primary-500);
  --ds-input-border-color-disabled: var(--ds-color-neutral-200);

  /* Canonical runtime aliases. Kept separate from the legacy `*-color`
     names so BrandTheme/TenantTheme can override the complete control without
     an application selector. */
  --ds-input-border: var(--ds-input-border-color);
  --ds-input-border-hover: var(--ds-input-border-color-hover);
  --ds-input-border-focus: var(--ds-input-border-color-focus);
  --ds-input-border-disabled: var(--ds-input-border-color-disabled);

  --ds-input-border-width: 1px;
  --ds-input-border-width-focus: 2px;
  --ds-input-border-style: solid;
  --ds-input-radius: var(--ds-radius-input, var(--ds-radius-md));
  --ds-input-gap: var(--ds-input-affix-gap, var(--ds-spacing-2));
  --ds-input-message-gap: var(--ds-spacing-1);
  --ds-input-caret-color: var(--ds-input-border-focus);
  --ds-input-selection-bg: color-mix(in srgb, var(--ds-input-border-focus) 20%, transparent);
  --ds-input-selection-color: var(--ds-input-color);
  --ds-input-placeholder-opacity: 1;

  /* ========================================================================
     VARIANTS - Semantic States
     Success, warning, error variants
     ======================================================================== */

  /* Success variant */
  --ds-input-success-border-color: var(--ds-color-success-500);
  --ds-input-success-border-color-focus: var(--ds-color-success-600);
  --ds-input-success-shadow-focus: var(--ds-shadow-focus-ring-success);
  --ds-input-success-icon-color: var(--ds-color-success-500);
  --ds-input-success-border: var(--ds-input-success-border-color);
  --ds-input-success-bg: color-mix(in srgb, var(--ds-input-success-border) 4%, var(--ds-input-bg));

  /* Warning variant */
  --ds-input-warning-border-color: var(--ds-color-warning-500);
  --ds-input-warning-border-color-focus: var(--ds-color-warning-600);
  --ds-input-warning-shadow-focus: var(--ds-shadow-focus-ring-warning);
  --ds-input-warning-icon-color: var(--ds-color-warning-500);
  --ds-input-warning-border: var(--ds-input-warning-border-color);
  --ds-input-warning-bg: color-mix(in srgb, var(--ds-input-warning-border) 4%, var(--ds-input-bg));

  /* Error variant */
  --ds-input-error-border-color: var(--ds-color-error-500);
  --ds-input-error-border-color-focus: var(--ds-color-error-600);
  --ds-input-error-shadow-focus: var(--ds-shadow-focus-ring-error);
  --ds-input-error-icon-color: var(--ds-color-error-500);
  --ds-input-error-border: var(--ds-input-error-border-color);
  --ds-input-error-color: var(--ds-input-color);
  --ds-input-error-bg: color-mix(in srgb, var(--ds-input-error-border) 4%, var(--ds-input-bg));

  /* ========================================================================
     SHADOWS
     Focus and state shadows
     ======================================================================== */
  --ds-input-shadow-rest: var(--ds-shadow-input-rest);
  --ds-input-shadow-hover: var(--ds-input-shadow-rest);
  --ds-input-shadow-focus: var(--ds-shadow-input-focus);
  --ds-input-shadow-error-focus: var(--ds-shadow-input-error);

  /* ========================================================================
     ADDONS - Prefix/Suffix
     Settings for input addons and affixes
     ======================================================================== */
  --ds-input-addon-bg: var(--ds-color-neutral-50);
  --ds-input-addon-color: var(--ds-color-neutral-600);
  --ds-input-addon-border-color: var(--ds-color-neutral-300);
  --ds-input-addon-border: var(--ds-input-addon-border-color);
  --ds-input-addon-padding-x: 0.75rem;

  --ds-input-affix-gap: 0.5rem;            /* Gap between affix and input text */
  --ds-input-affix-color: var(--ds-color-neutral-500);
  --ds-input-affix-size: var(--ds-input-md-icon-size);
  --ds-input-affix-size-compact: var(--ds-input-sm-icon-size);
  --ds-input-affix-padding-x: 0;
  --ds-input-affix-bg: transparent;
  --ds-input-affix-border: 0 solid transparent;
  --ds-input-affix-radius: var(--ds-radius-sm);

  /* ========================================================================
     ICONS - Prefix/Suffix Icons
     Settings for icons inside inputs
     ======================================================================== */
  --ds-input-icon-color: var(--ds-color-neutral-500);
  --ds-input-icon-color-hover: var(--ds-color-neutral-600);
  --ds-input-icon-gap: 0.5rem;

  /* ========================================================================
     CLEAR BUTTON
     Settings for the clear button (x icon)
     ======================================================================== */
  --ds-input-clear-size: 1rem;
  --ds-input-clear-color: var(--ds-color-neutral-400);
  --ds-input-clear-color-hover: var(--ds-color-neutral-600);
  --ds-input-clear-bg-hover: var(--ds-color-neutral-100);
  --ds-input-clear-bg: transparent;
  --ds-input-clear-border: 1px solid transparent;
  --ds-input-clear-border-hover: var(--ds-input-border);
  --ds-input-action-shadow-hover: none;
  --ds-input-action-focus-ring: var(--ds-focus-ring);
  --ds-input-clear-radius: var(--ds-radius-full);
  --ds-input-action-size: var(--ds-input-md-icon-size);
  --ds-input-action-radius: var(--ds-input-clear-radius);
  --ds-input-action-active-transform: scale(0.94);
  --ds-input-touch-target-min: 2.75rem;

  /* Loading */
  --ds-input-loading-size: var(--ds-input-md-icon-size);
  --ds-input-loading-stroke: 2;
  --ds-input-loading-color: var(--ds-input-border-focus);
  --ds-input-loading-duration: 720ms;

  /* ========================================================================
     PASSWORD TOGGLE
     Settings for password visibility toggle
     ======================================================================== */
  --ds-input-password-toggle-size: 1.25rem;
  --ds-input-password-toggle-color: var(--ds-color-neutral-500);
  --ds-input-password-toggle-color-hover: var(--ds-color-neutral-700);

  /* ========================================================================
     CHARACTER COUNT
     Settings for character counter
     ======================================================================== */
  --ds-input-count-color: var(--ds-color-neutral-500);
  --ds-input-count-color-warning: var(--ds-color-warning-600);
  --ds-input-count-color-error: var(--ds-color-error-600);
  --ds-input-count-font-size: var(--ds-font-size-sm);
  --ds-input-count-margin-top: 0.25rem;

  /* ========================================================================
     LABEL
     Settings for input labels
     ======================================================================== */
  --ds-input-label-color: var(--ds-color-neutral-700);
  --ds-input-label-color-disabled: var(--ds-color-neutral-400);
  --ds-input-label-font-size: var(--ds-font-size-sm);
  --ds-input-label-font-weight: var(--ds-font-weight-medium);
  --ds-input-label-margin-bottom: 0.375rem;
  --ds-input-label-required-color: var(--ds-color-error-500);

  /* ========================================================================
     HELPER TEXT
     Settings for helper/description text
     ======================================================================== */
  --ds-input-helper-color: var(--ds-color-neutral-600);
  --ds-input-helper-font-size: var(--ds-font-size-sm);
  --ds-input-helper-margin-top: 0.25rem;
  --ds-input-helper-line-height: var(--ds-line-height-snug);

  /* ========================================================================
     ERROR MESSAGE
     Settings for error message text
     ======================================================================== */
  --ds-input-error-message-color: var(--ds-color-error-600);
  --ds-input-error-message-font-size: var(--ds-font-size-sm);
  --ds-input-error-message-margin-top: 0.25rem;
  --ds-input-error-message-icon-size: 1rem;
  --ds-input-error-message-font-weight: var(--ds-font-weight-medium);

  /* ========================================================================
     SUCCESS MESSAGE
     Settings for success message text
     ======================================================================== */
  --ds-input-success-message-color: var(--ds-color-success-600);
  --ds-input-success-message-font-size: var(--ds-font-size-sm);
  --ds-input-success-message-margin-top: 0.25rem;

  /* ========================================================================
     GROUP/COMPACT
     Settings for input groups
     ======================================================================== */
  --ds-input-group-gap: 0;
  --ds-input-group-gap-separated: var(--ds-spacing-2);
  --ds-input-group-overlap: -1px;
  --ds-input-group-min-item-width: 12rem;
  --ds-input-group-border-radius-first: var(--ds-radius-md) 0 0 var(--ds-radius-md);
  --ds-input-group-border-radius-last: 0 var(--ds-radius-md) var(--ds-radius-md) 0;
  --ds-input-group-border-radius-middle: 0;

  /* ========================================================================
     SEARCH INPUT
     Specific settings for search inputs
     ======================================================================== */
  --ds-input-search-icon-color: var(--ds-color-neutral-500);
  --ds-input-search-clear-color: var(--ds-color-neutral-400);

  /* ========================================================================
     NUMBER INPUT
     Specific settings for number inputs
     ======================================================================== */
  --ds-input-number-controls-width: 1.5rem;
  --ds-input-number-controls-bg: var(--ds-color-neutral-50);
  --ds-input-number-controls-bg-hover: var(--ds-color-neutral-100);
  --ds-input-number-controls-color: var(--ds-color-neutral-600);
  --ds-input-number-controls-border-color: var(--ds-color-neutral-300);

  /* ========================================================================
     FILE INPUT
     Specific settings for file inputs
     ======================================================================== */
  --ds-input-file-button-bg: var(--ds-color-neutral-100);
  --ds-input-file-button-bg-hover: var(--ds-color-neutral-200);
  --ds-input-file-button-color: var(--ds-color-neutral-700);
  --ds-input-file-button-padding: 0.5rem 1rem;

  /* ========================================================================
     TRANSITIONS
     Animation timing for state changes
     ======================================================================== */
  --ds-input-transition-duration: 0.2s;
  --ds-input-transition-timing: ease-in-out;
  --ds-input-transition: all var(--ds-input-transition-duration) var(--ds-input-transition-timing);

  /* FormField composition */
  --ds-form-field-gap: var(--ds-input-label-margin-bottom);
  --ds-form-field-horizontal-gap: var(--ds-spacing-4);
  --ds-form-field-label-offset-y: 0;
  --ds-form-field-required-gap: 0.25em;
  --ds-form-field-disabled-opacity: var(--ds-input-disabled-opacity);

  /* Textarea composition */
  --ds-textarea-padding-x: var(--ds-input-md-padding-x);
  --ds-textarea-padding-y: var(--ds-input-md-padding-y);
  --ds-textarea-radius: var(--ds-radius-input);
  --ds-textarea-resize: vertical;

  /* ========================================================================
     TYPOGRAPHY
     Font settings for input text
     ======================================================================== */
  --ds-input-font-family: var(--ds-font-family-base);
  --ds-input-font-weight: var(--ds-font-weight-normal);
  --ds-input-letter-spacing: normal;

  /* ========================================================================
     DISABLED STATE
     Appearance when disabled
     ======================================================================== */
  --ds-input-disabled-opacity: 0.6;
  --ds-input-disabled-cursor: not-allowed;

  /* ========================================================================
     READ-ONLY STATE
     Appearance when read-only
     ======================================================================== */
  --ds-input-readonly-bg: var(--ds-color-neutral-50);
  --ds-input-readonly-color: var(--ds-input-color);
  --ds-input-readonly-border: var(--ds-input-border);
  --ds-input-readonly-cursor: default;
  --ds-input-readonly-border-style: dashed;

  /* ========================================================================
     AUTOFILL
     Browser autofill appearance
     ======================================================================== */
  --ds-input-autofill-bg: var(--ds-color-primary-50);
  --ds-input-autofill-color: var(--ds-color-neutral-900);
  --ds-input-autofill-caret: var(--ds-input-caret-color);
}

}
@layer rottay-components {
/**
 * Card Component Tokens - Rottay Design System
 *
 * Design tokens specific to the Card component.
 * Includes sizes, variants, states, and compositional properties.
 */

:root {
  /* ========================================================================
     SIZES - Card Padding Variants
     Three size variants for different card densities
     ======================================================================== */
  --ds-card-sm-padding: 0.75rem; /* 12px */
  --ds-card-md-padding: 1rem; /* 16px - Default */
  --ds-card-lg-padding: 1.5rem; /* 24px */
  --ds-card-xl-padding: 2rem; /* 32px */

  --ds-card-default-padding: var(--ds-card-md-padding);

  /* ========================================================================
     BACKGROUND & COLORS
     Base appearance for cards
     ======================================================================== */
  --ds-card-bg: var(--ds-color-white);
  --ds-card-bg-hover: var(--ds-color-neutral-50);
  --ds-card-bg-active: var(--ds-color-neutral-100);
  --ds-card-bg-selected: color-mix(
    in srgb,
    var(--ds-color-primary) 8%,
    var(--ds-card-bg)
  );
  --ds-card-bg-disabled: var(--ds-color-neutral-50);

  --ds-card-color: var(--ds-color-neutral-900);
  --ds-card-color-hover: var(--ds-card-color);
  --ds-card-color-active: var(--ds-card-color);
  --ds-card-color-selected: var(--ds-card-color);
  --ds-card-color-disabled: var(--ds-color-text-disabled);
  --ds-card-color-muted: var(--ds-color-neutral-600);

  /* ========================================================================
     BORDERS
     Border styling for cards
     ======================================================================== */
  --ds-card-border-width: 1px;
  --ds-card-border-color: var(--ds-color-neutral-200);
  --ds-card-border-color-hover: var(--ds-color-neutral-300);
  --ds-card-border-color-active: var(--ds-card-border-color-hover);
  --ds-card-border-color-selected: color-mix(
    in srgb,
    var(--ds-color-primary) 52%,
    var(--ds-card-border-color)
  );
  --ds-card-border-color-disabled: color-mix(
    in srgb,
    var(--ds-card-border-color) 58%,
    transparent
  );
  --ds-card-border-active: var(--ds-card-border-color-active);
  --ds-card-border-selected: var(--ds-card-border-color-selected);
  --ds-card-border-disabled: var(--ds-card-border-color-disabled);
  --ds-card-border-style: solid;
  --ds-card-border-radius: var(--ds-radius-lg);
  --ds-card-radius: var(--ds-card-border-radius);
  --ds-card-radius-sm: var(--ds-radius-sm);
  --ds-card-radius-lg: var(--ds-radius-xl);
  --ds-card-radius-xl: var(--ds-radius-2xl);

  /* Borderless variant */
  --ds-card-borderless-border-width: 0;

  /* ========================================================================
     SHADOWS
     Elevation levels for cards
     ======================================================================== */
  --ds-card-shadow-none: none;
  --ds-card-shadow-sm: var(--ds-shadow-sm);
  --ds-card-shadow-md: var(--ds-shadow-md);
  --ds-card-shadow-lg: var(--ds-shadow-lg);
  --ds-card-shadow-xl: var(--ds-shadow-xl);

  /* Interactive shadows */
  --ds-card-shadow-hover: var(--ds-shadow-card-hover);
  --ds-card-shadow-active: var(--ds-shadow-card-active);
  --ds-card-shadow-selected: var(--ds-shadow-focus-ring);

  /* Default shadow */
  --ds-card-shadow-default: var(--ds-card-shadow-sm);

  /* ========================================================================
     HEADER
     Card header section styling
     ======================================================================== */
  --ds-card-header-padding: var(--ds-card-default-padding);
  --ds-card-header-padding-sm: var(--ds-spacing-3)
    var(--ds-spacing-4);
  --ds-card-header-padding-lg: var(--ds-spacing-5)
    var(--ds-spacing-6);
  --ds-card-header-gap: var(--ds-spacing-3);
  --ds-card-header-padding-bottom: calc(var(--ds-card-default-padding) * 0.75);
  --ds-card-header-border-width: 1px;
  --ds-card-header-border-color: var(--ds-color-neutral-200);
  --ds-card-header-bg: transparent;
  --ds-card-header-min-height: 4rem;
  --ds-card-header-copy-max-width: 68ch;
  --ds-card-header-eyebrow-size: 0.625rem;
  --ds-card-header-eyebrow-tracking: 0.11em;
  --ds-card-header-icon-size: 2.25rem;
  --ds-card-header-icon-radius: var(--ds-radius-lg);
  --ds-card-header-icon-bg: var(
    --ds-surface-icon-bg,
    color-mix(in srgb, var(--ds-color-primary) 9%, var(--ds-card-bg))
  );
  --ds-card-header-icon-border: color-mix(
    in srgb,
    var(--ds-color-primary) 20%,
    var(--ds-card-border-color)
  );
  --ds-card-header-icon-color: var(--ds-color-primary);
  --ds-card-header-extra-bg: color-mix(
    in srgb,
    var(--ds-card-bg) 94%,
    var(--ds-color-primary)
  );
  --ds-card-header-extra-border: var(--ds-card-header-border-color);
  --ds-card-header-extra-radius: var(--ds-radius-lg);
  --ds-card-header-extra-padding: 3px;

  /* Header title */
  --ds-card-title-font-size: var(--ds-font-size-lg);
  --ds-card-title-font-weight: var(--ds-font-weight-semibold);
  --ds-card-title-line-height: var(--ds-line-height-tight);
  --ds-card-title-letter-spacing: var(--ds-letter-spacing-heading);
  --ds-card-title-color: var(--ds-color-neutral-900);

  /* Header subtitle */
  --ds-card-subtitle-font-size: var(--ds-font-size-sm);
  --ds-card-subtitle-color: var(--ds-color-neutral-600);
  --ds-card-subtitle-margin-top: 0.25rem;

  /* Header actions */
  --ds-card-header-actions-gap: 0.5rem;

  /* ========================================================================
     BODY
     Card content area styling
     ======================================================================== */
  --ds-card-body-padding: var(--ds-card-default-padding);
  --ds-card-body-padding-sm: var(--ds-spacing-3)
    var(--ds-spacing-4);
  --ds-card-body-padding-lg: var(--ds-spacing-5)
    var(--ds-spacing-6);
  --ds-card-body-color: var(--ds-color-neutral-700);
  --ds-card-body-font-size: var(--ds-font-size-base);
  --ds-card-body-line-height: var(--ds-line-height-normal);

  /* ========================================================================
     FOOTER
     Card footer section styling
     ======================================================================== */
  --ds-card-footer-padding: var(--ds-card-default-padding);
  --ds-card-footer-padding-sm: var(--ds-spacing-3)
    var(--ds-spacing-4);
  --ds-card-footer-padding-lg: var(--ds-spacing-5)
    var(--ds-spacing-6);
  --ds-card-footer-padding-top: calc(var(--ds-card-default-padding) * 0.75);
  --ds-card-footer-border-width: 1px;
  --ds-card-footer-border-color: var(--ds-color-neutral-200);
  --ds-card-footer-bg: transparent;
  --ds-card-footer-color: var(--ds-color-neutral-600);

  /* Footer actions */
  --ds-card-footer-actions-gap: 0.5rem;
  --ds-card-footer-actions-justify: flex-end;
  --ds-card-actions-gap: var(--ds-spacing-2);
  --ds-card-actions-margin-top: var(--ds-spacing-4);
  --ds-card-actions-padding-top: var(--ds-spacing-4);

  /* ========================================================================
     MEDIA/IMAGE
     Card image and media styling
     ======================================================================== */
  --ds-card-media-border-radius-top: var(--ds-card-border-radius);
  --ds-card-media-border-radius-bottom: 0;
  --ds-card-media-aspect-ratio: 16 / 9;
  --ds-card-media-object-fit: cover;
  --ds-card-image-height: 12.5rem;

  /* Cover variant (full background image) */
  --ds-card-cover-min-height: 12rem; /* 192px */
  --ds-card-cover-overlay-bg: linear-gradient(
