  );
  --ds-card-cover-content-color: var(--ds-color-white);
  --ds-card-cover-inline-size: 12rem;
  --ds-card-cover-inline-min-size: 9rem;
  --ds-card-cover-block-min-size: 10rem;
  --ds-card-cover-aspect-ratio: var(--ds-card-media-aspect-ratio);
  --ds-card-cover-object-position: center;
  --ds-card-cover-object-fit: cover;
  --ds-card-body-inline-min-size: 16rem;

  /* Image loading/error anatomy */
  --ds-card-image-loading-track: var(--ds-color-neutral-200);
  --ds-card-image-loading-active: var(--ds-color-primary);
  --ds-card-image-loading-size: 2.5rem;
  --ds-card-image-loading-stroke: 3px;
  --ds-card-image-loading-duration: var(--ds-motion-glacial);
  --ds-card-image-error-icon-size: 3rem;

  /* Root loading anatomy */
  --ds-card-spinner-size: 1.5rem;
  --ds-card-spinner-stroke: 2px;
  --ds-card-spinner-track: var(--ds-color-border);
  --ds-card-spinner-color: var(--ds-color-primary);
  --ds-card-spinner-duration: var(--ds-motion-glacial);

  /* ========================================================================
     VARIANTS
     Different card visual styles
     ======================================================================== */

  /* Default variant */
  --ds-card-default-bg: var(--ds-card-bg);
  --ds-card-default-border-color: var(--ds-card-border-color);
  --ds-card-default-shadow: var(--ds-card-shadow-default);

  /* Bordered variant (emphasized border, no shadow) */
  --ds-card-bordered-bg: var(--ds-card-bg);
  --ds-card-bordered-border-width: var(--ds-card-border-width);
  --ds-card-bordered-border-color: var(--ds-card-border, var(--ds-card-border-color));
  --ds-card-bordered-shadow: none;

  /* Flat variant (no border, no shadow) */
  --ds-card-flat-bg: var(--ds-surface-panel, var(--ds-card-bg));
  --ds-card-flat-border-width: 0;
  --ds-card-flat-shadow: none;

  /* Elevated variant (strong shadow, no border) */
  --ds-card-elevated-bg: var(--ds-card-bg);
  --ds-card-elevated-border-width: 0;
  --ds-card-elevated-shadow: var(--ds-card-shadow, var(--ds-card-shadow-md));
  --ds-card-elevated-shadow-hover: var(--ds-card-shadow-hover, var(--ds-card-shadow-lg));

  /* Ghost variant (transparent background) */
  --ds-card-ghost-bg: transparent;
  --ds-card-ghost-border-color: var(--ds-color-neutral-200);
  --ds-card-ghost-shadow: none;

  /* ========================================================================
     INTERACTIVE STATES
