  --ds-card-focus-ring-color: var(--ds-focus-ring-color);
  --ds-card-focus-ring-width: var(--ds-focus-ring-width);
  --ds-card-focus-ring-offset: 2px;
  --ds-card-selected-outline-width: var(--ds-card-border-width);
  --ds-card-focus-outline: none;

  /* ========================================================================
     DISABLED STATE
     Appearance when disabled
     ======================================================================== */
  --ds-card-disabled-opacity: 0.5;
  --ds-card-disabled-cursor: not-allowed;
  --ds-card-disabled-bg: var(--ds-card-bg-disabled);
}

.ds-card {
  position: relative;
  isolation: isolate;
}

.ds-card.ds-card--modern::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  border-radius: inherit;
  background-image: var(--ds-card-texture), var(--ds-card-overlay);
  background-size: var(--ds-card-texture-size), auto;
  opacity: var(--ds-card-texture-opacity);
  mask-image: linear-gradient(
    180deg,
    var(--ds-color-text-primary),
    transparent 86%
  );
}

.ds-card.ds-card--modern[data-variant='ghost']::before,
[data-anatomy-card='ghost'] .ds-card.ds-card--modern::before {
  opacity: 0;
}

@media (forced-colors: active) {
  .ds-card.ds-card--modern::before {
    display: none;
  }
}

.ds-card > * {
  position: relative;
  z-index: 1;
}

.ds-card--interactive {
  transition: var(--ds-premium-card-transition);
}

