  /* Success modal */
  --ds-modal-success-icon-color: var(--ds-color-success-500);
  --ds-modal-success-icon-bg: var(--ds-color-success-100);

  /* Warning modal */
  --ds-modal-warning-icon-color: var(--ds-color-warning-500);
  --ds-modal-warning-icon-bg: var(--ds-color-warning-100);

  /* Error/Destructive modal */
  --ds-modal-error-icon-color: var(--ds-color-error-500);
  --ds-modal-error-icon-bg: var(--ds-color-error-100);

  /* Info modal */
  --ds-modal-info-icon-color: var(--ds-color-info-500);
  --ds-modal-info-icon-bg: var(--ds-color-info-100);

  /* ========================================================================
     ICON
