  --ds-select-lg-height: 3rem;              /* 48px */
  --ds-select-lg-font-size: 1rem;           /* 16px */
  --ds-select-lg-padding: 0 0.875rem;       /* 0 14px */
  --ds-select-lg-padding-x: 0.875rem;       /* 14px */
  --ds-select-lg-icon-size: 1.25rem;        /* 20px */
  --ds-select-lg-border-radius: var(--ds-radius-lg);

  /* XL - Extra Large */
  --ds-select-xl-height: 3.5rem;            /* 56px */
  --ds-select-xl-font-size: 1.125rem;       /* 18px */
  --ds-select-xl-padding: 0 1rem;           /* 0 16px */
  --ds-select-xl-padding-x: 1rem;           /* 16px */
  --ds-select-xl-icon-size: 1.5rem;         /* 24px */
  --ds-select-xl-border-radius: var(--ds-radius-lg);

  /* Default size */
  --ds-select-default-height: var(--ds-select-md-height);
  --ds-select-default-font-size: var(--ds-select-md-font-size);
  --ds-select-default-padding: var(--ds-select-md-padding);
  --ds-select-default-padding-x: var(--ds-select-md-padding-x);

  /* ========================================================================
     DEFAULT STATE - Base Appearance
     Default select styling
     ======================================================================== */
  /* Derived, not white. `--ds-surface-control` is declared on the same element
     by the tenant scope, and a var() reference resolves against the computed
     value regardless of rule order, so this follows the tenant. A literal here
     outranked the tenant for every customer that did not hand-write a select
     colour into its artifact, which is all of them. */
  --ds-select-bg: var(--ds-surface-control, var(--ds-color-bg-input, var(--ds-color-white)));
  --ds-select-bg-hover: var(--ds-surface-control, var(--ds-color-bg-input, var(--ds-color-white)));
  --ds-select-bg-focus: var(--ds-surface-control, var(--ds-color-bg-input, var(--ds-color-white)));
  --ds-select-bg-disabled: var(--ds-color-neutral-50);

  --ds-select-color: var(--ds-color-neutral-900);
  --ds-select-color-placeholder: var(--ds-color-neutral-400);
  --ds-select-color-disabled: var(--ds-color-neutral-400);

  --ds-select-border-color: var(--ds-color-neutral-300);
  --ds-select-border-color-hover: var(--ds-color-neutral-400);
  --ds-select-border-color-focus: var(--ds-color-primary-500);
  --ds-select-border-color-disabled: var(--ds-color-neutral-200);

  --ds-select-border-width: 1px;
  --ds-select-border-style: solid;

  /* ========================================================================
     VARIANTS - Visual Styles
     Outline, filled, flushed variants
     ======================================================================== */

  /* Outline variant (default) */
  --ds-select-outline-bg: transparent;
  --ds-select-outline-border-color: var(--ds-color-neutral-300);

  /* Filled variant */
  --ds-select-filled-bg: var(--ds-color-neutral-100);
  --ds-select-filled-bg-hover: var(--ds-color-neutral-200);
  --ds-select-filled-border-color: transparent;

  /* Flushed variant */
  --ds-select-flushed-border-radius: 0;
  --ds-select-flushed-border-width: 0 0 1px 0;

  /* ========================================================================
     STATUS VARIANTS - Semantic States
     Success, warning, error status
     ======================================================================== */

  /* Success status */
  --ds-select-success-border-color: var(--ds-color-success-500);
  --ds-select-success-border-color-focus: var(--ds-color-success-600);
  --ds-select-success-shadow-focus: var(--ds-shadow-focus-ring-success);

  /* Warning status */
  --ds-select-warning-border-color: var(--ds-color-warning-500);
  --ds-select-warning-border-color-focus: var(--ds-color-warning-600);
  --ds-select-warning-shadow-focus: var(--ds-shadow-focus-ring-warning);

  /* Error status */
  --ds-select-error-border-color: var(--ds-color-error-500);
  --ds-select-error-border-color-focus: var(--ds-color-error-600);
  --ds-select-error-shadow-focus: var(--ds-shadow-focus-ring-error);

  /* ========================================================================
     DROPDOWN - Dropdown Panel Styling
     Settings for the dropdown panel
     ======================================================================== */
  --ds-select-dropdown-bg: var(--ds-color-white);
  --ds-select-dropdown-border-color: var(--ds-color-neutral-200);
  --ds-select-dropdown-border-radius: var(--ds-radius-md);
  --ds-select-dropdown-shadow: var(--ds-shadow-lg);
  --ds-select-dropdown-max-height: 16rem;   /* 256px */
  --ds-select-dropdown-padding: 0.25rem;    /* 4px */
  --ds-select-dropdown-z-index: 1050;

  /* ========================================================================
     OPTION - Option Item Styling
     Settings for individual options
     ======================================================================== */
  --ds-select-option-height: 2.25rem;       /* 36px */
  --ds-select-option-padding: 0.5rem 0.75rem;
  --ds-select-option-font-size: 0.875rem;   /* 14px */
  --ds-select-option-border-radius: var(--ds-radius-sm);

  --ds-select-option-bg: transparent;
  --ds-select-option-bg-hover: var(--ds-color-neutral-100);
  --ds-select-option-bg-selected: var(--ds-color-primary-50);
  --ds-select-option-bg-focused: var(--ds-color-neutral-100);
  --ds-select-option-bg-disabled: transparent;

  --ds-select-option-color: var(--ds-color-neutral-900);
  --ds-select-option-color-selected: var(--ds-color-primary-700);
  --ds-select-option-color-disabled: var(--ds-color-neutral-400);

  /* ========================================================================
     ICONS - Arrow and Clear Icons
     Settings for select icons
     ======================================================================== */
  --ds-select-arrow-color: var(--ds-color-neutral-500);
  --ds-select-arrow-color-hover: var(--ds-color-neutral-700);
  --ds-select-arrow-size: 1rem;
  --ds-select-arrow-transition: transform 0.2s ease;

  --ds-select-clear-color: var(--ds-color-neutral-400);
  --ds-select-clear-color-hover: var(--ds-color-neutral-600);
  --ds-select-clear-size: 0.875rem;
  --ds-select-clear-bg-hover: var(--ds-color-neutral-100);
  --ds-select-clear-radius: var(--ds-radius-full);

  /* ========================================================================
     MULTIPLE/TAGS - Multi-select Styling
     Settings for multiple selection mode
     ======================================================================== */
  --ds-select-tag-height: 1.5rem;           /* 24px */
  --ds-select-tag-padding: 0 0.5rem;        /* 0 8px */
  --ds-select-tag-font-size: 0.75rem;       /* 12px */
  --ds-select-tag-border-radius: var(--ds-radius-sm);
  --ds-select-tag-bg: var(--ds-color-neutral-100);
  --ds-select-tag-color: var(--ds-color-neutral-700);
  --ds-select-tag-gap: 0.25rem;             /* 4px */

  --ds-select-tag-close-size: 0.75rem;      /* 12px */
  --ds-select-tag-close-color: var(--ds-color-neutral-500);
  --ds-select-tag-close-color-hover: var(--ds-color-neutral-700);

  /* ========================================================================
     SEARCH - Search Input in Dropdown
     Settings for searchable selects
     ======================================================================== */
  --ds-select-search-bg: var(--ds-color-white);
  --ds-select-search-border-color: var(--ds-color-neutral-200);
  --ds-select-search-padding: 0.5rem 0.75rem;
  --ds-select-search-margin: 0.25rem;

  /* ========================================================================
     LOADING - Loading State
     Settings for loading spinner
     ======================================================================== */
  --ds-select-loading-size: 1rem;
  --ds-select-loading-color: var(--ds-color-primary-500);

  /* ========================================================================
     EMPTY - Empty State
     Settings for no options state
     ======================================================================== */
  --ds-select-empty-padding: 1rem;
  --ds-select-empty-color: var(--ds-color-neutral-500);
  --ds-select-empty-font-size: 0.875rem;

  /* ========================================================================
     GROUP - Option Groups
     Settings for grouped options
     ======================================================================== */
  --ds-select-group-label-padding: 0.5rem 0.75rem;
  --ds-select-group-label-font-size: 0.75rem;
  --ds-select-group-label-font-weight: var(--ds-font-weight-semibold);
  --ds-select-group-label-color: var(--ds-color-neutral-500);
  --ds-select-group-label-text-transform: uppercase;
  --ds-select-group-divider-color: var(--ds-color-neutral-200);

  /* ========================================================================
     TRANSITIONS
     Animation timing for state changes
     ======================================================================== */
  --ds-select-transition-duration: 0.2s;
  --ds-select-transition-timing: ease-in-out;
  --ds-select-transition: all var(--ds-select-transition-duration) var(--ds-select-transition-timing);

  /* ========================================================================
     DISABLED STATE
     Appearance when disabled
     ======================================================================== */
  --ds-select-disabled-opacity: 0.6;
  --ds-select-disabled-cursor: not-allowed;
}

