@keyframes ds-surface-enter {
  from {
    opacity: 0;
    transform: translateY(6px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes ds-meter-sweep {
  from {
    transform: translateX(-100%);
  }

  to {
    transform: translateX(100%);
  }
}

@keyframes ds-command-home-spin {
  to {
    transform: rotate(360deg);
  }
}

:where(.ds-workspace-frame) {
  position: relative;
  isolation: isolate;
  width: 100%;
  max-width: 100%;
  overflow: hidden;
  border-radius: var(--ds-radius-md);
  color: var(--ds-color-text-primary);
  font-family: var(--ds-font-family-base);
  animation: ds-surface-enter var(--ds-motion-reveal)
    var(--ds-motion-ease-enter) both;
}

:where(.ds-workspace-frame--list) {
  --ds-workspace-shell-bg: linear-gradient(
    180deg,
    var(--ds-surface-card-bg) 0%,
    var(--ds-surface-canvas, var(--ds-surface-panel-bg)) 50%,
    color-mix(in srgb, var(--ds-color-primary) 4%, var(--ds-surface-panel-bg))
      100%
  );
}

:where(.ds-workspace-frame--detail) {
  --ds-workspace-shell-overlay: linear-gradient(
    180deg,
    color-mix(in srgb, var(--ds-color-primary) 5.5%, transparent) 0%,
    transparent 44%,
    color-mix(
        in srgb,
        var(--ds-color-secondary, var(--ds-color-primary)) 7%,
        transparent
      )
      100%
  );
}

:where(.ds-workspace-frame--form) {
  overflow: visible;
  --ds-workspace-shell-bg: linear-gradient(
    180deg,
    var(--ds-surface-card-bg) 0%,
    var(--ds-surface-canvas, var(--ds-surface-panel-bg)) 46%,
    color-mix(in srgb, var(--ds-color-primary) 5%, var(--ds-surface-panel-bg))
      100%
  );
}

:where(.ds-workspace-frame)::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

:where(.ds-workspace-frame__inner) {
  position: relative;
  z-index: 1;
}

:where(.ds-workspace-frame) > :not(:where(.ds-workspace-frame__inner)) {
  position: relative;
  z-index: 1;
}

:where(.ds-workspace-frame--loading) {
  min-height: min(720px, calc(100vh - 64px));
}

:where(.ds-workspace-grid) {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(
      280px,
      var(--ds-workflow-rail-width, 360px)
    );
  gap: clamp(20px, 2.2vw, 32px);
  width: 100%;
}

:where(.ds-workspace-grid__main, .ds-workspace-grid__rail) {
  min-width: 0;
}

:where(.ds-command-grid) {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: var(--ds-command-grid-opacity, 0.18);
}

:where(
    .ds-surface-hero,
    .ds-surface-card,
    .ds-surface-rail-card,
    .ds-surface-table-card,
    .ds-rich-card,
    .ds-metric-card,
    .ds-stat-card
  ) {
  color: var(--ds-surface-card-color);
}

:where(.ds-surface-panel) {
  color: var(--ds-surface-panel-color);
}

:where(.ds-surface-control-row) {
  color: var(--ds-surface-control-color);
}

:where(.ds-surface-hero) {
  position: relative;
  overflow: hidden;
  border-radius: var(--ds-radius-md);
}

:where(.ds-surface-card, .ds-surface-rail-card) {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: var(--ds-radius-md);
  animation: ds-surface-enter var(--ds-motion-reveal)
    var(--ds-motion-ease-enter) both;
  transition: var(--ds-premium-card-transition),
    filter var(--ds-motion-feedback) var(--ds-motion-ease-enter);
}

:where(.ds-surface-card, .ds-surface-rail-card)::before,
:where(.ds-surface-table-card)::before,
:where(.ds-rich-card)::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: 0.28;
  mask-image: linear-gradient(
    180deg,
    var(--ds-color-text-primary),
    transparent 82%
  );
  transition: opacity var(--ds-motion-feedback) var(--ds-motion-ease-enter);
}

:where(.ds-surface-card, .ds-surface-rail-card)::after,
:where(.ds-surface-table-card)::after,
:where(.ds-rich-card)::after {
  content: none;
}

:where(
    .ds-surface-card,
    .ds-surface-rail-card,
    .ds-surface-table-card,
    .ds-rich-card
  )
  > * {
  position: relative;
  z-index: 2;
}

:where(.ds-surface-card, .ds-surface-rail-card):is(
    a,
    button,
    [role="button"],
    [data-interactive="true"]
  ):hover {
  transform: translateY(-1px);
  filter: saturate(1.01);
}

:where(.ds-surface-card, .ds-surface-rail-card):is(
    a,
    button,
    [role="button"],
    [data-interactive="true"]
  ):hover::before {
  opacity: 0.42;
}

:where(.ds-surface-card, .ds-surface-rail-card):is(
    a,
    button,
    [role="button"],
    [data-interactive="true"]
  ):active {
  transform: translateY(0);
  filter: saturate(1);
}

:where(.ds-surface-card, .ds-surface-rail-card):is(
    [aria-disabled="true"],
    [data-disabled="true"]
  ) {
  pointer-events: none;
  filter: saturate(0.72);
}

:where(.ds-surface-panel) {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: var(--ds-radius-sm);
  transition: border-color var(--ds-motion-feedback)
