:where(.ds-rich-card) {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  color: var(--ds-color-text-primary);
  border-radius: var(--ds-radius-md);
  animation: ds-surface-enter var(--ds-motion-reveal)
    var(--ds-motion-ease-enter) both;
  transition: border-color var(--ds-motion-feedback)
      var(--ds-motion-ease-enter),
    box-shadow var(--ds-motion-feedback) var(--ds-motion-ease-enter),
    transform var(--ds-motion-feedback) var(--ds-motion-ease-enter),
    filter var(--ds-motion-feedback) var(--ds-motion-ease-enter);
