:where(.ds-rich-card__header) {
  position: relative;
  overflow: hidden;
}

:where(.ds-rich-card__icon) {
  border-radius: var(--ds-radius-md);
  color: var(--ds-color-primary);
  transition: border-color var(--ds-motion-feedback)
