}

@container (max-width: 900px) {
  .ds-pattern-record-facts .ds-record-facts__grid {
    grid-template-columns: repeat(12, minmax(0, 1fr));
  }

  /* Preserve the caller's deliberate 6+3+3 and 4+4+4 compositions. Flattening
     every fact to 6 columns created half-empty final rows for odd item counts. */
  .ds-pattern-record-facts .ds-record-facts__fact[data-span="1"],
  .ds-pattern-record-facts .ds-record-facts__fact[data-span="2"] {
    grid-column: span 3;
  }

