  .ds-pattern-record-facts .ds-record-facts__fact[data-span="8"],
  .ds-pattern-record-facts .ds-record-facts__fact[data-span="9"],
  .ds-pattern-record-facts .ds-record-facts__fact[data-span="10"],
  .ds-pattern-record-facts .ds-record-facts__fact[data-span="11"],
  .ds-pattern-record-facts .ds-record-facts__fact[data-span="12"],
  .ds-pattern-record-facts .ds-record-facts__fact[data-span="full"] {
    grid-column: span 12;
  }
}

@container (max-width: 560px) {
  .ds-pattern-record-facts .ds-record-facts__header {
    align-items: flex-start;
    padding: 13px 14px;
