.ds-pattern-widget-board .ds-widget-board__grid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  grid-auto-rows: 8px;
  grid-auto-flow: dense;
  align-items: start;
  column-gap: var(--ds-spacing-4, 16px);
  row-gap: var(--ds-spacing-2, 8px);
  width: 100%;
  min-width: 0;
}

.ds-pattern-widget-board .ds-widget-board__grid[data-narrow="true"] {
  grid-template-columns: minmax(0, 1fr);
  gap: var(--ds-spacing-3, 12px);
}

.ds-pattern-widget-board
  .ds-widget-board__grid[data-narrow="true"]
  > .ds-widget-board__cell {
  grid-column: 1 / -1;
}

.ds-pattern-widget-board .ds-widget-board__cell {
  position: relative;
  container-type: inline-size;
  container-name: ds-widget-cell;
  min-width: 0;
  min-height: 132px;
  overflow: hidden;
  border: 1px solid
    var(--ds-surface-card-border-strong, var(--ds-color-border-secondary));
  border-radius: var(--ds-radius-xl, 16px);
  background: radial-gradient(
      circle at 100% 0%,
      color-mix(in srgb, var(--ds-color-primary) 6%, transparent),
      transparent 34%
    ),
    linear-gradient(
      180deg,
      var(--ds-surface-card-bg, var(--ds-color-bg-elevated)),
      color-mix(
        in srgb,
        var(--ds-surface-panel-bg, var(--ds-color-bg-secondary)) 38%,
        var(--ds-surface-card-bg, var(--ds-color-bg-elevated))
      )
    );
  box-shadow: inset 0 1px 0
      color-mix(in srgb, var(--ds-color-bg-elevated) 74%, transparent),
    0 10px 28px color-mix(in srgb, var(--ds-color-primary) 5%, transparent);
  transform: translate3d(
      var(--ds-widget-board-layout-x),
      var(--ds-widget-board-layout-y),
      0
    )
    translateY(var(--ds-widget-board-hover-lift))
    translateY(var(--ds-widget-board-entry-offset))
    scale(var(--ds-widget-board-entry-scale))
    scale(var(--ds-widget-board-interaction-scale));
  transition: transform var(--ds-motion-rearrange)
      var(--ds-motion-ease-move, var(--ds-motion-ease-out, ease-out)),
    inline-size var(--ds-motion-rearrange, 320ms)
      var(--ds-motion-ease-move, var(--ds-motion-ease-out, ease-out)),
    block-size var(--ds-motion-resize, 200ms)
      var(--ds-motion-ease-move, var(--ds-motion-ease-out, ease-out)),
    border-color var(--ds-motion-feedback, 120ms)
      var(--ds-motion-ease-out, ease-out),
    box-shadow var(--ds-motion-feedback, 120ms)
      var(--ds-motion-ease-out, ease-out),
    opacity var(--ds-motion-feedback, 120ms) var(--ds-motion-ease-out, ease-out),
    height var(--ds-motion-resize, 200ms)
      var(--ds-motion-ease-move, cubic-bezier(0.2, 0, 0, 1));
  animation: ds-widget-board-cell-enter var(--ds-motion-reveal)
    var(--ds-motion-ease-enter, var(--ds-motion-ease-out, ease-out)) both;
  display: flex;
  align-self: start;
  flex-direction: column;
}

.ds-pattern-widget-board .ds-widget-board__cell:nth-child(2) {
  animation-delay: 35ms;
}
.ds-pattern-widget-board .ds-widget-board__cell:nth-child(3) {
  animation-delay: 70ms;
}
.ds-pattern-widget-board .ds-widget-board__cell:nth-child(4) {
  animation-delay: 105ms;
}
.ds-pattern-widget-board .ds-widget-board__cell:nth-child(5) {
  animation-delay: 140ms;
}
.ds-pattern-widget-board .ds-widget-board__cell:nth-child(6) {
  animation-delay: 175ms;
}
.ds-pattern-widget-board .ds-widget-board__cell:nth-child(n + 7) {
  animation-delay: 210ms;
}

.ds-pattern-widget-board .ds-widget-board__cell:active {
  border-color: color-mix(
    in srgb,
    var(--ds-color-primary) 28%,
    var(--ds-surface-card-border)
  );
  box-shadow: inset 0 1px 0
      color-mix(in srgb, var(--ds-color-bg-elevated) 82%, transparent),
    0 18px 38px -24px color-mix(in srgb, var(--ds-color-text-primary) 34%, transparent);
  --ds-widget-board-hover-lift: -2px;
}

.ds-pattern-widget-board[data-editing="true"] .ds-widget-board__cell {
  border-color: color-mix(
    in srgb,
    var(--ds-color-primary) 24%,
    var(--ds-surface-card-border)
  );
  box-shadow: inset 0 0 0 1px
      color-mix(in srgb, var(--ds-color-primary) 5%, transparent),
    0 10px 24px -22px color-mix(in srgb, var(--ds-color-text-primary) 34%, transparent);
}

.ds-pattern-widget-board[data-editing="true"] .ds-widget-board__cell:active {
  --ds-widget-board-hover-lift: 0px;
}

/* Hover is pointer-fine only. Every treatment below keeps a real `:active`
   twin at its original cascade position (unguarded, so touch press feedback
   matches), and the resize affordances keep unguarded
   `:focus-visible` / `[data-active="true"]` compounds beside their rails.
   The block sits before the resizing/dragging state rules so those states
   still win their specificity ties while a gesture is running. */
@media (hover: hover) {
  .ds-pattern-widget-board .ds-widget-board__toolbar:hover {
    background-position: 100% 50%;
    border-color: color-mix(
      in srgb,
      var(--ds-color-primary) 22%,
      var(--ds-surface-card-border-strong, var(--ds-color-border-primary))
    );
  }

  .ds-pattern-widget-board
    .ds-widget-board__toolbar:hover
    .ds-widget-board__toolbar-icon {
    transform: translateY(-1px) scale(1.025);
  }

  :is(.ds-pattern-widget-board, .ds-widget-board__catalog-surface)
    .ds-widget-board__catalog-item:hover {
    border-color: color-mix(
      in srgb,
      var(--ds-color-primary) 28%,
      var(--ds-surface-card-border)
    );
    box-shadow: 0 14px 32px -25px color-mix(in srgb, var(--ds-color-text-primary)
          38%, transparent);
    transform: translateY(-1px);
  }

  .ds-pattern-widget-board .ds-widget-board__cell:hover {
    border-color: color-mix(
      in srgb,
      var(--ds-color-primary) 28%,
      var(--ds-surface-card-border)
    );
    box-shadow: inset 0 1px 0
        color-mix(in srgb, var(--ds-color-bg-elevated) 82%, transparent),
      0 18px 38px -24px color-mix(in srgb, var(--ds-color-text-primary) 34%, transparent);
    --ds-widget-board-hover-lift: -2px;
  }

  .ds-pattern-widget-board[data-editing="true"]
    .ds-widget-board__cell:hover {
    --ds-widget-board-hover-lift: 0px;
  }

  .ds-pattern-widget-board
    .ds-widget-board__cell:hover
    > .ds-widget-board__item-header {
    background-position: 100% 50%;
  }

  .ds-pattern-widget-board
    .ds-widget-board__cell:hover
    .ds-widget-board__item-icon {
    transform: translateY(-1px) scale(1.025);
  }

  .ds-pattern-widget-board .ds-widget-board__resize-handle:hover {
    color: var(--ds-color-text-secondary);
    outline: none;
  }

  .ds-pattern-widget-board
    .ds-widget-board__resize-handle:hover
    .ds-widget-board__resize-rail {
    opacity: 1;
    background: color-mix(
      in srgb,
      var(--ds-color-text-primary) 36%,
      var(--ds-surface-card-border-strong)
    );
  }

  .ds-pattern-widget-board
    .ds-widget-board__resize-handle[data-edge^="inline"]:hover
    .ds-widget-board__resize-rail {
    transform: translateY(-50%) scaleY(1);
  }

  .ds-pattern-widget-board
    .ds-widget-board__resize-handle:is(
      [data-edge="block-start"],
      [data-edge="block-end"]
    ):hover
    .ds-widget-board__resize-rail {
    transform: translateX(-50%) scaleX(1);
  }

  .ds-pattern-widget-board
    .ds-widget-board__resize-handle[data-edge*="-inline-"]:hover
    .ds-widget-board__resize-rail {
    background: transparent;
    transform: scale(1);
  }

  .ds-pattern-widget-board
    .ds-widget-board__resize-handle:hover
    .ds-widget-board__resize-indicator {
    opacity: 1;
  }

  .ds-pattern-widget-board
    .ds-widget-board__resize-handle[data-edge^="inline"]:hover
    .ds-widget-board__resize-indicator {
    transform: translateY(-50%) translateX(0) scale(1);
  }

  .ds-pattern-widget-board
    .ds-widget-board__resize-handle:is(
      [data-edge="block-start"],
      [data-edge="block-end"]
    ):hover
    .ds-widget-board__resize-indicator {
    transform: translateX(-50%) translateY(0) scale(1);
  }

  .ds-pattern-widget-board
    .ds-widget-board__resize-handle[data-edge*="-inline-"]:hover
    .ds-widget-board__resize-indicator {
    transform: translate(0, 0) scale(1);
  }
}

/* Forced colors: frames read as ButtonText, the drop target and the focus
   ring read as Highlight; decorative shadows and mixed paints drop out. */
@media (forced-colors: active) {
  .ds-pattern-widget-board .ds-widget-board__toolbar,
  .ds-pattern-widget-board .ds-widget-board__cell,
  .ds-pattern-widget-board .ds-widget-board__empty,
  :is(.ds-pattern-widget-board, .ds-widget-board__catalog-surface)
    .ds-widget-board__catalog-item,
  :is(.ds-pattern-widget-board, .ds-widget-board__catalog-surface)
    .ds-widget-board__catalog-empty {
    border-color: ButtonText;
  }

  .ds-pattern-widget-board .ds-widget-board__cell[data-dragging="true"],
  .ds-pattern-widget-board .ds-widget-board__cell[data-drop-target="true"] {
    border-color: Highlight;
    outline-color: Highlight;
  }

  .ds-widget-board__catalog-surface[data-part="surface"] {
    border-inline-start-color: ButtonText;
  }

  .ds-pattern-widget-board .ds-widget-board__resize-rail {
    background: ButtonText;
  }

  .ds-pattern-widget-board .ds-widget-board__resize-handle:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 1px;
    box-shadow: none;
  }
}

.ds-pattern-widget-board .ds-widget-board__cell[data-resizing="true"] {
  z-index: var(--_ds-widget-board-z-resizing, 6);
  box-shadow: inset 0 0 0 1px
      color-mix(in srgb, var(--ds-color-text-primary) 12%, transparent),
    0 22px 42px -30px color-mix(in srgb, var(--ds-color-text-primary) 44%, transparent);
  --ds-widget-board-hover-lift: 0px;
  --ds-widget-board-interaction-scale: 1;
  will-change: height;
}

.ds-pattern-widget-board .ds-widget-board__cell[data-dragging="true"] {
  z-index: var(--_ds-widget-board-z-dragging, 8);
  opacity: 0.94;
  box-shadow: inset 0 1px 0
      color-mix(in srgb, var(--ds-color-bg-elevated) 86%, transparent),
    0 26px 54px -32px color-mix(in srgb, var(--ds-color-text-primary) 48%, transparent);
  --ds-widget-board-hover-lift: 0px;
  --ds-widget-board-interaction-scale: 0.996;
  cursor: grabbing;
  will-change: transform;
}

/* The move-mode `cursor: grabbing` cascade lives in
   `runtime/engines/modern/skin/widget-board.css`: the Button chrome it must
   beat is painted in the later `rottay-engines` layer, unreachable from this
   `rottay-components` skin without `!important`. */

.ds-pattern-widget-board .ds-widget-board__cell[data-drop-target="true"] {
  border-color: color-mix(
    in srgb,
    var(--ds-color-primary) 62%,
    var(--ds-surface-card-border)
  );
  outline: 2px solid
    color-mix(in srgb, var(--ds-color-primary) 38%, transparent);
}

.ds-pattern-widget-board .ds-widget-board__content {
  display: flex;
  flex: 0 0 auto;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}

.ds-pattern-widget-board
  .ds-widget-board__cell[data-height="fixed"]
  .ds-widget-board__content {
  flex: 1 1 auto;
  overflow: auto;
  overscroll-behavior: contain;
}

.ds-pattern-widget-board .ds-widget-board__item-header {
  position: relative;
  z-index: var(--_ds-widget-board-z-header, 1);
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--ds-spacing-3, 12px);
  min-width: 0;
  min-height: 70px;
  padding: var(--ds-spacing-4, 16px) var(--ds-spacing-5, 20px);
  border-bottom: 1px solid
    var(--ds-card-header-border, var(--ds-surface-card-border));
  background: var(
    --ds-card-header-bg,
    linear-gradient(
      112deg,
      color-mix(in srgb, var(--ds-color-primary) 7%, var(--ds-surface-card-bg)),
      var(--ds-surface-card-bg) 56%,
      color-mix(
        in srgb,
        var(--ds-surface-panel-bg) 68%,
        var(--ds-surface-card-bg)
      )
    )
  );
  background-position: 0% 50%;
  background-size: 180% 180%;
  box-shadow: inset 0 1px 0
    color-mix(in srgb, var(--ds-color-bg-elevated) 88%, transparent);
  transition: background-position var(--ds-motion-slow)
      var(--ds-motion-ease-out, ease-out),
    border-color var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out);
}

.ds-pattern-widget-board
  .ds-widget-board__cell:active
  > .ds-widget-board__item-header {
  background-position: 100% 50%;
}

.ds-pattern-widget-board .ds-widget-board__item-heading {
  display: flex;
  flex: 1 1 auto;
  align-items: flex-start;
  gap: var(--ds-spacing-3, 12px);
  min-width: 0;
}

.ds-pattern-widget-board .ds-widget-board__item-icon {
  display: grid;
  flex: 0 0 auto;
  width: 38px;
  height: 38px;
  place-items: center;
  border: 1px solid
    var(--ds-workspace-card-icon-border, var(--ds-color-border-primary));
  border-radius: var(--ds-radius-lg, 11px);
  background: var(--ds-workspace-card-icon-bg, var(--ds-surface-card-bg));
  color: var(--ds-workspace-card-icon-color, var(--ds-color-primary));
  box-shadow: inset 0 1px 0
      color-mix(in srgb, var(--ds-color-bg-elevated) 88%, transparent),
    0 6px 16px -11px color-mix(in srgb, var(--ds-color-primary) 52%, transparent);
  transition: transform var(--ds-motion-fast)
    var(--ds-motion-ease-out, ease-out);
}

.ds-pattern-widget-board
  .ds-widget-board__cell:active
  .ds-widget-board__item-icon {
  transform: translateY(-1px) scale(1.025);
}

.ds-pattern-widget-board .ds-widget-board__item-copy {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.ds-pattern-widget-board .ds-widget-board__item-eyebrow {
  color: var(--ds-color-text-muted);
  font-family: var(--ds-font-family-mono, ui-monospace, monospace);
  font-size: var(--ds-text-eyebrow-size, var(--ds-font-size-xs));
  font-weight: var(--ds-font-weight-semibold, 600);
  letter-spacing: 0.11em;
  line-height: 1.25;
  text-transform: uppercase;
}

.ds-pattern-widget-board .ds-widget-board__item-title {
  min-width: 0;
  margin: 0;
  color: var(--ds-color-text-primary);
  font-family: var(--ds-font-family-heading, var(--ds-font-family-base));
  font-size: var(--ds-font-size-lg, 16px);
  font-weight: var(--ds-font-weight-semibold, 600);
  letter-spacing: -0.022em;
  line-height: 1.2;
  text-wrap: balance;
}

.ds-pattern-widget-board .ds-widget-board__item-supporting {
  overflow: hidden;
  color: var(--ds-color-text-secondary);
  font-size: var(--ds-font-size-xs, 12px);
  line-height: 1.35;
  text-overflow: ellipsis;
}

.ds-pattern-widget-board .ds-widget-board__item-accessory {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: flex-end;
}

.ds-pattern-widget-board
  .ds-widget-board__cell[data-size="sm"]
  .ds-widget-board__item-header {
  min-height: 62px;
  padding: var(--ds-spacing-3, 12px) var(--ds-spacing-4, 16px);
}

.ds-pattern-widget-board
  .ds-widget-board__cell[data-size="sm"]
  .ds-widget-board__item-icon {
  width: 32px;
  height: 32px;
  border-radius: var(--ds-radius-md, 9px);
}

.ds-pattern-widget-board
  .ds-widget-board__cell[data-size="sm"]
  .ds-widget-board__item-title {
  font-size: var(--ds-font-size-sm, 14px);
}

/* The whole edit header is the grab target, so the drag affordance is not
   bound to the width of the move control. The Button and Button.Icon inside it
   keep their own primitive chrome. */
.ds-pattern-widget-board .ds-widget-board__cell-controls {
  position: relative;
  z-index: var(--_ds-widget-board-z-controls, 5);
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: flex-start;
  gap: var(--ds-spacing-2, 8px);
  min-height: 44px;
  padding: 6px var(--ds-spacing-3, 12px);
  border-bottom: 1px solid
    var(--ds-surface-card-border, var(--ds-color-border-primary));
  background: color-mix(
    in srgb,
    var(--ds-surface-panel-bg) 78%,
    var(--ds-surface-card-bg)
  );
  cursor: grab;
  touch-action: none;
  user-select: none;
}

.ds-pattern-widget-board .ds-widget-board__cell-controls:active {
  cursor: grabbing;
}

/* The readout and the remove control stay pinned to the inline-end of the
   header; the move control keeps its natural button width. */
.ds-pattern-widget-board .ds-widget-board__size-readout {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 28px;
  margin-inline-start: auto;
  padding-inline: 9px;
  border: 1px solid
    var(--ds-surface-card-border, var(--ds-color-border-primary));
  border-radius: 999px;
  background: color-mix(in srgb, var(--ds-surface-card-bg) 82%, transparent);
  color: var(--ds-color-text-muted);
  font-family: var(--ds-font-family-mono, ui-monospace, monospace);
  font-size: var(--ds-font-size-xs, 12px);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.ds-pattern-widget-board .ds-widget-board__drag {
  cursor: grab;
}

.ds-pattern-widget-board .ds-widget-board__drag:active {
  cursor: grabbing;
}

/* The entire physical border is the resize target. The visual rail only
   appears on hover/focus/drag, so edit mode stays precise without decorating
   a permanent coloured side. Inline-end and block-end remain keyboard
   sliders; their opposite edges provide the same pointer affordance. */
.ds-pattern-widget-board .ds-widget-board__resize-handle {
  position: absolute;
  z-index: var(--_ds-widget-board-z-handle, 7);
  display: block;
  padding: 0;
  overflow: visible;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: var(--ds-color-text-muted);
  touch-action: none;
  transition: color var(--ds-motion-fast)
    var(--ds-motion-ease-out, ease-out);
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="inline-start"],
.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="inline-end"] {
  inset-block: 9px;
  width: 14px;
  cursor: ew-resize;
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="inline-start"] {
  inset-inline-start: 0;
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="inline-end"] {
  inset-inline-end: 0;
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="block-start"],
.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="block-end"] {
  inset-inline: 9px;
  height: 14px;
  cursor: ns-resize;
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="block-start"] {
  inset-block-start: 0;
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="block-end"] {
  inset-block-end: 0;
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge*="-inline-"] {
  width: 20px;
  height: 20px;
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="block-start-inline-start"] {
  inset-block-start: 0;
  inset-inline-start: 0;
  cursor: nwse-resize;
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="block-start-inline-end"] {
  inset-block-start: 0;
  inset-inline-end: 0;
  cursor: nesw-resize;
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="block-end-inline-start"] {
  inset-block-end: 0;
  inset-inline-start: 0;
  cursor: nesw-resize;
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="block-end-inline-end"] {
  inset-block-end: 0;
  inset-inline-end: 0;
  cursor: nwse-resize;
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle:where(
    :focus-visible,
    :active,
    [data-active="true"]
  ) {
  color: var(--ds-color-text-secondary);
  outline: none;
}

.ds-pattern-widget-board .ds-widget-board__resize-handle:focus-visible {
  border-radius: 999px;
  box-shadow: var(
    --ds-shadow-focus-ring,
    0 0 0 3px color-mix(in srgb, var(--ds-color-primary) 24%, transparent)
  );
}

.ds-pattern-widget-board .ds-widget-board__resize-rail {
  position: absolute;
  border-radius: 999px;
  background: color-mix(
    in srgb,
    var(--ds-surface-card-border-strong, var(--ds-color-border-primary)) 86%,
    transparent
  );
  opacity: 0;
  transition: opacity var(--ds-motion-fast)
      var(--ds-motion-ease-out, ease-out),
    transform var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out),
    background var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out);
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge^="inline"]
  .ds-widget-board__resize-rail {
  inset-block-start: 50%;
  inset-inline: 6px;
  width: 2px;
  height: 38px;
  transform: translateY(-50%) scaleY(0.62);
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle:is(
    [data-edge="block-start"],
    [data-edge="block-end"]
  )
  .ds-widget-board__resize-rail {
  inset-block: 6px;
  inset-inline-start: 50%;
  width: 38px;
  height: 2px;
  transform: translateX(-50%) scaleX(0.62);
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle:where(
    :focus-visible,
    :active,
    [data-active="true"]
  )
  .ds-widget-board__resize-rail {
