.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge^="inline"]:where(
    :focus-visible,
    :active,
    [data-active="true"]
  )
  .ds-widget-board__resize-rail {
  transform: translateY(-50%) scaleY(1);
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle:is(
    [data-edge="block-start"],
    [data-edge="block-end"]
  ):where(:focus-visible, :active, [data-active="true"])
  .ds-widget-board__resize-rail {
  transform: translateX(-50%) scaleX(1);
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge*="-inline-"]
  .ds-widget-board__resize-rail {
  inset: 6px;
  width: 8px;
  height: 8px;
  border-color: color-mix(
    in srgb,
    var(--ds-color-text-primary) 34%,
    var(--ds-surface-card-border-strong)
  );
  border-style: solid;
  background: transparent;
  transform: scale(0.72);
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="block-start-inline-start"]
  .ds-widget-board__resize-rail {
  border-width: 2px 0 0 2px;
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="block-start-inline-end"]
  .ds-widget-board__resize-rail {
  border-width: 2px 2px 0 0;
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="block-end-inline-start"]
  .ds-widget-board__resize-rail {
  border-width: 0 0 2px 2px;
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="block-end-inline-end"]
  .ds-widget-board__resize-rail {
  border-width: 0 2px 2px 0;
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge*="-inline-"]:where(
    :active,
    [data-active="true"]
  )
  .ds-widget-board__resize-rail {
  background: transparent;
  transform: scale(1);
}

.ds-pattern-widget-board .ds-widget-board__resize-indicator {
  position: absolute;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  width: auto;
  min-width: 66px;
  height: 36px;
  padding-inline: 9px;
  border: 1px solid
    var(--ds-surface-card-border-strong, var(--ds-color-border-primary));
  border-radius: var(--ds-radius-md, 8px);
  background: var(--ds-surface-card-bg, var(--ds-color-bg-elevated));
  box-shadow: 0 6px 18px -12px color-mix(in srgb, var(--ds-color-text-primary)
        54%, transparent);
  opacity: 0;
  font-family: var(--ds-font-family-mono, ui-monospace, monospace);
  font-size: var(--ds-font-size-xs, 12px);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  transition: opacity var(--ds-motion-fast)
      var(--ds-motion-ease-out, ease-out),
    transform var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out);
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="inline-start"]
  .ds-widget-board__resize-indicator {
  inset-block-start: 50%;
  inset-inline-start: 20px;
  transform: translateY(-50%) translateX(-6px) scale(0.96);
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="inline-end"]
  .ds-widget-board__resize-indicator {
  inset-block-start: 50%;
  inset-inline-end: 20px;
  transform: translateY(-50%) translateX(6px) scale(0.96);
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle:is(
    [data-edge="block-start"],
    [data-edge="block-end"]
  )
  .ds-widget-board__resize-indicator {
  inset-inline-start: 50%;
  transform: translateX(-50%) translateY(-6px) scale(0.96);
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="block-start"]
  .ds-widget-board__resize-indicator {
  inset-block-start: 20px;
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="block-end"]
  .ds-widget-board__resize-indicator {
  inset-block-end: 20px;
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="block-start-inline-start"]
  .ds-widget-board__resize-indicator {
  inset-block-start: 20px;
  inset-inline-start: 20px;
  transform: translate(-6px, -6px) scale(0.96);
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="block-start-inline-end"]
  .ds-widget-board__resize-indicator {
  inset-block-start: 20px;
  inset-inline-end: 20px;
  transform: translate(6px, -6px) scale(0.96);
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="block-end-inline-start"]
  .ds-widget-board__resize-indicator {
  inset-block-end: 20px;
  inset-inline-start: 20px;
  transform: translate(-6px, 6px) scale(0.96);
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge="block-end-inline-end"]
  .ds-widget-board__resize-indicator {
  inset-block-end: 20px;
  inset-inline-end: 20px;
  transform: translate(6px, 6px) scale(0.96);
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle:where(
    :focus-visible,
    :active,
    [data-active="true"]
  )
  .ds-widget-board__resize-indicator {
  opacity: 1;
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge^="inline"]:where(
    :focus-visible,
    :active,
    [data-active="true"]
  )
  .ds-widget-board__resize-indicator {
  transform: translateY(-50%) translateX(0) scale(1);
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle:is(
    [data-edge="block-start"],
    [data-edge="block-end"]
  ):where(:focus-visible, :active, [data-active="true"])
  .ds-widget-board__resize-indicator {
  transform: translateX(-50%) translateY(0) scale(1);
}

.ds-pattern-widget-board
  .ds-widget-board__resize-handle[data-edge*="-inline-"]:where(
    :active,
    [data-active="true"]
  )
  .ds-widget-board__resize-indicator {
  transform: translate(0, 0) scale(1);
}

.ds-pattern-widget-board[data-resizing="true"][data-resize-axis="inline"] {
  cursor: ew-resize;
  user-select: none;
}

.ds-pattern-widget-board[data-resizing="true"][data-resize-axis="block"] {
  cursor: ns-resize;
  user-select: none;
}

.ds-pattern-widget-board[data-resizing="true"][data-resize-axis="both"] {
  cursor: nwse-resize;
  user-select: none;
}

/* Loading is a quiet state, not a repaint: the house idiom (decision-comparison)
   is a progress cursor while the engine marks the region aria-busy. */
.ds-pattern-widget-board[data-loading="true"] {
  cursor: progress;
}

/* The empty board consumes the shared empty-state premium contract so a blank
   workspace reads like the rest of the system's empty surfaces. */
.ds-pattern-widget-board .ds-widget-board__empty {
  display: grid;
  min-height: 220px;
  padding: var(--ds-spacing-6, 24px);
  place-items: center;
  border: 1px solid
    var(
      --ds-empty-state-border,
      var(--ds-surface-card-border, var(--ds-color-border-primary))
    );
  border-radius: var(--ds-radius-xl, 16px);
  background: var(--ds-empty-state-bg, var(--ds-surface-panel-bg));
  color: var(--ds-color-text-secondary);
}

@keyframes ds-widget-board-cell-enter {
  from {
    opacity: 0;
    --ds-widget-board-entry-offset: 8px;
    --ds-widget-board-entry-scale: 0.992;
  }
  to {
    opacity: 1;
    --ds-widget-board-entry-offset: 0px;
    --ds-widget-board-entry-scale: 1;
  }
}

/* Two-column widgets remain useful well below a 1024px board. Collapsing them
   earlier made the resize control report a half-width state while rendering a
   full-width card and produced the dead vertical space this pattern exists to
   prevent. */
@container ds-widget-board (max-width: 839px) {
  .ds-pattern-widget-board .ds-widget-board__cell[data-size="sm"],
  .ds-pattern-widget-board .ds-widget-board__cell[data-size="md"] {
    grid-column: span 6;
  }
  .ds-pattern-widget-board .ds-widget-board__cell[data-size="lg"],
  .ds-pattern-widget-board .ds-widget-board__cell[data-size="wide"] {
    grid-column: 1 / -1;
  }

  .ds-pattern-widget-board .ds-widget-board__resize-handle {
    display: none;
  }
}

@container ds-widget-board (max-width: 639px) {
  .ds-pattern-widget-board .ds-widget-board__toolbar {
    align-items: stretch;
    flex-direction: column;
  }
  .ds-pattern-widget-board .ds-widget-board__toolbar-actions > * {
    flex: 1 1 auto;
  }
  .ds-pattern-widget-board .ds-widget-board__toolbar-heading {
    flex: 0 1 auto;
    width: 100%;
  }
  .ds-pattern-widget-board .ds-widget-board__grid {
    grid-template-columns: minmax(0, 1fr);
    gap: var(--ds-spacing-3, 12px);
  }
  .ds-pattern-widget-board .ds-widget-board__cell[data-size] {
    grid-column: 1 / -1;
  }

  .ds-pattern-widget-board .ds-widget-board__item-header {
    align-items: stretch;
    flex-direction: column;
    min-height: 0;
    padding: var(--ds-spacing-3, 12px) var(--ds-spacing-4, 16px);
  }

  .ds-pattern-widget-board .ds-widget-board__item-heading {
    width: 100%;
  }

  /* In the stacked header the accessory drops under the copy column, so it
     aligns with the title text: icon box + heading gap. The compact widget
     carries a smaller icon box and needs its own offset. */
  .ds-pattern-widget-board .ds-widget-board__item-accessory {
    align-self: flex-start;
    justify-content: flex-start;
    padding-inline-start: calc(38px + var(--ds-spacing-3, 12px));
  }

  .ds-pattern-widget-board
    .ds-widget-board__cell[data-size="sm"]
    .ds-widget-board__item-accessory {
    padding-inline-start: calc(32px + var(--ds-spacing-3, 12px));
  }

  .ds-pattern-widget-board .ds-widget-board__resize-handle {
    display: none;
  }

  :is(.ds-pattern-widget-board, .ds-widget-board__catalog-surface)
    .ds-widget-board__catalog {
    gap: var(--ds-spacing-3, 12px);
  }

  :is(.ds-pattern-widget-board, .ds-widget-board__catalog-surface)
    .ds-widget-board__catalog-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  :is(.ds-pattern-widget-board, .ds-widget-board__catalog-surface)
    .ds-widget-board__catalog-item {
    min-height: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-pattern-widget-board .ds-widget-board__cell,
  .ds-pattern-widget-board .ds-widget-board__toolbar,
  .ds-pattern-widget-board .ds-widget-board__toolbar-icon,
  .ds-pattern-widget-board .ds-widget-board__item-header,
  .ds-pattern-widget-board .ds-widget-board__item-icon {
    animation: none;
    transition: none;
  }
}

}
@layer rottay-components {
/**
 * Collapse Engine Styles - Rottay Design System
 *
 * Engine-agnostic CSS that bridges design tokens to underlying library components.
 * Uses CSS custom properties set by the token system to style inner elements.
 *
 * Targets:
 * - .ds-collapse: Token wrapper (receives CSS custom properties)
 * - .ant-collapse-*: Ant Design internal classes (classic engine)
 *
 * This file is imported inside `rottay-components`, after Tailwind v4's
 * `base` layer in the canonical shared cascade. Wrapper and engine channels
 * therefore keep one deterministic owner without unlayered paint bridges.
 * The `.ant-*` channels remain bounded here; engine-specific corrections
 * belong to `rottay-engines`, not to host-application selectors.
 */

/* =============================================================================
   BASE COLLAPSE STYLES
   Applied to the wrapper element that receives tokens
   ============================================================================= */

.ds-collapse {
  /* Reset any inherited styles */
  box-sizing: border-box;

  /* Apply root material and geometry tokens */
  background: var(--ds-collapse-root-bg);
  border-color: var(--ds-collapse-root-border-color);
  border-width: var(--ds-collapse-root-border-width);
  border-style: solid;
  border-radius: var(--ds-collapse-root-border-radius);
  box-shadow: var(--ds-collapse-root-shadow);

  /* Ensure full width */
  width: 100%;

  /* Container for inner engine component */
  overflow: hidden;
}

.ds-collapse--ghost {
  background: var(--ds-collapse-root-ghost-idle-bg);
  border: none;
  box-shadow: none;
}

.ds-collapse--bordered {
  background: var(--ds-collapse-root-bordered-idle-bg);
  border-color: var(--ds-collapse-root-bordered-idle-border-color);
}

/* =============================================================================
   ANT DESIGN OVERRIDES (TITAN ENGINE)
   Override Ant Design's default styles with our tokens
   ============================================================================= */

/* Reset Ant Design's outer border - we handle it on wrapper */
.ds-collapse .ant-collapse {
  border: none;
  background: transparent;
  border-radius: 0;
}

/* Collapse header styling */
.ds-collapse .ant-collapse-header {
  background: var(--ds-collapse-header-default-idle-bg) !important;
  color: var(--ds-collapse-header-default-idle-color) !important;
  padding: var(--ds-collapse-header-padding-y)
    var(--ds-collapse-header-padding-x) !important;
  font-size: var(--ds-collapse-header-font-size) !important;
  font-weight: var(--ds-collapse-header-default-idle-font-weight);
  line-height: var(--ds-collapse-header-default-idle-line-height);
  cursor: pointer;
  transition: var(--ds-collapse-transition);
  border-bottom: 1px solid var(--ds-collapse-header-default-idle-border-color);
}

.ds-collapse .ant-collapse-header:hover {
  background: var(--ds-collapse-header-default-hover-bg) !important;
  color: var(--ds-collapse-header-default-hover-color) !important;
}

.ds-collapse .ant-collapse-header:focus-visible {
  outline: var(--ds-collapse-header-default-focus-outline);
  outline-offset: var(--ds-collapse-header-default-focus-outline-offset);
}

.ds-collapse .ant-collapse-header:active {
  background: var(--ds-collapse-header-default-active-bg) !important;
}

/* Expanded header state */
.ds-collapse .ant-collapse-item-active .ant-collapse-header {
  background: var(--ds-collapse-header-default-expanded-bg) !important;
  color: var(--ds-collapse-header-default-expanded-color) !important;
  border-color: var(--ds-collapse-header-default-expanded-border-color);
}

/* Disabled header state */
.ds-collapse .ant-collapse-item-disabled .ant-collapse-header {
  background: var(--ds-collapse-header-default-disabled-bg) !important;
  color: var(--ds-collapse-header-default-disabled-color) !important;
  cursor: not-allowed;
  opacity: var(--ds-collapse-header-default-disabled-opacity);
}

/* Collapse content styling */
.ds-collapse .ant-collapse-content {
  background: var(--ds-collapse-content-default-idle-bg) !important;
  color: var(--ds-collapse-content-default-idle-color) !important;
  border-top: none;
}

.ds-collapse .ant-collapse-content-box {
  padding: var(--ds-collapse-content-padding-y)
    var(--ds-collapse-content-padding-x) !important;
  font-size: var(--ds-collapse-content-default-idle-font-size);
  line-height: var(--ds-collapse-content-default-idle-line-height);
}

/* Expand icon styling */
.ds-collapse .ant-collapse-expand-icon {
  color: var(--ds-collapse-icon-default-idle-color);
  transition: var(--ds-collapse-icon-default-idle-transition);
}

.ds-collapse .ant-collapse-expand-icon svg {
  width: var(--ds-collapse-icon-size);
  height: var(--ds-collapse-icon-size);
}

.ds-collapse .ant-collapse-item-active .ant-collapse-expand-icon {
  color: var(--ds-collapse-icon-default-expanded-color);
}

.ds-collapse .ant-collapse-item-disabled .ant-collapse-expand-icon {
  color: var(--ds-collapse-icon-default-disabled-color);
}

/* Panel borders */
.ds-collapse .ant-collapse-item {
  border-bottom: 1px solid var(--ds-collapse-header-default-idle-border-color);
}

.ds-collapse .ant-collapse-item:last-child {
  border-bottom: none;
}

.ds-collapse .ant-collapse-item:last-child .ant-collapse-header {
  border-radius: 0 0 var(--ds-collapse-root-border-radius)
    var(--ds-collapse-root-border-radius);
}

.ds-collapse .ant-collapse-item:first-child .ant-collapse-header {
  border-radius: var(--ds-collapse-root-border-radius)
    var(--ds-collapse-root-border-radius) 0 0;
}

/* =============================================================================
   GHOST VARIANT
   ============================================================================= */

.ds-collapse--ghost .ant-collapse-header {
  background: var(--ds-collapse-header-ghost-idle-bg) !important;
  color: var(--ds-collapse-header-ghost-idle-color) !important;
  border-bottom: none;
  padding: var(--ds-collapse-header-ghost-idle-padding-y)
    var(--ds-collapse-header-ghost-idle-padding-x) !important;
}

.ds-collapse--ghost .ant-collapse-header:hover {
  background: var(--ds-collapse-header-ghost-hover-bg) !important;
  color: var(--ds-collapse-header-ghost-hover-color) !important;
}

.ds-collapse--ghost .ant-collapse-content {
  background: var(--ds-collapse-content-ghost-idle-bg) !important;
  color: var(--ds-collapse-content-ghost-idle-color) !important;
}

.ds-collapse--ghost .ant-collapse-content-box {
  padding: var(--ds-collapse-content-ghost-idle-padding-y)
    var(--ds-collapse-content-ghost-idle-padding-x) !important;
}

.ds-collapse--ghost .ant-collapse-item {
  border-bottom: none;
}

/* =============================================================================
   BORDERED VARIANT
   ============================================================================= */

/* =============================================================================
   SIZE VARIANTS
   ============================================================================= */

/* Small size */
.ds-collapse--small .ant-collapse-header {
  padding: var(--ds-collapse-size-small-header-padding-y)
    var(--ds-collapse-size-small-header-padding-x) !important;
  font-size: var(--ds-collapse-size-small-header-font-size) !important;
}

.ds-collapse--small .ant-collapse-content-box {
  padding: var(--ds-collapse-size-small-content-padding-y)
    var(--ds-collapse-size-small-content-padding-x) !important;
}

.ds-collapse--small .ant-collapse-expand-icon svg {
  width: var(--ds-collapse-size-small-icon-size);
  height: var(--ds-collapse-size-small-icon-size);
}

/* Large size */
.ds-collapse--large .ant-collapse-header {
  padding: var(--ds-collapse-size-large-header-padding-y)
    var(--ds-collapse-size-large-header-padding-x) !important;
  font-size: var(--ds-collapse-size-large-header-font-size) !important;
}

.ds-collapse--large .ant-collapse-content-box {
  padding: var(--ds-collapse-size-large-content-padding-y)
    var(--ds-collapse-size-large-content-padding-x) !important;
}

.ds-collapse--large .ant-collapse-expand-icon svg {
  width: var(--ds-collapse-size-large-icon-size);
  height: var(--ds-collapse-size-large-icon-size);
}

/* =============================================================================
   DISABLED STATE
   ============================================================================= */

.ds-collapse--disabled {
  pointer-events: none;
  opacity: var(--ds-collapse-header-default-disabled-opacity);
}

}

/* Layer 3: Engine themes */
@layer rottay-engines {
/**
 * Engine Styles Index - Rottay Design System
 *
 * Central import file for all engine theme files.
 * These CSS files map --ds-* design tokens to library-specific classes.
 *
 * Architecture:
 * 1. default.css provides all base tokens (:root)
 * 2. Engine themes map tokens to library classes (Ant Design, Tailwind, Vanilla)
 * 3. Tenant CSS can override token values via [data-tenant] selectors
 *
 * Usage:
 *   This file is internal to the package. It is bundled into the public
 *   `@rottay/design-system/styles*` artifacts at build time. Consumers
 *   should not import it directly.
 *
 * @version 0.4.0
 */

/* Collapse bridge imported in foundation/base.css, not here.
   Engine themes map --ds-* tokens to library-specific classes. */

/* Engine-specific themes */
/**
 * Classic Engine Theme - Rottay Design System
 *
 * Maps --ds-* design tokens to Ant Design component classes.
 * This file bridges the centralized token system with Ant Design 5.x.
 *
 * Architecture:
 * - Uses html[data-tenant] selector for tenant-scoped overrides
 * - All values reference --ds-* variables from default.css
 * - Covers all interactive states: hover, focus, active, disabled
 *
 * @version 0.4.0
 * @engine Classic (Ant Design 5.21)
 */

/* =============================================================================
   GLOBAL RESETS & BASE STYLES
   ============================================================================= */

html[data-tenant] {
  font-family: var(--ds-font-family-base);
  font-size: var(--ds-font-size-base);
  line-height: var(--ds-line-height-normal);
  color: var(--ds-text-primary);
}

/* =============================================================================
   BUTTON - .ant-btn
   ============================================================================= */

html[data-tenant] .ant-btn {
  font-family: var(--ds-font-family-base);
  font-weight: var(--ds-button-font-weight);
  border-radius: var(--ds-button-md-radius);
  transition: var(--ds-button-transition);
  height: var(--ds-button-md-height);
  padding: 0 var(--ds-button-md-padding-x);
  font-size: var(--ds-button-md-font-size);
  will-change: transform;
}

html[data-tenant] .ant-btn:focus-visible {
  box-shadow: var(--ds-button-focus-ring);
}

html[data-tenant] .ant-btn:hover:not(:disabled) {
  transform: var(--ds-button-hover-transform, translateY(0) scale(1));
}

html[data-tenant] .ant-btn:active:not(:disabled) {
  transform: var(--ds-button-active-transform, scale(0.98));
}

/* Button Sizes */
html[data-tenant] .ant-btn-sm {
  height: var(--ds-button-sm-height);
  padding: 0 var(--ds-button-sm-padding-x);
  font-size: var(--ds-button-sm-font-size);
  border-radius: var(--ds-button-sm-radius);
}

html[data-tenant] .ant-btn-lg {
  height: var(--ds-button-lg-height);
  padding: 0 var(--ds-button-lg-padding-x);
  font-size: var(--ds-button-lg-font-size);
  border-radius: var(--ds-button-lg-radius);
}

/* Primary Button */
html[data-tenant] .ant-btn-primary {
  background: var(--ds-button-primary-bg);
  border-color: var(--ds-button-primary-border);
  color: var(--ds-button-primary-color);
  box-shadow: var(--ds-button-primary-shadow);
}

html[data-tenant] .ant-btn-primary:hover:not(:disabled) {
  background: var(--ds-button-primary-bg-hover);
  border-color: var(--ds-button-primary-bg-hover);
  box-shadow: var(--ds-button-primary-shadow-hover);
  transform: var(--ds-button-hover-transform, translateY(0) scale(1));
}

html[data-tenant] .ant-btn-primary:active:not(:disabled) {
  background: var(--ds-button-primary-bg-active);
