  width: var(--ds-colorpicker-slider-thumb-size);
  height: var(--ds-colorpicker-slider-thumb-size);
  background: var(--ds-colorpicker-slider-thumb-bg);
  box-shadow: var(--ds-colorpicker-slider-thumb-shadow);
}

html[data-tenant] .ant-color-picker-slider {
  height: var(--ds-colorpicker-slider-height);
}

html[data-tenant] .ant-color-picker-input input {
  background: var(--ds-colorpicker-input-bg);
  border-color: var(--ds-colorpicker-input-border);
  border-radius: var(--ds-colorpicker-input-radius);
}

html[data-tenant] .ant-color-picker-presets-color {
  width: var(--ds-colorpicker-preset-size);
  height: var(--ds-colorpicker-preset-size);
  border-color: var(--ds-colorpicker-preset-border);
  border-radius: var(--ds-colorpicker-preset-radius);
}

html[data-tenant] .ant-color-picker-presets-label {
  color: var(--ds-colorpicker-label-color);
  font-size: var(--ds-colorpicker-label-font-size);
}

/* =============================================================================
   SWITCH (Toggle) - .ant-switch
   ============================================================================= */

html[data-tenant] .ant-switch {
  background: var(--ds-toggle-bg);
  min-width: var(--ds-toggle-md-width);
  height: var(--ds-toggle-md-height);
  border-radius: calc(var(--ds-toggle-md-height) / 2);
  transition: var(--ds-toggle-transition);
}

html[data-tenant] .ant-switch:hover:not(.ant-switch-disabled) {
  background: var(--ds-toggle-bg-hover);
}

html[data-tenant] .ant-switch-checked {
  background: var(--ds-toggle-checked-bg);
}

html[data-tenant] .ant-switch-checked:hover:not(.ant-switch-disabled) {
  background: var(--ds-toggle-checked-bg-hover);
}

html[data-tenant] .ant-switch-handle {
  width: var(--ds-toggle-md-thumb);
  height: var(--ds-toggle-md-thumb);
  top: var(--ds-toggle-thumb-offset);
  inset-inline-start: var(--ds-toggle-thumb-offset);
}

html[data-tenant] .ant-switch-handle::before {
  background: var(--ds-toggle-thumb-bg);
  box-shadow: var(--ds-toggle-thumb-shadow);
  border-radius: 50%;
}

html[data-tenant] .ant-switch-checked .ant-switch-handle {
  inset-inline-start: calc(100% - var(--ds-toggle-md-thumb) - var(--ds-toggle-thumb-offset));
}

html[data-tenant] .ant-switch:focus-visible {
  outline: none;
  box-shadow: var(--ds-toggle-focus-ring);
}

html[data-tenant] .ant-switch-disabled {
  opacity: var(--ds-toggle-disabled-opacity);
  background: var(--ds-toggle-disabled-bg);
}

/* Switch Sizes */
html[data-tenant] .ant-switch-small {
  min-width: var(--ds-toggle-sm-width);
  height: var(--ds-toggle-sm-height);
  border-radius: calc(var(--ds-toggle-sm-height) / 2);
}

html[data-tenant] .ant-switch-small .ant-switch-handle {
  width: var(--ds-toggle-sm-thumb);
  height: var(--ds-toggle-sm-thumb);
}

html[data-tenant] .ant-switch-small.ant-switch-checked .ant-switch-handle {
  inset-inline-start: calc(100% - var(--ds-toggle-sm-thumb) - var(--ds-toggle-thumb-offset));
}

/* =============================================================================
   COLLAPSE - .ant-collapse
   ============================================================================= */

html[data-tenant] .ant-collapse {
  background-color: var(--ds-collapse-bg);
  border-color: var(--ds-collapse-border-color);
  border-radius: var(--ds-collapse-radius);
}

html[data-tenant] .ant-collapse > .ant-collapse-item {
  border-color: var(--ds-collapse-border-color);
}

html[data-tenant] .ant-collapse > .ant-collapse-item:last-child {
  border-radius: 0 0 var(--ds-collapse-radius) var(--ds-collapse-radius);
}

html[data-tenant] .ant-collapse > .ant-collapse-item > .ant-collapse-header {
  padding: var(--ds-collapse-header-padding);
  background-color: var(--ds-collapse-header-bg);
  color: var(--ds-collapse-header-color);
  font-weight: var(--ds-collapse-header-font-weight);
  gap: var(--ds-collapse-header-gap);
}

html[data-tenant] .ant-collapse > .ant-collapse-item > .ant-collapse-header:hover {
  background-color: var(--ds-collapse-header-bg-hover);
}

html[data-tenant] .ant-collapse-content {
  background-color: var(--ds-collapse-content-bg);
  border-color: var(--ds-collapse-border-color);
}

html[data-tenant] .ant-collapse-content > .ant-collapse-content-box {
  padding: var(--ds-collapse-content-padding);
}

html[data-tenant] .ant-collapse .ant-collapse-expand-icon {
  color: var(--ds-collapse-icon-color);
  font-size: var(--ds-collapse-icon-size);
}

html[data-tenant] .ant-collapse-item-active > .ant-collapse-header .ant-collapse-expand-icon {
  color: var(--ds-collapse-icon-color-expanded);
}

/* Collapse borderless variant */
html[data-tenant] .ant-collapse-borderless {
  background-color: transparent;
  border: none;
}

html[data-tenant] .ant-collapse-borderless > .ant-collapse-item {
  border-bottom: 1px solid var(--ds-collapse-border-color);
}

/* Collapse ghost variant */
html[data-tenant] .ant-collapse-ghost {
  background-color: transparent;
  border: none;
}

html[data-tenant] .ant-collapse-ghost > .ant-collapse-item > .ant-collapse-header {
  background-color: transparent;
}

html[data-tenant] .ant-collapse-ghost > .ant-collapse-item > .ant-collapse-content {
  background-color: transparent;
  border: none;
}

/**
 * Modern framework token projection.
 *
 * This is deliberately NOT a tenant theme. BrandTheme (first-party products)
 * and compiled Appearance (DB-authored tenants) own the canonical `--ds-*`
 * values. This file only projects that resolved authority into the private
 * DaisyUI variable vocabulary required by the Modern engine.
 *
 * Contract:
 * - framework variables only; never define a canonical `--ds-*` token here;
 * - every value must resolve from a canonical `--ds-*` token;
 * - no literal color, typography, spacing, radius, border or motion values;
 * - product/page customisation stays above this layer through DS props, slots,
 *   recipes and scoped semantic tokens.
 */

[data-tenant] {
  /* DaisyUI colour vocabulary projected from the compiled DS authority. */
  --color-primary: var(--ds-color-primary);
  --color-primary-content: var(--ds-button-primary-color);
  --color-secondary: var(--ds-color-secondary);
  --color-secondary-content: var(--ds-button-secondary-color);
  --color-accent: var(--ds-color-accent);
  --color-accent-content: var(--ds-color-text-on-primary);
  --color-neutral: var(--ds-color-neutral-800);
  --color-neutral-content: var(--ds-color-text-inverse);
  --color-base-100: var(--ds-color-bg-primary);
  --color-base-200: var(--ds-color-bg-secondary);
  --color-base-300: var(--ds-color-bg-tertiary);
  --color-base-content: var(--ds-color-text-primary);
  --color-success: var(--ds-color-success);
  --color-success-content: var(--ds-button-success-color);
  --color-warning: var(--ds-color-warning);
  --color-warning-content: var(--ds-button-warning-color);
  --color-error: var(--ds-color-error);
  --color-error-content: var(--ds-button-error-color);
  --color-info: var(--ds-color-info);
  --color-info-content: var(--ds-button-info-color);

  /* DaisyUI 5 structural vocabulary. Do not reintroduce the removed Daisy 4
     `--rounded-*`, `--animation-*`, `--btn-focus-scale` or `--tab-*` names. */
  --radius-selector: var(--ds-radius-sm);
  --radius-field: var(--ds-radius-button);
  --radius-box: var(--ds-radius-lg);
  --size-selector: var(--ds-spacing-1);
  --size-field: var(--ds-spacing-1);
  --border: var(--ds-border-width-1);
  --depth: var(--ds-effect-intensity);
  --noise: var(--ds-effect-intensity);
}

/**
 * Modern Engine Theme - Rottay Design System
 *
 * Maps --ds-* design tokens to Tailwind CSS and DaisyUI component classes.
 * This file bridges the centralized token system with Tailwind CSS 4.x / DaisyUI 5.x.
 *
 * CONTRACT: This file defines ONE bridge to DaisyUI 5.
 * Legacy DaisyUI 4 variables (--p, --b1, etc.) are NOT supported.
 * All tenant CSS must provide --color-* in oklch format.
 *
 * Architecture:
 * - Uses [data-tenant] selector for tenant-scoped overrides
 * - All values reference --ds-* variables from default.css
 * - Covers all interactive states: hover, focus, active, disabled
 * - Maintains visual parity with the Classic engine
 *
 * @version 0.5.0
 * @engine Modern (Tailwind CSS 4.x / DaisyUI 5.x)
 */


/* =============================================================================
   BUTTON - .btn
   ============================================================================= */

[data-tenant] .btn {
  font-family: var(--ds-font-family-base);
  font-weight: var(--ds-button-font-weight);
  border-radius: var(--ds-button-md-radius);
  transition: var(--ds-button-transition);
  height: var(--ds-button-md-height);
  min-height: var(--ds-button-md-height);
  padding-left: var(--ds-button-md-padding-x);
  padding-right: var(--ds-button-md-padding-x);
  font-size: var(--ds-button-md-font-size);
  text-transform: none;
  letter-spacing: normal;
  will-change: transform;
}

[data-tenant] .btn:focus-visible {
  box-shadow: var(--ds-button-focus-ring);
  outline: none;
}

[data-tenant] .btn:hover:not(:disabled) {
  transform: var(--ds-button-hover-transform, translateY(0) scale(1));
}

[data-tenant] .btn:active:not(:disabled) {
  transform: var(--ds-button-active-transform, scale(0.98));
}

/* Primary Button */
[data-tenant] .btn-primary {
  background-color: var(--ds-button-primary-bg);
  border-color: var(--ds-button-primary-border);
  color: var(--ds-button-primary-color);
  box-shadow: var(--ds-button-primary-shadow);
}

[data-tenant] .btn-primary:hover:not(:disabled) {
  background-color: var(--ds-button-primary-bg-hover);
  border-color: var(--ds-button-primary-bg-hover);
  box-shadow: var(--ds-button-primary-shadow-hover);
  transform: var(--ds-button-hover-transform, translateY(0) scale(1));
}

[data-tenant] .btn-primary:active:not(:disabled) {
  background-color: var(--ds-button-primary-bg-active);
  transform: var(--ds-button-active-transform, scale(0.98));
}

/* Ghost Button */
[data-tenant] .btn-ghost {
  background-color: var(--ds-button-ghost-bg);
  border-color: var(--ds-button-ghost-border);
  color: var(--ds-button-ghost-color);
}

[data-tenant] .btn-ghost:hover:not(:disabled) {
  background-color: var(--ds-button-ghost-bg-hover);
  color: var(--ds-button-ghost-color-hover);
  transform: var(--ds-button-hover-transform, translateY(0) scale(1));
}

[data-tenant] .btn-ghost:active:not(:disabled) {
  background-color: var(--ds-button-ghost-bg-active);
  color: var(--ds-button-ghost-color-active);
  transform: var(--ds-button-active-transform, scale(0.98));
}

/* =============================================================================
   INPUT - .input
   ============================================================================= */

[data-tenant] .input {
  font-family: var(--ds-font-family-base);
  font-size: var(--ds-input-md-font-size);
  height: var(--ds-input-md-height);
  padding-left: var(--ds-input-md-padding-x);
  padding-right: var(--ds-input-md-padding-x);
  background-color: var(--ds-input-bg);
  border-color: var(--ds-input-border);
  border-radius: var(--ds-input-radius);
  color: var(--ds-input-color);
  transition: var(--ds-input-transition);
}

[data-tenant] .input::placeholder {
  color: var(--ds-input-color-placeholder);
}

[data-tenant] .input:hover:not(:disabled) {
  border-color: var(--ds-input-border-hover);
}

[data-tenant] .input:focus {
  border-color: var(--ds-input-border-focus);
  box-shadow: var(--ds-input-shadow-focus);
  outline: none;
}

[data-tenant] .input:disabled {
  background-color: var(--ds-input-bg-disabled);
  border-color: var(--ds-input-border-disabled);
  color: var(--ds-input-color-disabled);
  opacity: var(--ds-input-disabled-opacity);
  cursor: not-allowed;
}

/* =============================================================================
   CHECKBOX - .checkbox
   ============================================================================= */

[data-tenant] .checkbox {
  width: var(--ds-checkbox-size);
  height: var(--ds-checkbox-size);
  border-color: var(--ds-checkbox-border);
  border-radius: var(--ds-checkbox-radius);
  transition: var(--ds-transition-fast);
}

[data-tenant] .checkbox:hover:not(:disabled) {
  border-color: var(--ds-checkbox-border-hover);
}

[data-tenant] .checkbox:checked {
  background-color: var(--ds-checkbox-checked-bg);
  border-color: var(--ds-checkbox-checked-border);
}

[data-tenant] .checkbox:focus-visible {
  box-shadow: var(--ds-checkbox-focus-ring);
  outline: none;
}

/* =============================================================================
   RADIO - .radio
   ============================================================================= */

[data-tenant] .radio {
  width: var(--ds-radio-size);
  height: var(--ds-radio-size);
  border-color: var(--ds-radio-border);
  transition: var(--ds-transition-fast);
}

[data-tenant] .radio:hover:not(:disabled) {
  border-color: var(--ds-radio-border-hover);
}

[data-tenant] .radio:checked {
  background-color: var(--ds-radio-checked-bg);
  border-color: var(--ds-radio-checked-border);
}

[data-tenant] .radio:focus-visible {
  box-shadow: var(--ds-radio-focus-ring);
  outline: none;
}

/* MODAL — bridge drained. AlertDialog was the last modern consumer of the
   Daisy `.modal-box`/`.modal-backdrop`/`.modal-action` classes; it now paints
   from `skin/alert-dialog.css`, which reads the same `--ds-modal-*` tokens
   this bridge referenced (shadow, overlay backdrop, footer padding and gap),
   so tenant white-labelling is unchanged. The Modal primitive never consumed
   this block — its skins key on `.rottay-modal-*`/`.ds-modal*` instead. */

/* =============================================================================
   LOADING / SPINNER - .loading
   ============================================================================= */

[data-tenant] .loading {
  color: var(--ds-spinner-color);
}

/* =============================================================================
   MENU - .menu (Sidebar Navigation)
   ============================================================================= */

[data-tenant] .rottay-menu {
  list-style: none;
  padding: var(--ds-sidebar-shell-padding-inline, 14px);
  margin: 0;
}

[data-tenant] .rottay-menu li {
  list-style: none;
  margin-bottom: 2px;
}

[data-tenant] .rottay-menu li > a,
[data-tenant] .rottay-menu li > button {
  display: flex;
  align-items: center;
  gap: var(--ds-sidebar-item-gap, 10px);
  min-height: var(--ds-sidebar-item-height, 60px);
  padding: var(--ds-sidebar-item-padding, 0 18px);
  border-radius: var(--ds-radius-lg, 12px);
  color: var(--ds-text-secondary);
  background-color: transparent;
  transition:
    background-color var(--ds-motion-normal, 200ms)
      var(--ds-motion-ease-out, ease),
    color var(--ds-motion-normal, 200ms) var(--ds-motion-ease-out, ease);
  text-decoration: none;
  cursor: pointer;
  border: none;
  width: 100%;
  text-align: start;
  font-size: var(--ds-sidebar-item-font-size, 15.75px);
  font-weight: 500;
  line-height: 1.28;
}

[data-tenant] .rottay-menu li > a:hover,
[data-tenant] .rottay-menu li > button:hover {
  background-color: color-mix(
    in srgb,
    var(--ds-color-neutral-100) 92%,
    transparent
  );
  color: var(--ds-text-primary);
}

[data-tenant] .rottay-menu li > a.active,
[data-tenant] .rottay-menu li > button.active {
  background-color: color-mix(
    in srgb,
    var(--ds-color-primary-50) 78%,
    transparent
  );
  color: var(--ds-color-primary-800);
  font-weight: 600;
}

/* Menu Icons */
[data-tenant] .rottay-menu li > a > span:first-child,
[data-tenant] .rottay-menu li > button > span:first-child {
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  width: var(--ds-sidebar-icon-column-size, 22px);
  font-size: var(--ds-sidebar-icon-size, 17.5px);
}

/* Submenu (details/summary) */
[data-tenant] .rottay-menu details {
  margin-bottom: 2px;
}

[data-tenant] .rottay-menu details > summary {
  display: flex;
  align-items: center;
  gap: var(--ds-sidebar-item-gap, 10px);
  min-height: var(--ds-sidebar-item-height, 60px);
  padding: var(--ds-sidebar-item-padding, 0 18px);
  border-radius: var(--ds-radius-lg, 12px);
  color: var(--ds-text-secondary);
  background-color: transparent;
  transition:
    background-color var(--ds-motion-normal, 200ms)
      var(--ds-motion-ease-out, ease),
    color var(--ds-motion-normal, 200ms) var(--ds-motion-ease-out, ease);
  cursor: pointer;
  font-size: var(--ds-sidebar-item-font-size, 15.75px);
  font-weight: 500;
  line-height: 1.28;
  list-style: none;
}

[data-tenant] .rottay-menu details > summary::-webkit-details-marker {
  display: none;
}

[data-tenant] .rottay-menu details > summary:hover {
  background-color: color-mix(
    in srgb,
    var(--ds-color-neutral-100) 92%,
    transparent
  );
  color: var(--ds-text-primary);
}

[data-tenant] .rottay-menu details[open] > summary {
  color: var(--ds-text-primary);
  font-weight: 600;
}

[data-tenant] .rottay-menu details > ul {
  padding-left: var(--ds-sidebar-child-padding-inline, 8px);
  margin-top: 1px;
  margin-bottom: 3px;
}

/* Disabled state */
[data-tenant] .rottay-menu li > a.disabled,
[data-tenant] .rottay-menu li > button.disabled,
[data-tenant] .rottay-menu details > summary.disabled {
  opacity: 0.5;
  cursor: not-allowed;
  pointer-events: none;
}

/* Table cells and rows should not clip dropdown */
[data-tenant] table,
[data-tenant] tbody,
[data-tenant] tr,
[data-tenant] td {
  overflow: visible;
}

/* =============================================================================
   COLLAPSE / ACCORDION
   ============================================================================= */

/* Bridge: .rottay-collapse (modern engine) */
[data-tenant] .rottay-collapse {
  border-color: var(--ds-collapse-border);
  border-radius: var(--ds-collapse-radius);
}

[data-tenant] .rottay-collapse .rottay-collapse-content {
  background-color: var(--ds-collapse-content-bg);
  color: var(--ds-text-primary);
}

[data-tenant] .rottay-collapse--ghost {
  background-color: transparent;
}

[data-tenant] .rottay-collapse--borderless {
  border: none;
}

/* =============================================================================
   RANGE / SLIDER - .range
   ============================================================================= */
/* Bridge removed (K2-V drain): modern Slider/Rate engines no longer emit the
   Daisy `.range`/`.rating` classes — slider.css and rate.css are the single
   paint owners. The `--ds-slider-*`/`--ds-rate-*` token channels stay (the
   skins consume them). */
/* =============================================================================
   TOAST - .toast
   ============================================================================= */
/* Bridge removed (Message drain): the modern Message engine no longer emits
   the Daisy `.toast`/`toast-top`/`toast-bottom`/`toast-center` placement
   classes — skin/message.css is the single paint owner for its stack. The
   six `--ds-toast-*` tokens this bridge referenced were declared nowhere, so
   the rules were already inert. The Toast primitive never consumed this
   block (its skins key on `.rottay-toast-*` classes only). */

/* LINK — bridge drained. FileManager's folder anchor was the last modern
   consumer of the Daisy `link` class; its affordance now lives in
   `skin/file-manager.css` on `.ds-file-manager__folder-link`, resolving the
   colour through `--ds-color-link`/`--ds-color-link-hover`. The Link primitive
   never consumed this block (its skin keys on `.rottay-link-shell--modern`). */

/* TIMELINE — bridge drained. The Timeline pattern was the last modern consumer
   of the Daisy `timeline*` classes; the rail now paints from
   `skin/pattern-timeline.css`, which keeps `--ds-timeline-line-color` and
   `--ds-timeline-line-width` in its fallback chain. `.timeline::before` was
   already inert — a `::before` with no `content` never generates a box. The
   Timeline primitive drained the same classes earlier (`skin/timeline.css`). */

/* =============================================================================
   TREE
   ============================================================================= */

/* Bridge: .rottay-tree (modern engine) */
[data-tenant] .rottay-tree {
  background-color: var(--ds-tree-bg);
}

[data-tenant] .rottay-tree .rottay-tree-node {
  padding: var(--ds-tree-node-padding);
  color: var(--ds-tree-node-color);
  transition: var(--ds-transition-fast);
}

[data-tenant] .rottay-tree .rottay-tree-node:hover {
  background-color: var(--ds-tree-node-bg-hover);
}

/* =============================================================================
   EMPTY
   ============================================================================= */

/* Bridge: .rottay-empty (modern engine) */
[data-tenant] .rottay-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: var(--ds-empty-padding);
  color: var(--ds-text-secondary);
}

[data-tenant] .rottay-empty__footer {
  margin-top: 0.5rem;
}

/* =============================================================================
   QRCODE
   ============================================================================= */

/* Bridge: .rottay-qrcode (modern engine) */
[data-tenant] .rottay-qrcode {
  border-radius: var(--ds-qrcode-border-radius);
  border-color: var(--ds-qrcode-border-color);
  background-color: var(--ds-qrcode-background-color);
}

[data-tenant] .rottay-qrcode[data-status="loading"] {
  opacity: var(--ds-qrcode-loading-opacity);
  background-color: var(--ds-qrcode-loading-bg);
}

[data-tenant] .rottay-qrcode[data-status="expired"] {
  opacity: var(--ds-qrcode-status-expired-opacity);
}

[data-tenant] .rottay-qrcode[data-status="scanned"] {
  opacity: var(--ds-qrcode-status-scanned-opacity);
}

@media (prefers-reduced-motion: reduce) {
  [data-tenant] .rottay-menu li > a,
  [data-tenant] .rottay-menu li > button,
  [data-tenant] .rottay-menu details > summary {
    transition: none;
  }
}

/**
 * Modern framework compatibility bridge.
 *
 * Temporary ownership boundary for legacy DaisyUI compatibility selectors,
 * utility shims and raw-control normalization that have not yet migrated to
 * protected DS anatomy. New component paint is forbidden here. Each rule is
 * tenant-scoped and this file is reduced as individual primitives graduate.
 */

/* =============================================================================
   INPUT - Mejoras adicionales
   ============================================================================= */

[data-tenant] .input {
  width: 100%;
  height: var(--ds-input-md-height, 40px);
  padding: 0 12px;
  font-size: 14px;
  background-color: var(--ds-input-bg);
  border: 1px solid var(--ds-border-color);
  border-radius: var(--ds-input-radius, 8px);
  color: var(--ds-text-primary);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  outline: none;
}

[data-tenant] .input::placeholder {
  color: var(--ds-text-tertiary);
}

[data-tenant] .input:hover:not(:disabled):not(:focus) {
  border-color: var(--ds-input-border-hover);
}

[data-tenant] .input:focus {
  border-color: var(--ds-color-primary-500);
  box-shadow: 0 0 0 3px var(--ds-color-primary-100);
}

[data-tenant] .input:disabled {
