/* XL breakpoint (1280px) */
@media (min-width: 1280px) {
  [data-tenant] .rottay-grid[data-cols-xl="1"] {
    grid-template-columns: repeat(1, minmax(0, 1fr));
  }
  [data-tenant] .rottay-grid[data-cols-xl="2"] {
