.rottay-stack[data-justify="space-around"] {
  justify-content: space-around;
}

.rottay-stack[data-justify="space-evenly"] {
  justify-content: space-evenly;
}

.rottay-stack[data-spacing="none"] {
  --_ds-stack-gap-current: 0;
}

.rottay-stack[data-spacing="xs"] {
  --_ds-stack-gap-current: var(--ds-spacing-1);
}

.rottay-stack[data-spacing="sm"] {
  --_ds-stack-gap-current: var(--ds-spacing-2);
