}

/* A consumer's numeric gap is exact geometry: honored as-is, never
   density-scaled. */
.rottay-stack[data-spacing="custom"] {
  --_ds-stack-gap-current: var(--ds-stack-gap);
}

.rottay-stack[data-full-width="true"] {
  width: 100%;
}

.rottay-stack[data-full-height="true"] {
  height: 100%;
}

/* Optional Stack separators are structural children. Their size follows the
   active flex axis automatically, so the same contract works in LTR, RTL,
   horizontal and vertical stacks without physical-side paint. The negative
   main-axis margins of half the current gap center the hairline INSIDE the
   governed rhythm: two neighbors keep exactly one gap between them instead
   of gap + divider + gap (measured as a doubled seam in dense lists). The
   margins ride the root-declared axis flags so a RESPONSIVE direction (which
   stamps no data-direction attribute) still lands the hairline on the right
   axis at every breakpoint. */
.rottay-stack > .rottay-stack-divider[data-part="divider"] {
  align-self: stretch;
  flex: 0 0 var(--ds-stack-divider-size, 1px);
  min-inline-size: 0;
  min-block-size: 0;
  margin-block: var(
    --_ds-proto-stack-divider-gap-block,
    calc(var(--_ds-stack-gap-current, 0px) / -2)
  );
  margin-inline: var(
    --_ds-proto-stack-divider-gap-inline,
    var(--ds-stack-divider-inset, 0px)
  );
  background: var(
    --ds-stack-divider-color,
    var(--ds-color-border-subtle)
  );
  opacity: var(--ds-stack-divider-opacity, 0.72);
  pointer-events: none;
}

@media (forced-colors: active) {
  /* The hairline is structural: it must survive color stripping. */
  .rottay-stack > .rottay-stack-divider[data-part="divider"] {
    background: ButtonText;
    opacity: 1;
  }
}

/* Container is intentionally a quiet structural canvas. Vertical/tenant
   finish arrives through compiler-owned variables; consumer inline styles
   remain the final override layer. `max-inline-size` is logical so the
   fluid rule below actually lifts the cap (a physical `max-width` would
   survive it) and RTL stays neutral. */
.rottay-container.rottay-container--modern[data-part="root"] {
  inline-size: 100%;
  min-inline-size: 0;
  box-sizing: border-box;
  max-inline-size: var(
    --ds-container-instance-max-width,
    var(--ds-container-lg, 1024px)
  );
  padding: var(--ds-container-instance-padding, var(--ds-spacing-4));
  background: var(--ds-container-background, transparent);
  border: var(--ds-container-border, 0 solid transparent);
  border-radius: var(--ds-container-radius, 0);
  box-shadow: var(--ds-container-shadow, none);
  transition: max-inline-size
      var(--ds-container-motion-duration, var(--ds-motion-normal))
      var(--ds-container-motion-easing, var(--ds-motion-ease-out)),
    padding
      var(--ds-container-motion-duration, var(--ds-motion-normal))
      var(--ds-container-motion-easing, var(--ds-motion-ease-out)),
    margin var(--ds-container-motion-duration, var(--ds-motion-normal))
      var(--ds-container-motion-easing, var(--ds-motion-ease-out)),
    background-color
      var(--ds-container-motion-duration, var(--ds-motion-normal))
      var(--ds-container-motion-easing, var(--ds-motion-ease-out)),
    border-color
      var(--ds-container-motion-duration, var(--ds-motion-normal))
      var(--ds-container-motion-easing, var(--ds-motion-ease-out)),
    box-shadow
      var(--ds-container-motion-duration, var(--ds-motion-normal))
      var(--ds-container-motion-easing, var(--ds-motion-ease-out));
}

.rottay-container.rottay-container--modern[data-centered="true"] {
  margin-inline: auto;
}

.rottay-container.rottay-container--modern[data-fluid="true"] {
  max-inline-size: none;
}

/* Responsive media frames use the same material channel as every other
   layout primitive, without owning product-specific imagery or gradients. */
.rottay-aspect-ratio.rottay-aspect-ratio--modern[data-part="root"] {
  position: relative;
  inline-size: 100%;
  min-inline-size: 0;
  max-inline-size: var(--ds-aspect-ratio-instance-max-width, none);
  aspect-ratio: var(--ds-aspect-ratio-instance-ratio, 16 / 9);
  overflow: var(--ds-aspect-ratio-overflow, hidden);
  box-sizing: border-box;
  background: var(--ds-aspect-ratio-background, transparent);
  border: var(--ds-aspect-ratio-border, 0 solid transparent);
  border-radius: var(--ds-aspect-ratio-radius, 0);
  box-shadow: var(--ds-aspect-ratio-shadow, none);
  transition: aspect-ratio
      var(--ds-aspect-ratio-motion-duration, var(--ds-motion-normal))
      var(--ds-aspect-ratio-motion-easing, var(--ds-motion-ease-out)),
    max-inline-size
      var(--ds-aspect-ratio-motion-duration, var(--ds-motion-normal))
      var(--ds-aspect-ratio-motion-easing, var(--ds-motion-ease-out)),
    border-radius
      var(--ds-aspect-ratio-motion-duration, var(--ds-motion-normal))
      var(--ds-aspect-ratio-motion-easing, var(--ds-motion-ease-out)),
    background-color
      var(--ds-aspect-ratio-motion-duration, var(--ds-motion-normal))
      var(--ds-aspect-ratio-motion-easing, var(--ds-motion-ease-out)),
    border-color
      var(--ds-aspect-ratio-motion-duration, var(--ds-motion-normal))
      var(--ds-aspect-ratio-motion-easing, var(--ds-motion-ease-out)),
    box-shadow
      var(--ds-aspect-ratio-motion-duration, var(--ds-motion-normal))
      var(--ds-aspect-ratio-motion-easing, var(--ds-motion-ease-out));
}

/* Replaced media fills the frame without distortion: cover by default,
   optically centered, both decisions on tenant channels. `display: block`
   removes the inline baseline strut, whose extra line-box slack would paint a
   letterbox sliver the moment a tenant opens `--ds-aspect-ratio-overflow` to
   `visible` (the reserved ratio box must match the media box exactly). */
.rottay-aspect-ratio.rottay-aspect-ratio--modern[data-part="root"]
  > :where(img, video, canvas, iframe) {
  display: block;
  inline-size: 100%;
  block-size: 100%;
  object-fit: var(--ds-aspect-ratio-object-fit, cover);
  object-position: var(--ds-aspect-ratio-object-position, center);
}

/* A <picture> wrapper (art direction, format fallback) is an inline,
   non-replaced element: left at its defaults it collapses to the baseline
   strut and the inner <img> never receives the frame geometry -- the reserved
   ratio box then paints empty or letterboxed media. The wrapper becomes a
   block fill and forwards the same governed object-fit/object-position
   channels to its img, so art-directed media honors the frame exactly like a
   direct child. */
.rottay-aspect-ratio.rottay-aspect-ratio--modern[data-part="root"]
  > :where(picture) {
  display: block;
  inline-size: 100%;
  block-size: 100%;
}

.rottay-aspect-ratio.rottay-aspect-ratio--modern[data-part="root"]
  > :where(picture) > img {
  display: block;
  inline-size: 100%;
  block-size: 100%;
  object-fit: var(--ds-aspect-ratio-object-fit, cover);
  object-position: var(--ds-aspect-ratio-object-position, center);
}

.rottay-space.rottay-space--modern[data-part="root"] {
  display: inline-flex;
  flex-direction: row;
  flex-wrap: nowrap;
  align-items: center;
  min-inline-size: 0;
  max-inline-size: 100%;
  /* Ramp-first fallback: `--ds-space-small-size` stays as the compat alias a
     tenant may already set, but the terminal value is the DS spacing ramp so
     a spacing refinement moves Space together with Stack (pre-flag 9). */
  gap: var(
    --ds-space-instance-gap,
    var(--ds-space-small-size, var(--ds-spacing-2))
  );
  transition: gap
      var(--ds-space-motion-duration, var(--ds-motion-fast))
      var(--ds-space-motion-easing, var(--ds-motion-ease-out)),
    align-items var(--ds-space-motion-duration, var(--ds-motion-fast))
      var(--ds-space-motion-easing, var(--ds-motion-ease-out));
}

/* Density-aware preset gaps. The engine projects presets as the legacy
   `--ds-space-*-size` aliases, which `presentation/components/space.css`
   declares as fixed rem values that never track the density profile -- so a
   compact density shrank Stack but left Space untouched. Keyed on the preset
   `data-size` spellings only (raw numbers and [h, v] arrays stay exact
   geometry, the same law Stack declares for custom gaps), the preset terminal
   now scales with `--ds-density-effective-scale` exactly like the
   `--ds-spacing-*` ramp it aliases. `:where()` keeps this at the root rule's
   specificity so source order -- not escalation -- decides. */
.rottay-space.rottay-space--modern[data-part="root"]:where(
  [data-size="small"],
  [data-size="middle"],
  [data-size="large"],
  [data-size="sm"],
  [data-size="md"],
  [data-size="lg"]
) {
  gap: calc(
    var(
        --ds-space-instance-gap,
        var(--ds-space-small-size, var(--ds-spacing-2))
      ) *
      var(--ds-density-effective-scale)
  );
}

.rottay-space.rottay-space--modern[data-direction="vertical"] {
  flex-direction: column;
}

.rottay-space.rottay-space--modern[data-wrap="true"] {
  flex-wrap: wrap;
}

.rottay-space.rottay-space--modern[data-align="start"] {
  align-items: flex-start;
}

.rottay-space.rottay-space--modern[data-align="end"] {
  align-items: flex-end;
}

.rottay-space.rottay-space--modern[data-align="baseline"] {
  align-items: baseline;
}

.rottay-space.rottay-space--modern
  > .rottay-space-separator[data-part="separator"] {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
}

@media (prefers-reduced-motion: reduce) {
  .rottay-container.rottay-container--modern[data-part="root"],
  .rottay-aspect-ratio.rottay-aspect-ratio--modern[data-part="root"],
  .rottay-space.rottay-space--modern[data-part="root"] {
    transition: none;
  }
}

}

/* Engine skins stay bounded inside the DS engine layer. */
@layer rottay-engines {
/**
 * Modern Button skin.
 *
 * The React engine owns semantics, anatomy and interaction state. This file
 * owns paint and geometry exclusively through public --ds-button-* channels.
 * Product code can compose the primitive, but it never needs to restyle its
 * internals for hover, press, focus, busy, touch, RTL or high contrast.
 */

/* -------------------------------------------------------------------------
   Anatomy and geometry
   ------------------------------------------------------------------------- */

.rottay-button.rottay-button--modern[data-part='trigger'] {
  --ds-button-resolved-icon-size: var(--ds-button-md-icon-size);
  --_ds-button-resolved-radius: var(--ds-button-md-radius);
  --ds-button-resolved-height: var(--ds-button-md-height);
  --ds-button-resolved-padding-y: var(--ds-button-md-padding-y);

  position: relative;
  isolation: isolate;
  display: inline-flex;
  box-sizing: border-box;
  align-items: center;
  justify-content: center;
  min-inline-size: 0;
  max-inline-size: 100%;
  block-size: calc(
    var(--ds-button-resolved-height) * var(--ds-density-effective-scale)
  );
  gap: calc(var(--ds-button-gap) * var(--ds-density-effective-scale));
  padding-block: 0;
  appearance: none;
  overflow: clip;
  cursor: pointer;
  user-select: none;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;

  font-family: var(--ds-button-font-family);
  font-weight: var(--ds-button-font-weight);
  line-height: 1;
  letter-spacing: var(--ds-button-letter-spacing);
  text-align: center;
  text-decoration: none;
  text-transform: var(--ds-button-text-transform);
  white-space: nowrap;

  border-width: var(--ds-button-border-width);
  border-style: solid;
  border-radius: var(--_ds-button-resolved-radius);
  outline: none;

  transition:
    transform var(--ds-button-transition-duration) var(--ds-button-transition-timing),
    background-color var(--ds-button-transition-duration) var(--ds-button-transition-timing),
    background-position var(--ds-motion-reveal) var(--ds-button-transition-timing),
    border-color var(--ds-button-transition-duration) var(--ds-button-transition-timing),
    box-shadow var(--ds-button-transition-duration) var(--ds-button-transition-timing),
    color var(--ds-button-transition-duration) var(--ds-button-transition-timing),
    filter var(--ds-button-transition-duration) var(--ds-button-transition-timing),
    opacity var(--ds-button-transition-duration) var(--ds-button-transition-timing);
}

/* A quiet optical highlight gives solid controls material depth without
   inventing another app-owned gradient. It is a public token channel and is
   deliberately absent from text, ghost and link controls. As the decoration
   layer of the material stack it rides the governed `--ds-effect-intensity`
   dial: at 0 the sheen disappears while base, border, state channels and the
   focus ring keep the hierarchy intact. */
.rottay-button.rottay-button--modern:is(
    [data-variant='primary'],
    [data-variant='secondary'],
    [data-variant='default'],
    [data-variant='outline'],
    [data-variant='dashed'],
    [data-variant='danger'],
    [data-variant='success'],
    [data-variant='warning'],
    [data-variant='info'],
    [data-variant='ai']
  )::before {
  position: absolute;
  z-index: 0;
  inset: 0;
  border-radius: inherit;
  background: var(--ds-button-surface-highlight);
  opacity: calc(
    var(--ds-button-surface-highlight-opacity) * var(--ds-effect-intensity)
  );
  pointer-events: none;
  content: '';
  transition: opacity var(--ds-button-transition-duration)
    var(--ds-button-transition-timing);
}

.rottay-button.rottay-button--modern [data-part='content'],
.rottay-button.rottay-button--modern [data-part='busy-content'],
.rottay-button.rottay-button--modern [data-part='content-frame'],
.rottay-button.rottay-button--modern [data-part='icon'],
.rottay-button.rottay-button--modern [data-part='prefix'],
.rottay-button.rottay-button--modern [data-part='suffix'] {
  display: inline-flex;
  min-inline-size: 0;
  align-items: center;
  justify-content: center;
}

.rottay-button.rottay-button--modern [data-part='content'],
.rottay-button.rottay-button--modern [data-part='busy-content'],
.rottay-button.rottay-button--modern [data-part='content-frame'] {
  position: relative;
  z-index: 1;
}

.rottay-button.rottay-button--modern [data-part='content'],
.rottay-button.rottay-button--modern [data-part='busy-content'] {
  gap: inherit;
  max-inline-size: 100%;
}

.rottay-button.rottay-button--modern [data-part='label'] {
  min-inline-size: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  translate: 0 var(--ds-button-label-offset-y);
}

.rottay-button.rottay-button--modern [data-part='icon'] {
  flex: 0 0 auto;
  inline-size: var(--ds-button-resolved-icon-size);
  block-size: var(--ds-button-resolved-icon-size);
  transition: transform var(--ds-button-transition-duration)
    var(--ds-button-transition-timing);
}

.rottay-button.rottay-button--modern [data-part='icon'] > svg {
  inline-size: 100%;
  block-size: 100%;
}

.rottay-button.rottay-button--modern [data-part='spinner'] {
  flex: 0 0 var(--ds-button-resolved-icon-size);
  inline-size: var(--ds-button-resolved-icon-size);
  block-size: var(--ds-button-resolved-icon-size);
  color: var(--ds-button-spinner-color);
  animation: ds-button-spin var(--ds-button-spinner-duration) linear infinite;
}

.rottay-button.rottay-button--modern [data-part='spinner-track'],
.rottay-button.rottay-button--modern [data-part='spinner-indicator'] {
  stroke-width: var(--ds-button-spinner-stroke-width);
}

.rottay-button.rottay-button--modern [data-part='spinner-track'] {
  opacity: var(--ds-button-spinner-track-opacity);
}

.rottay-button.rottay-button--modern [data-part='content-frame'] {
  position: relative;
  inline-size: 100%;
}

.rottay-button.rottay-button--modern [data-part='content'][data-layer='reserve'] {
  visibility: hidden;
}

.rottay-button.rottay-button--modern [data-part='content'][data-state='hidden'] {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.rottay-button.rottay-button--modern [data-part='content-frame'] > [data-part='busy-content'] {
  position: absolute;
  inset: 0;
  overflow: hidden;
}

/* The busy accessible label renders through the canonical `VisuallyHidden`
   primitive (`.ds-visually-hidden`, owned by
   presentation/components/visually-hidden.css) — this family no longer keeps
   a local clip rule for it. */

.rottay-button.rottay-button--modern[data-full-width='true'] {
  display: flex;
  inline-size: 100%;
  min-block-size: calc(
    var(--ds-button-resolved-height) * var(--ds-density-effective-scale)
  );
  block-size: auto;
  padding-block: calc(
    var(--ds-button-resolved-padding-y) * var(--ds-density-effective-scale)
  );
  white-space: normal;
}

.rottay-button.rottay-button--modern[data-full-width='true'] [data-part='content'],
.rottay-button.rottay-button--modern[data-full-width='true'] [data-part='content-frame'] {
  inline-size: 100%;
}

.rottay-button.rottay-button--modern[data-full-width='true'] [data-part='label'] {
  overflow-wrap: anywhere;
  text-overflow: clip;
}

/* -------------------------------------------------------------------------
   Size and shape
   ------------------------------------------------------------------------- */

.rottay-button.rottay-button--modern[data-size='xs']:not([data-size-responsive]) {
  --ds-button-resolved-icon-size: var(--ds-button-xs-icon-size);
  --_ds-button-resolved-radius: var(--ds-button-xs-radius);
  --ds-button-resolved-height: var(--ds-button-xs-height);
  --ds-button-resolved-padding-y: var(--ds-button-xs-padding-y);
  padding-inline: calc(
    var(--ds-button-xs-padding-x) * var(--ds-density-effective-scale)
  );
  gap: calc(var(--ds-button-xs-gap) * var(--ds-density-effective-scale));
  font-size: var(--ds-button-xs-font-size);
  line-height: var(--ds-button-xs-line-height);
}

.rottay-button.rottay-button--modern[data-size='sm']:not([data-size-responsive]) {
  --ds-button-resolved-icon-size: var(--ds-button-sm-icon-size);
