/* base */
.rottay-button.rottay-button--rustic[data-part='trigger'] {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: auto;
  min-width: auto;
  font-weight: 500;
  font-family: inherit;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  white-space: nowrap;
  vertical-align: middle;
  cursor: pointer;
  opacity: 1;
  transition: var(--ds-button-transition, all 150ms ease);
  outline: none;
  box-sizing: border-box;
  user-select: none;
  /* disables double-tap zoom on mobile, removing the 300ms click delay */
  touch-action: manipulation;
  box-shadow: none;
  /* explicit identity so `transition` has a value to animate from */
  transform: translateY(0) scale(1);
  animation: none;
}

/* variant, at rest */
.rottay-button.rottay-button--rustic[data-part='trigger'][data-variant='primary'] {
