  --_ds-card-radius-current: var(--ds-card-radius);
}
.ds-card.ds-card--modern[data-part='root'][data-radius='lg'] {
  border-radius: var(--ds-card-radius-lg);
  --_ds-card-radius-current: var(--ds-card-radius-lg);
}
.ds-card.ds-card--modern[data-part='root'][data-radius='xl'] {
  border-radius: var(--ds-card-radius-xl);
  --_ds-card-radius-current: var(--ds-card-radius-xl);
}

/* variant, at rest */
.ds-card.ds-card--modern[data-part='root'][data-variant='elevated'] {
  background-color: var(--ds-card-elevated-bg, var(--ds-card-bg, var(--ds-surface-card)));
  background-image: linear-gradient(var(--ds-card-elevation-surface), var(--ds-card-elevation-surface)), var(--ds-card-surface-gradient, var(--ds-gradient-surface));
  border: var(--ds-card-elevated-border-width) solid var(--ds-card-border);
