  border-style: var(--ds-card-border-style);
}
.ds-card.ds-card--modern[data-part='root'][data-bordered='false'] {
  border-color: transparent;
}
.ds-card.ds-card--modern[data-part='root'][data-shadowed='true'] {
  box-shadow: var(--ds-card-shadow);
}
.ds-card.ds-card--modern[data-part='root'][data-shadowed='false'] {
  box-shadow: none;
}

/* The shared hover fill is a white-label state channel, independent from the
   selected/pressed terminal states below. Semantic tones retain their hue and
   use the state wash instead. Gated to hover-capable pointers (see above). */
@media (hover: hover) {
  .ds-card.ds-card--modern[data-part='root'][data-interactive='true'][data-state~='hovered']:not([data-tone]):not([data-selected='true']):not([data-disabled='true']) {
    background-color: var(--ds-card-bg-hover, var(--ds-material-card-background-hover, var(--ds-card-bg)));
  }

  /* hover, only on an interactive card, and only where the variant answers */
  .ds-card.ds-card--modern[data-part='root'][data-interactive='true'][data-variant='elevated'][data-state~='hovered']:not([data-disabled='true']) {
    --ds-elevation-lift: 1;
  }
  .ds-card.ds-card--modern[data-part='root'][data-interactive='true'][data-variant='elevated'][data-state~='hovered']:not([data-disabled='true']):not([data-shadowed='false']) {
    box-shadow: var(--ds-card-elevated-shadow-hover, var(--ds-card-shadow-hover));
  }
  .ds-card.ds-card--modern[data-part='root'][data-interactive='true'][data-variant='outlined'][data-state~='hovered']:not([data-tone]):not([data-disabled='true']) {
    border-color: var(--ds-card-border-accent-hover, var(--ds-card-border-hover, var(--ds-card-border-color-hover, var(--ds-color-border-secondary))));
  }
}
.ds-card.ds-card--modern[data-part='root'][data-interactive='true'][data-state~='pressed']:not([data-disabled='true']) {
  transform: var(--ds-card-active-transform, translateY(0) scale(0.995));
  color: var(--ds-card-color-active, var(--ds-card-color));
  background-color: var(--ds-card-bg-active, var(--ds-material-card-background-active, var(--ds-card-bg)));
  border-color: var(--ds-card-border-active, var(--ds-card-border-hover, var(--ds-card-border)));
}
.ds-card.ds-card--modern[data-part='root'][data-interactive='true'][data-state~='pressed']:not([data-disabled='true']):not([data-shadowed='false']) {
  box-shadow: var(--ds-card-shadow-active, var(--ds-card-shadow));
}
.ds-card.ds-card--modern[data-part='root'][data-interactive='true'][data-state~='pressed']:not([data-disabled='true'])::after {
  opacity: var(--ds-card-state-overlay-active-opacity);
}

.ds-card.ds-card--modern[data-part='root'][data-selectable='true'][data-selected='true']:not([data-disabled='true']) {
  color: var(--ds-card-color-selected, var(--ds-card-color));
  background-color: var(--ds-card-bg-selected, var(--ds-material-card-background-selected, var(--ds-card-bg)));
  border-color: var(--ds-card-border-selected, var(--ds-color-primary));
  outline: var(--ds-card-selected-outline-width, var(--ds-card-border-width)) solid var(--ds-card-border-selected, var(--ds-color-primary));
  outline-offset: calc(-1 * var(--ds-card-selected-outline-width, var(--ds-card-border-width)));
}
.ds-card.ds-card--modern[data-part='root'][data-selectable='true'][data-selected='true']:not([data-disabled='true']):not([data-shadowed='false']) {
  box-shadow: var(--ds-card-shadow-selected, var(--ds-card-focus-ring));
}
.ds-card.ds-card--modern[data-part='root'][data-selectable='true'][data-selected='true']:not([data-disabled='true'])::after {
  opacity: var(--ds-card-state-overlay-selected-opacity);
}

/* Focus is an outline, so it never destroys tenant elevation or selection. */
.ds-card.ds-card--modern[data-part='root'][data-actionable='true'][data-state~='focus-visible']:not([data-disabled='true']) {
  outline: var(--ds-card-focus-ring-width, var(--ds-focus-ring-width)) solid var(--ds-card-focus-ring-color, var(--ds-focus-ring-color));
  outline-offset: var(--ds-card-focus-ring-offset);
}

/* colour tone: it wins the border and the fill, and it suppresses the surface tint */
.ds-card.ds-card--modern[data-part='root'][data-tone='primary'] {
  border-color: var(--ds-card-primary-border-color, var(--ds-color-primary));
  background-color: var(--ds-card-primary-bg, color-mix(in srgb, var(--ds-color-primary) 8%, var(--ds-card-bg)));
  background-image: none;
}
.ds-card.ds-card--modern[data-part='root'][data-tone='success'] {
  border-color: var(--ds-card-success-border-color, var(--ds-color-success));
  background-color: var(--ds-card-success-bg, color-mix(in srgb, var(--ds-color-success) 8%, var(--ds-card-bg)));
  background-image: none;
}
.ds-card.ds-card--modern[data-part='root'][data-tone='warning'] {
  border-color: var(--ds-card-warning-border-color, var(--ds-color-warning));
  background-color: var(--ds-card-warning-bg, color-mix(in srgb, var(--ds-color-warning) 8%, var(--ds-card-bg)));
  background-image: none;
}
.ds-card.ds-card--modern[data-part='root'][data-tone='error'] {
  border-color: var(--ds-card-error-border-color, var(--ds-color-error));
  background-color: var(--ds-card-error-bg, color-mix(in srgb, var(--ds-color-error) 8%, var(--ds-card-bg)));
  background-image: none;
}
.ds-card.ds-card--modern[data-part='root'][data-tone='info'] {
  border-color: var(--ds-card-info-border-color, var(--ds-color-info));
  background-color: var(--ds-card-info-bg, color-mix(in srgb, var(--ds-color-info) 8%, var(--ds-card-bg)));
  background-image: none;
}

/* Explicit frame suppression remains authoritative after semantic tones. */
.ds-card.ds-card--modern[data-part='root'][data-bordered='false'] {
  border-color: transparent;
}

/* Selection stays legible on semantic materials without becoming a side rail. */
.ds-card.ds-card--modern[data-part='root'][data-selectable='true'][data-selected='true'][data-tone]:not([data-disabled='true']) {
  outline: var(--ds-card-selected-outline-width, var(--ds-card-border-width)) solid var(--ds-card-border-selected, var(--ds-color-primary));
  outline-offset: calc(-1 * var(--ds-card-selected-outline-width, var(--ds-card-border-width)));
}
.ds-card.ds-card--modern[data-part='root'][data-selectable='true'][data-selected='true'][data-tone]:not([data-disabled='true']):not([data-shadowed='false']) {
  box-shadow: var(--ds-card-shadow-selected, var(--ds-card-focus-ring));
}

/* ===========================================================================
 * WO-SKIN-05 checkpoint D1 — everything the ARC-07 migration left inline: the
 * loading state, and the header/body/actions text and rules.
 *
 * Loading shares the exact same root contract as the ready state. `data-loading`
 * distinguishes the placeholder cover from the real cover wrapper, keeping
 * radius, tenant material and accessibility state stable while content resolves.
 *
 * The `:not(.rottay-card-header)` guard on the header is equally load-bearing.
 * `Card.Header` is a compound a caller can drop into `children`, where it lands as
 * a direct child of `[data-part='body']` — exactly where this engine renders its
 * OWN header. Both stamp `data-part='header'` and `data-part='title'`, and their
 * token fallback chains differ, so without the guard this rule would repaint the
 * compound. The compound has its own file: components/skin/card-compounds.css.
 *
 * SPECIFICITY (P-48): the header and actions rules carry a border colour and must
 * clear the tenant's unlayered `*` border-color floor at (0,3,1); their selector
 * chains are far past it. They stay SHORTHANDS because preflight zeroes
 * `border-width` on every element.
 * ======================================================================== */

/* ---- loading: the cover placeholder (a fill the real cover wrapper never has) ---- */
.ds-card.ds-card--modern[data-part='root'][data-loading='true'] > [data-part='cover'] {
  height: var(--ds-card-cover-height, var(--ds-card-cover-min-height));
  opacity: var(--ds-card-loading-cover-opacity);
  background-color: var(--ds-surface-inset);
}

/* ---- loading: the four skeleton bars share one fill and one radius; only their
        widths and heights differ, and those stay inline ---- */
.ds-card.ds-card--modern[data-part='root'][data-loading='true'] [data-part='skeleton'] [data-part='skeleton-bar'] {
  background-color: var(--ds-card-skeleton-bg, var(--ds-surface-inset));
  background-image: linear-gradient(
    100deg,
    transparent 18%,
    var(--ds-card-skeleton-highlight) 48%,
    transparent 78%
  );
  background-size: 220% 100%;
  border-radius: var(--ds-card-skeleton-radius, var(--ds-radius-sm));
  animation: ds-card-skeleton-sweep var(--ds-card-skeleton-duration, var(--ds-motion-glacial)) var(--ds-card-transition-timing) infinite;
}
.ds-card.ds-card--modern[data-part='root'][data-loading='true'] [data-part='skeleton'] {
  display: flex;
  flex-direction: column;
  gap: var(--ds-card-skeleton-gap, var(--ds-spacing-3));
  opacity: var(--ds-card-loading-skeleton-opacity);
}
.ds-card.ds-card--modern[data-part='root'][data-loading='true'] [data-part='skeleton-stack'] {
  display: flex;
  flex-direction: column;
  gap: var(--ds-card-skeleton-stack-gap, var(--ds-spacing-2));
  margin-block-start: var(--ds-card-skeleton-stack-margin-top, var(--ds-spacing-1));
}

/* ---- loading: the frosted spinner scrim ---- */
.ds-card.ds-card--modern[data-part='root'][data-loading='true'] [data-part='loading-overlay'] {
  position: absolute;
  inset: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 1;
  backdrop-filter: blur(var(--ds-card-loading-backdrop-blur));
  -webkit-backdrop-filter: blur(var(--ds-card-loading-backdrop-blur));
  background-color: var(--ds-card-loading-overlay-bg, color-mix(in srgb, var(--ds-surface-card) 60%, transparent));
  border-radius: inherit;
  transition: opacity var(--ds-motion-feedback) var(--ds-motion-ease-enter);
}
.ds-card.ds-card--modern[data-part='root'][data-loading='true'] [data-part='spinner'] {
  display: block;
  width: var(--ds-card-spinner-size);
  height: var(--ds-card-spinner-size);
  border: var(--ds-card-spinner-stroke) solid var(--ds-card-spinner-track, var(--ds-color-border));
  border-block-start-color: var(--ds-card-spinner-color, var(--ds-color-primary));
  border-radius: 50%;
  animation: ds-card-spinner-rotate var(--ds-card-spinner-duration, var(--ds-motion-glacial)) linear infinite;
}

/* ---- body ---- */
.ds-card.ds-card--modern[data-part='root'] {
  --ds-card-padding-current: var(--ds-card-padding-md, var(--ds-card-md-padding));
}
.ds-card.ds-card--modern[data-part='root'][data-padding='none'] {
  --ds-card-padding-current: 0;
}
.ds-card.ds-card--modern[data-part='root'][data-padding='sm'] {
  --ds-card-padding-current: var(--ds-card-padding-sm, var(--ds-card-sm-padding));
}
.ds-card.ds-card--modern[data-part='root'][data-padding='lg'] {
  --ds-card-padding-current: var(--ds-card-padding-lg, var(--ds-card-lg-padding));
}

/* size axis: density scaling of the header copy and body text. `md`/`lg` keep
   the baseline above; compact sizes de-escalate, amplified sizes scale up.
   The `-current` channels leave the tenant's explicit `--ds-card-*-font-size`
   untouched as each rule's fallback, so BrandTheme still wins by default. */
.ds-card.ds-card--modern[data-part='root'][data-size='xs'],
.ds-card.ds-card--modern[data-part='root'][data-size='sm'] {
  --_ds-card-title-font-size-current: var(--ds-card-title-font-size-sm, var(--ds-font-size-base));
  --_ds-card-body-font-size-current: var(--ds-card-body-font-size-sm, var(--ds-font-size-sm));
}
.ds-card.ds-card--modern[data-part='root'][data-size='xl'],
.ds-card.ds-card--modern[data-part='root'][data-size='2xl'],
.ds-card.ds-card--modern[data-part='root'][data-size='3xl'] {
  --_ds-card-title-font-size-current: var(--ds-card-title-font-size-lg, var(--ds-font-size-xl));
}
.ds-card.ds-card--modern[data-part='root'] > [data-part='body'] {
  min-inline-size: 0;
  padding: var(--ds-card-instance-padding, var(--ds-card-padding-current));
  color: var(--ds-card-body-color);
  font-size: var(--_ds-card-body-font-size-current, var(--ds-card-body-font-size));
  line-height: var(--ds-card-body-line-height);
  overflow-wrap: anywhere;
  /* Nested-material grammar: the corner a card nested in this body should
     wear. Concentric derivation — the parent's resolved radius minus the
     body inset, bounded at 8px so generous padding never collapses the
     nested corner to a square. Published on the body (not the root) so a
     nested card reads the PARENT's value through inheritance while its own
     body recomputes for the next level down. */
  --_ds-card-nest-radius: max(
    0px,
    calc(var(--_ds-card-radius-current, var(--ds-card-radius)) - min(var(--ds-card-instance-padding, var(--ds-card-padding-current, 0px)), 8px))
  );
}
.ds-card.ds-card--modern[data-part='root'] > [data-part='loading-content'] {
  position: relative;
  min-block-size: var(--ds-card-skeleton-min-height, 120px);
  padding: var(--ds-card-instance-padding, var(--ds-card-padding-current));
}
.ds-card.ds-card--modern[data-part='root'] > [data-part='cover'] {
  overflow: hidden;
  line-height: 0;
}
.ds-card.ds-card--modern[data-part='root'] > [data-part='cover'] > [data-part='cover-image'] {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: var(--ds-card-cover-object-fit, var(--ds-card-media-object-fit));
  object-position: var(--ds-card-cover-object-position);
}

.ds-card.ds-card--modern[data-part='root'][data-cover-position='top'] > [data-part='cover'],
.ds-card.ds-card--modern[data-part='root'][data-cover-position='bottom'] > [data-part='cover'] {
  aspect-ratio: var(--ds-card-cover-aspect-ratio, var(--ds-card-media-aspect-ratio));
}

.ds-card.ds-card--modern[data-part='root'][data-cover-position='start'],
.ds-card.ds-card--modern[data-part='root'][data-cover-position='end'] {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
}
.ds-card.ds-card--modern[data-part='root'][data-cover-position='start'] > [data-part='cover'],
.ds-card.ds-card--modern[data-part='root'][data-cover-position='end'] > [data-part='cover'] {
  flex: 1 1 var(--ds-card-cover-inline-size);
  min-inline-size: min(100%, var(--ds-card-cover-inline-min-size));
  min-block-size: var(--ds-card-cover-block-min-size);
}
.ds-card.ds-card--modern[data-part='root'][data-cover-position='start'] > [data-part='body'],
.ds-card.ds-card--modern[data-part='root'][data-cover-position='end'] > [data-part='body'] {
  flex: 999 1 var(--ds-card-body-inline-min-size);
}

/* ---- this engine's OWN header (never the Card.Header compound) ---- */
.ds-card.ds-card--modern[data-part='root'] > [data-part='body'] > [data-part='header']:not(.rottay-card-header) {
  display: flex;
  /* title copy and the trailing actions share one text baseline instead of
     hanging from unrelated top edges; in the stacked container composition
     below the cross axis stretches instead. */
  align-items: baseline;
  justify-content: space-between;
  gap: var(--ds-card-header-gap, var(--ds-card-header-actions-gap));
}
.ds-card.ds-card--modern[data-part='root'] > [data-part='body'] > [data-part='header']:not(.rottay-card-header)[data-divider='true'] {
  padding-block-end: var(--ds-card-header-padding-bottom);
  margin-block-end: var(--ds-card-header-padding-bottom);
  border-block-end: var(--ds-card-header-border-width) solid var(--ds-card-header-border, var(--ds-color-border));
}
.ds-card.ds-card--modern[data-part='root'] > [data-part='body'] > [data-part='header']:not(.rottay-card-header) > [data-part='extra'] {
  flex: 0 0 auto;
  max-inline-size: 100%;
  margin-inline-start: var(--ds-card-header-actions-gap);
}
.ds-card.ds-card--modern[data-part='root'] > [data-part='body'] > [data-part='header']:not(.rottay-card-header) > [data-part='header-main'] {
  flex: 1 1 auto;
  min-inline-size: 0;
}
.ds-card.ds-card--modern[data-part='root'] > [data-part='body'] > [data-part='header']:not(.rottay-card-header) > [data-part='header-main'] > [data-part='title'] {
  margin: 0;
  color: var(--ds-card-title-color, var(--ds-card-header-color, var(--ds-color-text-primary)));
  font-family: var(--ds-font-family-heading, var(--ds-font-family-base));
  font-size: var(--_ds-card-title-font-size-current, var(--ds-card-title-font-size));
  font-weight: var(--ds-card-title-font-weight);
  line-height: var(--ds-card-title-line-height);
  letter-spacing: var(--ds-card-title-letter-spacing, var(--ds-letter-spacing-heading));
  overflow-wrap: anywhere;
  text-wrap: balance;
}
.ds-card.ds-card--modern[data-part='root'] > [data-part='body'] > [data-part='header']:not(.rottay-card-header) > [data-part='header-main'] > [data-part='description'] {
  color: var(--ds-card-subtitle-color, var(--ds-color-text-secondary));
  font-size: var(--ds-card-subtitle-font-size);
  line-height: var(--ds-card-body-line-height);
  max-inline-size: var(--ds-card-header-copy-max-width);
  overflow-wrap: anywhere;
  text-wrap: pretty;
}
.ds-card.ds-card--modern[data-part='root'] > [data-part='body'] > [data-part='header']:not(.rottay-card-header) > [data-part='header-main'] > [data-part='description'][data-has-title='true'] {
  margin-block-start: var(--ds-card-subtitle-margin-top);
}

/* ---- actions rail (layout was inline in the engine until the R2+R3 pass;
        the skin now owns the row: flex, wrap, justify, gap and rhythm) ---- */
.ds-card.ds-card--modern[data-part='root'] > [data-part='body'] > [data-part='actions'] {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: var(--ds-card-actions-justify, flex-end);
  /* the tenant footer border wins when emitted; the shared premium contract
     supplies the quieter default hairline */
  border-block-start: var(--ds-card-footer-border-width) solid var(--ds-card-footer-border, var(--ds-premium-card-footer-border, var(--ds-color-border)));
  background-color: var(--ds-card-footer-bg);
  gap: var(--ds-card-actions-gap, var(--ds-spacing-2));
  margin-block-start: var(--ds-card-actions-margin-top, var(--ds-spacing-4));
  padding-block-start: var(--ds-card-actions-padding-top, var(--ds-spacing-4));
}
.ds-card.ds-card--modern[data-part='root'] > [data-part='body'] > [data-part='actions'] > * {
  max-inline-size: 100%;
}
/* empty-region safety: with no header and no content, the rail is the body's
   only region — its rhythm margin must not become a phantom top gap. */
.ds-card.ds-card--modern[data-part='root'] > [data-part='body'] > [data-part='actions']:first-child {
  margin-block-start: 0;
}

@container (max-width: 28rem) {
  .ds-card.ds-card--modern[data-part='root'] {
    --ds-card-actions-justify: stretch;
  }

  .ds-card.ds-card--modern[data-part='root'] > [data-part='body'] > [data-part='header']:not(.rottay-card-header) {
    flex-direction: column;
    /* stacked composition: full-width regions, no cross-axis baseline hunt */
    align-items: stretch;
  }

  .ds-card.ds-card--modern[data-part='root'] > [data-part='body'] > [data-part='header']:not(.rottay-card-header) > [data-part='extra'] {
    inline-size: 100%;
    margin-inline-start: 0;
  }

  .ds-card.ds-card--modern[data-part='root'][data-cover-position='start'] > [data-part='cover'],
  .ds-card.ds-card--modern[data-part='root'][data-cover-position='end'] > [data-part='cover'] {
    flex-basis: 100%;
    min-block-size: 0;
    aspect-ratio: var(--ds-card-cover-aspect-ratio, var(--ds-card-media-aspect-ratio));
  }

  .ds-card.ds-card--modern[data-part='root'] > [data-part='body'] > [data-part='actions'] > * {
    flex: 1 1 auto;
  }
}

/* ===========================================================================
 * Anatomy variants (W4-A). `cardComponent.anatomy` in the tenant chrome compiles
 * to a `data-anatomy-card` attribute on the DS root; the closed vocabulary lives
 * in TENANT_THEME_ANATOMY_VARIANTS and is enforced by anatomy-variant-gate.mjs.
 * `default`/absent selects the base rendering above and needs no rule here.
 *
 * Each block prefixes the anatomy attribute onto the base root chain and REPEATS
 * `[data-part='root']`, reaching (0,5,0): one attribute over the (0,4,0)
 * variant/tone/radius rules it governs, so it wins in the same unlayered origin
 * without `!important`. Anatomy is a cross-variant frame treatment; the
 * per-instance variant still colours within the frame the anatomy defines. State
 * rules (hover/focus at (0,6,0)+) intentionally still react on top of the frame.
 * ======================================================================== */

/* framed: an explicit full border + surface shadow, uniform across variants. The
   shadow/radius reach every framed card; the neutral border is added only to an
   untoned card, so a toned card keeps its tone frame. */
[data-anatomy-card='framed'] .ds-card.ds-card--modern[data-part='root'][data-part='root'] {
  border-radius: var(--ds-card-radius);
  box-shadow: var(--ds-card-shadow, var(--ds-elevation-1));
}
[data-anatomy-card='framed'] .ds-card.ds-card--modern[data-part='root'][data-part='root']:not([data-tone]) {
  border: var(--ds-card-border-width) solid var(--ds-card-border, var(--ds-color-border-subtle));
}

/* underline: no side/top borders, one block-end hairline, tighter radius, no lift. */
[data-anatomy-card='underline'] .ds-card.ds-card--modern[data-part='root'][data-part='root'] {
  border: 0;
  border-block-end: var(--ds-card-underline-border-width, 1px) solid var(--ds-card-border, var(--ds-color-border-subtle));
  border-radius: var(--ds-card-radius-sm);
  box-shadow: none;
}

/* ghost: no frame at rest; an interactive ghost card tints only on hover
   (gated to hover-capable pointers like every other hover paint above). */
[data-anatomy-card='ghost'] .ds-card.ds-card--modern[data-part='root'][data-part='root'] {
  border: 0;
  box-shadow: none;
  background-color: transparent;
  background-image: none;
}
@media (hover: hover) {
  [data-anatomy-card='ghost'] .ds-card.ds-card--modern[data-part='root'][data-part='root'][data-interactive='true'][data-state~='hovered']:not([data-disabled='true']) {
    background-color: var(--ds-card-bg-hover, color-mix(in srgb, var(--ds-color-text-primary) 5%, transparent));
  }
}

/* Nesting: a card rendered inside another card's body is grouping, not a new
