/* the expand/selection header cells share the data-part; their fixed 48px
   column width is keyed on the explicit `data-cell-kind` */
.ds-table.ds-table--modern [data-part='header-cell'][data-cell-kind='expand'],
.ds-table.ds-table--modern [data-part='header-cell'][data-cell-kind='selection'] {
  width: calc(var(--_ds-proto-table-utility-column-width, 48px) * var(--ds-density-effective-scale));
}

/* ---- sortable header: affordance + keyboard focus ring. Hover paints only
        under (hover: hover); the ungated :active is the touch equivalent.
        The hover wash consumes the opaque `--ds-table-header-bg-hover` mix so
        a sticky header never turns translucent mid-scroll. ---- */
.ds-table.ds-table--modern [data-part='header-cell'][data-sortable='true'] {
  cursor: pointer;
  user-select: none;
  transition:
    color var(--ds-motion-fast),
    background-color var(--ds-motion-fast);
}
.ds-table.ds-table--modern [data-part='header-cell'][data-sortable='true']:focus-visible {
  outline: var(--ds-focus-ring-width) solid var(--ds-focus-ring-color, var(--ds-color-primary));
  outline-offset: calc(-1 * var(--ds-focus-ring-offset));
}
@media (hover: hover) {
  .ds-table.ds-table--modern [data-part='header-cell'][data-sortable='true']:hover {
    background: var(
      --ds-table-header-bg-hover,
      color-mix(in srgb, var(--ds-color-primary) 5%, var(--ds-table-header-bg, var(--ds-surface-inset)))
    );
    color: var(--ds-color-primary);
  }
  .ds-table.ds-table--modern [data-part='header-cell'][data-sortable='true']:hover [data-part='sort-indicator'] {
    opacity: 1;
  }
}
.ds-table.ds-table--modern [data-part='header-cell'][data-sortable='true']:active {
  background: var(
    --ds-table-header-bg-hover,
    color-mix(in srgb, var(--ds-color-primary) 8%, var(--ds-table-header-bg, var(--ds-surface-inset)))
  );
}

/* ---- header cell content: title + sort indicator + resize handle ---- */
.ds-table.ds-table--modern [data-part='header-content'] {
  display: flex;
  align-items: center;
  gap: 4px;
  position: relative;
}
.ds-table.ds-table--modern [data-part='header-title'] {
  flex: 1;
  /* flex items refuse to shrink below their content width by default; the
     zero floor + break-word let long tenant headers wrap instead of forcing
     the column wide */
  min-inline-size: 0;
  overflow-wrap: break-word;
}

/* ---- sort indicator: rotates with the sort order. The affordance rests
        quiet (60%) but the ACTIVE order reads at a glance: full opacity and
        the primary tone, so the sorted column is legible without hunting. ---- */
.ds-table.ds-table--modern [data-part='sort-indicator'] {
  font-size: var(--ds-font-size-xs);
  opacity: 0.6;
  display: inline-block;
  transition:
    transform var(--ds-motion-normal),
    opacity var(--ds-motion-fast);
  transform: rotate(0deg);
}
.ds-table.ds-table--modern [data-part='sort-indicator'][data-order='ascend'],
.ds-table.ds-table--modern [data-part='sort-indicator'][data-order='descend'] {
  opacity: 1;
  color: var(--ds-color-primary);
}
.ds-table.ds-table--modern [data-part='sort-indicator'][data-order='descend'] {
  transform: rotate(180deg);
}

/* ---- resize handle: a live drag, and a hover the pointer paints. The edge
        is logical so the handle tracks the column's inline-end in RTL. ---- */
.ds-table.ds-table--modern [data-part='resize-handle'] {
  position: absolute;
  inset-inline-end: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  cursor: col-resize;
}
.ds-table.ds-table--modern [data-part='resize-handle'][data-resizing='true'] {
  background: color-mix(in srgb, var(--ds-color-primary) 60%, transparent);
}
@media (hover: hover) {
  .ds-table.ds-table--modern [data-part='resize-handle']:not([data-resizing='true']):hover {
    background: color-mix(in srgb, var(--ds-color-primary) 40%, transparent);
  }
}

/* ---- filter row + its inputs ---- */
.ds-table.ds-table--modern [data-part='filter-row'] {
  background: var(--ds-table-header-bg, var(--ds-surface-inset));
  transition: background-color var(--ds-motion-normal);
}
.ds-table.ds-table--modern [data-part='filter-spacer'] {
  width: calc(var(--_ds-proto-table-utility-column-width, 48px) * var(--ds-density-effective-scale));
}
.ds-table.ds-table--modern [data-part='filter-cell'] {
  padding: 4px;
}
/* the filter row is the bottom edge of the header band: when the header
   hairline is on, the row closes with the same keyline so the body does not
   bleed into the filter inputs */
.ds-table.ds-table--modern [data-part='filter-cell'][data-hairline='true'],
.ds-table.ds-table--modern [data-part='filter-spacer'][data-hairline='true'] {
  border-bottom: 1px solid var(--ds-table-border, var(--ds-color-border));
}

/* ---- fields: filter input, and the editable text/number/date/select cells.
        `data-field` ('filter' | 'edit') is stamped for cross-engine contract
        parity with rustic, whose two field kinds paint different borders;
        modern paints both kinds identically, so one declaration block serves
        both selectors. ---- */
.ds-table.ds-table--modern [data-part='field'][data-field='filter'],
.ds-table.ds-table--modern [data-part='field'][data-field='edit'] {
  width: 100%;
  padding: 2px 6px;
  font-size: var(--ds-font-size-xs);
  border: 1px solid var(--ds-color-border);
  border-radius: var(--ds-radius-sm);
  background: var(--ds-surface-card);
  color: var(--ds-color-text-primary);
  outline: none;
}
.ds-table.ds-table--modern select[data-part='field'][data-field='edit'] {
  appearance: auto;
}
.ds-table.ds-table--modern [data-part='field'][data-field='filter'] {
  transition: border-color var(--ds-motion-normal);
}
/* keyboard focus: the base rule zeroes the UA outline, so the governed focus
   ring must be re-asserted or the filter/edit fields leave keyboard users
   blind (B2.5) */
.ds-table.ds-table--modern [data-part='field'][data-field]:focus-visible {
  outline: var(--ds-focus-ring-width) solid var(--ds-focus-ring-color, var(--ds-color-primary));
  outline-offset: 1px;
}

/* ---- selection controls: checkbox/radio row-selection inputs (including
        select-all) + the editable checkbox cell ---- */
.ds-table.ds-table--modern [data-part='selection-control'] {
  width: 16px;
  height: 16px;
  cursor: pointer;
  accent-color: var(--ds-color-primary);
}
.ds-table.ds-table--modern [data-part='selection-control']:focus-visible {
  outline: var(--ds-focus-ring-width) solid var(--ds-focus-ring-color, var(--ds-color-primary));
  outline-offset: 1px;
}
/* getCheckboxProps({ disabled: true }) rows: readable but unmistakably
   inactive, and never swept up by select-all (the hook skips them) */
.ds-table.ds-table--modern [data-part='selection-control']:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}
/* ---- selection hit area: the `<label>` wrapping every row-selection control
        (and select-all). On fine pointers it is an invisible layout box that
        centers the control in the cell (matching the skeleton's centered
        control well). On coarse pointers it grows to fill the whole cell --
        negative margins cancel the per-size cell padding -- so the entire
        48px column toggles natively. The block reach stays capped by the
        dense row: a full 44px reach would swallow the neighboring row's
        target (the density law the header resize handle documents). ---- */
.ds-table.ds-table--modern [data-part='selection-hit'] {
  display: flex;
  align-items: center;
  justify-content: center;
}

/* ---- muted text: empty-state cell, footer, pagination range ---- */
.ds-table.ds-table--modern [data-part='empty-cell'] {
  text-align: center;
  padding: 32px 0;
}
.ds-table.ds-table--modern [data-part='empty-cell'],
.ds-table.ds-table--modern [data-part='footer'],
.ds-table.ds-table--modern [data-part='pagination-range'] {
  color: var(--ds-color-text-secondary);
}
.ds-table.ds-table--modern [data-part='footer'] {
  margin-block-start: var(--ds-table-footer-margin-block-start, 8px);
  font-size: var(--ds-font-size-sm);
}
.ds-table.ds-table--modern [data-part='pagination-range'] {
  font-size: var(--ds-font-size-sm);
  /* The range readout is pure numerals and separators (Quiet Premium numeral
     law, pagination.css's `--ds-pagination-numeric` precedent). */
  font-variant-numeric: var(--ds-table-pagination-numeric, tabular-nums);
}

/* ---- metric cells: numeric columns align figures in columns (the hook is
        the engine-stamped `data-field-type`, additive anatomy). ---- */
.ds-table.ds-table--modern [data-part='cell'][data-field-type='number'],
.ds-table.ds-table--modern [data-part='cell'][data-field-type='date'] {
  font-variant-numeric: var(--ds-table-cell-numeric, tabular-nums);
}

/* ---- body row: selected fill, and the hover a non-selected hoverable row
        takes. Hover paints only where hover exists (button.css idiom): on
        touch columns the wash would stick after the tap. ---- */
.ds-table.ds-table--modern [data-part='row'][data-hoverable='true'] {
  transition: background-color var(--ds-motion-normal);
}
.ds-table.ds-table--modern [data-part='row'][data-selected='true'] {
  background: color-mix(in srgb, var(--ds-color-primary) 10%, transparent);
}
/* selection reads as a framed band, not a bare tint: a quiet primary keyline
   closes the row's bottom edge (never the ONLY signal -- the checked control
   carries the state for color-blind and forced-colors users) */
.ds-table.ds-table--modern [data-part='row'][data-selected='true'] > td {
  box-shadow: inset 0 -1px 0 0 color-mix(in srgb, var(--ds-color-primary) 30%, transparent);
}
@media (hover: hover) {
  .ds-table.ds-table--modern [data-part='row'][data-hoverable='true']:not([data-selected='true']):hover {
    background: var(--ds-table-row-bg-hover, color-mix(in srgb, var(--ds-color-primary) 5%, transparent));
  }
}

/* ---- body cell: bottom border in `bordered` mode, long-copy resilience, and
        the editable-cell hover ---- */
.ds-table.ds-table--modern [data-part='cell'] {
  /* unbroken strings (URLs, ids) wrap instead of blowing out fixed layouts */
  overflow-wrap: break-word;
}
.ds-table.ds-table--modern [data-part='cell'][data-bordered='true'] {
  border-bottom: 1px solid var(--ds-table-border, var(--ds-color-border));
}
.ds-table.ds-table--modern [data-part='cell'][data-editable='true'] {
  cursor: pointer;
  transition:
    outline-color var(--ds-motion-fast) var(--ds-motion-ease-out),
    background-color var(--ds-motion-fast) var(--ds-motion-ease-out);
}
@media (hover: hover) {
  .ds-table.ds-table--modern [data-part='cell'][data-editable='true']:hover {
    outline: 1px dashed color-mix(in srgb, var(--ds-color-primary) 30%, transparent);
    outline-offset: -1px;
    background: color-mix(in srgb, var(--ds-color-primary) 5%, transparent);
  }
}

/* ---- pinned/fixed columns: sticky positioning with an opaque fill so
        scrolled content cannot bleed through. Applies to header and body
        cells; the offsets (and the edge keylines below) are physical because
        the `fixed` column contract is itself physical ('left' | 'right').
        Filter cells join the pinning: the filter row is part of the header
        band, and an unpinned filter cell would scroll away under its own
        stuck column. ---- */
.ds-table.ds-table--modern [data-part='cell'][data-fixed],
.ds-table.ds-table--modern [data-part='header-cell'][data-fixed],
.ds-table.ds-table--modern [data-part='filter-cell'][data-fixed] {
  position: sticky;
  z-index: 10;
  background: var(--ds-table-bg, var(--ds-surface-card));
  /* the pinned state fills (hover/selected, below) track the row's wash on
     the same motion channel instead of snapping a frame behind it */
  transition: background-color var(--ds-motion-normal);
}
/* a pinned HEADER-band cell (header cell or filter cell) takes the header
   fill, not the body fill, or the corner tiles read lighter/darker than
   their row */
.ds-table.ds-table--modern [data-part='header-cell'][data-fixed],
.ds-table.ds-table--modern [data-part='filter-cell'][data-fixed] {
  background: var(--ds-table-header-bg, var(--ds-surface-inset));
}
.ds-table.ds-table--modern [data-fixed='true'],
.ds-table.ds-table--modern [data-fixed='left'] {
  left: 0;
}
.ds-table.ds-table--modern [data-fixed='right'] {
  right: 0;
}
/* the corner where a sticky header meets a pinned column must float above
   BOTH planes (body fixed cells: 10, sticky header: 20; the loading overlay
   stays on top at 30) or scrolling neighbors slide over it */
.ds-table.ds-table--modern [data-part='header-cell'][data-sticky='true'][data-fixed] {
  z-index: 25;
}
/* pinned-edge keylines: an inset shadow glued to the cell box, so the
   separation line tracks the column through scroll and resize without the
   collapsed-border detachment the header hairline already guards against */
.ds-table.ds-table--modern [data-part='cell'][data-fixed='left'],
.ds-table.ds-table--modern [data-part='cell'][data-fixed='true'],
.ds-table.ds-table--modern [data-part='header-cell'][data-fixed='left'],
.ds-table.ds-table--modern [data-part='header-cell'][data-fixed='true'],
.ds-table.ds-table--modern [data-part='filter-cell'][data-fixed='left'],
.ds-table.ds-table--modern [data-part='filter-cell'][data-fixed='true'] {
  box-shadow: inset -1px 0 0 0 var(--ds-table-border, var(--ds-color-border));
}
.ds-table.ds-table--modern [data-part='cell'][data-fixed='right'],
.ds-table.ds-table--modern [data-part='header-cell'][data-fixed='right'],
.ds-table.ds-table--modern [data-part='filter-cell'][data-fixed='right'] {
  box-shadow: inset 1px 0 0 0 var(--ds-table-border, var(--ds-color-border));
}
/* corner cells carry BOTH keylines (pinned edge + header hairline shadow) */
.ds-table.ds-table--modern [data-part='header-cell'][data-sticky='true'][data-hairline='true'][data-fixed='left'],
.ds-table.ds-table--modern [data-part='header-cell'][data-sticky='true'][data-hairline='true'][data-fixed='true'] {
  box-shadow:
    inset -1px 0 0 0 var(--ds-table-border, var(--ds-color-border)),
    inset 0 -1px 0 0 var(--ds-table-border, var(--ds-color-border));
}
.ds-table.ds-table--modern [data-part='header-cell'][data-sticky='true'][data-hairline='true'][data-fixed='right'] {
  box-shadow:
    inset 1px 0 0 0 var(--ds-table-border, var(--ds-color-border)),
    inset 0 -1px 0 0 var(--ds-table-border, var(--ds-color-border));
}
/* state fills on pinned body cells: the opaque base fill would otherwise
   swallow the row's hover/selected wash, making a selected row's pinned
   columns read unselected. The mixes stay opaque (no bleed-through). */
@media (hover: hover) {
  .ds-table.ds-table--modern [data-part='row'][data-hoverable='true']:not([data-selected='true']):hover > [data-part='cell'][data-fixed] {
    background: var(
      --ds-table-row-bg-hover,
      color-mix(in srgb, var(--ds-color-primary) 5%, var(--ds-table-bg, var(--ds-surface-card)))
    );
  }
}
.ds-table.ds-table--modern [data-part='row'][data-selected='true'] > [data-part='cell'][data-fixed] {
  background: color-mix(in srgb, var(--ds-color-primary) 10%, var(--ds-table-bg, var(--ds-surface-card)));
}

/* ---- expand column ---- */
.ds-table.ds-table--modern [data-part='expand-cell'] {
  width: calc(var(--_ds-proto-table-utility-column-width, 48px) * var(--ds-density-effective-scale));
  text-align: center;
}
.ds-table.ds-table--modern [data-part='selection-cell'] {
  width: calc(var(--_ds-proto-table-utility-column-width, 48px) * var(--ds-density-effective-scale));
}
.ds-table.ds-table--modern [data-part='expand-button'] {
  height: 24px;
  padding: 0 8px;
  font-size: var(--ds-font-size-xs);
  cursor: pointer;
  transition:
    color var(--ds-motion-normal) var(--ds-motion-ease-out),
    background-color var(--ds-motion-normal) var(--ds-motion-ease-out);
  background: transparent;
  color: var(--ds-color-text-primary);
  border: none;
  border-radius: var(--ds-radius-md);
}
.ds-table.ds-table--modern [data-part='expand-indicator'] {
  display: inline-block;
  transition: transform var(--ds-motion-normal);
  transform: rotate(0deg);
}
.ds-table.ds-table--modern [data-part='expand-indicator'][data-expanded='true'] {
  transform: rotate(90deg);
}
/* Sighted RTL: the collapsed chevron mirrors through the icon facade
   (`NavigationForwardIcon` auto-mirror flips the svg), so a 90° clockwise
   turn would land the expanded glyph pointing UP. The wrapper counter-rotates
   and the mirrored arrow still settles pointing down (the collapse.css
   sighted-RTL idiom; no double-mirror -- the skin never flips the glyph). */
.ds-table.ds-table--modern [data-part='expand-indicator'][data-expanded='true']:dir(rtl) {
  transform: rotate(-90deg);
}
/* hover wash (fine pointers) + pressed state (the touch equivalent): the
   button already carried the transitions but no states were painted */
@media (hover: hover) {
  .ds-table.ds-table--modern [data-part='expand-button']:hover {
    background: color-mix(in srgb, var(--ds-color-primary) 8%, transparent);
    color: var(--ds-color-primary);
  }
}
.ds-table.ds-table--modern [data-part='expand-button']:active {
  background: color-mix(in srgb, var(--ds-color-primary) 12%, transparent);
}

/* ---- expanded row content ---- */
.ds-table.ds-table--modern [data-part='expanded-row'] {
  background: var(--ds-table-row-bg-striped, var(--ds-surface-inset));
}
.ds-table.ds-table--modern [data-part='expanded-row'] > td {
  padding: 16px;
  animation: ds-table-expand-modern var(--ds-motion-slow) ease-out;
}

/* ---- first-load skeleton: row-shaped placeholders that mirror the real
        anatomy (control wells + one bar per column), painted with the
        canonical `ds-skeleton-shimmer` keyframes (the stats-grid.css idiom).
        Widths vary per row so the stack reads as data, not a striped box.
        The control-well override comes last at equal specificity so the
        16px square beats the per-row width variants. ---- */
.ds-table.ds-table--modern [data-part='skeleton-bar'] {
  display: block;
  block-size: 12px;
  inline-size: 72%;
  border-radius: var(--ds-radius-sm);
  background: linear-gradient(
    90deg,
    var(--ds-surface-panel) 25%,
    var(--ds-surface-inset) 50%,
    var(--ds-surface-panel) 75%
  );
  background-size: 200% 100%;
  animation: ds-skeleton-shimmer var(--ds-motion-attention) ease-in-out infinite;
}
.ds-table.ds-table--modern [data-part='skeleton-row']:nth-child(2n) [data-part='skeleton-bar'] {
  inline-size: 58%;
}
.ds-table.ds-table--modern [data-part='skeleton-row']:nth-child(3n) [data-part='skeleton-bar'] {
  inline-size: 66%;
}
.ds-table.ds-table--modern [data-part='skeleton-row'] [data-part='skeleton-cell'][data-kind='control'] [data-part='skeleton-bar'] {
  inline-size: 16px;
  block-size: 16px;
  margin-inline: auto;
}

/* ---- loading overlay + spinner. The spinner needs (0,4,0): its
        `border-top-color` longhand would otherwise lose to the tenant `*`
        border-color floor and never show the primary colour. ---- */
.ds-table.ds-table--modern [data-part='loading-overlay'] {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 30;
  background: color-mix(in srgb, var(--ds-table-bg, var(--ds-surface-card)) 50%, transparent);
}
.ds-table.ds-table--modern [data-part='spinner'][data-part='spinner'] {
  display: inline-block;
  width: 24px;
  height: 24px;
  animation: ds-foundation-spin var(--ds-motion-glacial) linear infinite;
  border: 2px solid var(--ds-color-border);
  border-top-color: var(--ds-color-primary);
  border-radius: 50%;
}

/* ---- scroll container: horizontal overflow always, vertical bounds stay
        inline (they project the consumer's `scroll.y` contract). The
        container paints the themed table base (the `--ds-table-bg` channel
        the pinned cells already used piecemeal, so pinned and scrolling
        regions now share one continuous fill) plus a pure-CSS scroll-shadow
        affordance: two `scroll`-attached radial shadows mark a clipped edge,
        two `local`-attached covers of the same base color erase each shadow
        when its edge is reached. Physical gradients track the physical
        scrollport, so the affordance mirrors itself under RTL with no
        logical-property wiring. ---- */
.ds-table.ds-table--modern [data-part='scroll-container'] {
  overflow-x: auto;
  background-color: var(--ds-table-bg, var(--ds-surface-card));
  background-image:
    linear-gradient(to right, var(--ds-table-bg, var(--ds-surface-card)) 30%, transparent),
    linear-gradient(to left, var(--ds-table-bg, var(--ds-surface-card)) 30%, transparent),
    radial-gradient(farthest-side at 0% 50%, color-mix(in srgb, var(--ds-color-text-primary) 16%, transparent), transparent),
    radial-gradient(farthest-side at 100% 50%, color-mix(in srgb, var(--ds-color-text-primary) 16%, transparent), transparent);
  background-position: left top, right top, left top, right top;
  background-size: 24px 100%, 24px 100%, 10px 100%, 10px 100%;
  background-repeat: no-repeat;
  background-attachment: local, local, scroll, scroll;
}
.ds-table.ds-table--modern [data-part='scroll-container'][data-loading='true'] {
  opacity: 0.5;
}
.ds-table.ds-table--modern [data-part='scroll-container'][data-resizing='true'] {
  user-select: none;
}

/* ---- pagination controls ---- */
.ds-table.ds-table--modern [data-part='pagination'] {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 8px;
  margin-block-start: var(--ds-table-pagination-margin-block-start, 16px);
}
.ds-table.ds-table--modern [data-part='pagination-controls'] {
  display: inline-flex;
}
.ds-table.ds-table--modern [data-part='pagination-button'] {
  height: 32px;
  padding: 0 12px;
  font-size: var(--ds-table-pagination-font-size, 13px);
  font-variant-numeric: var(--ds-table-pagination-numeric, tabular-nums);
  cursor: pointer;
  transition:
    color var(--ds-motion-normal) var(--ds-motion-ease-out),
    background-color var(--ds-motion-normal) var(--ds-motion-ease-out);
  background: transparent;
  color: var(--ds-color-text-primary);
  border: none;
  border-radius: var(--ds-radius-md);
}
.ds-table.ds-table--modern [data-part='pagination-button'][data-current='true'] {
  pointer-events: none;
  font-weight: var(--ds-table-pagination-current-font-weight, var(--ds-font-weight-semibold));
}
/* hover wash (fine pointers) + pressed state (the touch equivalent); the
   current page and disabled controls are excluded from both */
@media (hover: hover) {
  .ds-table.ds-table--modern [data-part='pagination-button']:not([data-current='true']):not(:disabled):hover {
    background: color-mix(in srgb, var(--ds-color-primary) 8%, transparent);
    color: var(--ds-color-primary);
  }
}
.ds-table.ds-table--modern [data-part='pagination-button']:not([data-current='true']):active {
  background: color-mix(in srgb, var(--ds-color-primary) 12%, transparent);
}
/* disabled prev/next: readable but unmistakably inactive (B2.1) */
.ds-table.ds-table--modern [data-part='pagination-button']:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.ds-table.ds-table--modern [data-part='pagination-button']:focus-visible,
.ds-table.ds-table--modern [data-part='expand-button']:focus-visible {
  outline: var(--ds-focus-ring-width) solid var(--ds-focus-ring-color, var(--ds-color-primary));
  outline-offset: var(--ds-focus-ring-offset);
}

/* ---- coarse pointers: the row-level actions meet the physical 44px floor.
        The 4px resize edge keeps its visual width and grows a capped
        transparent hit area (the density contract forbids a full 44px reach
        inside a dense header — it would swallow the sort click target). ---- */
@media (hover: none), (pointer: coarse) {
  .ds-table.ds-table--modern [data-part='pagination-button'],
  .ds-table.ds-table--modern [data-part='expand-button'] {
    min-block-size: var(--ds-table-touch-target-min, 44px);
  }

  .ds-table.ds-table--modern [data-part='expand-button'] {
    min-inline-size: var(--ds-table-touch-target-min, 44px);
  }

  .ds-table.ds-table--modern [data-part='selection-control'] {
    width: var(--ds-table-selection-control-coarse-size, 20px);
    height: var(--ds-table-selection-control-coarse-size, 20px);
  }

  /* the label's box fills the cell (negative margins cancel its padding), so
     the coarse hit area is the full 48px column x the row's own height */
  .ds-table.ds-table--modern [data-part='table'][data-size='sm'] [data-part='selection-hit'] {
    margin: -4px -8px;
    padding: 4px 8px;
  }
  .ds-table.ds-table--modern [data-part='table'][data-size='md'] [data-part='selection-hit'] {
    margin: -8px -12px;
    padding: 8px 12px;
  }
  .ds-table.ds-table--modern [data-part='table'][data-size='lg'] [data-part='selection-hit'] {
    margin: -12px -16px;
    padding: 12px 16px;
  }

  .ds-table.ds-table--modern [data-part='resize-handle']::after {
    content: '';
    position: absolute;
    inset-block: 0;
    inset-inline: -10px;
  }
}

/* ---- reduced motion: every animation/transition in this skin quiets down. ---- */
@media (prefers-reduced-motion: reduce) {
  .ds-table.ds-table--modern [data-part='cell'][data-editable='true'],
  .ds-table.ds-table--modern [data-part='cell'][data-fixed],
  .ds-table.ds-table--modern [data-part='expand-button'],
  .ds-table.ds-table--modern [data-part='expand-indicator'],
  .ds-table.ds-table--modern [data-part='header-cell'][data-sortable='true'],
  .ds-table.ds-table--modern [data-part='sort-indicator'],
  .ds-table.ds-table--modern [data-part='pagination-button'] {
    transition: none;
  }

  .ds-table.ds-table--modern [data-part='expanded-row'] > td {
    animation: none;
  }

  .ds-table.ds-table--modern [data-part='spinner'] {
    animation: none;
  }

  .ds-table.ds-table--modern [data-part='skeleton-bar'] {
    animation: none;
  }
}

/* ---- forced colors (system colors only): background washes disappear, so
        the selected row, the sort/expand/pagination focus rings and the
        spinner keep system-color boundaries. ---- */
@media (forced-colors: active) {
  .ds-table.ds-table--modern [data-part='row'][data-selected='true'] {
    outline: 1px solid Highlight;
    outline-offset: -1px;
  }
  /* box-shadows are stripped in forced colors: the sticky header keyline (an
     inset shadow over a transparent border) re-expresses as a real
     system-color border. The pinned-column edges keep their opaque forced
     fill, which already separates them from scrolling content. */
  .ds-table.ds-table--modern [data-part='header-cell'][data-sticky='true'][data-hairline='true'] {
    border-bottom-color: CanvasText;
  }
  .ds-table.ds-table--modern [data-part='header-cell'][data-sortable='true']:focus-visible,
  .ds-table.ds-table--modern [data-part='pagination-button']:focus-visible,
  .ds-table.ds-table--modern [data-part='expand-button']:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 1px;
  }
  .ds-table.ds-table--modern [data-part='spinner'][role='status'] {
    border-color: ButtonText;
    border-top-color: Highlight;
  }
  .ds-table.ds-table--modern [data-part='resize-handle'][data-resizing='true'],
  .ds-table.ds-table--modern [data-part='resize-handle']:not([data-resizing='true']):hover {
    background: ButtonText;
  }
  /* the shimmer gradient is forced away; the bars keep a system-color fill
     (the stats-grid.css idiom) so the loading anatomy still reads */
  .ds-table.ds-table--modern [data-part='skeleton-bar'] {
    background: GrayText;
    animation: none;
  }
}

}
@layer rottay-engines {
/**
 * Rustic Table skin (WO-ARC-09 checkpoint 1).
 *
 * DELIBERATELY UNLAYERED -- mirrors `engines/modern/skin/table.css`'s reasoning
 * verbatim: every `rottay-*` layer sorts before Tailwind's `base` layer, so a
 * layered rule loses to preflight regardless of specificity (P-47). Unlayered
 * outranks preflight + DaisyUI and still yields to a caller's inline `style`.
 *
 * SCOPE ROOT IS THE OUTER `<div>`, not the `<table>`. The loading overlay, the
 * title/footer and the pagination controls are SIBLINGS of the `<table>` under
 * that div, so scoping on the table would leave them unpainted. The div
 * carries `ds-table ds-table--rustic`; every painted element is a descendant
 * with a `data-part`.
 *
 * SPECIFICITY (P-48): the Platform-only Rottay artifact ships an unlayered
 * `html[data-tenant]:not([data-theme]):not(.light) *` border-color floor at
 * (0,3,1). A descendant rule that sets `border` / `border-color` / a
 * `border-*-color` longhand must therefore reach (0,4,0): the div's two
 * classes (0,2,0) + two attributes on the target (0,2,0). Rules that set only
 * non-border paint (background, color, box-shadow, outline, transform,
 * accent-color) beat preflight while unlayered and need no more than the two
 * classes + one attribute.
 *
 * The 4th unit must be bought either by REPEATING the `data-part` attribute
 * (`[data-part='x'][data-part='x']`, a legal double-count) or by an
 * EXPLICITLY stamped attribute (e.g. `data-field`, `data-nav`) -- never by an
 * incidental attribute an unrelated refactor could move or remove (`role`,
 * `aria-label`, `placeholder`). Pure `border: none` resets carry no color and
 * are exempt from the (0,4,0) floor. This is the pattern the other five
 * components will copy.
 *
 * RUSTIC DIFFERS FROM MODERN IN TWO STRUCTURAL WAYS this file encodes:
 *  1. Rustic's header/body separators are UNCONDITIONAL. Rustic has no
 *     `headerBordered` prop, and its per-cell bottom border never read
 *     `bordered` either -- so `data-hairline` (header) and `data-bordered`
 *     (body cell) are stamped "true" unconditionally in the engine file,
 *     rather than tracking a prop the way modern's do. Only the OUTER
 *     `<table>`'s `data-bordered` tracks the `bordered` prop, matching
 *     modern exactly.
 *  2. Hover in rustic was previously five pieces of React state (`hoveredRow`,
 *     `hoveredEditableCell`, `hoveredSortCol`, `activePageBtn`,
 *     `hoveredPageBtn`) driving imperative paint because inline styles cannot
 *     express `:hover`. All five are gone; every hover/active/focus effect
 *     below is a real pseudo-class keyed on the same data-part contract.
 *     Where rustic's hover priority differs from modern's (a selected AND
 *     hovered row shows the HOVER background in rustic; modern's shows the
 *     SELECTED background), the rule specificity below reproduces rustic's
 *     own prior behavior, not modern's -- see the body-row block.
 *
 * Values are transcribed verbatim from `engines/rustic.tsx`'s (pre-migration)
 * `baseStyles`; the rule order mirrors the order that file painted them.
 */

/* ---- keyframes: referenced by the inline `animation` shorthand the engine
        sets on the expanded-row cell (a sanctioned inline residual,
        WO-ARC-09). Defined globally here, not per table instance. ---- */
@keyframes ds-table-expand-in-rustic {
  from { opacity: 0; max-height: 0; }
  to { opacity: 1; max-height: 500px; }
}

/* ---- table element: border only in `bordered` mode ---- */
.ds-table.ds-table--rustic [data-part='table'][data-bordered='true'] {
  border: 1px solid var(--ds-table-border, var(--ds-color-border-primary));
}

/* ---- header cells: background + text color are unconditional in rustic ---- */
.ds-table.ds-table--rustic [data-part='header-cell'] {
  background-color: var(--ds-table-header-bg, var(--ds-color-bg-secondary));
  color: var(--ds-table-header-color);
}
.ds-table.ds-table--rustic [data-part='header-cell'][data-hairline='true'] {
  border-bottom: 1px solid var(--ds-table-border, var(--ds-color-border-primary));
}
.ds-table.ds-table--rustic [data-part='header-cell'][data-sortable='true']:hover {
  background-color: var(--ds-table-header-bg-hover, var(--ds-color-bg-tertiary));
}
/* the sort column title underlines on hover -- rustic-only, no modern analog
   (see the migration report). Structural child selector: the title span is
   always the first child of the header cell's first child (the flex
   wrapper), regardless of whether the sort-icon sibling is present. */
.ds-table.ds-table--rustic [data-part='header-cell'][data-sortable='true']:hover > span:first-child > span:first-child {
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* ---- sort indicator: rotates with the sort order; dims unless current or
        its header is hovered (rustic-only hover dim step, no modern analog) ---- */
.ds-table.ds-table--rustic [data-part='sort-indicator'] {
  transform: rotate(0deg);
}
.ds-table.ds-table--rustic [data-part='sort-indicator'][data-order='descend'] {
  transform: rotate(180deg);
}
.ds-table.ds-table--rustic [data-part='header-cell'][data-sortable='true']:hover [data-part='sort-indicator'][data-order='none'] {
  opacity: 0.8;
}

/* ---- resize handle: only a live drag paints in rustic -- there is no
        separate hover-only tint the way modern has ---- */
.ds-table.ds-table--rustic [data-part='resize-handle'][data-resizing='true'] {
  background-color: var(--ds-color-primary);
}

/* ---- filter row + its input ---- */
.ds-table.ds-table--rustic [data-part='filter-row'] {
  background-color: var(--ds-table-filter-row-bg, var(--ds-color-bg-secondary));
}
/* filter input: neutral resting border. Distinguished from the edit fields
   below by the explicit `data-field='filter'` stamp -- never an incidental
   attribute like `placeholder`, which an unrelated UX/i18n change could add
   to or remove from either kind. */
.ds-table.ds-table--rustic [data-part='field'][data-field='filter'] {
  border: 1px solid var(--ds-color-border-secondary, var(--ds-color-neutral-300));
  border-radius: var(--ds-radius-sm, 6px);
  background-color: var(--ds-color-bg-elevated, var(--ds-color-bg-primary));
  outline: none;
}
.ds-table.ds-table--rustic [data-part='field'][data-field='filter']:focus {
  border-color: var(--ds-color-primary);
  box-shadow: var(--ds-table-filter-focus-shadow, 0 0 0 3px var(--ds-color-primary-100), 0 0 8px var(--ds-color-primary-200));
}
/* edit field (text/number/date/select): primary-colored border is the
   "you're editing" signal, always on -- stamped `data-field='edit'`. */
.ds-table.ds-table--rustic [data-part='field'][data-field='edit'] {
  border: 1px solid var(--ds-color-primary);
  border-radius: var(--ds-radius-sm, 6px);
  background-color: var(--ds-color-bg-elevated, var(--ds-color-bg-primary));
  outline: none;
}

/* ---- selection controls: rustic never painted accent-color, nothing to move ---- */

/* ---- muted text: empty-state cell + footer share one value; pagination
        range carries its own separate fallback chain ---- */
.ds-table.ds-table--rustic [data-part='empty-cell'],
.ds-table.ds-table--rustic [data-part='footer'] {
  color: var(--ds-color-text-secondary);
}
.ds-table.ds-table--rustic [data-part='pagination-range'] {
  color: var(--ds-color-text-secondary, var(--ds-color-text-muted));
}

/* ---- title bar: rustic colors it, modern does not (no analog) ---- */
.ds-table.ds-table--rustic [data-part='title'] {
  color: var(--ds-color-text-primary);
}

/* ---- body row: hover ALWAYS wins over selected in rustic (the pre-migration
        JS checked `isHovered` before `isSelected`), so the hover background
        rule below is NOT qualified with `:not([data-selected])` -- its added
        `:hover` pseudo-class already gives it higher specificity than the
        selected rule, so it wins regardless of source order. ---- */
.ds-table.ds-table--rustic [data-part='row'][data-selected='true'] {
  background-color: var(--ds-table-row-bg-selected, var(--ds-color-primary-100));
}
.ds-table.ds-table--rustic [data-part='row'][data-hoverable='true']:hover {
  background-color: var(--ds-table-row-bg-hover, var(--ds-color-bg-secondary));
}
/* ---- body cell: bottom border is unconditional in rustic (data-bordered is
        stamped "true" on every cell, not gated on the `bordered` prop), and
        the editable-cell hover ---- */
.ds-table.ds-table--rustic [data-part='cell'][data-bordered='true'] {
  border-bottom: 1px solid var(--ds-table-row-border, var(--ds-color-border-primary));
}
.ds-table.ds-table--rustic [data-part='cell'][data-editable='true']:hover {
  outline: 1px dashed var(--ds-color-primary-200, var(--ds-color-primary));
  outline-offset: -1px;
  background-color: var(--ds-color-alpha-primary-5);
}

/* ---- pinned/fixed columns: an opaque fill so scrolled content cannot bleed
        through. Applies to both header and body cells. ---- */
.ds-table.ds-table--rustic [data-part='cell'][data-fixed],
.ds-table.ds-table--rustic [data-part='header-cell'][data-fixed] {
  background-color: var(--ds-table-bg, var(--ds-color-bg-elevated, var(--ds-color-bg-primary)));
}

/* ---- expand column: rustic rotates the button itself directly -- there is
        no separate indicator element the way modern has (no analog) ---- */
.ds-table.ds-table--rustic [data-part='expand-button'] {
  transform: rotate(0deg);
}
.ds-table.ds-table--rustic [data-part='expand-button'][data-expanded='true'] {
  transform: rotate(90deg);
}

/* ---- expanded row content ---- */
.ds-table.ds-table--rustic [data-part='expanded-row'] {
  background-color: var(--ds-table-row-bg-expanded, var(--ds-color-bg-secondary, var(--ds-color-bg-muted)));
}

/* ---- loading overlay. Rustic shows a text label, not a spinner glyph --
        `data-part='spinner'` is stamped on that label for contract parity
        but paints nothing here, since rustic never painted it. ---- */
.ds-table.ds-table--rustic [data-part='loading-overlay'] {
  background-color: var(--ds-table-loading-overlay-bg, var(--ds-color-alpha-white-70));
}

/* ---- summary / tfoot: rustic colors it, modern does not (no analog) ---- */
.ds-table.ds-table--rustic [data-part='summary-row'] {
  background-color: var(--ds-table-header-bg, var(--ds-color-bg-secondary));
}

/* ---- pagination buttons: base chrome, then hover, then active. Rustic only
        ever renders two pagination-button elements (prev/next) -- there is
        no separate current-page button (rustic shows the current page as a
        plain, unstyled <span>, not a button) -- so the base-chrome rule below
        applies to ALL pagination-button elements and reaches (0,4,0) with a
        repeated `data-part` rather than depending on `aria-label`, which
        both buttons happen to carry today but neither is required to. Active
        must sort AFTER hover so its transform/box-shadow win when both
        pseudo-classes match at once (the mouse held down while over the
        button matches both), matching the JS's own spread order
        (`pageButtonHover` before `pageButtonActive`). `:not(:disabled)` is
        redundant with native `:hover`/`:active` behavior (disabled controls
        never match either) but is kept to document that the original JS
        guarded on it explicitly. ---- */
.ds-table.ds-table--rustic [data-part='pagination-button'][data-part='pagination-button'] {
  border: 1px solid var(--ds-color-border-secondary, var(--ds-color-neutral-300));
  border-radius: var(--ds-radius-sm, 6px);
  background-color: var(--ds-table-bg, var(--ds-color-bg-elevated));
}
.ds-table.ds-table--rustic [data-part='pagination-button']:not(:disabled):hover {
  transform: translateY(-1px) scale(1.02);
  box-shadow: var(--ds-table-page-button-hover-shadow, var(--ds-shadow-sm));
  border-color: var(--ds-color-primary);
}
.ds-table.ds-table--rustic [data-part='pagination-button']:not(:disabled):active {
  transform: scale(0.97);
  box-shadow: none;
}

}
@layer rottay-components {
/**
 * FieldFiltersPanel skin — engine-agnostic.
 * Home: foundation/tokens/css/presentation/components/skin/field-filters-panel.css — the structures/
 * shared-file home of the WO-ARC-09 contract; no --modern/--rustic
 * discriminator because the component renders one DOM under every engine.
 *
 * LAYER: imported by `facade/entrypoints/base.css` and
 * `facade/entrypoints/styles.css` into `layer(rottay-components)` (the old
 * "deliberately unlayered" note predates the wiring).
 *
 * SPECIFICITY (P-48): the Platform-only Rottay artifact ships an unlayered
 * `html[data-tenant]:not([data-theme]):not(.light) *` at (0,3,1) that sets
 * `border-color` on every element. Border paint reaches (0,4,0) through the
 * always-stamped root `data-part` ancestor — repeating a class or attribute
 * is forbidden (the source-gated contract bans role/aria-label/placeholder
 * as the fourth unit and audits this file's specificity). Text rules add the
 * always-stamped `data-size` for b>=5 over Typography's `[data-color]`.
 *
 * CONTROL LANDINGS: `.ds-field-filters-panel__control` is passed as
 * `className` to the panel's Select/Input controls and lands on the element
 * each engine gives the caller: the modern Select/Input OUTER wrapper (no
 * engine paint, no skin targets it), the rustic Select container (same), and
 * the rustic Input `[data-part='root']` — the one landing the rustic input
 * skin itself paints. The suppression rule below keeps the pine of the
 * source-gated contract (b>=7, self-selecting via `[data-part='root']`,
 * declaring border/background/box-shadow/border-radius) through the real
 * ancestor chain (root > filter-card > control-slot), WITHOUT the old
 * class×2 + data-part×4 repetition. LAYER TRUTH: this file sorts in
 * `rottay-components`, BEFORE `rottay-engines`, so against the rustic input
 * skin the layer — never the specificity — decides; the honest fix for the
 * rustic focus repaint is a `--ds-input-*` channel in the rustic input skin
