/* filter card ---------------------------------------------------------------- */

.ds-structure.ds-field-filters-panel [data-part='filter-card'] {
  border-radius: 18px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--ds-surface-card) 95%, var(--ds-color-bg-elevated) 5%), color-mix(in srgb, var(--ds-surface-card) 90%, var(--ds-color-bg-primary) 10%));
