.ds-structure.ds-field-filters-panel[data-part='root'] [data-part='filter-card'] {
  border: 1px solid color-mix(in srgb, var(--ds-color-border-secondary) 84%, transparent);
}

.ds-structure.ds-field-filters-panel [data-part='filter-card-icon'] {
  border-radius: 12px;
  background: color-mix(in srgb, var(--ds-color-bg-primary) 52%, transparent);
