.ds-structure.ds-field-filters-panel .ds-field-filters-panel__control {
  border-radius: 12px;
  background: color-mix(in srgb, var(--ds-color-bg-primary) 72%, var(--ds-surface-card));
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--ds-color-bg-elevated) 4%, transparent);
}

.ds-structure.ds-field-filters-panel[data-part='root'] .ds-field-filters-panel__control {
  border: 1px solid color-mix(in srgb, var(--ds-color-border-secondary) 88%, transparent);
