@layer rottay-components {
/**
 * Engine-neutral DataTable action anatomy.
 *
 * Engines stamp the parts; vertical and tenant layers provide the values. The
 * wrapper makes arbitrary app-authored action renderers align consistently
 * without depending on the action column's DOM position or accessible copy.
 */

.ds-pattern-data-table [data-part="actions-content"] {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: nowrap;
  gap: var(--ds-table-action-gap, var(--ds-spacing-2, 0.5rem));
  width: max-content;
  min-width: 0;
  max-width: 100%;
  margin-inline-start: auto;
}

.ds-pattern-data-table[data-has-actions="true"]
  [data-part="header-cell"][data-cell-kind="actions"],
.ds-pattern-data-table[data-has-actions="true"]
  [data-part="actions-cell"][data-part="actions-cell"] {
  background: var(--ds-table-action-bg, var(--ds-surface-card));
  border-inline-start: 1px solid
    var(--ds-table-action-border, var(--ds-table-row-border, transparent));
  box-shadow: var(--ds-table-action-shadow, none);
}

}
@layer rottay-components {
/**
 * DataTable agnostic skin (WO-ARC-09 checkpoint 6) — the engine-free leaves of
 * the data-table family: the inline cell editors (rendered inside the modern
 * engine, but with engine-free markup) and the mobile-card fallback + mobile
 * state panels (rendered by PatternDataTable/DataTableMobileCards under BOTH
 * engines, below the window-width breakpoint). Home in components/skin/ because
 * these render one DOM under every engine; no --modern/--rustic discriminator.
 *
 * DELIBERATELY UNLAYERED (P-47). SPECIFICITY (P-48): the tenant `*` border floor
 * sits at (0,3,1); a border-painting rule must reach (0,4,0).
 *
 * CELL EDITORS scope on `.ds-pattern-data-table [data-part='editor-*']` — they
 * render inside the pattern root. The editor input's rest AND error borders both
 * paint a color, so both reach (0,4,0) by repeating `data-part`/`data-invalid`;
 * non-border channels win at (0,2,0). The error border keys on the stamped
 * `data-invalid='true'` and sits after the rest border so it wins on the invalid
 * cell.
 *
 * MOBILE CARD (trap-1): the caller previously froze the Card's
 * background/border-color/border-radius/box-shadow with an inline `style` that
 * beat ALL of card.css — including its hover/focus rules. Preserving that
 * byte-exact means an unlayered rule that outranks card.css's MAX specificity on
 * those channels. The contract test measures the current MAX across modern +
 * rustic card.css rather than relying on a stale literal. This rule uses the
 * FFP suppression idiom and stays one b-column unit above that measured floor,
 * so it wins at rest and in the (unphotographed) hover/focus a clickable card
 * could take, exactly as the inline style did. Card sets border-WIDTH/STYLE via
 * its variant; this rule overrides only border-COLOR, matching the inline
 * `borderColor` it replaces. The `--selected` modifier repeats the same way and
 * follows the base rule so it wins the conditional border-color/box-shadow.
 *
 * MOBILE STATE PANEL: the loading and empty panels share `data-part=
 * 'mobile-state-panel'` and carry byte-identical values (verified); one rule.
 *
 * Values are transcribed verbatim from cell-editors/index.tsx,
 * DataTableMobileCards.tsx and PatternDataTable.tsx.
 */

/* ---- inline cell editor input: rest + error border, plus the shared chrome --- */
.ds-pattern-data-table [data-part="editor-input"] {
  border-radius: var(--ds-radius-sm, 6px);
  background: var(--ds-surface-card, #fff);
  color: var(--ds-color-text-primary, #1a1a1a);
  outline: none;
}
.ds-pattern-data-table
  [data-part="editor-input"][data-part="editor-input"][data-part="editor-input"] {
  border: 1.5px solid var(--ds-color-primary, #3b82f6);
}
.ds-pattern-data-table
  [data-part="editor-input"][data-part="editor-input"][data-invalid="true"] {
  border: 1.5px solid var(--ds-color-error, #e53e3e);
}

/* ---- checkbox editor + error message ---- */
.ds-pattern-data-table [data-part="editor-checkbox"] {
  accent-color: var(--ds-color-primary, #3b82f6);
}
.ds-pattern-data-table [data-part="editor-error"] {
  color: var(--ds-color-error, #e53e3e);
}

/* ---- mobile card chrome (FFP suppression: beats card.css MAX = 9) ---- */
.ds-data-table-responsive-root[data-part="responsive-root"] {
  width: 100%;
  min-width: 0;
  container-name: ds-data-table-responsive;
  container-type: inline-size;
}

.ds-pattern-data-table.ds-data-table--mobile[data-part="mobile-root"] {
  --ds-card-bg: var(--ds-collection-card-bg, var(--ds-premium-card-bg));
  --ds-card-border: var(
    --ds-collection-card-border,
    var(--ds-premium-card-border)
  );
  --ds-card-border-hover: var(
    --ds-collection-card-border-hover,
    var(--ds-premium-card-border-hover)
  );
  --ds-card-radius: var(
    --ds-collection-card-radius,
    var(--ds-premium-card-radius, var(--ds-radius-lg))
  );
  --ds-card-shadow: var(
    --ds-collection-card-shadow,
    var(--ds-premium-card-shadow, none)
  );
  --ds-card-shadow-hover: var(
    --ds-collection-card-shadow-hover,
    var(--ds-premium-card-shadow-hover, var(--ds-elevation-2))
  );

  width: 100%;
  min-width: 0;
  container-name: ds-mobile-table;
  container-type: inline-size;
}

.ds-pattern-data-table.ds-data-table--mobile[data-part="mobile-root"][data-density="compact"] {
  --ds-density-local-factor: var(--ds-density-factor-compact, 0.85);
  --ds-density-card-padding: var(
    --ds-density-card-padding-compact,
    calc(
      0.75rem *
        var(--ds-density-global-effective-scale, var(--ds-density-scale, 1))
    )
  );
}

.ds-pattern-data-table.ds-data-table--mobile[data-part="mobile-root"][data-density="comfortable"] {
  --ds-density-local-factor: var(--ds-density-factor-comfortable, 1);
  --ds-density-card-padding: var(
    --ds-density-card-padding-comfortable,
    calc(
      1rem *
        var(--ds-density-global-effective-scale, var(--ds-density-scale, 1))
    )
  );
}

.ds-pattern-data-table.ds-data-table--mobile[data-part="mobile-root"][data-density="spacious"] {
  --ds-density-local-factor: var(--ds-density-factor-spacious, 1.15);
  --ds-density-card-padding: var(
    --ds-density-card-padding-spacious,
    calc(
      1.125rem *
        var(--ds-density-global-effective-scale, var(--ds-density-scale, 1))
    )
  );
}

.ds-pattern-data-table.ds-data-table--mobile .ds-data-table__mobile-card {
  overflow: hidden;
  transition: var(
    --ds-transition-rearrange,
    transform var(--ds-motion-feedback)
      var(--ds-motion-ease-move, ease-out),
    box-shadow var(--ds-motion-feedback)
      var(--ds-motion-ease-move, ease-out)
  );
}

