 * SPECIFICITY (P-48 + 4th-wave recount): the Platform-only Rottay artifact
 * ships an unlayered border-color floor at (0,3,1). With only ONE root
 * class, the border rules reach (0,4,0) via the always-stamped
 * `[data-size]` + `[data-variant]` pair (and the state attribute on the
 * active/error chains) -- no repeated `[data-part='root']` anywhere. The
 * former thrice-repeated mint is gone; the fragility note lives on the
 * border block below. Non-border paint wins unlayered at (0,2,0)+.
 */

.ds-voice-input-button[data-part='root'] {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  cursor: pointer;
  flex-shrink: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--ds-color-text-muted);
  transition:
    background-color var(--ds-motion-feedback) var(--ds-motion-ease-out),
    border-color var(--ds-motion-feedback) var(--ds-motion-ease-out),
    color var(--ds-motion-feedback) var(--ds-motion-ease-out);
}

/* Idle hover is hover-capable-only (4th-wave law); the held press answers
   with the canonical press scale on every pointer. */
@media (hover: hover) {
  .ds-voice-input-button[data-part='root']:hover:not([data-active='true']):not([data-error='true']) {
    background: var(
      --ds-voice-input-bg-hover,
      color-mix(in srgb, var(--ds-color-text-primary) 6%, transparent)
    );
  }
}
.ds-voice-input-button[data-part='root']:active {
  transform: scale(var(--ds-state-press-scale));
}

/* control + icon geometry per size preset (transcribed verbatim: no global
   control-size token covers these values) */
.ds-voice-input-button[data-part='root'][data-size='sm'] {
  inline-size: 28px;
  block-size: 28px;
  min-inline-size: 28px;
}
.ds-voice-input-button[data-part='root'][data-size='md'] {
  inline-size: 34px;
  block-size: 34px;
  min-inline-size: 34px;
}
.ds-voice-input-button[data-part='root'][data-size='sm'] > .rottay-icon {
  inline-size: 13px;
  block-size: 13px;
}
.ds-voice-input-button[data-part='root'][data-size='md'] > .rottay-icon {
  inline-size: 15px;
  block-size: 15px;
}

/* state animations (keyframes declared at the bottom of this file; durations
   derive from the motion scale -- never literals). The recording halo is a
   `::before` ring animating compositor-safe transform + opacity (the former
   box-shadow spread forced paint on every frame). */
.ds-voice-input-button[data-part='root'][data-part='root'][data-status='listening']::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--ds-color-primary) 38%, transparent);
  pointer-events: none;
  animation: ds-voice-input-button-pulse
    var(--ds-voice-input-pulse-duration, calc(var(--ds-motion-glacial) * 3))
    var(--ds-motion-ease-out) infinite;
}
.ds-voice-input-button[data-part='root'][data-status='transcribing'] > .rottay-icon {
  animation: ds-voice-input-button-spin calc(var(--ds-motion-glacial) * 2) linear infinite;
}
/* Error marker (shape, not hue): corner dot for the generic error posture.
   Blocked is suppressed -- the MicOff glyph already carries that shape. */
.ds-voice-input-button[data-part='root'][data-error='true']:not([data-blocked='true'])::after {
  content: '';
  position: absolute;
  inset-block-start: -2px;
  inset-inline-end: -2px;
  inline-size: var(--_ds-proto-voice-input-error-dot-size, 8px);
  block-size: var(--_ds-proto-voice-input-error-dot-size, 8px);
  border-radius: 999px;
  background: var(--ds-color-error);
  border: 1px solid var(--ds-surface-card);
  pointer-events: none;
}
@media (prefers-reduced-motion: reduce) {
  /* Static final state: the ring stays painted, only the pulse quiets. */
  .ds-voice-input-button[data-part='root'][data-part='root'][data-status='listening']::before {
    animation: none;
  }
}

/* focus ring (K4-B Pass 2: the button relied on the UA outline) — badge idiom. */
.ds-voice-input-button[data-part='root']:focus-visible {
  outline: none;
  box-shadow: var(
    --ds-voice-input-focus-ring,
    0 0 0 3px color-mix(in srgb, var(--ds-color-primary) 24%, transparent)
  );
}
/* forced colors: the focus ring degrades to a system outline, and every
   state keeps a FRAME (never hue alone): the base frame and the active
   Highlight frame carry idle vs recording. */
@media (forced-colors: active) {
  .ds-voice-input-button[data-part='root']:focus-visible {
    outline: 2px solid Highlight;
    box-shadow: none;
  }

  .ds-voice-input-button[data-part='root'][data-size][data-variant] {
    border-color: ButtonText;
  }
  .ds-voice-input-button[data-part='root'][data-variant][data-active='true'] {
    border-color: Highlight;
  }
  .ds-voice-input-button[data-part='root'][data-variant][data-blocked='true'] {
    border-color: GrayText;
    color: GrayText;
  }
  /* Error dot: system ink on a canvas ring (the ::before recording ring
     border auto-forces to a system color, so the state frame survives). */
  .ds-voice-input-button[data-part='root'][data-error='true']:not([data-blocked='true'])::after {
    background: CanvasText;
    border-color: Canvas;
  }
}

/* coarse pointers: the 28/34px presets miss the wave's 44px touch law; the
   floor is physical px, never rem (the fluid 15px root erodes rem floors at
   narrow widths -- measured on the live bundle, Axe R0). */
@media (pointer: coarse) {
  .ds-voice-input-button[data-part='root'] {
    min-inline-size: 44px;
    min-block-size: 44px;
  }
}

/* border color: default (base) > active > error (error wins the tie, last).
   4th-wave de-hack of the former thrice/twice-repeated `[data-part='root']`:
   `[data-size]` and `[data-variant]` are stamped on EVERY render, so they
   lend the specificity units with no repetition (FRAGILITY NOTE: restore the
   stamps if a future render ever drops them -- never re-double the part). */
.ds-voice-input-button[data-part='root'][data-size][data-variant] {
  border: 1px solid color-mix(in srgb, var(--ds-color-border-secondary) 82%, transparent);
}
.ds-voice-input-button[data-part='root'][data-variant][data-active='true'] {
  border-color: color-mix(in srgb, var(--ds-color-primary) 44%, transparent);
}
.ds-voice-input-button[data-part='root'][data-variant][data-error='true'] {
  border-color: color-mix(in srgb, var(--ds-color-error) 36%, transparent);
}

/* background: only the filled variant tints; state overrides in error>active order. */
.ds-voice-input-button[data-part='root'][data-variant='filled'] {
  background: color-mix(in srgb, var(--ds-surface-card) 85%, var(--ds-color-bg-primary) 15%);
}
.ds-voice-input-button[data-part='root'][data-variant='filled'][data-active='true'] {
  background: color-mix(in srgb, var(--ds-color-primary) 14%, var(--ds-surface-card));
}
.ds-voice-input-button[data-part='root'][data-variant='filled'][data-error='true'] {
  background: color-mix(in srgb, var(--ds-color-error) 12%, var(--ds-surface-card));
}

/* text color */
.ds-voice-input-button[data-part='root'][data-active='true'] {
  color: var(--ds-color-primary);
}
.ds-voice-input-button[data-part='root'][data-error='true'] {
  color: var(--ds-color-error);
}
/* Permission denied reads muted (the tooltip carries the explanation; the
   button stays operable so the browser can re-prompt). */
.ds-voice-input-button[data-part='root'][data-blocked='true'] {
  color: var(--ds-color-text-disabled);
}

@keyframes ds-voice-input-button-pulse {
  0% { opacity: 0.9; transform: scale(1); }
  70% { opacity: 0; transform: scale(1.45); }
  100% { opacity: 0; transform: scale(1.45); }
}
@keyframes ds-voice-input-button-spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

}
@layer rottay-components {
/**
 * CodeBlock skin -- engine-agnostic, no `@layer` in-file (the facade
 * entrypoints import it into `layer(rottay-components)`, the same
 * registration as the voice-input-button family skin).
 * Home: foundation/tokens/css/presentation/components/skin/code-block.css --
 * this component has no engine split (one `index.tsx` renders under every
 * engine).
 *
 * SCOPE ROOT is `.ds-code-block[data-part='root']`.
 *
 * OWNERSHIP (single owner PER PART): this skin owns ONLY
 *   (a) the copy-button part -- wholesale: geometry, static paint (evolved
 *       from the old inline styles) and its interaction states (hover,
 *       active, focus-visible and the transient copied confirmation);
 *   (b) the scroll region's focus ring (the region became keyboard-focusable
 *       in the K4-B R4 remediation; the ring is its contract);
 *   (c) the ::selection tint inside the block (state paint the inline styles
 *       cannot express -- same tier as (a)'s interaction states); and
 *   (d) the scroll-edge affordance of the scroll region (Phase B): gradient
 *       scroll shadows via the background-attachment idiom -- paint the inline
 *       styles cannot layer without re-owning the region's background, and the
 *       cover tint must read the surface token, which only a stylesheet rule
 *       can keep in sync with the skin grammar; and
 *   (e) the language-badge chip on the header title -- conditional paint keyed
 *       on `data-language-badge`, expressed as a rule so the chip is a skin
 *       state rather than a branch inside a style object.
 * Every other part (root surface, header, gutter, code) keeps its inline paint
 * in `index.tsx`. Inline styles cannot express :hover/:focus-visible, selection
 * or attribute-conditional state, which is why that paint lives here.
 *
 * Hover grammar: the certified ghost-button law (same as Transfer's
 * move/pagination buttons and Calendar's header chrome) --
 * `--ds-button-ghost-bg-hover` over a `--ds-surface-inset` floor, gated
 * `:not(:disabled)`, family escape hatches `--ds-code-block-*`.
 */

.ds-code-block[data-part='root'] [data-part='copy-button'] {
  display: inline-flex;
  align-items: center;
  gap: var(--ds-spacing-1);
  padding: var(--ds-spacing-1) var(--ds-spacing-2);
  border-radius: var(--ds-radius-sm);
  border: 1px solid var(--ds-color-border);
  background: transparent;
  color: var(--ds-color-text-secondary);
  font: inherit;
  font-size: var(--ds-font-size-xs);
  font-weight: 500;
  cursor: pointer;
  transition:
    background var(--ds-code-block-motion-duration, var(--ds-motion-fast)) ease,
    color var(--ds-code-block-motion-duration, var(--ds-motion-fast)) ease,
    border-color var(--ds-code-block-motion-duration, var(--ds-motion-fast)) ease;
}

/* The idle/copied glyph sits on the button's text baseline: inline-flex with a
   fixed 1em square keeps the icon optically centered next to the xs label and
   holds the button's inline size steady across the copy -> copied swap (both
   glyphs are 12px; the label is the only width variable). */
.ds-code-block[data-part='root'] [data-part='copy-tick'] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: 1em;
  block-size: 1em;
}

/* Coarse-pointer floor (B1.3): the chrome-sized control grows to the governed
   touch target on touch devices; fine pointers keep the compact geometry. The
   centering above keeps the hit-area growth invisible. */
@media (pointer: coarse) {
  .ds-code-block[data-part='root'] [data-part='copy-button'] {
    min-block-size: var(--ds-touch-target-min);
    min-inline-size: var(--ds-touch-target-min);
    justify-content: center;
  }
}

/* Scroll-edge affordance (Phase B): the region tells the truth about hidden
   content. The background-attachment idiom paints edge shadows that appear
   only when more content exists in that direction -- `local` covers ride the
   content (they mask the shadow exactly when the edge is reached), `scroll`
   shadows stay pinned to the frame. The cover tint reads the same inset
   surface the root paints, so the masks are invisible at rest; when the
   region cannot scroll (wrap, no maxHeight) covers and shadows coincide and
   nothing shows. No JS, no scroll listeners, compositor-free static paint. */
/* Language badge: the bare language tag wears a quiet chip (hairline frame +
   whisper tint, no second box) so it reads as METADATA instead of floating
   header copy. A filename title stays bare -- it is content, not a tag -- so
   the chip is gated on `data-language-badge`, which the TSX stamps only when
   `language` arrives without `title`. The part keeps `data-part='title'`: the
   badge is a MODE of the title, not a second part. */
.ds-code-block[data-part='root'] [data-part='title'][data-language-badge='true'] {
  padding: 0 var(--ds-spacing-2);
  border: 1px solid var(--ds-color-border);
  border-radius: var(--ds-radius-sm);
  background: var(
    --_ds-proto-codeblock-language-badge-bg,
    color-mix(in srgb, var(--ds-color-text-primary) 4%, transparent)
  );
  line-height: var(--ds-line-height-snug);
}

.ds-code-block[data-part='root'] [data-part='scroll'] {
  background-image:
    linear-gradient(to bottom, var(--ds-surface-inset) 30%, transparent),
    linear-gradient(to top, var(--ds-surface-inset) 30%, transparent),
    radial-gradient(
      farthest-side at 50% 0,
      var(--_ds-proto-codeblock-scroll-shadow, color-mix(in srgb, var(--ds-color-text-primary) 16%, transparent)),
      transparent
    ),
    radial-gradient(
      farthest-side at 50% 100%,
      var(--_ds-proto-codeblock-scroll-shadow, color-mix(in srgb, var(--ds-color-text-primary) 16%, transparent)),
      transparent
    );
  background-position: 0 0, 0 100%, 0 0, 0 100%;
  background-repeat: no-repeat;
  background-size: 100% 2.5rem, 100% 2.5rem, 100% 0.625rem, 100% 0.625rem;
  background-attachment: local, local, scroll, scroll;
}

/* Pointer-fine hover only (hover law); the press below is the touch and
   keyboard equivalent. The test-pinned selector string is preserved. */
@media (hover: hover) {
  .ds-code-block[data-part='root'] [data-part='copy-button']:not(:disabled):hover {
    background: var(--ds-code-block-copy-bg-hover, var(--ds-button-ghost-bg-hover, var(--ds-surface-inset)));
    color: var(--ds-code-block-copy-ink-hover, var(--ds-color-text-primary));
  }
}

.ds-code-block[data-part='root'] [data-part='copy-button']:active:not(:disabled) {
  background: var(
    --ds-code-block-copy-bg-pressed,
    color-mix(in srgb, var(--ds-color-text-primary) 8%, transparent)
  );
}

/* Copied confirmation: the control flashes the success grammar (success ink,
   success-tinted frame) for the reset window, then settles back. The ink is
   pulled 30% toward the source's own primary text ink so it keeps reading on
   light surfaces where a raw status-500 green would wash out (same law as the
   gutter-ink mix in the engine). */
.ds-code-block[data-part='root'] [data-part='copy-button'][data-copied='true'],
.ds-code-block[data-part='root'] [data-part='copy-button'][data-copied='true']:not(:disabled):hover {
  color: var(
    --ds-code-block-copied-ink,
    color-mix(in srgb, var(--ds-color-success) 70%, var(--ds-color-text-primary))
  );
  border-color: var(
    --ds-code-block-copied-frame,
    color-mix(in srgb, var(--ds-color-success) 40%, transparent)
  );
}

/* Selection inside the block paints with the primary tint instead of the UA
   default -- state paint the inline styles cannot express. */
.ds-code-block[data-part='root'] ::selection {
  background: var(
    --ds-code-block-selection-bg,
    color-mix(in srgb, var(--ds-color-primary) 28%, transparent)
  );
}

.ds-code-block[data-part='root'] [data-part='copy-button']:focus-visible,
.ds-code-block[data-part='root'] [data-part='scroll']:focus-visible {
  outline: none;
  box-shadow: var(
    --ds-code-block-focus-ring,
    0 0 0 3px color-mix(in srgb, var(--ds-color-primary) 24%, transparent)
  );
}

@media (forced-colors: active) {
  .ds-code-block[data-part='root'] [data-part='copy-button'] {
    /* `ButtonBorder` is not a CSS system color (it never resolved); the frame
       reads the canonical button-text ink instead. */
    border-color: ButtonText;
  }
  .ds-code-block[data-part='root'] [data-part='copy-button']:not(:disabled):hover {
    background: Highlight;
    color: HighlightText;
  }
  .ds-code-block[data-part='root'] [data-part='copy-button']:focus-visible,
  .ds-code-block[data-part='root'] [data-part='scroll']:focus-visible {
    outline: 2px solid Highlight;
    box-shadow: none;
  }

  /* The scroll-edge shadows are background-image paint: forced colors strips
     them at used-value time (no explicit reset needed) and the block inverts
     safely -- root frame/background, header tint and language-badge chip are
     inline author colors, so the UA re-maps them to Canvas/CanvasText; the
     channeled scrollbar falls back to the system scrollbar. The block's frame
     and structure survive the inversion with zero author intervention. */

  /* Line-highlight bands carry STATE (which lines are flagged), and the
     system palette reserves exactly this pair for it. The band rides a custom
     property precisely so this remap wins WITHOUT !important (the family test
     contract bans it): forced colors leave the variable alone, so
     `background: var(--ds-code-block-line-highlight-bg)` resolves to Mark. */
  .ds-code-block[data-part='root'] [data-part='line'][data-highlighted='true'] {
    --ds-code-block-line-highlight-bg: Mark;
    color: MarkText;
  }

  /* Syntax highlighting is DATA (adapter-supplied token colors, the
     ColorPicker swatch precedent): collapsing it to one system ink would
     strip the component's function — distinguishing code structure by token
     kind. The opt-out is scoped to the highlighted token spans only; every
     chrome part above stays on system colors. */
  .ds-code-block[data-part='root'] [data-part='token'] {
    forced-color-adjust: none;
  }
}

}
@layer rottay-components {
/**
 * MarkdownView skin -- engine-agnostic, no `@layer` in-file (the facade
 * entrypoints import it into `layer(rottay-components)`, the same
 * registration as the voice-input-button family skin).
 * Home: foundation/tokens/css/presentation/components/skin/markdown-view.css --
