  align-items: center;
  justify-content: center;
  block-size: 24px;
  flex-shrink: 0;
  padding-inline: 8px;
  font-size: var(--ds-upload-action-font-size, 12px);
  cursor: pointer;
  background: transparent;
  color: var(--ds-color-text-primary);
  border-radius: var(--ds-radius-md);
  border: none;
}

/* ---- add-button (picture-card/circle "add" tile): Upload only, Dragger has
        no add-button. Layout, cursor and radius were drained from the
        utilities (`flex items-center justify-center`, `rounded-lg` /
        `rounded-full`, `cursor-pointer`) in the second pass; the quiet
        treatment (1px dashed hairline + 4% tint) was already owned here.
        The card radius takes the tile channel (`--ds-upload-file-radius`)
        so the nested radii relate -- the drained `rounded-lg` sat at 8px
        next to the 6px tile. ---- */
.ds-upload.ds-upload--modern [data-part='add-button'] {
  display: flex;
  align-items: center;
  justify-content: center;
  min-inline-size: var(--ds-upload-card-size, 104px);
  min-block-size: var(--ds-upload-card-size, 104px);
  /* Density (second pass): the tile padding rides the density-scaled spacing
     channel instead of a fixed 16px. */
  padding: var(--ds-spacing-4);
  cursor: pointer;
  background: transparent;
  border-radius: var(--ds-upload-file-radius);
  transition:
    border-color var(--ds-motion-fast) var(--ds-motion-ease-out),
    background var(--ds-motion-fast) var(--ds-motion-ease-out);
}
.ds-upload.ds-upload--modern.ds-upload--picture-circle [data-part='add-button'] {
  border-radius: 50%;
}
.ds-upload.ds-upload--modern .ds-upload__add-button[data-part='add-button'] {
  border: 1px dashed var(--ds-upload-add-border, var(--ds-color-border));
}
@media (hover: hover) {
  .ds-upload.ds-upload--modern .ds-upload__add-button[data-part='add-button']:where(:hover):not([data-disabled='true']) {
    background: var(--ds-upload-add-bg-hover, color-mix(in srgb, var(--ds-color-primary) 4%, transparent));
    border-color: var(--ds-upload-add-border-hover, color-mix(in srgb, var(--ds-color-primary) 55%, var(--ds-color-border)));
  }
}
