.ds-upload.ds-upload--modern .ds-upload__add-button[data-part='add-button']:active:not([data-disabled='true']) {
  background: var(--ds-upload-add-bg-hover, color-mix(in srgb, var(--ds-color-primary) 4%, transparent));
