.ds-upload-dragger.ds-upload-dragger--modern [data-part='dropzone'][data-state='dragging'] {
  border-color: var(--ds-upload-dropzone-border-active, color-mix(in srgb, var(--ds-color-primary) 55%, var(--ds-color-border)));
}
