  .ds-upload-dragger.ds-upload-dragger--modern [data-part='file-item'],
  .ds-upload.ds-upload--modern [data-part='file-item-action'],
  .ds-upload-dragger.ds-upload-dragger--modern [data-part='file-item-action'],
  .ds-upload.ds-upload--modern [data-part='add-button'],
  .ds-upload-dragger.ds-upload-dragger--modern [data-part='dropzone'],
  .ds-upload.ds-upload--modern [data-part='trigger'] button,
