  /* Per-file error hairlines: the semantic red is forced away, so the frame
     takes the system text ink -- the state still reads shape (frame + error
     glyph + message), never hue. */
  .ds-upload.ds-upload--modern:not(.ds-upload--picture-card) .ds-upload__file-item[data-part='file-item'][data-status='error'],
  .ds-upload-dragger.ds-upload-dragger--modern:not(.ds-upload-dragger--picture-card) .ds-upload__file-item[data-part='file-item'][data-status='error'],
  .ds-upload.ds-upload--modern.ds-upload--picture-card [data-part='file-item'][data-status='error'],
  .ds-upload-dragger.ds-upload-dragger--modern.ds-upload-dragger--picture-card [data-part='file-item'][data-status='error'],
  .ds-upload.ds-upload--modern.ds-upload--picture-circle [data-part='file-item'][data-status='error'],
  .ds-upload-dragger.ds-upload-dragger--modern.ds-upload-dragger--picture-circle [data-part='file-item'][data-status='error'] {
    border-color: ButtonText;
  }
  .ds-upload.ds-upload--modern [data-part='trigger'] button:focus-visible,
  .ds-upload.ds-upload--modern [data-part='add-button']:focus-visible,
  .ds-upload.ds-upload--modern [data-part='file-item-action']:focus-visible,
  .ds-upload-dragger.ds-upload-dragger--modern [data-part='file-item-action']:focus-visible,
  .ds-upload-dragger.ds-upload-dragger--modern [data-part='dropzone']:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
  .ds-upload.ds-upload--modern [data-part='preview-close-button'],
  .ds-upload-dragger.ds-upload-dragger--modern [data-part='preview-close-button'] {
    background: ButtonFace;
    color: ButtonText;
  }
