}
.rottay-transfer.rottay-transfer--modern [data-part='panel-select-all'][data-disabled='true'],
.rottay-transfer.rottay-transfer--modern [data-part='panel-item-checkbox'][data-disabled='true'] {
  cursor: var(--ds-transfer-button-disabled-cursor, var(--ds-button-disabled-cursor, not-allowed));
}

/* Coarse-pointer floor (K4-D remediation round 2): the search input measured
   28px tall on real mobile chromium; the move (32px) and pagination (24px)
   buttons fail the same 44px wave floor. Same `media (pointer: coarse)`
   idiom as the certified Textarea skin; `--ds-input-touch-target-min` is the
   governed channel (bithire emits 44px). */
@media (pointer: coarse) {
  .rottay-transfer.rottay-transfer--modern [data-part='panel-search'] {
    min-block-size: var(--ds-input-touch-target-min, 44px);
  }
  .rottay-transfer.rottay-transfer--modern [data-part='move-button'] {
    min-inline-size: var(--ds-input-touch-target-min, 44px);
    min-block-size: var(--ds-input-touch-target-min, 44px);
  }
  .rottay-transfer.rottay-transfer--modern [data-part='pagination-button'] {
    min-inline-size: var(--ds-input-touch-target-min, 44px);
    min-block-size: var(--ds-input-touch-target-min, 44px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .rottay-transfer.rottay-transfer--modern [data-part='move-button'],
  .rottay-transfer.rottay-transfer--modern [data-part='pagination-button'],
  .rottay-transfer.rottay-transfer--modern [data-part='panel-item'] {
    transition-duration: 0.01ms;
  }
}

@media (forced-colors: active) {
