.rottay-transfer.rottay-transfer--rustic [data-part='panel'][data-part='panel'] {
  border: 1px solid var(--ds-transfer-border);
}

.rottay-transfer.rottay-transfer--rustic [data-part='panel-header'] {
  background-color: var(--ds-transfer-header-bg);
}
.rottay-transfer.rottay-transfer--rustic [data-part='panel-header'][data-part='panel-header'] {
  border-bottom: 2px solid var(--ds-transfer-header-border);
}

.rottay-transfer.rottay-transfer--rustic [data-part='panel-count'] {
  color: var(--ds-transfer-count-color);
}

.rottay-transfer.rottay-transfer--rustic .rottay-transfer__search.rottay-transfer__search {
  border-bottom: 1px solid var(--ds-transfer-header-border);
}

.rottay-transfer.rottay-transfer--rustic [data-part='panel-search'] {
  border-radius: var(--ds-transfer-search-input-radius);
  outline: none;
}
.rottay-transfer.rottay-transfer--rustic [data-part='panel-search'][data-part='panel-search'] {
  border: 1px solid var(--ds-transfer-search-input-border);
}
.rottay-transfer.rottay-transfer--rustic [data-part='panel-search'][data-part='panel-search']:focus {
