.rottay-transfer.rottay-transfer--rustic [data-part='panel-pagination'][data-part='panel-pagination'] {
  border-top: 1px solid var(--ds-transfer-header-border);
}
.rottay-transfer.rottay-transfer--rustic [data-part='panel-pagination'] > span {
  color: var(--ds-transfer-count-color);
}

.rottay-transfer.rottay-transfer--rustic [data-part='pagination-button'] {
  background: none;
  border-radius: 4px;
  color: inherit;
}
.rottay-transfer.rottay-transfer--rustic [data-part='pagination-button'][data-part='pagination-button'] {
  border: 1px solid var(--ds-transfer-border);
}

.rottay-transfer.rottay-transfer--rustic [data-part='move-button'] {
  background-color: var(--ds-transfer-button-bg);
  color: var(--ds-transfer-button-color);
