.rottay-colorpicker.rottay-colorpicker--modern [data-part='swatch'][data-size='middle'] {
  inline-size: var(--ds-colorpicker-swatch-size-md, 2rem);
  block-size: var(--ds-colorpicker-swatch-size-md, 2rem);
