.rottay-colorpicker.rottay-colorpicker--modern [data-part='swatch'][data-size='large'] {
  inline-size: var(--ds-colorpicker-swatch-size-lg, 2.5rem);
  block-size: var(--ds-colorpicker-swatch-size-lg, 2.5rem);
