.ds-autocomplete.ds-autocomplete--modern[data-part='root'] [data-part='input']:focus-visible {
  border-color: var(--ds-autocomplete-border-focus, var(--ds-color-primary));
  box-shadow: var(--ds-autocomplete-shadow-focus, var(--ds-shadow-focus-ring));
}
.ds-autocomplete.ds-autocomplete--modern[data-part='root'] [data-part='input']:disabled {
