/* Status grammar (contract `status`, wired in the Phase-B engine pass): the
   Input family's error/warning posture -- surface tint + border step +
   status-tinted ring on focus. Ordered AFTER hover/focus so equal-specificity
   state rules yield to the semantic state. */
.ds-autocomplete.ds-autocomplete--modern[data-part='root'][data-status='error'] [data-part='input'] {
  background: var(--ds-input-error-bg, var(--ds-autocomplete-bg, var(--ds-input-bg, var(--ds-surface-control))));
  border-color: var(--ds-autocomplete-error-border, var(--ds-color-error));
}
.ds-autocomplete.ds-autocomplete--modern[data-part='root'][data-status='error'] [data-part='input']:focus-visible {
  border-color: var(--ds-autocomplete-error-border, var(--ds-color-error));
  box-shadow: var(--ds-input-error-shadow-focus, var(--ds-autocomplete-shadow-focus, var(--ds-shadow-focus-ring)));
}
.ds-autocomplete.ds-autocomplete--modern[data-part='root'][data-status='warning'] [data-part='input'] {
  background: var(--ds-input-warning-bg, var(--ds-autocomplete-bg, var(--ds-input-bg, var(--ds-surface-control))));
  border-color: var(--ds-autocomplete-warning-border, var(--ds-color-warning));
}
.ds-autocomplete.ds-autocomplete--modern[data-part='root'][data-status='warning'] [data-part='input']:focus-visible {
  border-color: var(--ds-autocomplete-warning-border, var(--ds-color-warning));
  box-shadow: var(--ds-input-warning-shadow-focus, var(--ds-autocomplete-shadow-focus, var(--ds-shadow-focus-ring)));
}

/* Browser chrome: keep autofill legible and on-surface (webkit + standard). */
.ds-autocomplete.ds-autocomplete--modern[data-part='root'] [data-part='input']:-webkit-autofill {
  -webkit-text-fill-color: var(--ds-input-autofill-color, var(--ds-color-text-primary));
  caret-color: var(--ds-input-autofill-caret, var(--ds-input-caret-color, var(--ds-color-primary)));
  box-shadow: 0 0 0 1000px var(--ds-input-autofill-bg, var(--ds-autocomplete-bg, var(--ds-input-bg, var(--ds-surface-control)))) inset;
