  box-shadow: 0 0 0 1000px var(--ds-input-autofill-bg, var(--ds-autocomplete-bg, var(--ds-input-bg, var(--ds-surface-control)))) inset;
}

/* Inline-end reserve so a long value never runs under the clear button. */
.ds-autocomplete.ds-autocomplete--modern[data-part='root'] [data-part='input-wrapper']:has([data-part='clear-button']) [data-part='input'] {
  padding-inline-end: var(--ds-autocomplete-clear-reserve, 32px);
