  block-size: var(--ds-autocomplete-clear-size, 24px);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  cursor: pointer;
  background: transparent;
  color: var(--ds-autocomplete-clear-color, var(--ds-color-text-muted));
