  border-radius: var(--ds-autocomplete-dropdown-radius, var(--ds-radius-lg));
  background:
    linear-gradient(var(--ds-elevation-surface-3), var(--ds-elevation-surface-3)),
    var(--ds-autocomplete-dropdown-bg, var(--ds-surface-card));
  border: 1px solid var(--ds-color-border-subtle);
  box-shadow: var(--ds-autocomplete-dropdown-shadow, var(--ds-elevation-2));
  animation: ds-autocomplete-slide-in var(--ds-motion-fast) var(--ds-motion-ease-out);
