.ds-autocomplete.ds-autocomplete--modern[data-part='root'] [data-part='dropdown'][data-match-width='false'] {
  inline-size: max-content;
  min-inline-size: 100%;
  max-inline-size: min(var(--_ds-proto-autocomplete-dropdown-max-width, 28rem), calc(100vw - 1rem));
}

