  display: inline-grid;
  place-items: center;
  color: var(--ds-select-arrow-color, var(--ds-color-text-muted));
  transform: translateY(-50%);
  pointer-events: none;
}

.ds-select-shell.ds-select-shell--modern[data-part='root'][data-loading='true'] [data-part='native-arrow'] {
  opacity: 0;
}

/* Native branch: the spinner parks where the arrow lives (logical inset). */
.ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='loading'] {
  position: absolute;
  inset-block-start: 50%;
  inset-inline-end: var(--ds-select-loading-inset, 2rem);
  display: inline-flex;
  transform: translateY(-50%);
  pointer-events: none;
}

/* Custom branch: the status wrapper stays in the trigger-actions flex flow
   (the absolute parking above is native-only). */
.ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='loading-status'] {
  display: inline-grid;
  flex: none;
  place-items: center;
}

/* Accessible announcement: audible through role="status" on the wrapper,
   invisible on screen (the Button `accessible-label` idiom). */
.ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='loading-label'] {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='loading-spinner'] {
  display: inline-block;
  inline-size: var(--ds-select-loading-size);
  block-size: var(--ds-select-loading-size);
  animation: ds-foundation-spin var(--ds-motion-glacial) linear infinite;
}

.ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='loading-spinner'][data-part='loading-spinner'] {
  border: 2px solid
    color-mix(in srgb, var(--ds-color-primary) 28%, var(--ds-color-border));
  border-top-color: var(--ds-color-primary);
  border-radius: 50%;
}

/* Portaled panel ----------------------------------------------------------- */

.ds-select-shell__dropdown.ds-select-shell__dropdown[data-part='dropdown'] {
  --ds-select-enter-y: -5px;
  isolation: isolate;
  min-inline-size: min(var(--ds-select-dropdown-min-width, 15rem), calc(100vw - 1rem));
  max-inline-size: min(var(--ds-select-dropdown-max-width, 28rem), calc(100vw - 1rem));
  padding: var(--ds-select-dropdown-padding);
  overflow: hidden;
  color: var(--ds-color-text-primary);
  font-family: var(--ds-select-font-family, var(--ds-font-family-base));
  border-radius: var(--ds-select-dropdown-radius, var(--ds-radius-lg));
  background: var(--ds-select-dropdown-bg, var(--ds-surface-card));
  box-shadow: var(--ds-select-dropdown-shadow, var(--ds-elevation-3));
  backdrop-filter: var(--ds-select-backdrop-filter, none);
  transform-origin: center top;
  animation: ds-select-appear var(--ds-motion-fast) var(--ds-motion-ease-out);
}

.ds-select-shell__dropdown.ds-select-shell__dropdown[data-part='dropdown'][data-part='dropdown'] {
  border: var(--ds-select-dropdown-border-width, 1px) solid
    var(--ds-select-dropdown-border-color, var(--ds-color-border));
}

.ds-select-shell__dropdown[data-part='dropdown'][data-placement='top'] {
  --ds-select-enter-y: 5px;
  transform-origin: center bottom;
}

/* ---- Search row inside the panel. ---- */

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='search-input-wrapper'] {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 0.55rem;
  min-block-size: calc(2.55rem * var(--ds-density-effective-scale));
  margin-block-end: 0.35rem;
  padding: 0.45rem 0.65rem;
  align-items: center;
  color: var(--ds-color-text-secondary);
  border-radius: var(--ds-select-search-radius, var(--ds-radius-md));
  background: var(--ds-select-search-bg, var(--ds-surface-inset, var(--ds-surface-canvas)));
  transition:
    border-color var(--ds-motion-fast) var(--ds-motion-ease-out),
    background-color var(--ds-motion-fast) var(--ds-motion-ease-out),
    box-shadow var(--ds-motion-fast) var(--ds-motion-ease-out);
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='search-input-wrapper'][data-part='search-input-wrapper'] {
  border: 1px solid var(--ds-select-search-border, var(--ds-color-border-subtle));
}

/* The internal filter field owns no chrome of its own: focus surfaces on the
   well, mirroring the trigger's border + ring grammar (one focus language). */
.ds-select-shell__dropdown[data-part='dropdown'] [data-part='search-input-wrapper']:focus-within {
  border-color: var(--ds-select-border-color-focus, var(--ds-color-primary));
  background: var(--ds-select-bg-focus, var(--ds-select-search-bg, var(--ds-surface-inset, var(--ds-surface-canvas))));
  box-shadow: var(--ds-select-shadow-focus, var(--ds-focus-ring));
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='search-icon'] {
  color: var(--ds-select-search-icon-color, var(--ds-color-text-muted));
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='search-input'] {
  inline-size: 100%;
  min-inline-size: 0;
  padding: 0;
  color: var(--ds-color-text-primary);
  border: 0;
  background: transparent;
  font-family: var(--ds-font-family-base);
  font-size: var(--ds-font-size-sm);
  line-height: var(--ds-line-height-snug);
  outline: 0;
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='search-input']::placeholder {
  color: var(--ds-color-text-muted);
}

/* ---- Option list. ---- */

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option-list'] {
  display: grid;
  gap: 0.2rem;
  max-block-size: var(--ds-select-max-height, 240px);
  overflow-x: hidden;
  overflow-y: auto;
  scrollbar-color: color-mix(in srgb, var(--ds-color-primary) 24%, var(--ds-color-border)) transparent;
  scrollbar-width: thin;
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option-list'][data-virtual='true'] {
  max-block-size: none;
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option-list']::-webkit-scrollbar {
  inline-size: 6px;
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option-list']::-webkit-scrollbar-thumb {
  border-radius: var(--ds-radius-full);
  background: color-mix(in srgb, var(--ds-color-primary) 24%, var(--ds-color-border));
}

/* ---- Group labels: the editorial eyebrow. ---- */

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='group-label'] {
  display: flex;
  min-block-size: 1.8rem;
  margin-block: 0.3rem 0.05rem;
  padding: 0.35rem 0.65rem;
  align-items: center;
  color: var(--ds-select-group-color, var(--ds-color-text-muted));
  font-family: var(--ds-font-family-heading, var(--ds-font-family-base));
  font-size: var(--ds-font-size-xs);
  font-weight: var(--ds-font-weight-semibold);
  letter-spacing: var(--ds-letter-spacing-wide);
  line-height: 1.2;
  text-transform: uppercase;
  user-select: none;
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='group-label'][data-divider='true'] {
  margin-block-start: 0.55rem;
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='group-label'][data-divider][data-divider='true'] {
  border-block-start: 1px solid var(--ds-select-group-divider, var(--ds-color-border-subtle));
}

/* ---- Options: hairline frames, no lifts; state by surface and ink. ---- */

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option'] {
  position: relative;
  display: flex;
  inline-size: 100%;
  min-block-size: calc(
    var(--ds-select-option-height) * var(--ds-density-effective-scale)
  );
  padding: var(--ds-select-option-padding-y, 0.48rem) var(--ds-select-option-padding-x, 0.62rem);
  align-items: center;
  gap: 0.55rem;
  overflow: hidden;
  color: var(--ds-select-option-color, var(--ds-color-text-secondary));
  border-radius: var(--ds-select-option-radius, var(--ds-radius-md));
  background: transparent;
  font-family: var(--ds-font-family-base);
  font-size: var(--ds-select-option-font-size, var(--ds-font-size-sm));
  line-height: var(--ds-line-height-snug);
  text-align: start;
  cursor: pointer;
  outline: none;
  user-select: none;
  transition:
    color var(--ds-motion-fast) var(--ds-motion-ease-out),
    border-color var(--ds-motion-fast) var(--ds-motion-ease-out),
    background-color var(--ds-motion-fast) var(--ds-motion-ease-out);
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option'][data-part='option'] {
  border: 1px solid transparent;
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option']:not([data-disabled='true']):hover,
.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option'][data-active='true'] {
  color: var(--ds-select-option-color-hover, var(--ds-color-text-primary));
  border-color: var(--ds-select-option-border-hover, var(--ds-color-border-subtle));
  background: var(
    --ds-select-option-bg-hover,
    color-mix(in srgb, var(--ds-color-primary) 5%, var(--ds-surface-card))
  );
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option'][data-selected='true'] {
  color: var(--ds-select-option-color-selected, var(--ds-color-primary));
  border-color: var(
    --ds-select-option-border-selected,
    color-mix(in srgb, var(--ds-color-primary) 32%, var(--ds-color-border-subtle))
  );
  background: var(
    --ds-select-option-bg-selected,
    color-mix(in srgb, var(--ds-color-primary) 9%, var(--ds-surface-card))
  );
  font-weight: var(--ds-font-weight-semibold);
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option'][data-disabled='true'] {
  color: var(--ds-color-text-disabled, var(--ds-color-text-muted));
  cursor: not-allowed;
  opacity: var(--ds-opacity-disabled, 0.46);
}

/* ---- Option affordances (checkbox, icon well, check). ---- */

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option-checkbox'] {
  display: inline-grid;
  flex: none;
  inline-size: 1.05rem;
  block-size: 1.05rem;
  place-items: center;
  color: var(--ds-color-text-on-primary, var(--ds-color-white));
  border-radius: var(--ds-radius-sm);
  background: var(--ds-surface-card);
  transition:
    border-color var(--ds-motion-fast) var(--ds-motion-ease-out),
    background-color var(--ds-motion-fast) var(--ds-motion-ease-out);
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option-checkbox'][data-part='option-checkbox'] {
  border: 1px solid var(--ds-color-border);
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-selected='true'] [data-part='option-checkbox'] {
  border-color: var(--ds-color-primary);
  background: var(--ds-color-primary);
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option-icon'] {
  display: inline-grid;
  flex: none;
  inline-size: var(--ds-select-option-icon-well-size, 1.8rem);
  block-size: var(--ds-select-option-icon-well-size, 1.8rem);
  place-items: center;
  color: var(--ds-color-primary);
  border-radius: var(--ds-radius-md);
  background: color-mix(in srgb, currentColor 7%, transparent);
  transition:
    background-color var(--ds-motion-fast) var(--ds-motion-ease-out);
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option']:hover [data-part='option-icon'] {
  background: color-mix(in srgb, currentColor 11%, transparent);
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option-content'] {
  display: flex;
  min-inline-size: 0;
  flex: 1 1 auto;
  flex-direction: column;
  gap: 0.12rem;
  overflow: hidden;
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option-label'],
.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option-description'] {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option-label'] {
  color: currentColor;
  font-weight: var(--ds-font-weight-medium);
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option-description'] {
  color: var(--ds-color-text-muted);
  font-size: var(--ds-font-size-xs);
  font-weight: var(--ds-font-weight-normal);
  line-height: 1.35;
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='option-check'] {
  display: inline-grid;
  flex: none;
  inline-size: 1.5rem;
  block-size: 1.5rem;
  place-items: center;
  color: var(--ds-color-primary);
  border-radius: var(--ds-radius-full);
  background: color-mix(in srgb, var(--ds-color-primary) 9%, transparent);
}

/* ---- Empty posture: quiet dashed well with the honest message. ---- */

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='empty'] {
  display: grid;
  min-block-size: 4.5rem;
  padding: 1rem;
  place-items: center;
  color: var(--ds-color-text-muted);
  border-radius: var(--ds-radius-md);
  background: var(--ds-select-empty-bg, transparent);
  font-size: var(--ds-font-size-sm);
  line-height: var(--ds-line-height-relaxed);
  text-align: center;
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='empty'][data-part='empty'] {
  border: 1px dashed var(--ds-select-empty-border, var(--ds-color-border));
}

/* ---- Loading posture: the empty well's spatial contract, spinner + copy.
       Async search never flashes "no options" while results stream in. ---- */

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='loading-state'] {
  display: flex;
  min-block-size: 4.5rem;
  padding: 1rem;
  align-items: center;
  justify-content: center;
  gap: var(--ds-spacing-2);
  color: var(--ds-select-loading-color, var(--ds-color-text-muted));
  border-radius: var(--ds-radius-md);
  background: var(--ds-select-empty-bg, transparent);
  font-size: var(--ds-font-size-sm);
  line-height: var(--ds-line-height-relaxed);
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='loading-state'][data-part='loading-state'] {
  border: 1px dashed var(--ds-select-empty-border, var(--ds-color-border));
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='loading-state'] [data-part='loading-spinner'] {
  display: inline-block;
  flex: none;
  inline-size: var(--ds-select-loading-size);
  block-size: var(--ds-select-loading-size);
  animation: ds-foundation-spin var(--ds-motion-glacial) linear infinite;
}

.ds-select-shell__dropdown[data-part='dropdown'] [data-part='loading-state'] [data-part='loading-spinner'][data-part='loading-spinner'] {
  border: 2px solid
    color-mix(in srgb, var(--ds-color-primary) 28%, var(--ds-color-border));
  border-top-color: var(--ds-color-primary);
  border-radius: 50%;
}

/* ---- Coarse pointers: the option row meets the touch floor. ---- */

@media (pointer: coarse) {
  .ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='trigger'] {
    min-block-size: max(
      calc(
        var(--ds-select-trigger-responsive-height, var(--ds-select-trigger-height, 36px)) *
          var(--ds-density-effective-scale)
      ),
      var(--ds-select-touch-target-min, 44px)
    );
  }

  .ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='clear-button'] {
    min-inline-size: var(--ds-select-touch-target-min, 44px);
    min-block-size: var(--ds-select-touch-target-min, 44px);
  }

  /* The tag remove lives inside a 1.42rem pill: a 44px floor would blow the
     chip up, so it meets the smaller WCAG 2.5.8 target instead. */
  .ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='tag-remove'] {
    min-inline-size: var(--ds-select-tag-remove-touch-min, 1.5rem);
    min-block-size: var(--ds-select-tag-remove-touch-min, 1.5rem);
  }

  .ds-select-shell__dropdown[data-part='dropdown'] [data-part='option'] {
    min-block-size: max(
      calc(var(--ds-select-option-height) * var(--ds-density-effective-scale)),
      var(--ds-select-touch-target-min, 44px)
    );
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='trigger'],
  .ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='arrow-icon'],
  .ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='tag-remove'],
  .ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='clear-button'],
  .ds-select-shell__dropdown[data-part='dropdown'],
  .ds-select-shell__dropdown[data-part='dropdown'] [data-part='option'],
  .ds-select-shell__dropdown[data-part='dropdown'] [data-part='option-icon'],
  .ds-select-shell__dropdown[data-part='dropdown'] [data-part='option-checkbox'],
  .ds-select-shell__dropdown[data-part='dropdown'] [data-part='search-input-wrapper'] {
    animation: none;
    transition: none;
  }

  /* Keep a slowed spin rather than a frozen frame so the loading posture
     stays legible; the duration derives from the motion scale. */
  .ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='loading-spinner'],
  .ds-select-shell__dropdown[data-part='dropdown'] [data-part='loading-state'] [data-part='loading-spinner'] {
    animation-duration: calc(var(--ds-motion-glacial) * 2);
  }
}

@media (forced-colors: active) {
  .ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='trigger'][data-variant] {
    forced-color-adjust: auto;
    border-color: ButtonText;
  }

  .ds-select-shell.ds-select-shell--modern[data-part='root'] div[data-part='trigger'][data-open='true'],
  .ds-select-shell.ds-select-shell--modern[data-part='root'] select[data-part='trigger']:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }

  .ds-select-shell.ds-select-shell--modern[data-part='root'][data-disabled='true'] [data-part='trigger'],
  .ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='trigger'][data-disabled='true'] {
    color: GrayText;
    border-color: GrayText;
  }

  .ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='tag'],
  .ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='tag-count'] {
    border-color: ButtonText;
  }

  .ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='clear-button'],
  .ds-select-shell.ds-select-shell--modern[data-part='root'] [data-part='tag-remove'] {
    forced-color-adjust: auto;
    border-color: ButtonText;
  }

  /* Keyboard focus inside the listbox must survive the forced palette: the
     active option gets the same Highlight grammar as the selected one. */
  .ds-select-shell__dropdown[data-part='dropdown'] [data-part='option'][data-selected='true'],
  .ds-select-shell__dropdown[data-part='dropdown'] [data-part='option'][data-active='true'] {
    outline: 1px solid Highlight;
  }

  .ds-select-shell__dropdown[data-part='dropdown'] [data-part='option'][data-active='true'] {
    outline-offset: -1px;
  }

  .ds-select-shell__dropdown[data-part='dropdown'] [data-part='option-checkbox'] {
    border-color: ButtonText;
  }

  .ds-select-shell__dropdown[data-part='dropdown'] [data-selected='true'] [data-part='option-checkbox'] {
    color: HighlightText;
    border-color: Highlight;
    background: Highlight;
  }

  .ds-select-shell__dropdown[data-part='dropdown'] [data-part='option-check'] {
    color: Highlight;
    background: transparent;
  }

  .ds-select-shell__dropdown[data-part='dropdown'] [data-part='empty'],
  .ds-select-shell__dropdown[data-part='dropdown'] [data-part='loading-state'] {
    border-color: ButtonText;
  }
}

}
@layer rottay-engines {
/**
 * Rustic Select skin (WO-SKIN-02 checkpoint B, dropdown family).
 *
 * DELIBERATELY UNLAYERED, same rationale as every other engine skin (P-47).
 *
 * SCOPE ROOT is the container `<div>`, carrying the BEM pair
 * `.rottay-select.rottay-select--rustic` + `data-part='root'` plus the variant
 * class (`--filled`/`--flushed`/…), `data-open`, `data-disabled` and
 * `data-status`. The dropdown is IN-TREE (rustic never portals), so every part
 * is a descendant of the root and the two root classes already lift each rule
 * to (0,4,0) — no repeated-`data-part` trick is needed here.
 *
 * TRIGGER reproduces `getBorderColor()`'s priority error > warning > success >
 * open > default. The open rule carries `:not([data-status])` so a field with a
 * status keeps its status border even while open (the JS checks status first).
 * `border-color` is set on all four sides; the `--flushed` variant zeroes the
 * box and shows only a 2px bottom edge, so the same color surfaces there.
 *
 * The imperative hover handlers are removed and transcribed verbatim as `:hover`
 * rules: the selected-tag chip's `transform: scale(1.05)`, and the tag-remove
 * button's `color: var(--ds-form-error-color, #ef4444)`. The option row's
 * highlight rides `data-active`/`data-selected` (set from `focusedIndex` by the
 * retained `onMouseEnter`), and the arrow's open rotation rides `data-open`.
 *
 * Hardcoded literals transcribed byte-exact from the source `var(--…, #hex)`
 * fallbacks: `#1677ff` (option focus border-left, tag-remove uses
 * `#ef4444`), `rgba(22, 119, 255, 0.15)` (option focus box-shadow).
 *
 * Keyframes moved out of the engine's `<style>` tag, renamed `ds-select-spin`,
 * `ds-select-dropdown-in`, `ds-select-check-in`.
 */

@keyframes ds-select-spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}
@keyframes ds-select-dropdown-in {
  from { opacity: 0; transform: scaleY(0.95) translateY(-4px); }
  to { opacity: 1; transform: scaleY(1) translateY(0); }
}
@keyframes ds-select-check-in {
  from { opacity: 0; transform: scale(0); }
  to { opacity: 1; transform: scale(1); }
}

/* ---- trigger: box, radius, colors ---- */
.rottay-select.rottay-select--rustic[data-part='root'] [data-part='trigger'] {
  border-style: solid;
  border-width: 1px;
  border-color: var(--ds-select-border);
  border-radius: var(--ds-select-radius);
  background-color: var(--ds-select-bg);
  color: var(--ds-select-color);
  outline: none;
  box-shadow: none;
}
/* flushed: only a 2px bottom edge, square corners */
.rottay-select.rottay-select--rustic.rottay-select--flushed[data-part='root'] [data-part='trigger'] {
  border-width: 0;
  border-bottom-width: 2px;
  border-radius: 0;
}

