.ds-cascader.ds-cascader--modern[data-part="root"] [data-part="clear-button"] {
  position: absolute;
  inset-inline-end: var(--ds-cascader-clear-inset-inline-end, 30px);
  inset-block-start: 50%;
  transform: translateY(-50%);
  inline-size: var(--ds-cascader-clear-size, 24px);
  block-size: var(--ds-cascader-clear-size, 24px);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  cursor: pointer;
  background: transparent;
  color: var(--ds-color-text-primary);
  border-radius: 50%;
  border: none;
  transition: color var(--ds-motion-fast)
    var(--ds-motion-ease-out);
}
.ds-cascader.ds-cascader--modern[data-part="root"]:has(
    [data-part="clear-button"]
  )
  [data-part="arrow-icon"] {
  margin-inline-start: var(--ds-cascader-clear-gap, 20px);
}
@media (hover: hover) {
  .ds-cascader.ds-cascader--modern[data-part="root"]
    [data-part="clear-button"]:hover {
    color: var(--ds-input-clear-color-hover, var(--ds-color-text-primary));
  }
}
/* Touch/active equivalent. The clear reset is a NEUTRAL action: it reads the
   Input clear grammar's ink step, never the error hue (a destructive
   miscue). */
