  [data-part="clear-button"]:active {
  color: var(--ds-input-clear-color-hover, var(--ds-color-text-primary));
}
.ds-cascader.ds-cascader--modern[data-part="root"]
  [data-part="clear-button"]:focus-visible {
  outline: none;
  box-shadow: var(--ds-cascader-shadow-focus, var(--ds-shadow-focus-ring));
}

/* Trigger chevron: open rotation drained from the `rotate-180` utility +
   inline transition. The glyph is vertically symmetric -- no RTL mirror. */
.ds-cascader.ds-cascader--modern[data-part="root"] [data-part="arrow-icon"] {
  transition: transform var(--ds-motion-fast)
    var(--ds-motion-ease-out);
}
.ds-cascader.ds-cascader--modern[data-part="root"]
  [data-part="trigger"][data-open="true"]
  [data-part="arrow-icon"] {
  transform: rotate(180deg);
}

/* ---- dropdown panel (in-tree): geometry drained from the inline style.
        The panel caps at the viewport and the column set scrolls inline on
        narrow instead of overflowing. z rides the token scale (dropdown
        tier); the dark-aware luminance step is its own layer above the fill
        (lane overlay register). ---- */
.ds-cascader.ds-cascader--modern[data-part="root"] [data-part="dropdown"] {
  position: absolute;
  inset-inline-start: 0;
  z-index: var(--ds-cascader-dropdown-z, var(--ds-z-index-dropdown));
  margin-block-start: var(--ds-spacing-1);
  max-inline-size: calc(100vw - 2 * var(--ds-spacing-4));
  border-radius: var(--ds-radius-lg);
  background: linear-gradient(
      var(--ds-elevation-surface-3),
      var(--ds-elevation-surface-3)
    ),
    var(--ds-surface-card);
  box-shadow: var(--ds-elevation-2);
  border-color: var(--ds-color-border);
  border-width: 1px;
  border-style: solid;
  animation: ds-cascader-slide-in var(--ds-motion-fast)
    var(--ds-motion-ease-out);
}
/* The columns wrap is a horizontal track (drained from the `flex` utility). */
.ds-cascader.ds-cascader--modern[data-part="root"]
  [data-part="dropdown"]
  div[data-part="option-list"] {
  display: flex;
}
.ds-cascader.ds-cascader--modern[data-part="root"]
  [data-part="dropdown"]
  [data-part="option-list"] {
  max-inline-size: calc(
    100vw - 2 * var(--ds-spacing-4) - 2 * var(--ds-spacing-1)
  );
  overflow-x: auto;
}

.ds-cascader.ds-cascader--modern[data-part="root"]
  [data-part="search-input-wrapper"] {
  padding: var(--ds-spacing-2);
  border-bottom: 1px solid var(--ds-color-border);
}

.ds-cascader.ds-cascader--modern[data-part="root"] [data-part="search-input"] {
  inline-size: 100%;
  border: 1px solid var(--ds-color-border);
  border-radius: var(--ds-radius-md);
  background: var(--ds-input-bg, var(--ds-surface-control));
  color: var(--ds-color-text-primary);
  outline: none;
  transition: border-color var(--ds-motion-fast)
      var(--ds-motion-ease-out),
    box-shadow var(--ds-motion-fast) var(--ds-motion-ease-out);
}
.ds-cascader.ds-cascader--modern[data-part="root"]
  [data-part="search-input"]:focus-visible {
  border-color: var(--ds-cascader-border-focus, var(--ds-color-primary));
  box-shadow: var(--ds-cascader-shadow-focus, var(--ds-shadow-focus-ring));
}
@media (hover: hover) {
  .ds-cascader.ds-cascader--modern[data-part="root"]
    [data-part="search-input"]:where(:hover):not(:disabled):not(:focus-visible) {
    border-color: var(--ds-cascader-border-hover, var(--ds-color-border-hover));
  }
}
/* Touch/active equivalent of the hover border (4th-tanda law). */
.ds-cascader.ds-cascader--modern[data-part="root"]
  [data-part="search-input"]:active:not(:disabled):not(:focus-visible) {
  border-color: var(--ds-cascader-border-hover, var(--ds-color-border-hover));
}
.ds-cascader.ds-cascader--modern[data-part="root"] [data-part="search-input"]::placeholder {
  color: var(--ds-input-color-placeholder, var(--ds-color-text-muted));
}

/* Empty posture: the dropdown family's empty-well spatial contract (dashed
   hairline, 4.5rem min-block, radius, muted helper ink) -- never a bare
   padded string (AutoComplete/Select idiom). */
.ds-cascader.ds-cascader--modern[data-part="root"] [data-part="empty"] {
  display: grid;
  place-items: center;
  min-block-size: 4.5rem;
  padding: var(--ds-spacing-2) var(--ds-spacing-3);
  border: 1px dashed var(--ds-color-border);
  border-radius: var(--ds-radius-md);
  color: var(--ds-color-text-muted);
  font-size: var(--ds-font-size-sm);
  line-height: var(--ds-line-height-snug);
  text-align: center;
