@media (hover: hover) {
  .ds-cascader.ds-cascader--modern[data-part="root"]
    [data-part="option"]:where(:hover):not([data-selected="true"]):not(
      [data-disabled="true"]
    ) {
    background: var(--ds-color-bg-hover);
  }
