/* Touch/active equivalent of the hover wash (4th-tanda law: every hover
   paints an equivalent active state). */
.ds-cascader.ds-cascader--modern[data-part="root"]
  [data-part="option"]:active:not([data-selected="true"]):not(
    [data-disabled="true"]
  ) {
  background: var(--ds-color-bg-hover);
}
.ds-cascader.ds-cascader--modern[data-part="root"]
  [data-part="option"]:focus-visible {
  outline: none;
  box-shadow: var(--ds-cascader-shadow-focus, var(--ds-shadow-focus-ring));
}
.ds-cascader.ds-cascader--modern[data-part="root"]
  [data-part="option"][data-disabled="true"] {
  opacity: var(--ds-disabled-opacity, 0.5);
  cursor: not-allowed;
}
.ds-cascader.ds-cascader--modern[data-part="root"]
  [data-part="option"][data-selected="true"] {
  background: var(
    --ds-color-bg-selected,
    color-mix(in srgb, var(--ds-color-primary) 10%, transparent)
  );
  border-color: color-mix(in srgb, var(--ds-color-primary) 24%, transparent);
  font-weight: var(--ds-font-weight-medium);
}

/* Option label truncation (never wraps mid-word). */
.ds-cascader.ds-cascader--modern[data-part="root"]
  [data-part="option"]
  > [data-part="option-label"] {
  min-inline-size: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Child chevron: governed icon (icon facade autoMirror flips it under RTL --
   no skin transform needed). */
.ds-cascader.ds-cascader--modern[data-part="root"] [data-part="chevron"] {
  display: inline-flex;
  margin-inline-start: var(--ds-spacing-2);
  color: var(--ds-color-text-muted);
}

.ds-cascader.ds-cascader--modern[data-part="root"] [data-part="loading"] {
  inline-size: 12px;
  block-size: 12px;
  border: 2px solid var(--ds-color-border);
  border-top-color: var(--ds-color-primary);
  border-radius: 50%;
  /* Drained from the inline animation (reduced-motion now governs it). */
  animation: ds-foundation-spin
    var(--ds-cascader-spinner-duration, var(--ds-motion-glacial)) linear
    infinite;
}
/* ---- coarse pointer: rows/trigger/clear reach the 44px floor via
        min-block-size (wins over inline heights, fine pointers untouched). ---- */
@media (hover: none) and (pointer: coarse) {
  .ds-cascader.ds-cascader--modern[data-part="root"] [data-part="trigger"],
  .ds-cascader.ds-cascader--modern[data-part="root"] [data-part="option"],
  .ds-cascader.ds-cascader--modern[data-part="root"]
    [data-part="clear-button"] {
    min-block-size: var(--ds-cascader-touch-target-min, 44px);
  }
}

/* ---- reduced motion: panel/column entrances, spinner and every state
        transition go quiet. ---- */
@media (prefers-reduced-motion: reduce) {
  .ds-cascader.ds-cascader--modern[data-part="root"] [data-part="dropdown"],
  .ds-cascader.ds-cascader--modern[data-part="root"] [data-part="menu-column"] {
    animation: none;
  }
  .ds-cascader.ds-cascader--modern[data-part="root"] [data-part="loading"] {
    animation: none;
  }
  .ds-cascader.ds-cascader--modern[data-part="root"] [data-part="trigger"],
  .ds-cascader.ds-cascader--modern[data-part="root"] [data-part="search-input"],
  .ds-cascader.ds-cascader--modern[data-part="root"] [data-part="option"],
  .ds-cascader.ds-cascader--modern[data-part="root"] [data-part="arrow-icon"],
  .ds-cascader.ds-cascader--modern[data-part="root"]
    [data-part="clear-button"] {
    transition: none;
  }
}

/* ---- forced colors (system colors only): the selected path option reads as
        a system selection; focus rings re-map to Highlight outlines (the
        box-shadow rings drop); the column hairline and chevron inherit the
        forced palette. ---- */
@media (forced-colors: active) {
  .ds-cascader.ds-cascader--modern[data-part="root"]
    [data-part="option"][data-selected="true"] {
    background: Highlight;
    border-color: Highlight;
    color: HighlightText;
  }
  .ds-cascader.ds-cascader--modern[data-part="root"]
    [data-part="trigger"]:focus-visible,
  .ds-cascader.ds-cascader--modern[data-part="root"]
    [data-part="search-input"]:focus-visible,
  .ds-cascader.ds-cascader--modern[data-part="root"]
    [data-part="option"]:focus-visible,
  .ds-cascader.ds-cascader--modern[data-part="root"]
    [data-part="clear-button"]:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 1px;
    box-shadow: none;
  }
  .ds-cascader.ds-cascader--modern[data-part="root"]
    [data-part="option"][data-disabled="true"] {
    color: GrayText;
  }
  .ds-cascader.ds-cascader--modern[data-part="root"]
    [data-part="menu-column"]:not([data-last="true"]) {
    border-inline-end-color: ButtonText;
  }
  .ds-cascader.ds-cascader--modern[data-part="root"] [data-part="chevron"] {
    color: ButtonText;
  }
}

/* ---- Phase B second pass: geometry drain, status frames, root loading ---- */

/* Trigger geometry, drained from the engine's last inline style (the
   historical getSizeStyle map, mirrored 1:1 on the --ds-input-* channels so a
   token-layer outage cannot shift the field). The coarse-pointer
   min-block-size floor above still wins over these block sizes. */
.ds-cascader.ds-cascader--modern[data-part="root"] [data-part="trigger"] {
  box-sizing: border-box;
}
.ds-cascader.ds-cascader--modern[data-part="root"][data-size="small"] [data-part="trigger"] {
  block-size: var(--ds-input-sm-height);
  padding-block: var(--ds-spacing-1);
  padding-inline: var(--ds-input-sm-padding-x);
  font-size: var(--ds-input-sm-font-size);
}
.ds-cascader.ds-cascader--modern[data-part="root"][data-size="middle"] [data-part="trigger"] {
  block-size: var(--ds-input-md-height);
  padding-block: calc(var(--ds-spacing-3) / 2);
  padding-inline: var(--ds-input-md-padding-x);
  font-size: var(--ds-input-md-font-size);
}
.ds-cascader.ds-cascader--modern[data-part="root"][data-size="large"] [data-part="trigger"] {
  block-size: var(--ds-input-lg-height);
  padding-block: var(--ds-spacing-2);
  padding-inline: var(--ds-input-lg-padding-x);
  font-size: var(--ds-input-lg-font-size);
}

/* Search input geometry, drained from inline (same channels, small step). */
.ds-cascader.ds-cascader--modern[data-part="root"] [data-part="search-input"] {
  box-sizing: border-box;
  block-size: var(--ds-input-sm-height);
  padding-block: var(--ds-spacing-1);
  padding-inline: var(--ds-input-sm-padding-x);
  font-size: var(--ds-input-sm-font-size);
}

/* Status frames (Select idiom): the border carries the status at rest; the
   focus ring stays the governed primary ring during keyboard focus, and the
   composed FormField message remains the non-border signal. Specificity over
   the hover repaint comes from the extra root attribute. */
.ds-cascader.ds-cascader--modern[data-part="root"][data-status="error"] [data-part="trigger"] {
  border-color: var(--ds-color-error);
}
.ds-cascader.ds-cascader--modern[data-part="root"][data-status="warning"] [data-part="trigger"] {
  border-color: var(--ds-color-warning);
}

/* Root loading: the suffix spinner replaces the chevron in flow (same dock),
   and the panel loading-state keeps the empty state's rhythm. */
.ds-cascader.ds-cascader--modern[data-part="root"] [data-part="trigger-loading"],
.ds-cascader.ds-cascader--modern[data-part="root"] [data-part="loading-spinner"] {
  border: 2px solid var(--ds-color-border);
  border-top-color: var(--ds-color-primary);
  border-radius: 50%;
  animation: ds-foundation-spin
    var(--ds-cascader-spinner-duration, var(--ds-motion-glacial)) linear
    infinite;
}
.ds-cascader.ds-cascader--modern[data-part="root"] [data-part="trigger-loading"] {
  inline-size: 12px;
  block-size: 12px;
  flex-shrink: 0;
}
.ds-cascader.ds-cascader--modern[data-part="root"] [data-part="loading-spinner"] {
  inline-size: 14px;
  block-size: 14px;
  flex-shrink: 0;
}
/* Clear + busy suffix coexistence (mirrors the arrow-icon gap rule above). */
.ds-cascader.ds-cascader--modern[data-part="root"]:has(
    [data-part="clear-button"]
  )
  [data-part="trigger-loading"] {
  margin-inline-start: var(--ds-cascader-clear-gap, 20px);
}
.ds-cascader.ds-cascader--modern[data-part="root"] [data-part="loading-state"] {
  display: flex;
  align-items: center;
  gap: var(--ds-spacing-2);
  padding: var(--ds-spacing-2);
  color: var(--ds-color-text-secondary);
  font-size: var(--ds-input-sm-font-size);
}

@media (prefers-reduced-motion: reduce) {
  .ds-cascader.ds-cascader--modern[data-part="root"] [data-part="trigger-loading"],
  .ds-cascader.ds-cascader--modern[data-part="root"] [data-part="loading-spinner"] {
    animation: none;
  }
}

@media (forced-colors: active) {
  .ds-cascader.ds-cascader--modern[data-part="root"] [data-part="trigger-loading"],
  .ds-cascader.ds-cascader--modern[data-part="root"] [data-part="loading-spinner"] {
    border-color: ButtonText;
    border-top-color: Highlight;
  }
}

}
