  --ds-progress-resolved-fill: var(--ds-progress-arc-color, var(--ds-color-primary));
}
.rottay-progress-shell.rottay-progress-shell--modern[data-status='success'] {
  --ds-progress-resolved-fill: var(--ds-progress-arc-color, var(--ds-color-success));
}
.rottay-progress-shell.rottay-progress-shell--modern[data-status='error'] {
  --ds-progress-resolved-fill: var(--ds-progress-arc-color, var(--ds-color-error));
}
.rottay-progress-shell.rottay-progress-shell--modern[data-status='active'] {
  --ds-progress-resolved-fill: var(--ds-progress-arc-color, var(--ds-color-primary));
