.rottay-progress-shell.rottay-progress-shell--modern[data-type='line'][data-indeterminate='true'] {
  overflow: hidden;
  border-radius: var(--ds-progress-radius);
}

/* ---- track + fused native fill ---- */
.rottay-progress-shell.rottay-progress-shell--modern [data-part='fill'] {
  grid-area: 1 / 1;
  width: 100%;
  height: var(--ds-progress-height);
  overflow: hidden;
  appearance: none;
  background: var(--ds-progress-bg);
  border: 0;
  border-radius: var(--ds-progress-radius);
}

.rottay-progress-shell.rottay-progress-shell--modern [data-part='fill']::-webkit-progress-bar {
  border-radius: inherit;
  background: var(--ds-progress-bg);
}

.rottay-progress-shell.rottay-progress-shell--modern [data-part='fill']::-webkit-progress-value {
  border-radius: inherit;
  background: var(--ds-progress-resolved-fill, var(--ds-color-primary));
  transition: width var(--ds-motion-normal) var(--ds-motion-ease-out);
}

.rottay-progress-shell.rottay-progress-shell--modern [data-part='fill']::-moz-progress-bar {
  border-radius: inherit;
  background: var(--ds-progress-resolved-fill, var(--ds-color-primary));
