    45deg,
    color-mix(in srgb, white 22%, transparent) 25%,
    transparent 25%,
    transparent 50%,
    color-mix(in srgb, white 22%, transparent) 50%,
    color-mix(in srgb, white 22%, transparent) 75%,
    transparent 75%
  );
  background-size: var(--ds-spacing-4) var(--ds-spacing-4);
}
.rottay-progress-shell.rottay-progress-shell--modern[data-status='active'] [data-part='fill']::-moz-progress-bar {
  background-color: var(--ds-progress-resolved-fill, var(--ds-color-primary));
  background-image: linear-gradient(
    45deg,
    color-mix(in srgb, white 22%, transparent) 25%,
    transparent 25%,
    transparent 50%,
    color-mix(in srgb, white 22%, transparent) 50%,
    color-mix(in srgb, white 22%, transparent) 75%,
    transparent 75%
  );
  background-size: var(--ds-spacing-4) var(--ds-spacing-4);
}

