  align-items: center;
  justify-content: center;
  gap: var(--ds-spacing-1);
  margin-block-start: var(--ds-progress-label-gap, var(--ds-spacing-xs));
  color: var(--ds-color-text-secondary);
  font-size: var(--ds-font-size-sm);
  font-variant-numeric: tabular-nums;
  text-align: center;
