   ========================================================================== */

.rottay-progress-shell.rottay-progress-shell--modern[data-type='circle'][data-type='circle'] {
  --_ds-arc-value: var(--ds-progress-circle-value);
  --_ds-arc-size: var(--ds-progress-circle-size, 6rem);
  --_ds-arc-thickness: var(
    --ds-progress-circle-thickness,
    calc(var(--_ds-arc-size) / 10)
  );
  --_ds-arc-fill: var(--ds-progress-resolved-fill, var(--ds-color-primary));
  --_ds-arc-track: var(--ds-progress-bg);

  box-sizing: content-box;
  vertical-align: middle;
