/* Center value text: sized off the ring so it scales with the token. */
.rottay-progress-shell.rottay-progress-shell--modern[data-type='circle'] > [data-part='label'] {
  display: inline-flex;
  align-items: center;
  gap: 0.18em;
  color: var(--ds-color-text-primary);
  font-family: var(--ds-font-family-heading, var(--ds-font-family-base));
  font-size: calc(var(--_ds-arc-size) * 0.22);
  font-variant-numeric: tabular-nums;
  font-weight: var(--ds-font-weight-semibold);
  line-height: 1;
