    background: ButtonFace;
    border: 1px solid ButtonText;
  }

  .rottay-progress-shell.rottay-progress-shell--modern [data-part='fill']::-webkit-progress-bar {
    background: ButtonFace;
  }

  .rottay-progress-shell.rottay-progress-shell--modern [data-part='fill']::-webkit-progress-value {
    background: Highlight;
  }

  .rottay-progress-shell.rottay-progress-shell--modern [data-part='fill']::-moz-progress-bar {
    background: Highlight;
  }

  .rottay-progress-shell.rottay-progress-shell--modern [data-part='indeterminate'][data-part='indeterminate'] {
    background: Highlight;
  }

  /* The active status stripes sit ABOVE these rules in normal specificity, so
     they are re-flattened here explicitly: solid Highlight, no stripe image. */
  .rottay-progress-shell.rottay-progress-shell--modern[data-status='active'] [data-part='fill']::-webkit-progress-value,
  .rottay-progress-shell.rottay-progress-shell--modern[data-status='active'] [data-part='fill']::-moz-progress-bar {
    background: Highlight;
    background-image: none;
  }

  /* Forced colors also strips background IMAGES, which would erase the
     conic ring and its cap entirely. No opt-out: the circle is re-expressed
     with system colors — a CanvasText ring outline keeps the shape
     perceivable; the center label already follows system inks. */
  .rottay-progress-shell.rottay-progress-shell--modern[data-type='circle'] {
    outline: 2px solid CanvasText;
    outline-offset: -2px;
  }
