  stroke: var(--ds-progress-arc-color, var(--ds-progress-error-color, var(--ds-color-error-500, var(--ds-color-error))));
  background-color: var(--ds-progress-arc-color, var(--ds-progress-error-color, var(--ds-color-error-500, var(--ds-color-error))));
