.rottay-progress-shell.rottay-progress-shell--rustic[data-status='active'] [data-part='fill'] {
  stroke: var(--ds-progress-arc-color, var(--ds-progress-active-color, var(--ds-color-primary-500, var(--ds-color-primary))));
