.rottay-progress-shell.rottay-progress-shell--rustic[data-status='error'] svg ~ [data-part='label'] {
  color: var(--ds-progress-arc-color, var(--ds-progress-error-color, var(--ds-color-error-500, var(--ds-color-error))));
