  background-image: linear-gradient(
    45deg,
    var(--ds-color-alpha-white-20) 25%,
    transparent 25%,
    transparent 50%,
    var(--ds-color-alpha-white-20) 50%,
    var(--ds-color-alpha-white-20) 75%,
    transparent 75%,
