.rottay-toast-container[data-placement='top-center'][data-center-transform='true'],
.rottay-toast-container[data-placement='bottom-center'][data-center-transform='true'] {
  transform: translateX(-50%);
}

/* ---- stack item: compress/fan transform, depth-derived, via a hatch ---- */
.rottay-toast-container > [data-stack-depth] {
  transform: var(--ds-toast-stack-transform);
}

/* ---- Toast.Undo: the ring/bar countdown wrapper ---- */
.rottay-undo-toast[data-part='root'] {
  color: var(--ds-color-text-primary);
}

/* Scoped through the bar's own track so it cannot also match the ring's
   `<circle data-part='fill'>` sibling, which paints via SVG stroke attributes. */
.rottay-undo-toast [data-part='track'] > [data-part='fill'] {
  background: var(--ds-color-primary);
