  from {
    stroke-dashoffset: 0;
  }
  to {
    stroke-dashoffset: var(--_ds-toast-undo-ring-circumference);
  }
}

@keyframes ds-toast-undo-bar-deplete {
  from {
    transform: scaleX(1);
  }
  to {
    transform: scaleX(0);
  }
}

