.rottay-dropdown__surface.rottay-dropdown__surface[data-part='surface'] {
  isolation: isolate;
  container: rottay-dropdown / inline-size;
  /* Density indirections (Pass-B): the item track consumes these private
     proto `-current` channels (the naming law bars new `--ds-*` variables);
     the tenant `--ds-dropdown-item-*` channels remain the source for the
     default posture and density postures retune without shadowing them. */
  --_ds-proto-dropdown-item-height-current: var(--ds-dropdown-item-height, 2.4rem);
  --_ds-proto-dropdown-item-padding-block-current: var(--ds-dropdown-item-padding-y, 0.45rem);
  --_ds-proto-dropdown-item-padding-inline-current: var(--ds-dropdown-item-padding-x, 0.55rem);
  min-inline-size: min(var(--ds-dropdown-min-width, 14rem), calc(100vw - 1rem));
  max-inline-size: min(var(--ds-dropdown-max-width, 22rem), calc(100vw - 1rem));
  padding: var(--ds-dropdown-padding);
  overflow: visible;
  color: var(--ds-dropdown-color, var(--ds-color-text-secondary));
  border-radius: var(--ds-dropdown-radius, var(--ds-radius-xl));
