  transform-origin: center top;
}

.rottay-dropdown__surface.rottay-dropdown__surface[data-part='surface'][data-part='surface'] {
  border: var(--ds-dropdown-border-width, 1px) solid
    var(--ds-dropdown-border-color, color-mix(in srgb, var(--ds-color-border) 86%, var(--ds-color-primary) 14%));
}

.rottay-dropdown__surface[data-part='surface'][data-placement^='top'] {
  transform-origin: center bottom;
}

/* Density postures: intentional compositions, not a uniform scale. Compact
   tightens the block rhythm and the icon gap; spacious lets rows breathe.
   Values are deliberately fixed per posture -- the tenant tunables stay on
   the default (`-current` fallback) track. */
.rottay-dropdown__surface.rottay-dropdown__surface[data-part='surface'][data-density='compact'] {
  --_ds-proto-dropdown-item-height-current: 2rem;
  --_ds-proto-dropdown-item-padding-block-current: var(--ds-spacing-1);
  --_ds-proto-dropdown-item-padding-inline-current: var(--ds-spacing-sm);
}

.rottay-dropdown__surface.rottay-dropdown__surface[data-part='surface'][data-density='spacious'] {
  --_ds-proto-dropdown-item-height-current: 2.75rem;
  --_ds-proto-dropdown-item-padding-block-current: 0.625rem;
  --_ds-proto-dropdown-item-padding-inline-current: var(--ds-spacing-md);
}

.rottay-dropdown__surface[data-part='surface'] > [data-part='menu'] {
  display: grid;
  gap: var(--ds-dropdown-item-gap, 0.2rem);
  inline-size: 100%;
  margin: 0;
  padding: 0;
  list-style: none;
}

