.rottay-dropdown__surface[data-part='surface'] [data-part='item']:not(:disabled):hover::after {
  opacity: 0.8;
  transform: translateX(40%);
}

.rottay-dropdown__surface[data-part='surface'] [data-part='item'][data-selected='true'] {
  color: var(--ds-dropdown-item-color-selected, var(--ds-color-primary));
  border-color: var(
    --ds-dropdown-item-border-selected,
    color-mix(in srgb, var(--ds-color-primary) 36%, var(--ds-color-border-subtle))
  );
  background: var(
    --ds-dropdown-item-bg-selected,
    linear-gradient(
      135deg,
      color-mix(in srgb, var(--ds-color-primary) 14%, var(--ds-surface-card)),
      color-mix(in srgb, var(--ds-color-primary) 6%, var(--ds-surface-card))
    )
  );
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--ds-color-text-on-primary) 60%, transparent),
    var(--ds-shadow-xs);
}

.rottay-dropdown__surface[data-part='surface'] [data-part='item'][data-tone='danger'] {
  color: var(--ds-dropdown-danger-color, var(--ds-color-error));
}

.rottay-dropdown__surface[data-part='surface'] [data-part='item'][data-tone='danger']:not(:disabled):hover,
.rottay-dropdown__surface[data-part='surface'] [data-part='item'][data-tone='danger']:not(:disabled):focus-visible {
  border-color: color-mix(in srgb, var(--ds-color-error) 30%, var(--ds-color-border-subtle));
  background: linear-gradient(
    135deg,
    color-mix(in srgb, var(--ds-color-error) 10%, var(--ds-surface-card)),
    color-mix(in srgb, var(--ds-color-error) 4%, var(--ds-surface-card))
