.rottay-dropdown__surface[data-part='surface'] [data-part='selection-indicator'] {
  grid-column: 1;
  inline-size: 1rem;
  color: var(--ds-color-primary);
  opacity: 0;
  transform: scale(0.72);
  transition:
    opacity var(--ds-motion-fast) var(--ds-ease-standard, ease),
    transform var(--ds-motion-fast) var(--ds-ease-spring);
}

.rottay-dropdown__surface[data-part='surface'] [data-selected='true'] [data-part='selection-indicator'] {
  opacity: 1;
  transform: scale(1);
}

.rottay-dropdown__surface[data-part='surface'] [data-part='icon'] {
  grid-column: 2;
  inline-size: var(--ds-dropdown-icon-well-size, 1.75rem);
  block-size: var(--ds-dropdown-icon-well-size, 1.75rem);
  color: var(--ds-dropdown-icon-color, currentColor);
  border-radius: var(--ds-radius-md);
  background: color-mix(in srgb, currentColor 7%, transparent);
  transition:
    background var(--ds-motion-fast) var(--ds-ease-standard, ease),
    transform var(--ds-motion-fast) var(--ds-ease-spring);
}

.rottay-dropdown__surface[data-part='surface'] [data-part='item']:hover [data-part='icon'] {
  background: color-mix(in srgb, currentColor 11%, transparent);
  transform: scale(1.04);
}

.rottay-dropdown__surface[data-part='surface'] [data-part='label'] {
  position: relative;
  z-index: 1;
  grid-column: 3;
  min-inline-size: 0;
  overflow: visible;
  overflow-wrap: anywhere;
  text-overflow: clip;
  white-space: normal;
}

/* Iconless actions use the icon track instead of collapsing into an intrinsic
 * auto column. This keeps every label inside the surface and gives it the full
 * remaining width without fabricating an empty icon well. */
.rottay-dropdown__surface[data-part='surface']
  [data-part='selection-indicator'] + [data-part='label'] {
  grid-column: 2 / 4;
}

.rottay-dropdown__surface[data-part='surface'] [data-part='submenu-indicator'] {
  grid-column: 4;
  inline-size: 1.5rem;
  block-size: 1.5rem;
  border-radius: var(--ds-radius-full);
  background: color-mix(in srgb, currentColor 6%, transparent);
  transition: transform var(--ds-motion-fast) var(--ds-ease-spring);
}

.rottay-dropdown__surface[data-part='surface'] [data-submenu-open='true'] > [data-part='item'] [data-part='submenu-indicator'] {
  transform: translateX(2px);
}

/* RTL: the submenu opens toward the reading-start side, so the nudge mirrors. */
.rottay-dropdown__surface[data-part='surface'] [data-submenu-open='true'] > [data-part='item'] [data-part='submenu-indicator']:dir(rtl) {
  transform: translateX(-2px);
}

.rottay-dropdown__surface[data-part='surface'] [data-part='group-label'] {
  margin-block: 0.35rem 0.15rem;
  padding: 0.38rem 0.6rem;
  color: var(--ds-dropdown-group-color, var(--ds-color-text-muted));
  border-radius: var(--ds-radius-md);
  background: linear-gradient(90deg, color-mix(in srgb, var(--ds-color-text-primary) 4%, transparent), transparent 78%);
  font-family: var(--ds-font-family-heading, var(--ds-font-family-base));
  font-size: var(--ds-font-size-xs);
  font-weight: var(--ds-font-weight-semibold);
  letter-spacing: var(--ds-letter-spacing-wide);
  line-height: 1.2;
  text-transform: uppercase;
}

.rottay-dropdown__surface[data-part='surface'] [data-part='divider'] {
  block-size: 1px;
  margin: 0.35rem 0.3rem;
  border: 0;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in srgb, var(--ds-color-border) 92%, transparent) 15%,
    color-mix(in srgb, var(--ds-color-border) 92%, transparent) 85%,
    transparent
  );
}

.rottay-dropdown__surface[data-part='surface'] [data-part='submenu'] {
  position: absolute;
  inset-block-start: -0.42rem;
  inset-inline-start: calc(100% + 0.48rem);
  display: grid;
  gap: 0.2rem;
  min-inline-size: var(--ds-dropdown-min-width, 14rem);
  margin: 0;
  padding: var(--ds-dropdown-padding);
  list-style: none;
  border-radius: var(--ds-dropdown-radius, var(--ds-radius-xl));
  background:
    linear-gradient(145deg, color-mix(in srgb, var(--ds-color-primary) 5%, transparent), transparent 45%),
    linear-gradient(var(--ds-elevation-surface-3), var(--ds-elevation-surface-3)),
    var(--ds-surface-card);
  box-shadow: var(--ds-dropdown-shadow, var(--ds-elevation-3));
  animation: ds-dropdown-popover-enter-modern var(--ds-motion-fast) var(--ds-ease-standard, ease) both;
}

.rottay-dropdown__surface[data-part='surface'] [data-part='submenu'][data-part='submenu'] {
  border: 1px solid var(--ds-dropdown-border-color, var(--ds-color-border));
}

.rottay-dropdown__surface[data-part='surface'] > [data-part='arrow'] {
  position: absolute;
  z-index: -1;
  inline-size: 0.72rem;
  block-size: 0.72rem;
  border: 1px solid var(--ds-dropdown-border-color, var(--ds-color-border));
  /* the same fill + dark-aware lift layer the surface declares, so the seam
     does not flash a lighter square where the arrow crosses the border */
  background:
    linear-gradient(var(--ds-elevation-surface-3), var(--ds-elevation-surface-3)),
    var(--ds-surface-card);
  transform: rotate(45deg);
}

.rottay-dropdown__surface[data-part='surface'][data-placement^='bottom'] > [data-part='arrow'] {
  inset-block-start: -0.38rem;
  inset-inline-start: calc(50% - 0.36rem);
  border-inline-end: 0;
  border-block-end: 0;
}

.rottay-dropdown__surface[data-part='surface'][data-placement^='top'] > [data-part='arrow'] {
  inset-block-end: -0.38rem;
  inset-inline-start: calc(50% - 0.36rem);
  border-inline-start: 0;
  border-block-start: 0;
}

/* Arrow anchor tracking (portal branch): the measured inline-start offset of
   the trigger's center wins over the 50% default, clamped one radius away
   from the rounded corners so the diamond never sits on the corner curve. */
.rottay-dropdown__surface[data-part='surface'][data-arrow-tracked='true'][data-placement^='bottom'] > [data-part='arrow'],
.rottay-dropdown__surface[data-part='surface'][data-arrow-tracked='true'][data-placement^='top'] > [data-part='arrow'] {
  inset-inline-start: clamp(
    var(--ds-dropdown-radius, var(--ds-radius-xl)),
    calc(var(--_ds-proto-dropdown-arrow-anchor-offset) - 0.36rem),
    calc(100% - var(--ds-dropdown-radius, var(--ds-radius-xl)) - 0.72rem)
  );
}

@container rottay-dropdown (max-width: 20rem) {
  .rottay-dropdown__surface[data-part='surface'] [data-part='submenu'] {
    position: relative;
    inset: auto;
    min-inline-size: 0;
    margin-block-start: 0.25rem;
    box-shadow: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .rottay-dropdown__surface[data-part='surface'],
  .rottay-dropdown__surface[data-part='surface'] [data-part='item'],
  .rottay-dropdown__surface[data-part='surface'] [data-part='item']::after,
  .rottay-dropdown__surface[data-part='surface'] [data-part='icon'],
  .rottay-dropdown__surface[data-part='surface'] [data-part='selection-indicator'],
  .rottay-dropdown__surface[data-part='surface'] [data-part='submenu'] {
    animation: none;
    transition: none;
  }

  .rottay-dropdown__surface[data-part='surface'] [data-part='item']:not(:disabled):hover,
  .rottay-dropdown__surface[data-part='surface'] [data-part='item']:not(:disabled):active {
    transform: none;
  }
}

/* forced-colors contract: backgrounds are stripped, so hover/focus must
   still read -- a plain outline survives the forced palette. The selected
   item keeps its own Highlight boundary (its wash disappears too). */
@media (forced-colors: active) {
  .rottay-dropdown__surface[data-part='surface'] [data-part='item']:not(:disabled):hover,
  .rottay-dropdown__surface[data-part='surface'] [data-part='item']:not(:disabled):focus-visible {
    outline: 1px solid;
    outline-offset: -1px;
  }

  .rottay-dropdown__surface[data-part='surface'] [data-part='item'][data-selected='true'] {
    outline: 1px solid Highlight;
    outline-offset: -1px;
  }
}

/* coarse pointers: physical 44px floor, never a rem floor (tabs.css idiom).
   The repeated data-part ties the base item rule's specificity so source
   order lets the floor win; the declaration pins the BASE channel on
   purpose -- touch geometry never shrinks with density. */
@media (pointer: coarse) {
  .rottay-dropdown__surface[data-part='surface'] [data-part='item'][data-part='item'] {
    min-block-size: max(44px, var(--ds-dropdown-item-height, 2.4rem));
  }
}

}
@layer rottay-engines {
/**
 * Rustic Dropdown skin (WO-SKIN-04 checkpoint P).
 *
 * DELIBERATELY UNLAYERED, same rationale as every other engine skin (P-47).
 *
 * PORTAL: this engine's panel mounts via the shared `Portal` util in the measured
 * (js) branch (which stamps `data-rottay-portal`) and in-tree in the top-layer
 * (anchor-css) branch, so it is not reliably a descendant of the trigger root.
 * Every rule is therefore STANDALONE on the panel's own class
 * `.rottay-dropdown--rustic`, which the panel carries alongside
 * `data-part='surface'` — a SELF-CARRYING scope element, so the panel's own rules
 * take the COMPOUND form with no descendant space. The item rows live inside the
 * panel and are its descendants.
 *
 * Unlike the modern engine, this one renders ZERO DaisyUI classes: `theme.css`'s
 * `.menu li > button` rules do not reach it and its item hover was IMPERATIVE
 * (`.style.backgroundColor` on mouseenter/leave). That hover becomes a real `:hover`
 * rule here, gated on `:not([data-disabled='true'])` — exactly reproducing the
 * handler's `if (!item.disabled)` guard. The mouseleave handler restored
 * `transparent`, which is the resting value below.
 *
 * This engine declares no `transition`, so the hover snaps — do NOT add one (the
 * near-identical rustic ContextMenu row DOES ease, and that asymmetry ships today).
 *
 * SCOPE: `rottay-dropdown--rustic`. NOT `ds-dropdown` — that name carries a DORMANT
 * entrance-animation rule in personality.css that matches nothing today (P3).
 *
 * POSITIONING: `position`/`top`/`left`/`position-anchor`/`position-area` etc. come
 * from `runtime/overlay/positioning`'s `useOverlayPosition` and stay inline —
 * genuine runtime data, not paint. The panel carries NO placement transform here:
 * the shared engine already subtracts overlay height for top placements, so a skin
 * translate would double-shift it.
 */

/* ---- portaled menu panel ---- */
.rottay-dropdown--rustic[data-part='surface'] {
  background-color: var(--ds-dropdown-bg, #fff);
  border-radius: var(--ds-dropdown-radius, 12px);
  box-shadow: var(--ds-dropdown-shadow, 0 4px 12px rgba(0, 0, 0, 0.15));
}
/* ---- top-layer branch: the panel carries the `popover` attribute there, and UA
        [popover] rules paint `border: solid`, clip via `overflow: auto`, and force
        `color: CanvasText` (the item rows read `color: inherit`, so the UA color
        would reach them); this surface owns none of those. `data-ds-position-strategy`
        is stamped by the engine alongside data-part. ---- */
.rottay-dropdown--rustic[data-part='surface'][data-ds-position-strategy='anchor-css'] {
  border: 0;
  overflow: visible;
  color: inherit;
}

/* ---- structural rows ---- */
.rottay-dropdown--rustic[data-part='surface'] [data-part='divider'] {
  background-color: var(--ds-dropdown-divider-color, var(--ds-color-neutral-200, #e5e7eb));
}
.rottay-dropdown--rustic[data-part='surface'] [data-part='group-label'] {
  color: var(--ds-dropdown-group-color, var(--ds-color-neutral-500, #6b7280));
}

/* ---- item row: resting chrome + the transcribed imperative hover ---- */
.rottay-dropdown--rustic[data-part='surface'] [data-part='item'] {
  border: none;
  background: transparent;
  color: inherit;
}
.rottay-dropdown--rustic[data-part='surface'] [data-part='item'][data-tone='danger'] {
  color: var(--ds-dropdown-danger-color, var(--ds-color-error-500, #ef4444));
