  --ds-popover-texture-current: var(--ds-popover-minimal-texture, none);
  --ds-popover-highlight-current: var(--ds-popover-minimal-highlight, none);
  --ds-popover-padding-block-current: var(
    --ds-popover-minimal-padding-block,
