.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"]
  > [data-part="body"] {
  position: relative;
  z-index: 1;
  min-inline-size: 0;
  max-block-size: var(--ds-popover-body-max-height, 26rem);
  padding-block: var(--ds-popover-padding-block-current);
  padding-inline: var(--ds-popover-padding-inline-current);
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
  /* quiet scrollbar: thin track alongside the stable gutter, so long content
     scrolls without chrome weight (list-toolbar precedent) */
  scrollbar-width: var(--ds-popover-body-scrollbar-width, thin);
  color: var(--ds-popover-content-color, var(--ds-popover-muted-ink));
  font: var(
    --ds-popover-body-type,
    var(
      --ds-type-body-sm,
      var(--ds-font-weight-normal) var(--ds-font-size-sm) /
