.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"]:not([data-has-title="true"])
  > [data-part="body"] {
  border-radius: inherit;
}

.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"]:focus-visible,
.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"]:focus-within {
  outline: var(--ds-focus-ring-width) solid
    var(--ds-focus-ring-color, var(--ds-color-primary));
  outline-offset: var(--ds-focus-ring-offset);
}

/* Arrow paint derives from the same local material as the surface. The fill
   carries the SAME elevation-lift layer the surface declares, so a dark theme
   with a raised lift strength does not seam a darker arrow against a lifted
   panel at the joint. The tenant motif moves to the arrow's own `::before`
   decoration slot (the surface's idiom): it scales by the governed
   `--ds-effect-intensity` dial exactly like the surface's, so
   `effectIntensity: 0` dissolves the motif on both sides of the joint instead
   of leaving a textured arrow against a flattened panel. */
.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"]
  > [data-part="arrow"][data-part="arrow"] {
  position: absolute;
  z-index: 0;
  inline-size: var(--ds-popover-arrow-size, 0.6875rem);
  block-size: var(--ds-popover-arrow-size, 0.6875rem);
  border: var(--ds-popover-edge-width) solid var(--ds-popover-edge);
  background:
    linear-gradient(var(--ds-elevation-surface-3), var(--ds-elevation-surface-3)),
    var(--ds-popover-surface);
  transform: rotate(45deg);
  transition: inset-block-start var(--ds-motion-feedback)
      var(--ds-motion-ease-move),
    inset-block-end var(--ds-motion-feedback) var(--ds-motion-ease-move),
    inset-inline-start var(--ds-motion-feedback) var(--ds-motion-ease-move),
    inset-inline-end var(--ds-motion-feedback) var(--ds-motion-ease-move);
}

.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"]
  > [data-part="arrow"][data-part="arrow"]::before {
  position: absolute;
  inset: 0;
  background-image: var(--ds-popover-texture-current);
  content: "";
  opacity: var(--ds-effect-intensity);
  pointer-events: none;
}

.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"][data-placement^="top"]
  > [data-part="arrow"] {
  inset-block-end: calc(var(--ds-popover-arrow-size, 0.6875rem) / -2);
  inset-inline-start: calc(50% - var(--ds-popover-arrow-size, 0.6875rem) / 2);
  border-block-start: 0;
  border-inline-start: 0;
}

.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"][data-placement^="bottom"]
  > [data-part="arrow"] {
  inset-block-start: calc(var(--ds-popover-arrow-size, 0.6875rem) / -2);
  inset-inline-start: calc(50% - var(--ds-popover-arrow-size, 0.6875rem) / 2);
  border-block-end: 0;
  border-inline-end: 0;
}

.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"][data-placement^="left"]
  > [data-part="arrow"] {
  inset-block-start: calc(50% - var(--ds-popover-arrow-size, 0.6875rem) / 2);
  inset-inline-end: calc(var(--ds-popover-arrow-size, 0.6875rem) / -2);
  border-block-end: 0;
  border-inline-start: 0;
}

.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"][data-placement^="right"]
  > [data-part="arrow"] {
  inset-block-start: calc(50% - var(--ds-popover-arrow-size, 0.6875rem) / 2);
  inset-inline-start: calc(var(--ds-popover-arrow-size, 0.6875rem) / -2);
  border-block-start: 0;
  border-inline-end: 0;
}

.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"][data-arrow-centered="false"][data-placement$="-start"][data-placement^="top"]
  > [data-part="arrow"],
.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"][data-arrow-centered="false"][data-placement$="-start"][data-placement^="bottom"]
  > [data-part="arrow"] {
  inset-inline-start: var(--ds-popover-arrow-edge-offset, 1.25rem);
}

.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"][data-arrow-centered="false"][data-placement$="-end"][data-placement^="top"]
  > [data-part="arrow"],
.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"][data-arrow-centered="false"][data-placement$="-end"][data-placement^="bottom"]
  > [data-part="arrow"] {
  inset-inline: auto var(--ds-popover-arrow-edge-offset, 1.25rem);
}

.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"][data-arrow-centered="false"][data-placement$="-start"][data-placement^="left"]
  > [data-part="arrow"],
.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"][data-arrow-centered="false"][data-placement$="-start"][data-placement^="right"]
  > [data-part="arrow"] {
  inset-block-start: var(--ds-popover-arrow-edge-offset, 1.25rem);
}

.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"][data-arrow-centered="false"][data-placement$="-end"][data-placement^="left"]
  > [data-part="arrow"],
.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"][data-arrow-centered="false"][data-placement$="-end"][data-placement^="right"]
  > [data-part="arrow"] {
  inset-block: auto var(--ds-popover-arrow-edge-offset, 1.25rem);
}

/* JS measurement and post-collision geometry publish the anchor's real
 * cross-axis center. This higher-fidelity position wins over the preferred
 * alignment offsets above, but remains clamped away from rounded corners. */
.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"][data-arrow-tracked="true"][data-placement^="top"]
  > [data-part="arrow"],
.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"][data-arrow-tracked="true"][data-placement^="bottom"]
  > [data-part="arrow"] {
  inset-inline: auto;
  inset-inline-start: clamp(
    var(--ds-popover-arrow-edge-offset, 1.25rem),
    calc(
      var(--ds-popover-arrow-anchor-offset) -
        var(--ds-popover-arrow-size, 0.6875rem) / 2
    ),
    calc(
      100% - var(--ds-popover-arrow-edge-offset, 1.25rem) -
        var(--ds-popover-arrow-size, 0.6875rem)
    )
  );
}

.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"][data-arrow-tracked="true"][data-placement^="left"]
  > [data-part="arrow"],
.rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"][data-arrow-tracked="true"][data-placement^="right"]
  > [data-part="arrow"] {
  inset-block: auto;
  inset-block-start: clamp(
    var(--ds-popover-arrow-edge-offset, 1.25rem),
    calc(
      var(--ds-popover-arrow-anchor-offset) -
        var(--ds-popover-arrow-size, 0.6875rem) / 2
    ),
    calc(
      100% - var(--ds-popover-arrow-edge-offset, 1.25rem) -
        var(--ds-popover-arrow-size, 0.6875rem)
    )
  );
}

@media (pointer: coarse) {
  .rottay-popover--modern[data-part="trigger"]
    > [data-part="surface"]
    > [data-part="body"]
    :where(button, [role="button"], a, input, select, textarea) {
    min-block-size: var(--ds-popover-touch-target, 2.75rem);
  }
}

@media (prefers-reduced-motion: reduce) {
  .rottay-popover--modern[data-part="trigger"]
    > [data-part="surface"][data-part="surface"] {
    animation-duration: 1ms;
    animation-timing-function: linear;
    transform: none;
    will-change: auto;
  }

  .rottay-popover--modern[data-part="trigger"]
    > [data-part="surface"]
    > [data-part="arrow"] {
    transition: none;
  }
}

html[data-ds-motion="reduced"]
  .rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"][data-part="surface"] {
  animation-duration: 1ms;
  animation-timing-function: linear;
  transform: none;
  will-change: auto;
}

html[data-ds-motion="reduced"]
  .rottay-popover--modern[data-part="trigger"]
  > [data-part="surface"]
  > [data-part="arrow"] {
  transition: none;
}

/* Reduced transparency: the shared overlay material channel
 * (--ds-material-overlay-background) may resolve translucent, and a tenant
 * may do the same through the recipe channels. Users who request reduced
 * transparency get an opaque fill instead of a see-through panel
 * (semantic-surface.css idiom): the decoration layers drop out and the
 * hierarchy rides the opaque fill, edge and elevation. The inverse recipe
 * keeps its deliberately opaque dark fill. */
@media (prefers-reduced-transparency: reduce) {
  .rottay-popover--modern[data-part="trigger"]
    > [data-part="surface"][data-part="surface"] {
    --ds-popover-highlight-current: none;
    --ds-popover-texture-current: none;
  }

  /* The arrow inherits the redefined custom properties from the surface, so
     its fill and motif follow without a second declaration.
     The family's own opaque fill still wins: `--ds-popover-bg` is a declared
     solid a tenant owns, so the guard must not overwrite it.
     `--ds-material-overlay-opaque` replaces only the ad-hoc surface pick that
     used to close this chain. */
  .rottay-popover--modern[data-part="trigger"]
    > [data-part="surface"][data-part="surface"]:not([data-recipe="inverse"]) {
    --ds-popover-surface: var(
      --_ds-proto-popover-opaque-surface,
      var(--ds-popover-bg, var(--ds-material-overlay-opaque, var(--ds-surface-card)))
    );
  }
}

@media (forced-colors: active) {
  .rottay-popover--modern[data-part="trigger"]
    > [data-part="surface"][data-part="surface"] {
    --ds-popover-highlight-current: none;
    --ds-popover-texture-current: none;

    border-color: CanvasText;
    background: Canvas;
    box-shadow: none;
    color: CanvasText;
  }

  .rottay-popover--modern[data-part="trigger"]
    > [data-part="surface"]
    > [data-part="title"] {
    border-color: CanvasText;
    background: Canvas;
    color: CanvasText;
  }

  .rottay-popover--modern[data-part="trigger"]
    > [data-part="surface"]
    > [data-part="body"] {
    color: CanvasText;
  }

  /* Doubled data-part ties the base arrow rule's (0,5,0) so the system-color
     treatment actually lands (later source wins): the fill flattens to Canvas
     -- resetting the elevation-lift background-image with it -- and the frame
     keeps a system color. */
  .rottay-popover--modern[data-part="trigger"]
    > [data-part="surface"]
    > [data-part="arrow"][data-part="arrow"] {
    border-color: CanvasText;
    background: Canvas;
  }
}

}
@layer rottay-engines {
/**
 * Rustic Popover skin (WO-SKIN-04 checkpoint P).
 *
 * DELIBERATELY UNLAYERED, same rationale as every other engine skin (P-47).
 *
 * SCOPE IS `rottay-popover--rustic`, NEVER `ds-popover` (P3): personality.css carries a
 * DORMANT `[data-engine] .ds-popover { animation: ds-dropdown-enter … }` rule that
 * matches nothing today. Popover has NO entrance animation in either engine, and
 * adopting that classname would silently give it one.
 *
 * PORTAL: the panel portals in the measured (js) branch and renders in-tree in the
 * top-layer (anchor-css) branch, so it is not reliably a descendant of the trigger
 * root. Every rule is STANDALONE on the panel's own class, which it carries alongside
 * `data-part='surface'` — a SELF-CARRYING scope element, so the panel's own rules take
 * the COMPOUND form with no descendant space.
 *
 * POSITIONING: `position`/`top`/`left`/`position-anchor`/`position-area` etc. come
 * from `runtime/overlay/positioning`'s `useOverlayPosition` and stay inline — genuine
 * runtime data, not paint. The surface carries NO centering transform here: the shared
 * engine emits already-centered coordinates, so a skin translate would double-shift it.
 *
 * SPECIFICITY (P-48): the panel's and the title's colored borders repeat their
 * `data-part` to clear the tenant `*` border-color floor at (0,3,1).
 */

/* ---- portaled content panel ---- */
.rottay-popover--rustic[data-part='surface'] {
  background-color: var(--ds-popover-bg, var(--ds-color-bg-elevated, #fff));
  border-radius: var(--ds-popover-radius, var(--ds-radius-lg, 12px));
  box-shadow: var(--ds-popover-shadow, var(--ds-shadow-lg));
  backdrop-filter: var(--ds-modal-overlay-backdrop, blur(4px));
}
.rottay-popover--rustic[data-part='surface'][data-part='surface'] {
  border: 1px solid var(--ds-popover-border-color, var(--ds-color-neutral-200, #e5e7eb));
}

/* ---- top-layer branch: the panel carries the `popover` attribute there, and
        UA [popover] rules paint `border: solid` and clip via `overflow: auto`;
        this surface owns neither default. `data-ds-position-strategy` is stamped by
        the engine alongside data-part. ---- */
.rottay-popover--rustic[data-part='surface'][data-ds-position-strategy='anchor-css'] {
  border: 0;
  overflow: visible;
}

/* ---- title ---- */
.rottay-popover--rustic[data-part='surface'] [data-part='title'] {
  color: var(--ds-popover-title-color, inherit);
}
.rottay-popover--rustic[data-part='surface'] [data-part='title'][data-part='title'] {
  border-bottom: 1px solid var(--ds-popover-title-border, var(--ds-color-neutral-200, #e5e7eb));
}

/* ---- arrow: this engine's arrow HAS a box-shadow (modern's does not). Preserved. ---- */
.rottay-popover--rustic[data-part='surface'] [data-part='arrow'] {
  background-color: var(--ds-popover-bg, var(--ds-color-bg-elevated, #fff));
  transform: rotate(45deg);
  box-shadow: var(--ds-popover-arrow-shadow, -2px -2px 4px rgba(0, 0, 0, 0.05));
}

}
@layer rottay-engines {
/**
 * Modern ScrollArea skin (K3-C pass 1 — FIRST modern engine skin for this
 * family; previously the family's only paint lived in the engine-agnostic
 * `presentation/components/skin/scroll-area.css`).
