@keyframes ds-sheet-slide-out-bottom-modern {
  from { transform: translateY(0); }
  to   { transform: translateY(100%); }
}
@keyframes ds-sheet-slide-left-modern {
  from { transform: translateX(-100%); }
  to   { transform: translateX(0); }
}
@keyframes ds-sheet-slide-out-left-modern {
  from { transform: translateX(0); }
  to   { transform: translateX(-100%); }
}
@keyframes ds-sheet-slide-right-modern {
  from { transform: translateX(100%); }
  to   { transform: translateX(0); }
}
@keyframes ds-sheet-slide-out-right-modern {
  from { transform: translateX(0); }
  to   { transform: translateX(100%); }
