  .rottay-sheet--rustic[data-part='root'] {
    --ds-sheet-viewport-max-height: 85dvh;
    height: 100dvh;
  }
}

.rottay-sheet--rustic[data-part='root'] > [data-part='backdrop'] {
  background-color: var(--ds-overlay-bg, var(--ds-modal-overlay-bg, var(--ds-color-alpha-black-50, rgba(0, 0, 0, 0.5))));
  backdrop-filter: var(--ds-modal-overlay-backdrop, blur(4px));
}

/* ---- panel ---- */
.rottay-sheet--rustic[data-part='root'] > [data-part='surface'] {
  background-color: var(--ds-drawer-bg, var(--ds-modal-bg, var(--ds-color-bg-elevated, #fff)));
  color: var(--ds-modal-color, var(--ds-color-text-primary, #1a1a1a));
  box-shadow: var(--ds-modal-shadow, var(--ds-shadow-xl));
}
.rottay-sheet--rustic[data-part='root'] > [data-part='surface'][data-part='surface'] {
  border: 1px solid var(--ds-modal-border, var(--ds-color-neutral-200, #e5e7eb));
}

