.rottay-sheet--rustic[data-part='root'] > [data-part='surface'][data-placement='bottom'] {
  border-top-left-radius: 16px;
  border-top-right-radius: 16px;
  padding-bottom: var(--ds-sheet-safe-area-bottom, env(safe-area-inset-bottom, 0px));
}
.rottay-sheet--rustic[data-part='root'] > [data-part='surface'][data-placement='left'] {
  border-top-right-radius: 16px;
  border-bottom-right-radius: 16px;
}
.rottay-sheet--rustic[data-part='root'] > [data-part='surface'][data-placement='right'] {
  border-top-left-radius: 16px;
  border-bottom-left-radius: 16px;
}

