/* ---- header + title ---- */
.rottay-sheet--rustic[data-part='root'] [data-part='header'][data-part='header'] {
  border-bottom: 1px solid var(--ds-modal-header-border, var(--ds-color-neutral-200, #e5e7eb));
}
.rottay-sheet--rustic[data-part='root'] [data-part='title'] {
  color: var(--ds-modal-title-color, inherit);
}

/* ---- scroll anatomy ---- */
.rottay-sheet--rustic[data-part='root'] [data-part='body'] {
  min-height: 0;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
}
.rottay-sheet--rustic[data-part='root'] [data-part='footer'] {
  flex-shrink: 0;
  border-top: 1px solid var(--ds-modal-header-border, var(--ds-color-neutral-200));
}

