.rottay-steps--rustic[data-part='root'] [data-part='icon'] {
  border-radius: 50%;
}

/* ---- the bordered circle: bg + border + glyph color, per status. ---- */
.rottay-steps--rustic[data-part='root'] [data-status='finish'] [data-part='icon'][data-variant='circle'] {
  background-color: var(--ds-steps-finish-bg, var(--ds-color-primary-500, var(--ds-color-primary)));
  border: 2px solid var(--ds-steps-finish-border, var(--ds-color-primary-500, var(--ds-color-primary)));
  color: var(--ds-steps-finish-text, var(--ds-color-text-on-primary, var(--ds-color-text-inverse)));
