.rottay-steps--rustic[data-part='root'] [data-status='process'] [data-part='icon'][data-variant='circle'] {
  background-color: var(--ds-steps-process-bg, var(--ds-color-bg-elevated, var(--ds-color-bg-primary)));
  border: 2px solid var(--ds-steps-process-border, var(--ds-color-primary-500, var(--ds-color-primary)));
  color: var(--ds-steps-process-text, var(--ds-color-primary-500, var(--ds-color-primary)));
}

.rottay-steps--rustic[data-part='root'] [data-status='error'] [data-part='icon'][data-variant='circle'] {
  background-color: var(--ds-steps-error-bg, var(--ds-color-bg-elevated, var(--ds-color-bg-primary)));
  border: 2px solid var(--ds-steps-error-border, var(--ds-color-error-500, var(--ds-color-error)));
  color: var(--ds-steps-error-text, var(--ds-color-error-500, var(--ds-color-error)));
