.rottay-steps--rustic[data-part='root'] [data-status='wait'] [data-part='icon'][data-variant='circle'] {
  background-color: var(--ds-steps-wait-bg, var(--ds-color-bg-elevated, var(--ds-color-bg-primary)));
  border: 2px solid var(--ds-steps-wait-border, var(--ds-color-border-secondary, var(--ds-color-neutral-300)));
  color: var(--ds-steps-wait-text, var(--ds-color-text-tertiary, var(--ds-color-text-secondary)));
