.rottay-steps--rustic[data-part='root'] [data-status='process'] [data-part='icon'][data-variant='dot'] {
  background-color: var(--ds-steps-process-border, var(--ds-color-primary-500, var(--ds-color-primary)));
}

.rottay-steps--rustic[data-part='root'] [data-status='error'] [data-part='icon'][data-variant='dot'] {
  background-color: var(--ds-steps-error-border, var(--ds-color-error-500, var(--ds-color-error)));
}

.rottay-steps--rustic[data-part='root'] [data-status='wait'] [data-part='icon'][data-variant='dot'] {
  background-color: var(--ds-steps-wait-border, var(--ds-color-border-secondary, var(--ds-color-neutral-300)));
