.rottay-steps--rustic[data-part='root'] [data-status='error'] [data-part='label'] {
  color: var(--ds-steps-error-text, var(--ds-color-error-500, var(--ds-color-error)));
}

.rottay-steps--rustic[data-part='root'] [data-part='subtitle'] {
  color: var(--ds-steps-subtitle-color, var(--ds-color-text-tertiary, var(--ds-color-text-secondary)));
}

.rottay-steps--rustic[data-part='root'] [data-part='description'] {
  color: var(--ds-steps-description-color, var(--ds-color-text-tertiary, var(--ds-color-text-secondary)));
