  display: flex;
  inline-size: var(--ds-tabs-list-width, max-content);
  max-inline-size: var(--ds-tabs-list-max-width, 100%);
  min-inline-size: 0;
  flex: 0 1 auto;
  align-items: center;
  gap: var(--ds-tabs-gap, 4px);
  overflow-inline: auto;
  overflow-block: hidden;
  scrollbar-width: none;
  scroll-behavior: smooth;
  scroll-snap-type: inline proximity;
  /* Keyboard/scroll-into-view clearance: keeps a focused tab from parking
     flush under the rail edge fades. */
  scroll-padding-inline: var(--_ds-proto-tabs-scroll-pad, var(--ds-spacing-2));
  scrollbar-gutter: stable;
  -webkit-overflow-scrolling: touch;
}

.rottay-tabs--modern[data-part='root'] [data-part='tab-list']::-webkit-scrollbar {
  display: none;
}

.rottay-tabs--modern[data-part='root'][data-centered='true']:not([data-overflowing='true'])
  [data-part='tab-rail'] {
  justify-content: center;
}

.rottay-tabs--modern[data-part='root'][data-centered='true']:not([data-overflowing='true'])
  [data-part='tab-list'] {
  justify-content: center;
}

.rottay-tabs--modern[data-part='root'][data-overflow='wrap'] [data-part='tab-list'] {
  inline-size: 100%;
  flex-wrap: wrap;
  overflow: visible;
  scroll-snap-type: none;
}

/* Logical edge fades communicate continuation and work unchanged in RTL. */
.rottay-tabs--modern[data-part='root'] [data-part='tab-rail']::before,
.rottay-tabs--modern[data-part='root'] [data-part='tab-rail']::after {
  position: absolute;
  z-index: 2;
  inset-block: 0;
  inline-size: var(--ds-tabs-overflow-fade-width, 28px);
  content: '';
  pointer-events: none;
  opacity: 0;
  transition: opacity
    var(--ds-tabs-motion-duration, var(--ds-motion-feedback, var(--ds-motion-fast)))
    var(--ds-tabs-motion-easing, var(--ds-motion-ease-exit));
}

.rottay-tabs--modern[data-part='root'] [data-part='tab-rail']::before {
  inset-inline-start: 0;
  background: linear-gradient(
    to right,
    var(--ds-tabs-overflow-fade-color, var(--ds-surface-card)),
    transparent
  );
}

[dir='rtl'] .rottay-tabs--modern[data-part='root'] [data-part='tab-rail']::before {
  background: linear-gradient(
    to left,
    var(--ds-tabs-overflow-fade-color, var(--ds-surface-card)),
    transparent
  );
}

.rottay-tabs--modern[data-part='root'] [data-part='tab-rail']::after {
  inset-inline-end: 0;
  background: linear-gradient(
    to left,
    var(--ds-tabs-overflow-fade-color, var(--ds-surface-card)),
    transparent
  );
}

[dir='rtl'] .rottay-tabs--modern[data-part='root'] [data-part='tab-rail']::after {
  background: linear-gradient(
    to right,
    var(--ds-tabs-overflow-fade-color, var(--ds-surface-card)),
    transparent
  );
}

.rottay-tabs--modern[data-part='root'][data-before-overflow='true']
  [data-part='tab-rail']::before,
.rottay-tabs--modern[data-part='root'][data-after-overflow='true']
  [data-part='tab-rail']::after {
  opacity: 1;
}

/* Bounded recipe trays. */
.rottay-tabs--modern[data-part='root'][data-recipe='underline']
  [data-part='tab-list'][data-part='tab-list'] {
  inline-size: var(--ds-tabs-underline-list-width, 100%);
  flex: 1 1 auto;
  border-block-end: 1px solid var(--ds-tabs-border, var(--ds-color-border-subtle));
  background: var(
    --ds-tabs-underline-list-bg,
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--ds-surface-card) 76%, transparent),
      color-mix(in srgb, var(--ds-surface-inset) 44%, transparent)
    )
  );
  box-shadow: inset 0 -1px 0
    color-mix(in srgb, var(--ds-color-bg-elevated) 58%, transparent);
}

.rottay-tabs--modern[data-part='root'][data-recipe='contained'] [data-part='tab-list'],
.rottay-tabs--modern[data-part='root'][data-recipe='segmented'] [data-part='tab-list'],
.rottay-tabs--modern[data-part='root'][data-recipe='pills'] [data-part='tab-list'] {
  padding: var(--ds-tabs-list-padding, 4px);
  border: 1px solid var(--ds-tabs-list-border, var(--ds-color-border-subtle));
  border-radius: var(--ds-tabs-list-radius, var(--ds-radius-lg));
  box-shadow: var(
    --ds-tabs-list-shadow,
    inset 0 1px 0 color-mix(in srgb, var(--ds-color-bg-elevated) 82%, transparent)
  );
  isolation: isolate;
}

/*
 * Optical material layer: a low-contrast grain and inner highlight make the
 * tray feel authored without baking a visual personality into component DOM.
 * Both channels can be replaced with `none` by a flat tenant.
 */
.rottay-tabs--modern[data-part='root'][data-recipe='contained'] [data-part='tab-list']::before,
.rottay-tabs--modern[data-part='root'][data-recipe='segmented'] [data-part='tab-list']::before,
.rottay-tabs--modern[data-part='root'][data-recipe='pills'] [data-part='tab-list']::before {
  position: absolute;
  z-index: 0;
  inset: 1px;
  border-radius: inherit;
  background-image: var(
    --ds-tabs-list-texture,
    radial-gradient(
      circle at 1px 1px,
      color-mix(in srgb, var(--ds-color-text-primary) 13%, transparent) 0.55px,
      transparent 0.75px
    )
  );
  background-size: var(--ds-tabs-list-texture-size, 9px 9px);
  box-shadow: var(
    --ds-tabs-list-highlight,
    inset 0 1px 0 color-mix(in srgb, var(--ds-color-bg-elevated) 68%, transparent)
  );
  content: '';
  pointer-events: none;
  opacity: var(--ds-tabs-list-texture-opacity, 0.16);
}

.rottay-tabs--modern[data-part='root'][data-recipe='contained'] [data-part='tab-list'] {
  background: var(
    --ds-tabs-contained-list-bg,
    var(
      --ds-tabs-list-bg,
      linear-gradient(
        145deg,
        color-mix(in srgb, var(--ds-surface-inset) 90%, var(--ds-color-primary) 10%),
        var(--ds-surface-inset)
      )
    )
  );
}

.rottay-tabs--modern[data-part='root'][data-recipe='segmented'] [data-part='tab-list'] {
  background: var(
    --ds-tabs-segmented-list-bg,
    color-mix(in srgb, var(--ds-surface-inset) 94%, var(--ds-color-primary) 6%)
  );
}

.rottay-tabs--modern[data-part='root'][data-recipe='pills'] [data-part='tab-list'] {
  border-radius: var(--ds-tabs-list-radius, 9999px);
  background: var(
    --ds-tabs-pills-list-bg,
    color-mix(in srgb, var(--ds-surface-inset) 88%, transparent)
  );
  /* Glass is tenant opt-in via the `chrome.tabs.listBlur` contract: the
     default is blur(0), never baked-in frosting. */
  backdrop-filter: blur(var(--ds-tabs-list-blur, 0px));
}

/* Destination anatomy: all static geometry/type is tenant-owned. */
.rottay-tabs--modern[data-part='root'] [data-part='tab-button'] {
  position: relative;
  display: inline-flex;
  box-sizing: border-box;
  min-inline-size: 0;
  max-inline-size: var(--ds-tabs-item-max-width, 18rem);
  block-size: calc(
    var(--_ds-tabs-current-height) * var(--ds-density-effective-scale)
  );
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  gap: calc(var(--ds-tabs-item-gap, 8px) * var(--ds-density-effective-scale));
  padding: var(--_ds-tabs-current-padding);
  border: 1px solid transparent;
  outline: none;
  background: none;
  /* Available tabs are actionable reading text, not decorative metadata.
     Secondary ink is the lowest safe default; tenants can still move the
     hierarchy through the bounded --ds-tab-color / text-secondary channels. */
  color: var(--ds-tab-color, var(--ds-color-text-secondary));
  font-family: var(--ds-tabs-item-font-family, var(--ds-font-family-body));
  font-size: var(--_ds-tabs-current-font-size);
  font-weight: var(--ds-tabs-item-font-weight, var(--ds-font-weight-medium));
  line-height: var(--ds-tabs-item-line-height, 1.15);
  letter-spacing: var(--ds-tabs-item-letter-spacing, -0.006em);
  white-space: nowrap;
  cursor: pointer;
  isolation: isolate;
  scroll-snap-align: start;
  user-select: none;
  transition:
    color var(--ds-tabs-motion-duration, var(--ds-motion-feedback, var(--ds-motion-fast)))
      var(--ds-tabs-motion-easing, var(--ds-motion-ease-move)),
    background-color var(--ds-tabs-motion-duration, var(--ds-motion-feedback, var(--ds-motion-fast)))
      var(--ds-tabs-motion-easing, var(--ds-motion-ease-move)),
    border-color var(--ds-tabs-motion-duration, var(--ds-motion-feedback, var(--ds-motion-fast)))
      var(--ds-tabs-motion-easing, var(--ds-motion-ease-move)),
    box-shadow var(--ds-tabs-motion-duration, var(--ds-motion-feedback, var(--ds-motion-fast)))
      var(--ds-tabs-motion-easing, var(--ds-motion-ease-move)),
    transform var(--ds-tabs-motion-duration, var(--ds-motion-feedback, var(--ds-motion-fast)))
      var(--ds-tabs-motion-easing, var(--ds-motion-ease-move));
}

/* Selection clarity is a one-shot arrival cue, never a looping decoration. */
.rottay-tabs--modern[data-part='root'] [data-part='tab-button']::after {
  position: absolute;
  z-index: 0;
  inset: 1px;
  border-radius: inherit;
  background: var(
    --ds-tabs-active-highlight,
    linear-gradient(
      118deg,
      transparent 12%,
      color-mix(in srgb, var(--ds-color-bg-elevated) 72%, transparent) 48%,
      transparent 76%
    )
  );
  content: '';
  pointer-events: none;
  opacity: 0;
  transform: scaleX(0.76);
  transform-origin: center;
}

.rottay-tabs--modern[data-part='root']
  [data-part='tab-button'][data-selected='true']:not([data-disabled])::after {
  opacity: var(--ds-tabs-active-highlight-opacity, 0.44);
  transform: scaleX(1);
  animation: ds-tabs-selection-arrival
    var(--ds-tabs-active-reveal-duration, var(--ds-motion-feedback))
    var(--ds-tabs-motion-easing, var(--ds-motion-ease-enter)) both;
}

.rottay-tabs--modern[data-part='root'][data-recipe='underline'] [data-part='tab-button'] {
  margin-block-end: -1px;
  border-radius: var(--ds-tabs-line-item-radius, var(--ds-tabs-item-radius, var(--ds-radius-md)));
}

.rottay-tabs--modern[data-part='root'][data-recipe='contained'] [data-part='tab-button'],
.rottay-tabs--modern[data-part='root'][data-recipe='segmented'] [data-part='tab-button'] {
  border-radius: var(--ds-tabs-item-radius, var(--ds-radius-md));
}

.rottay-tabs--modern[data-part='root'][data-recipe='pills'] [data-part='tab-button'] {
  border-radius: var(--ds-tabs-item-radius, 9999px);
}

.rottay-tabs--modern[data-part='root'] [data-part='tab-label'] {
  position: relative;
  z-index: 1;
  display: block;
  min-inline-size: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rottay-tabs--modern[data-part='root'] [data-part='icon'] {
  position: relative;
  z-index: 1;
  display: inline-flex;
  inline-size: var(--_ds-tabs-current-icon-size);
  block-size: var(--_ds-tabs-current-icon-size);
  box-sizing: content-box;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  padding: var(--ds-tabs-icon-padding, 4px);
  border-radius: var(--ds-tabs-icon-radius, var(--ds-radius-sm));
  background: var(
    --ds-tabs-icon-bg,
    color-mix(in srgb, var(--ds-color-text-primary) 5%, transparent)
  );
  color: var(--ds-tabs-icon-color, currentColor);
  box-shadow: var(
    --ds-tabs-icon-shadow,
    inset 0 0 0 1px color-mix(in srgb, var(--ds-color-border-subtle) 72%, transparent)
  );
  transition:
    transform var(--ds-tabs-motion-duration, var(--ds-motion-feedback, var(--ds-motion-fast)))
      var(--ds-tabs-motion-easing, var(--ds-motion-ease-move)),
    background-color var(--ds-tabs-motion-duration, var(--ds-motion-feedback, var(--ds-motion-fast)))
      var(--ds-tabs-motion-easing, var(--ds-motion-ease-move)),
    box-shadow var(--ds-tabs-motion-duration, var(--ds-motion-feedback, var(--ds-motion-fast)))
      var(--ds-tabs-motion-easing, var(--ds-motion-ease-move));
}

.rottay-tabs--modern[data-part='root']
  [data-part='tab-button'][data-selected='true']
  [data-part='icon'] {
  transform: var(--ds-tabs-icon-transform-active, translateY(-1px));
  background: var(
    --ds-tabs-icon-bg-active,
    color-mix(in srgb, var(--ds-color-primary) 10%, transparent)
  );
  box-shadow: var(
    --ds-tabs-icon-shadow-active,
    inset 0 0 0 1px color-mix(in srgb, var(--ds-color-primary) 14%, transparent),
    0 3px 8px color-mix(in srgb, var(--ds-color-primary) 8%, transparent)
  );
}

/* Hover wash is hover-capable only; disabled/loading tabs never leak it. */
@media (hover: hover) {
  .rottay-tabs--modern[data-part='root']
    [data-part='tab-button']:not([data-disabled]):not([data-loading]):hover
    [data-part='icon'] {
    transform: var(--ds-tabs-icon-transform-active, translateY(-1px));
    background: var(
      --ds-tabs-icon-bg-active,
      color-mix(in srgb, var(--ds-color-primary) 10%, transparent)
    );
    box-shadow: var(
      --ds-tabs-icon-shadow-active,
      inset 0 0 0 1px color-mix(in srgb, var(--ds-color-primary) 14%, transparent),
      0 3px 8px color-mix(in srgb, var(--ds-color-primary) 8%, transparent)
    );
  }
}

/* State hierarchy: available, hover, active, disabled. */
@media (hover: hover) {
  .rottay-tabs--modern[data-part='root']
    [data-part='tab-button'][data-selected='false']:not([data-disabled]):not([data-loading]):hover {
    color: var(--ds-tab-color-hover, var(--ds-color-text-secondary));
    transform: translateY(-1px);
  }
}

.rottay-tabs--modern[data-part='root']
  [data-part='tab-button'][data-selected='true']:not([data-disabled]) {
  color: var(--ds-tab-color-active, var(--ds-color-text-primary));
  font-weight: var(--ds-tabs-item-font-weight-active, var(--ds-font-weight-semibold));
}

.rottay-tabs--modern[data-part='root'] [data-part='tab-button'][data-disabled] {
  background: var(--ds-tabs-disabled-bg, transparent);
  color: var(--ds-tabs-disabled-color, var(--ds-color-text-tertiary));
  opacity: var(--ds-tabs-disabled-opacity, 0.48);
  cursor: not-allowed;
  transform: none;
}

/* Loading remains visually distinct from disabled so a selected destination
 * can preserve context while its panel refreshes. Its activation is blocked
 * by the engine while progress and localized status remain perceivable. */
.rottay-tabs--modern[data-part='root'] [data-part='tab-button'][data-loading] {
  cursor: progress;
}

.rottay-tabs--modern[data-part='root'] [data-part='loading-indicator'] {
  position: relative;
  z-index: 1;
  display: inline-block;
  inline-size: var(--ds-tabs-loading-size, 0.875rem);
  block-size: var(--ds-tabs-loading-size, 0.875rem);
  box-sizing: border-box;
  flex: 0 0 auto;
  border: var(--ds-tabs-loading-stroke, 1.5px) solid
    var(
      --ds-tabs-loading-track,
      color-mix(in srgb, currentColor 22%, transparent)
    );
  border-block-start-color: var(--ds-tabs-loading-color, currentColor);
  border-radius: var(--ds-radius-full);
  animation: ds-tabs-loading-spin
    var(--ds-tabs-loading-duration, var(--ds-motion-deliberate)) linear
    infinite;
}

/* The loading-status live region is hidden by the canonical
   `.ds-visually-hidden` rule (the engine renders the VisuallyHidden
