   `data-part='loading-status'` hook stays for tests and consumers. */

.rottay-tabs--modern[data-part='root'] [data-part='tab-button']:focus-visible {
  outline: var(--ds-focus-ring-width) solid var(--ds-focus-ring-color);
  outline-offset: calc(-1 * var(--ds-focus-ring-offset));
}

@media (hover: hover) {
  .rottay-tabs--modern[data-part='root'][data-recipe='underline']
    [data-part='tab-button'][data-selected='false']:not([data-disabled]):not([data-loading]):hover {
    background: var(
      --ds-tabs-line-hover-bg,
      color-mix(in srgb, var(--ds-color-text-primary) 4%, transparent)
    );
  }
}

.rottay-tabs--modern[data-part='root'][data-recipe='underline']
  [data-part='tab-button'][data-selected='true']:not([data-disabled]) {
  background: var(
    --ds-tabs-line-active-bg,
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--ds-color-primary) 8%, transparent),
      color-mix(in srgb, var(--ds-color-primary) 3%, transparent)
    )
  );
}

@media (hover: hover) {
  .rottay-tabs--modern[data-part='root'][data-recipe='contained']
    [data-part='tab-button'][data-selected='false']:not([data-disabled]):not([data-loading]):hover,
  .rottay-tabs--modern[data-part='root'][data-recipe='segmented']
    [data-part='tab-button'][data-selected='false']:not([data-disabled]):not([data-loading]):hover {
    border-color: color-mix(
      in srgb,
      var(--ds-tabs-list-border, var(--ds-color-border-subtle)) 76%,
      transparent
    );
    background: var(--ds-tab-bg-hover, var(--ds-surface-highlight));
  }
}

.rottay-tabs--modern[data-part='root'][data-recipe='contained']
  [data-part='tab-button'][data-selected='true']:not([data-disabled]),
.rottay-tabs--modern[data-part='root'][data-recipe='segmented']
  [data-part='tab-button'][data-selected='true']:not([data-disabled]) {
  border-color: var(--ds-tabs-list-border, var(--ds-color-border-subtle));
  transform: var(--ds-tabs-active-transform, translateY(-1px));
}

.rottay-tabs--modern[data-part='root'][data-recipe='contained']
  [data-part='tab-button'][data-selected='true']:not([data-disabled]) {
  background: var(
    --ds-tabs-contained-active-bg,
    var(
      --ds-tabs-active-bg,
      linear-gradient(
        160deg,
        var(--ds-surface-card),
        color-mix(in srgb, var(--ds-surface-card) 93%, var(--ds-color-primary) 7%)
      )
    )
  );
  box-shadow: var(
    --ds-tabs-contained-active-shadow,
    var(--ds-tabs-active-shadow, var(--ds-elevation-1))
  );
}

.rottay-tabs--modern[data-part='root'][data-recipe='segmented']
  [data-part='tab-button'][data-selected='true']:not([data-disabled]) {
  background: var(
    --ds-tabs-segmented-active-bg,
    var(--ds-tabs-active-bg, var(--ds-surface-card))
  );
  box-shadow: var(
    --ds-tabs-segmented-active-shadow,
    var(--ds-tabs-active-shadow, var(--ds-elevation-1))
  );
  transform: var(--ds-tabs-active-transform, none);
}

@media (hover: hover) {
  .rottay-tabs--modern[data-part='root'][data-recipe='pills']
    [data-part='tab-button'][data-selected='false']:not([data-disabled]):not([data-loading]):hover {
    border-color: color-mix(
      in srgb,
      var(--ds-tabs-list-border, var(--ds-color-border-subtle)) 78%,
      transparent
    );
    background: var(
      --ds-tab-bg-hover,
      color-mix(in srgb, var(--ds-color-text-primary) 5%, transparent)
    );
  }
}

.rottay-tabs--modern[data-part='root'][data-recipe='pills']
  [data-part='tab-button'][data-selected='true']:not([data-disabled]) {
  border-color: var(
    --ds-tabs-pills-active-border,
    var(--ds-tab-border-active, var(--ds-color-primary))
  );
  /* A filled pill reads loud through ink-on-primary alone: flat solid fill
     and neutral elevation, no gradient sheen, no primary glow. */
  background: var(--ds-tabs-pills-active-bg, var(--ds-color-primary));
  color: var(--ds-tabs-pills-active-color, var(--ds-color-text-on-primary));
  box-shadow: var(--ds-tabs-pills-active-shadow, var(--ds-elevation-1));
  transform: var(--ds-tabs-active-transform, translateY(-1px));
}

/* Press feedback wins over recipe lift for both selected and idle tabs. */
.rottay-tabs--modern[data-part='root']
  [data-part='tab-button'][data-selected]:active:not([data-disabled]):not([data-loading]) {
  transform: var(--ds-tabs-pressed-transform, translateY(0) scale(0.985));
  transition-duration: var(--ds-motion-instant);
}

/* Explicit badge channel prevents product code from rebuilding tab anatomy. */
.rottay-tabs--modern[data-part='root'] [data-part='tab-badge'][data-part='tab-badge'] {
  position: relative;
  z-index: 1;
  display: inline-flex;
  min-inline-size: var(--ds-tabs-badge-min-width, 18px);
  block-size: var(--ds-tabs-badge-height, 18px);
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  padding: var(--ds-tabs-badge-padding, 0 6px);
  border: 1px solid
    var(--ds-tabs-badge-border, color-mix(in srgb, currentColor 16%, transparent));
  border-radius: var(--ds-tabs-badge-radius, 9999px);
  background: var(
    --ds-tabs-badge-bg,
    color-mix(in srgb, var(--ds-color-text-primary) 7%, transparent)
  );
  color: var(--ds-tabs-badge-color, var(--ds-color-text-secondary));
  font-size: var(--ds-tabs-badge-font-size, var(--ds-font-size-2xs));
  font-weight: var(--ds-tabs-badge-font-weight, var(--ds-font-weight-semibold));
  line-height: 1;
  font-variant-numeric: tabular-nums;
  box-shadow: inset 0 1px 0
    color-mix(in srgb, var(--ds-color-bg-elevated) 72%, transparent);
  transition:
    color var(--ds-tabs-motion-duration, var(--ds-motion-feedback, var(--ds-motion-fast)))
      var(--ds-tabs-motion-easing, var(--ds-motion-ease-move)),
    background-color var(--ds-tabs-motion-duration, var(--ds-motion-feedback, var(--ds-motion-fast)))
      var(--ds-tabs-motion-easing, var(--ds-motion-ease-move)),
    border-color var(--ds-tabs-motion-duration, var(--ds-motion-feedback, var(--ds-motion-fast)))
      var(--ds-tabs-motion-easing, var(--ds-motion-ease-move)),
    transform var(--ds-tabs-motion-duration, var(--ds-motion-feedback, var(--ds-motion-fast)))
      var(--ds-tabs-motion-easing, var(--ds-motion-ease-move));
}

.rottay-tabs--modern[data-part='root']
