  position: absolute;
  inset-block-start: var(--ds-tour-close-offset, var(--ds-spacing-2));
  inset-inline-end: var(--ds-tour-close-offset, var(--ds-spacing-2));
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--ds-tour-close-size, 1.75rem);
  block-size: var(--ds-tour-close-size, 1.75rem);
  padding: 0;
  cursor: pointer;
  border-radius: 50%;
  border: none;
  background: transparent;
  color: var(--ds-tour-close-ink, var(--ds-material-card-foreground-muted, var(--ds-color-text-secondary)));
  transition:
    color var(--ds-motion-fast) var(--ds-ease-standard, ease),
    background-color var(--ds-motion-fast) var(--ds-ease-standard, ease),
    box-shadow var(--ds-motion-fast) var(--ds-ease-standard, ease);
