.rottay-tour--modern[data-part='root']
  [data-part='surface'][data-type='primary']
  [data-part='action'][data-action='next'] {
  background: var(--ds-tour-action-next-bg, var(--ds-color-primary));
  color: var(--ds-tour-action-next-ink, var(--ds-material-overlay-foreground, var(--ds-color-text-on-primary)));
