.rottay-tour--modern[data-part='root'] [data-part='action'][data-action='next']:not(:disabled):active {
  transform: translateY(0);
  box-shadow: none;
}
.rottay-tour--modern[data-part='root'] [data-part='close-button']:not(:disabled):active {
  color: var(--ds-tour-close-ink-hover, var(--ds-material-card-foreground, var(--ds-color-text-primary)));
  background: var(--ds-tour-close-bg-hover, color-mix(in srgb, currentColor 8%, transparent));
