  .rottay-tour--modern[data-part='root'] [data-part='close-button']:not(:disabled):hover {
    outline: 1px solid;
  }
  .rottay-tour--modern[data-part='root'] [data-part='indicator'] {
    border: 1px solid ButtonText;
