html[data-ds-motion='reduced'] .rottay-tour--modern[data-part='root'] > [data-part='spotlight'],
html[data-ds-motion='reduced'] .rottay-tour--modern[data-part='root'] > [data-part='surface'] {
  animation: none;
}
html[data-ds-motion='reduced'] .rottay-tour--modern[data-part='root'] [data-part='action'],
html[data-ds-motion='reduced'] .rottay-tour--modern[data-part='root'] [data-part='close-button'],
html[data-ds-motion='reduced'] .rottay-tour--modern[data-part='root'] [data-part='indicator'] {
