.rottay-action-dock[data-part='root'][data-placement][data-mode] {
  box-sizing: border-box;
  width: 100%;
  padding-inline: var(--ds-action-dock-padding-inline, var(--ds-spacing-4, 1rem));
  z-index: var(--ds-action-dock-z-index, var(--ds-z-index-fixed, 1200));
  background: var(
    --ds-action-dock-bg,
    color-mix(in srgb, var(--ds-color-bg-primary) 90%, transparent)
  );
  backdrop-filter: var(--ds-action-dock-backdrop-filter, blur(var(--ds-glass-blur, 8px)));
  -webkit-backdrop-filter: var(--ds-action-dock-backdrop-filter, blur(var(--ds-glass-blur, 8px)));
  transition:
    background-color var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out),
    border-color var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out),
    box-shadow var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out);
}

.rottay-action-dock[data-part='root'][data-mode='fixed'] {
  position: fixed;
  inset-inline: 0;
}

.rottay-action-dock[data-part='root'][data-mode='sticky'] {
  position: sticky;
  z-index: var(--ds-action-dock-sticky-z-index, var(--ds-z-index-sticky, 1100));
}

.rottay-action-dock[data-part='root'][data-placement='bottom'] {
  /* Public reservation hook (the S02 `--ds-bottom-tab-bar-reserved-block-end`
     precedent): pages keep their content clear of the fixed dock with
     `padding-block-end: var(--ds-action-dock-reserved-block-end)`. The 60px
     base tracks the dock geometry (12+12+36) — update it if that changes. */
  --ds-action-dock-reserved-block-end: calc(
    60px + var(--ds-action-dock-safe-area-bottom, var(--ds-safe-area-bottom, env(safe-area-inset-bottom, 0px)))
  );

  padding-block-start: var(--ds-action-dock-padding-block, var(--ds-spacing-3, 0.75rem));
  padding-block-end: max(
    var(--ds-action-dock-padding-block, var(--ds-spacing-3, 0.75rem)),
    var(--ds-action-dock-safe-area-bottom, var(--ds-safe-area-bottom, env(safe-area-inset-bottom, 0px)))
  );
  border-block-start: 1px solid var(--ds-action-dock-edge-color, var(--ds-color-border-primary, transparent));
  box-shadow:
    inset 0 1px 0 var(
      --ds-action-dock-edge-highlight,
      color-mix(in srgb, var(--ds-color-bg-elevated) 72%, transparent)
    ),
    var(
      --ds-action-dock-shadow-bottom,
      0 -2px 4px color-mix(in srgb, var(--ds-color-shadow) 30%, transparent),
      0 -12px 28px -12px color-mix(in srgb, var(--ds-color-shadow) 60%, transparent)
    );
}

.rottay-action-dock[data-part='root'][data-placement='bottom'][data-mode='fixed'] {
  inset-block-end: calc(var(--ds-shell-bottom-inset, 0px) + var(--ds-virtual-keyboard-inset, 0px));
}

.rottay-action-dock[data-part='root'][data-placement='bottom'][data-mode='fixed'][data-keyboard-open='true'] {
  inset-block-end: var(--ds-virtual-keyboard-inset, 0px);
}

.rottay-action-dock[data-part='root'][data-placement='bottom'][data-mode='sticky'] {
  inset-block-end: 0;
}

.rottay-action-dock[data-part='root'][data-placement='top'] {
  /* Top-placement mirror of the bottom reservation hook. */
  --ds-action-dock-reserved-block-start: calc(
    60px + var(--ds-action-dock-safe-area-top, var(--ds-safe-area-top, env(safe-area-inset-top, 0px)))
  );

  inset-block-start: 0;
  padding-block-start: max(
    var(--ds-action-dock-padding-block, var(--ds-spacing-3, 0.75rem)),
    var(--ds-action-dock-safe-area-top, var(--ds-safe-area-top, env(safe-area-inset-top, 0px)))
  );
  padding-block-end: var(--ds-action-dock-padding-block, var(--ds-spacing-3, 0.75rem));
  border-block-end: 1px solid var(--ds-action-dock-edge-color, var(--ds-color-border-primary, transparent));
  box-shadow:
    inset 0 -1px 0 var(
      --ds-action-dock-edge-highlight,
      color-mix(in srgb, var(--ds-color-bg-elevated) 72%, transparent)
    ),
    var(--ds-action-dock-shadow-top, var(--ds-shadow-navbar));
}

.rottay-action-dock__actions {
  width: 100%;
  gap: var(--ds-action-dock-gap, var(--ds-spacing-3, 0.75rem));
}

/* Shrink guard: row children may shrink below content width so labels
 * ellipsize (Button label contract) instead of overflowing the dock. */
.rottay-action-dock__actions > * {
  min-inline-size: 0;
}

/* Priority grammar (layout only — Button owns its paint):
 * primary grows into the freed space; danger hugs the start edge and the auto
 * margin separates it from the action cluster at the end edge. */
.rottay-action-dock__actions > .rottay-action-dock__action[data-priority='primary'] {
  flex: 1 1 auto;
}

.rottay-action-dock__actions > .rottay-action-dock__action[data-priority='danger'] {
  margin-inline-end: auto;
}

.rottay-action-dock__actions > .rottay-action-dock__overflow-trigger {
  flex: 0 0 auto;
}

/* Coarse pointers: every direct action in the row meets the 44px physical
 * floor. min-block-size composes with Button's own height instead of
 * fighting its specificity. */
@media (pointer: coarse) {
  .rottay-action-dock__actions > :where(button, a),
  .rottay-action-dock__overflow-trigger {
    min-block-size: max(44px, var(--ds-size-touch-target, 44px));
  }
}

/* Reduced motion: the surface transition (theme/density channel switches)
 * is silenced; layout and the coarse floor are unaffected. */
@media (prefers-reduced-motion: reduce) {
  .rottay-action-dock[data-part='root'][data-placement][data-mode] {
    transition: none;
  }
}

