.rottay-mobile-header__back[data-part='trigger']:focus-visible {
  outline: none;
  box-shadow: var(--ds-mobile-header-focus-ring, var(--ds-focus-ring, 0 0 0 3px color-mix(in srgb, var(--ds-color-primary) 24%, transparent)));
}

/* Hover is pointer-fine only (the `:active` press scale above is the real
