}

.rottay-stepper-step[data-status='error'] [data-part='label'] {
  color: var(--ds-stepper-title-error-color, var(--ds-color-error));
}

.rottay-stepper-step [data-part='subtitle'] {
  color: var(--ds-stepper-subtitle-color, var(--ds-color-text-tertiary, var(--ds-color-text-secondary)));
}

.rottay-stepper-step [data-part='description'] {
  color: var(--ds-stepper-description-color, var(--ds-color-text-tertiary, var(--ds-color-text-secondary)));
}

/* ---- Stepper.Step's connector: one fill, two orientations. The source wrote
