.rottay-stepper-step[data-size='md'] [data-part='icon'] {
  inline-size: var(--ds-stepper-item-size-md, 32px);
  block-size: var(--ds-stepper-item-size-md, 32px);
  min-inline-size: var(--ds-stepper-item-size-md, 32px);
  font-size: var(--ds-stepper-item-font-size-md, var(--ds-font-size-sm));
