    display: grid;
    grid-column: 1 / -1;
    grid-template-columns: subgrid;
    align-items: baseline;
  }
  .rottay-descriptions.rottay-descriptions--modern[data-part='root'][data-layout='vertical'] > [data-part='body'] > [data-part='rows'] > [data-part='row'] > [data-part='label'] {
    inline-size: auto;
  }
  .rottay-descriptions.rottay-descriptions--modern[data-part='root'][data-layout='vertical'] > [data-part='body'] > [data-part='rows'] > [data-part='row'] > [data-part='content'] {
    min-inline-size: 0;
  }
}

/* ---- size axis: density. `data-size` was stamped but unpainted; small/middle
        de-escalate the row inset through their own channels (default keeps the
        base above). Font sizes stay put — density is an inset axis here. ---- */
.rottay-descriptions.rottay-descriptions--modern[data-part='root'][data-size='small'] > [data-part='body'] > [data-part='rows'] > [data-part='row'] {
  padding: var(--ds-descriptions-row-padding-sm, 0.5rem 0.625rem);
}
.rottay-descriptions.rottay-descriptions--modern[data-part='root'][data-size='middle'] > [data-part='body'] > [data-part='rows'] > [data-part='row'] {
  padding: var(--ds-descriptions-row-padding-md, 0.625rem 0.75rem);
}

@container (max-width: 860px) {
  .rottay-descriptions.rottay-descriptions--modern[data-part='root'][data-layout='horizontal']:not([data-column-count='1']) > [data-part='body'] > [data-part='rows'] {
    grid-template-columns: repeat(2, minmax(0, 1fr));
