  border-bottom: 1px solid var(--ds-descriptions-item-border-color, #f0f0f0);
}
.rottay-descriptions.rottay-descriptions--rustic[data-part='root'][data-bordered='false'] > [data-part='body'] > [data-part='rows'] > [data-part='row'] {
  border-bottom: none;
