.rottay-descriptions.rottay-descriptions--rustic[data-part='root'] > [data-part='body'] > [data-part='rows'] > [data-part='row'] > [data-part='label'] {
  color: var(--ds-descriptions-label-color, var(--ds-color-text-secondary, #666));
