.rottay-descriptions.rottay-descriptions--rustic[data-part='root'] > [data-part='body'] > [data-part='rows'] > [data-part='row'] > [data-part='content'] {
  color: var(--ds-descriptions-content-color, var(--ds-color-text-primary, #333));
