/* size steps de-escalate the ROW INSET too, not just the font: density is a
   composed posture, not a uniform scale. Items are direct children of
   [data-part='list'] (child combinators — a list nested inside an item keeps
   its own size step). The base item rule below stays the standalone/default
   authority; these consume the declared --ds-list-sm/lg-padding-* channels. */
.rottay-list.rottay-list--modern[data-part='root'][data-size='small'] > [data-part='list'] > .rottay-list-item.rottay-list-item--modern[data-part='item'] {
  padding: var(--ds-list-sm-padding-vertical) var(--ds-list-sm-padding-horizontal);
}
.rottay-list.rottay-list--modern[data-part='root'][data-size='large'] > [data-part='list'] > .rottay-list-item.rottay-list-item--modern[data-part='item'] {
  padding: var(--ds-list-lg-padding-vertical) var(--ds-list-lg-padding-horizontal);
}

/* loading posture (the vendor `animate-pulse` string is a test-pinned bridge:
   THIS animation declaration wins over the utilities-layer pulse by layer
   ownership, so the cadence rides the motion authority -- 4× glacial = the
   vendor pulse's 2s -- and reduced-motion can silence it) */
.rottay-list.rottay-list--modern[data-part='root'][data-loading='true'] {
  /* Static posture when motion is off; the pulse animates over it. */
  opacity: var(--ds-list-loading-opacity);
  animation: ds-list-skeleton-pulse-modern var(--ds-list-skeleton-pulse-duration, calc(var(--ds-motion-glacial) * 4)) var(--ds-motion-ease-in-out) infinite;
}
.rottay-list.rottay-list--modern[data-part='root'][data-loading='true'] [data-part='skeleton-row'] {
  padding-block: var(--ds-list-skeleton-row-padding-block, 12px);
}
.rottay-list.rottay-list--modern[data-part='root'][data-loading='true'] [data-part='skeleton-row-inner'] {
  display: flex;
  align-items: center;
  gap: var(--ds-list-skeleton-row-gap, 12px);
}
.rottay-list.rottay-list--modern[data-part='root'][data-loading='true'] [data-part='skeleton-lines'] {
  flex: 1;
  min-inline-size: 0;
}

/* loading skeleton: avatar disc + text bars share one fill (layout drained
   from the `w-10 h-10 rounded-full` / `h-4 rounded w-1/3 mb-2` / `h-3 rounded
   w-2/3` / `flex-1` utilities) */
.rottay-list.rottay-list--modern[data-part='root'][data-loading='true'] [data-part='skeleton-avatar'] {
  inline-size: var(--ds-list-skeleton-avatar-size, 40px);
  block-size: var(--ds-list-skeleton-avatar-size, 40px);
  flex-shrink: 0;
  border-radius: var(--ds-radius-full);
}
.rottay-list.rottay-list--modern[data-part='root'][data-loading='true'] [data-part='skeleton-line'] {
  border-radius: var(--ds-list-skeleton-line-radius, var(--ds-radius-sm));
}
.rottay-list.rottay-list--modern[data-part='root'][data-loading='true'] [data-part='skeleton-line']:first-child {
  inline-size: 33.333%;
  block-size: var(--ds-list-skeleton-line-height, 16px);
  margin-block-end: var(--ds-list-skeleton-line-gap, 8px);
}
