  padding: var(--ds-list-header-padding-vertical) var(--ds-list-header-padding-horizontal);
  font-size: var(--ds-list-header-font-size, var(--ds-font-size-sm));
  font-weight: var(--ds-list-header-font-weight);
  background: var(--ds-list-header-background-color);
}
.rottay-list.rottay-list--modern[data-part='root'] > [data-part='footer'] {
  padding: var(--ds-list-footer-padding-vertical) var(--ds-list-footer-padding-horizontal);
  font-size: var(--ds-list-footer-font-size, var(--ds-font-size-sm));
  background: var(--ds-list-footer-background-color);
}
.rottay-list.rottay-list--modern[data-part='root'][data-bordered='true'] > [data-part='header'] {
  border-bottom: var(--ds-list-border-width) solid var(--ds-list-border-color, var(--ds-color-border));
