/* ============================== List.Item ================================ */

.rottay-list-item.rottay-list-item--modern[data-part='item'] {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--ds-list-default-padding-vertical) var(--ds-list-default-padding-horizontal);
  background: var(--ds-list-item-background-color);
  color: var(--ds-list-text-color);
  transition: background var(--ds-list-transition-duration, var(--ds-motion-normal)) var(--ds-list-transition-timing);
}

/* Row states. The hover wash consumes the long-declared
   --ds-list-item-hover-background-color channel (previously read ONLY by the
   skeleton fill). Hover is gated to fine pointers; :active is the touch
   equivalent; :focus-within gives keyboard users the same row context when a
   slotted control takes focus. */
@media (hover: hover) {
  .rottay-list-item.rottay-list-item--modern[data-part='item']:hover {
    background: var(--ds-list-item-hover-background-color, var(--ds-surface-panel));
  }
