/* Selected (caller-stamped aria hook): tint PLUS a full inset keyline — the
   selection never reads by color alone, and the keyline wraps all four edges
   (a colored inline-start rail is prohibited frame grammar). */
.rottay-list-item.rottay-list-item--modern[data-part='item'][aria-selected='true'],
.rottay-list-item.rottay-list-item--modern[data-part='item'][aria-current] {
  background: color-mix(in srgb, var(--ds-color-primary) 8%, var(--ds-list-item-background-color));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ds-color-primary) 35%, transparent);
}

