  color: var(--ds-color-text-muted, var(--ds-color-text-secondary));
}
@media (hover: hover) {
  .rottay-list-item.rottay-list-item--modern[data-part='item'][aria-disabled='true']:hover {
    background: var(--ds-list-item-background-color);
  }
