.rottay-list-item.rottay-list-item--modern[data-part='item'] > [data-part='item-content'] {
  flex: 1;
  min-inline-size: 0;
  /* Long copy (URLs, AR strings) wraps inside the row instead of pushing
     extra/actions out of the box. */
  overflow-wrap: break-word;
}
.rottay-list-item.rottay-list-item--modern[data-part='item'] > [data-part='item-extra'] {
  flex-shrink: 0;
  margin-inline-start: var(--ds-list-extra-margin-left);
}
.rottay-list-item.rottay-list-item--modern[data-part='item'] > [data-part='item-actions'] {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  margin-inline-start: var(--ds-list-extra-margin-left);
  gap: var(--ds-list-actions-gap);
  color: var(--ds-list-actions-color, var(--ds-color-primary));
}

/* Plain text/link actions inherit the tray color and pick up the declared
   hover tone; slotted Buttons paint themselves and are unaffected. */
@media (hover: hover) {
  .rottay-list-item.rottay-list-item--modern[data-part='item'] > [data-part='item-actions'] > [data-part='item-action']:hover {
    color: var(--ds-list-actions-hover-color, var(--ds-color-primary));
  }
}

/* Vertical item layout (the contract's itemLayout='vertical', now stamped):
   content stacks above the action row; extra/actions drop their inline-start
   offset and settle at the trailing edge under the content. Child combinators
   keep a nested horizontal list untouched. */
.rottay-list.rottay-list--modern[data-part='root'][data-item-layout='vertical'] > [data-part='list'] > .rottay-list-item.rottay-list-item--modern[data-part='item'] {
  flex-direction: column;
  align-items: stretch;
}
.rottay-list.rottay-list--modern[data-part='root'][data-item-layout='vertical'] > [data-part='list'] > .rottay-list-item.rottay-list-item--modern[data-part='item'] > [data-part='item-extra'],
.rottay-list.rottay-list--modern[data-part='root'][data-item-layout='vertical'] > [data-part='list'] > .rottay-list-item.rottay-list-item--modern[data-part='item'] > [data-part='item-actions'] {
  margin-inline-start: 0;
  margin-block-start: var(--ds-spacing-2);
  justify-content: flex-end;
}

/* ============================ List.Item.Meta ============================= */

.rottay-list-item-meta.rottay-list-item-meta--modern[data-part='meta'] {
  display: flex;
  align-items: flex-start;
  gap: var(--ds-list-meta-avatar-margin-right);
}
.rottay-list-item-meta.rottay-list-item-meta--modern[data-part='meta'] > [data-part='meta-avatar'] {
  flex-shrink: 0;
}
.rottay-list-item-meta.rottay-list-item-meta--modern[data-part='meta'] > [data-part='meta-content'] {
  flex: 1;
  min-inline-size: 0;
}
.rottay-list-item-meta.rottay-list-item-meta--modern[data-part='meta'] > [data-part='meta-content'] > [data-part='meta-title'] {
  font-size: var(--ds-list-meta-title-font-size);
  font-weight: var(--ds-list-meta-title-font-weight);
  color: var(--ds-list-meta-title-color, var(--ds-color-text-primary));
  overflow-wrap: break-word;
}
.rottay-list-item-meta.rottay-list-item-meta--modern[data-part='meta'] > [data-part='meta-content'] > [data-part='meta-description'] {
  /* em (not rem) so the step follows the list's own data-size font step. */
  font-size: var(--ds-list-meta-description-font-size);
  margin-top: var(--ds-list-meta-description-margin-top);
  overflow-wrap: break-word;
  /* CONTRAST LAW (K3-A Pass 2, axe color-contrast/serious): the resolved
     description channel fails AA on the page surface (bithire's #888d9e =
     3.31:1 on #fff; TMM's #737373 = 4.74:1 passes but the channel must hold
     on every governed source). The ink deepens 30% toward the source's own
     primary text ink -- hue-faithful, no tenant fork (measured worst source:
     bithire 70% = 5.07:1). A tenant's explicit `--ds-list-meta-description-ink`
     stays raw. */
  color: var(
    --ds-list-meta-description-ink,
    color-mix(
      in srgb,
      var(--ds-list-meta-description-color, var(--ds-color-text-secondary)) 70%,
      var(--ds-color-text-primary) 30%
    )
  );
}

/* ---- reduced motion: the skeleton pulse and the item transition go quiet
        (the static loading opacity keeps the posture). ---- */
@media (prefers-reduced-motion: reduce) {
  .rottay-list.rottay-list--modern[data-part='root'][data-loading='true'] {
    animation: none;
  }
  .rottay-list-item.rottay-list-item--modern[data-part='item'] {
    transition: none;
  }
}

/* ---- forced colors (system colors only): the bordered frame, header/footer
        separators and split dividers keep system-color boundaries; the
        skeleton bars stay perceivable as shapes. ---- */
@media (forced-colors: active) {
  .rottay-list.rottay-list--modern[data-part='root'][data-bordered='true'],
  .rottay-list.rottay-list--modern[data-part='root'][data-bordered='true'] > [data-part='header'],
  .rottay-list.rottay-list--modern[data-part='root'][data-bordered='true'] > [data-part='footer'],
  .rottay-list.rottay-list--modern[data-part='root'] > [data-part='list'] > [data-part='divider'] {
    border-color: ButtonText;
  }
  .rottay-list.rottay-list--modern[data-part='root'][data-loading='true'] [data-part='skeleton-avatar'],
  .rottay-list.rottay-list--modern[data-part='root'][data-loading='true'] [data-part='skeleton-line'] {
    border: 1px solid ButtonText;
  }
  /* The selected tint + inset shadow wash out under forced colors; the
     selected row keeps a system-color keyline so selection never depends on
     the (now gone) background mix. */
  .rottay-list-item.rottay-list-item--modern[data-part='item'][aria-selected='true'],
  .rottay-list-item.rottay-list-item--modern[data-part='item'][aria-current] {
    outline: 1px solid ButtonText;
    outline-offset: -1px;
  }
}

