  font-size: var(--ds-statistic-title-font-size, var(--ds-font-size-xs));
  font-weight: var(--ds-statistic-title-font-weight, var(--ds-font-weight-medium));
  letter-spacing: var(--ds-statistic-title-letter-spacing, 0.045em);
  text-transform: var(--ds-statistic-title-transform, uppercase);
  text-wrap: balance;
  line-height: var(--ds-line-height-sm, 1.25rem);
  margin-bottom: var(--ds-statistic-title-margin-bottom, var(--ds-spacing-1));
}

