.rottay-tag-shell.rottay-tag-shell--modern[data-part='root'][data-part='root'][data-variant='success']:not([data-outlined]) {
  background: var(--ds-tag-custom-bg, var(--ds-tag-success-solid-bg, color-mix(in srgb, var(--ds-color-success) 62%, var(--ds-color-neutral-900) 38%)));
  color: var(--ds-tag-success-ink, var(--ds-color-white));
