  border-radius: var(--ds-tag-radius-lg, 0.5rem);
}
.rottay-tag.rottay-tag--rustic[data-part='root'][data-part='root'][data-radius='full'] {
  border-radius: var(--ds-tag-radius-full, 9999px);
}

/* ---- ink: the variant's text colour, outlined or not. The bare rule carries
        `default`, the lookup's own fallback for an unrecognised variant. ---- */
.rottay-tag.rottay-tag--rustic[data-part='root'][data-part='root'] {
  color: var(--ds-tag-default-color);
}
.rottay-tag.rottay-tag--rustic[data-part='root'][data-part='root'][data-variant='primary'] {
  color: var(--ds-tag-primary-color);
}
.rottay-tag.rottay-tag--rustic[data-part='root'][data-part='root'][data-variant='secondary'] {
  color: var(--ds-tag-secondary-color);
}
.rottay-tag.rottay-tag--rustic[data-part='root'][data-part='root'][data-variant='success'] {
