  font-weight: var(--ds-timeline-label-font-weight, var(--ds-font-weight-medium));
  letter-spacing: var(--ds-timeline-label-letter-spacing, 0.02em);
  font-variant-numeric: var(--ds-timeline-label-font-variant-numeric, tabular-nums);
  margin-bottom: var(--ds-spacing-1);
