.rottay-timeline.rottay-timeline--modern[data-part='root'] > [data-part='item'][data-tone='warning'] > [data-part='dot'] > [data-part='dot-marker'] {
  background: var(--ds-timeline-color-warning, var(--ds-color-warning));
