  .rottay-timeline.rottay-timeline--modern[data-part='root'] > [data-part='item'] > [data-part='connector'] {
    background: ButtonText;
  }
  .rottay-timeline.rottay-timeline--modern[data-part='root'] > [data-part='item'] > [data-part='dot'] > [data-part='dot-marker'] {
    background: ButtonText;
  }
  .rottay-timeline.rottay-timeline--modern[data-part='root'] > [data-part='item'][data-pending='true'] > [data-part='dot'] > [data-part='dot-marker'] {
    background: Highlight;
  }
  .rottay-timeline.rottay-timeline--modern[data-part='root'] > [data-part='item'][data-pending='true'] > [data-part='content'] > [data-part='spinner'] [data-part='indicator'][role='status'] {
    border-color: GrayText;
    border-top-color: Highlight;
