/* Composed primitives fill their layout wrapper. */
.ds-pattern-filter-builder.ds-engine-modern [data-part='rule-field'] > *,
.ds-pattern-filter-builder.ds-engine-modern [data-part='rule-operator'] > *,
.ds-pattern-filter-builder.ds-engine-modern [data-part='rule-value'] > * {
