.ds-pattern-form-builder.ds-engine-modern [data-part='field'] {
  inline-size: 100%;
}
.ds-pattern-form-builder.ds-engine-modern [data-part='fields'][data-layout='grid'] {
  display: grid;
}
.ds-pattern-form-builder.ds-engine-modern [data-part='fields'][data-layout='horizontal'] {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
}
.ds-pattern-form-builder.ds-engine-modern [data-part='fields'][data-layout='vertical'] {
  display: flex;
  flex-direction: column;
}

/* ---- empty schema (composed Empty primitive): rhythm only ---- */
.ds-pattern-form-builder.ds-engine-modern [data-part='empty'] {
  padding-block: var(--ds-form-builder-empty-padding-block, var(--ds-spacing-8, 32px));
}

/* ---- wizard step rail: the public Steps primitive renders inside; the
        pattern owns only the row offset. ---- */
.ds-pattern-form-builder.ds-engine-modern [data-part='step-list'] {
  margin-block-end: var(--ds-form-builder-step-list-offset, var(--ds-spacing-8, 32px));
}

/* ---- sections. ---- */
.ds-pattern-form-builder.ds-engine-modern[data-part='root'] [data-part='section-divider'] {
  block-size: 1px;
  margin-block: var(--ds-form-builder-section-divider-gap, 28px);
  background: var(--ds-color-border);
