.ds-pattern-form-builder.ds-engine-modern [data-part='section-title'] {
  color: var(--ds-color-text-primary);
  font-size: var(--ds-form-builder-section-title-font-size, 15px);
  font-weight: var(--ds-font-weight-semibold, 600);
  line-height: var(--ds-line-height-snug, 1.375);
  letter-spacing: var(--ds-form-builder-section-title-letter-spacing, -0.005em);
}
.ds-pattern-form-builder.ds-engine-modern [data-part='section-description'] {
  margin-block-start: var(--ds-spacing-1, 4px);
  color: var(--ds-color-text-muted);
  font-size: var(--ds-form-builder-section-description-font-size, 13px);
  line-height: var(--ds-line-height-snug, 1.375);
