/* autoAdaptive stays JS-driven (useBreakpoints); this container query only
   handles the nav bar wrap. */
@container ds-form-builder (inline-size < 30rem) {
  .ds-pattern-form-builder.ds-engine-modern [data-part='wizard-nav'] {
    flex-direction: column;
    align-items: stretch;
  }
  .ds-pattern-form-builder.ds-engine-modern [data-part='wizard-nav-end'] {
    justify-content: space-between;
  }
}

@media (hover: none) and (pointer: coarse) {
  .ds-pattern-form-builder.ds-engine-modern [data-part='section-header'],
  .ds-pattern-form-builder.ds-engine-modern [data-part='wizard-prev-button'],
  .ds-pattern-form-builder.ds-engine-modern [data-part='wizard-next-button'] {
    min-block-size: var(--ds-form-builder-touch-target-min, 44px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-pattern-form-builder.ds-engine-modern [data-part='skeleton-bar'] {
    animation: none;
  }
  .ds-pattern-form-builder.ds-engine-modern [data-part='section-content'],
  .ds-pattern-form-builder.ds-engine-modern [data-part='section-chevron'],
  .ds-pattern-form-builder.ds-engine-modern [data-part='section-header'] {
    transition: none;
  }
}

/* ---- forced colors: system colors only. The one documented opt-out is the
        colour swatch — it shows the hex the user actually picked (data, the
