.ds-pattern-page-shell.ds-engine-modern [data-part='subtitle'] {
  max-width: var(--ds-page-header-subtitle-max-width, 72ch);
  text-wrap: pretty;
}

.ds-pattern-page-shell.ds-engine-modern[data-part='root'] [data-part='actions'] {
  min-height: calc(var(--ds-control-height-sm, 32px) + 8px);
  padding: 3px;
  border: 1px solid var(--ds-toolbar-border, var(--ds-color-border-primary));
  border-radius: var(--ds-toolbar-radius, var(--ds-radius-lg));
  background: color-mix(
    in srgb,
    var(--ds-toolbar-control-bg, var(--ds-surface-card)) 88%,
    transparent
  );
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--ds-color-bg-elevated) 90%, transparent),
    0 8px 18px -16px color-mix(in srgb, var(--ds-color-text-primary) 30%, transparent);
  /* Glass is opt-in (default none): a default-ON blur taxed every scroll
     frame; tenants enable it through this channel (cockpit-header PT29
     precedent, Sheet glass contract). */
  backdrop-filter: var(--ds-page-shell-actions-backdrop, none);
}

.ds-pattern-page-shell.ds-engine-modern[data-part='root'] [data-part='header-content'] {
  padding-top: var(--ds-page-shell-section-gap);
  border-top: 1px solid var(--ds-toolbar-divider, var(--ds-color-border-subtle));
}

/* ---- shell-grid background: non-loading root only (main root had it, the loading
        root did not). Invisible until a tenant sets the grid tokens. ---- */
.ds-pattern-page-shell.ds-engine-modern[data-part='root'][data-loading='false'] {
  background-image: repeating-linear-gradient(0deg, var(--ds-shell-grid-line, transparent) 0 1px, transparent 1px var(--ds-shell-grid-size, 0px)), repeating-linear-gradient(90deg, var(--ds-shell-grid-line, transparent) 0 1px, transparent 1px var(--ds-shell-grid-size, 0px));
  background-size: var(--ds-shell-grid-size, 0px) var(--ds-shell-grid-size, 0px);
}

/* ---- breadcrumb: pattern-owned framed-pill grammar (the Breadcrumb P76
        primitive was evaluated; the cockpit-header framed-pill minimal
        contract covers this exact anatomy need, so the pill frame and the
        data-interactive/data-last crumb paint stay pattern-owned). Layout
        drained from the engine's inline styles. ---- */
.ds-pattern-page-shell.ds-engine-modern[data-part='root'] [data-part='breadcrumb'] {
  display: flex;
  align-items: center;
  gap: var(--ds-spacing-2, 8px);
  margin-block-end: var(--ds-spacing-3, 12px);
  width: fit-content;
  max-width: 100%;
  padding: 4px 9px;
  overflow-x: auto;
  border: 1px solid var(--ds-breadcrumb-border, var(--ds-color-border-subtle));
  border-radius: var(--ds-radius-full, 9999px);
  background: var(
    --ds-breadcrumb-bg,
    color-mix(in srgb, var(--ds-color-primary) 4%, var(--ds-surface-card))
  );
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--ds-color-bg-elevated) 86%, transparent);
  scrollbar-width: none;
  font-size: var(--ds-font-size-sm);
  line-height: var(--ds-line-height-body);
}

.ds-pattern-page-shell.ds-engine-modern [data-part='crumb'] {
  font-weight: var(--ds-font-weight-medium, 500);
}
.ds-pattern-page-shell.ds-engine-modern [data-part='crumb'][data-interactive='true'] {
  color: var(--ds-color-text-muted);
  cursor: pointer;
  text-decoration: none;
  transition: color var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out);
}
@media (hover: hover) {
  .ds-pattern-page-shell.ds-engine-modern [data-part='crumb'][data-interactive='true']:hover {
    color: var(--ds-color-text-secondary);
  }
}
.ds-pattern-page-shell.ds-engine-modern [data-part='crumb'][data-interactive='true']:active {
  color: var(--ds-color-text-primary);
}
.ds-pattern-page-shell.ds-engine-modern [data-part='crumb'][data-interactive='false'][data-last='true'] {
  color: var(--ds-color-text-secondary);
  font-weight: var(--ds-font-weight-semibold, 600);
}
.ds-pattern-page-shell.ds-engine-modern [data-part='crumb'][data-interactive='false'][data-last='false'] {
  color: var(--ds-color-text-muted);
}

/* ---- separator ---- */
.ds-pattern-page-shell.ds-engine-modern [data-part='separator'] {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  color: var(--ds-color-text-muted);
  font-size: var(--ds-font-size-xs, 12px);
  user-select: none;
}

/* ---- back button: borderless ghost, highlighted on hover||focus. No painting
        border, so no (0,4,0) chain is needed. The wrapper melts into the lead
        row (drained from the inline display:contents / flexShrink). ---- */
.ds-pattern-page-shell.ds-engine-modern [data-part='back'] {
  display: contents;
}
.ds-pattern-page-shell.ds-engine-modern [data-part='back'] > .rottay-button {
  flex-shrink: 0;
  color: var(--ds-color-text-secondary);
}
@media (hover: hover) {
  .ds-pattern-page-shell.ds-engine-modern [data-part='back'] > .rottay-button:hover {
    background: var(--ds-color-neutral-100);
    color: var(--ds-color-text-primary);
  }
}
.ds-pattern-page-shell.ds-engine-modern [data-part='back'] > .rottay-button:focus {
  background: var(--ds-color-neutral-100);
  color: var(--ds-color-text-primary);
}

/* ---- tab: base (the root chain buys (0,4,0) for the transparent 2px
        underline frame -- transparent is NOT a reset here) + active underline
        + guarded hover (only when not active, matching the JS guard).
        Typography and geometry live here (the engine owns structure/state
        only). ---- */
.ds-pattern-page-shell.ds-engine-modern[data-part='root'] [data-part='tab'] {
  position: relative;
  min-height: var(--ds-tabs-md-height);
  padding: var(--ds-tabs-md-padding);
  color: var(--ds-tab-color, var(--ds-color-text-muted));
  font-size: var(--ds-tabs-md-font-size);
  font-weight: var(--ds-tabs-item-font-weight);
  line-height: var(--ds-line-height-body);
  cursor: pointer;
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--ds-tabs-item-radius, var(--ds-radius-md));
  transition:
    color var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out),
    background var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out),
    border-color var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out),
    box-shadow var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out),
    transform var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out);
}
.ds-pattern-page-shell.ds-engine-modern [data-part='tab'][data-active='true'] {
  color: var(--ds-tab-color-active, var(--ds-color-primary));
  font-weight: var(--ds-tabs-item-font-weight-active);
  background: var(--ds-tabs-active-bg, var(--ds-surface-card));
  border-color: var(--ds-tabs-list-border, var(--ds-color-border-subtle));
  box-shadow: var(--ds-tabs-active-shadow, var(--ds-elevation-1));
  transform: translateY(-1px);
}
@media (hover: hover) {
  .ds-pattern-page-shell.ds-engine-modern [data-part='tab']:hover:not([data-active='true']) {
    color: var(--ds-tab-color-hover, var(--ds-color-text-primary));
    background: var(--ds-tab-bg-hover, var(--ds-color-neutral-50));
    border-color: color-mix(
      in srgb,
      var(--ds-tabs-list-border, var(--ds-color-border-subtle)) 72%,
      transparent
    );
  }
}
.ds-pattern-page-shell.ds-engine-modern [data-part='tab']:active:not([data-active='true']) {
  color: var(--ds-tab-color-hover, var(--ds-color-text-primary));
}
.ds-pattern-page-shell.ds-engine-modern [data-part='tab']:focus-visible {
  outline: none;
  box-shadow: var(--ds-focus-ring, 0 0 0 3px color-mix(in srgb, var(--ds-color-primary) 18%, transparent));
}

/* ---- title / subtitle ---- */
.ds-pattern-page-shell.ds-engine-modern [data-part='title'] {
  margin: 0;
  color: var(--ds-color-text-primary);
  /* W6-A cqi proof consumer: the fluid ramp only resolves against a
     `container-type` ancestor (the page-shell root). At full container width
     this equals the prior static 24px exactly; it steps down toward 20px as
     the shell is squeezed by a sibling rail/chat panel. */
  font-size: var(--ds-font-size-fluid-2xl, 1.5rem);
  font-weight: var(--ds-font-weight-bold);
  line-height: var(--ds-line-height-display);
  letter-spacing: var(--ds-letter-spacing-display);
}
.ds-pattern-page-shell.ds-engine-modern [data-part='subtitle'] {
  margin: var(--ds-spacing-1, 4px) 0 0;
  color: var(--ds-color-text-secondary);
  font-size: var(--ds-font-size-md);
  line-height: var(--ds-line-height-body);
}

/* ---- separators: tab strip and the no-tabs rule (both 1px bottom border).
        Layout drained from the engine's inline styles. ---- */
.ds-pattern-page-shell.ds-engine-modern[data-part='root'] [data-part='tabs'] {
  display: flex;
  align-items: center;
  gap: var(--ds-tabs-gap);
  margin-top: var(--ds-page-shell-section-gap);
  padding: var(--ds-tabs-list-padding, 3px);
  background: var(--ds-tabs-list-bg, var(--ds-surface-inset));
  border: 1px solid var(--ds-tabs-list-border, var(--ds-color-border-subtle));
  border-radius: var(--ds-tabs-list-radius, var(--ds-radius-lg));
  overflow-x: auto;
  box-shadow:
    inset 0 1px 2px color-mix(in srgb, var(--ds-color-text-primary) 5%, transparent),
    0 1px 0 color-mix(in srgb, var(--ds-color-bg-elevated) 80%, transparent);
  scrollbar-width: none;
}
.ds-pattern-page-shell.ds-engine-modern[data-part='root'] [data-part='rule'] {
  margin-top: var(--ds-page-shell-section-gap);
  border-bottom: 1px solid var(--ds-color-border-subtle);
}

/* ---- header layout anatomy (drained from the engine's inline styles) ---- */
.ds-pattern-page-shell.ds-engine-modern [data-part='header-row'] {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--ds-page-shell-section-gap);
}
.ds-pattern-page-shell.ds-engine-modern [data-part='lead'] {
  display: flex;
  flex: 1 1 auto;
  align-items: center;
  gap: var(--ds-page-shell-item-gap);
  min-width: 0;
}
.ds-pattern-page-shell.ds-engine-modern [data-part='titles'] {
  flex: 1 1 auto;
  min-width: 0;
}
.ds-pattern-page-shell.ds-engine-modern [data-part='title-row'] {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--ds-page-shell-item-gap);
}
.ds-pattern-page-shell.ds-engine-modern [data-part='actions'] {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: var(--ds-page-shell-action-gap);
}
.ds-pattern-page-shell.ds-engine-modern [data-part='header-content'] {
  margin-top: var(--ds-page-shell-section-gap);
}
.ds-pattern-page-shell.ds-engine-modern [data-part='content'] {
  padding: var(--ds-page-shell-content-padding);
}

/* ---- loading skeleton: layout frame (drained) + per-block geometry keyed on
        data-block (cockpit-header idiom) + the pulse cadence on the motion
        channel (the retired inline `1.5s` literal) ---- */
.ds-pattern-page-shell.ds-engine-modern[data-part='root'][data-loading='true'] {
  padding: var(--ds-page-shell-header-padding);
}
.ds-pattern-page-shell.ds-engine-modern [data-part='skeleton-group'] {
  display: flex;
  flex-direction: column;
  gap: var(--ds-page-shell-item-gap);
}
.ds-pattern-page-shell.ds-engine-modern [data-part='skeleton-title-row'] {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ds-page-shell-section-gap);
}
.ds-pattern-page-shell.ds-engine-modern [data-part='skeleton-title-copy'] {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: var(--ds-spacing-2, 8px);
  min-width: 0;
}
.ds-pattern-page-shell.ds-engine-modern [data-part='skeleton-action-row'] {
  display: flex;
  gap: var(--ds-page-shell-action-gap);
}
.ds-pattern-page-shell.ds-engine-modern [data-part='skeleton'] {
  border-radius: var(--ds-page-shell-skeleton-radius, var(--ds-radius-sm));
  background: var(--ds-color-neutral-100);
  animation: ds-foundation-pulse var(--ds-motion-attention, 1.5s) ease-in-out infinite;
}
.ds-pattern-page-shell.ds-engine-modern [data-part='skeleton'][data-block='breadcrumb'] {
  inline-size: 180px;
  block-size: 12px;
}
.ds-pattern-page-shell.ds-engine-modern [data-part='skeleton'][data-block='title'] {
  inline-size: 100%;
  max-inline-size: 280px;
  block-size: 28px;
}
.ds-pattern-page-shell.ds-engine-modern [data-part='skeleton'][data-block='subtitle'] {
  inline-size: 200px;
  max-inline-size: 100%;
  block-size: 14px;
}
.ds-pattern-page-shell.ds-engine-modern [data-part='skeleton'][data-block='action-sm'] {
  inline-size: 80px;
  block-size: 32px;
}
.ds-pattern-page-shell.ds-engine-modern [data-part='skeleton'][data-block='action-md'] {
  inline-size: 100px;
  block-size: 32px;
}

@container ds-page (max-width: 640px) {
  .ds-pattern-page-shell.ds-engine-modern [data-part='header-row'] {
    align-items: stretch;
    flex-direction: column;
  }

  .ds-pattern-page-shell.ds-engine-modern [data-part='actions'] {
    width: 100%;
    overflow-x: auto;
  }

  .ds-pattern-page-shell.ds-engine-modern [data-part='actions'] > * {
    flex: 1 0 max-content;
  }

  .ds-pattern-page-shell.ds-engine-modern [data-part='lead'] {
    align-items: flex-start;
  }

  .ds-pattern-page-shell.ds-engine-modern [data-part='header-icon'] {
    --ds-page-header-icon-size: 36px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-pattern-page-shell.ds-engine-modern [data-part='header'],
  .ds-pattern-page-shell.ds-engine-modern [data-part='header-icon'],
  .ds-pattern-page-shell.ds-engine-modern [data-part='tab'],
  .ds-pattern-page-shell.ds-engine-modern [data-part='crumb'] {
    transition: none;
  }

  .ds-pattern-page-shell.ds-engine-modern [data-part='header'],
  .ds-pattern-page-shell.ds-engine-modern [data-part='header']::after {
    animation: none;
  }
}

/* forced-colors: the identity panel's gradients, sheen and shadows are forced
   away, so every frame re-asserts in system colors and the sheen layer is
   removed outright. The ACTIVE tab keeps the system Highlight pair (the tab
   state never reads as colour alone -- aria-selected carries it too); the
   skeleton bars re-assert as GrayText with the pulse stopped; hairlines
   degrade to ButtonText. The back Button is a composed primitive with its
   own forced-colors contract. */
@media (forced-colors: active) {
  .ds-pattern-page-shell.ds-engine-modern[data-part='root'] [data-part='header'] {
    border-color: ButtonText;
    background: Canvas;
    box-shadow: none;
    animation: none;
  }
  .ds-pattern-page-shell.ds-engine-modern[data-part='root'] [data-part='header']::after {
    display: none;
  }
  .ds-pattern-page-shell.ds-engine-modern[data-part='root'] [data-part='header-icon'],
  .ds-pattern-page-shell.ds-engine-modern[data-part='root'] [data-part='actions'],
  .ds-pattern-page-shell.ds-engine-modern[data-part='root'] [data-part='breadcrumb'],
  .ds-pattern-page-shell.ds-engine-modern[data-part='root'] [data-part='tabs'] {
    border-color: ButtonText;
    background: Canvas;
    box-shadow: none;
  }
  .ds-pattern-page-shell.ds-engine-modern[data-part='root'] [data-part='header-icon'] {
    color: ButtonText;
  }
  .ds-pattern-page-shell.ds-engine-modern[data-part='root'] [data-part='header-content'],
  .ds-pattern-page-shell.ds-engine-modern[data-part='root'] [data-part='rule'] {
    border-color: ButtonText;
  }
  .ds-pattern-page-shell.ds-engine-modern [data-part='tab'][data-active='true'] {
    border-color: Highlight;
    background: Highlight;
    color: HighlightText;
    box-shadow: none;
    transform: none;
  }
  .ds-pattern-page-shell.ds-engine-modern [data-part='tab']:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 1px;
    box-shadow: none;
  }
  .ds-pattern-page-shell.ds-engine-modern [data-part='skeleton'] {
    background: GrayText;
    animation: none;
  }
}

@keyframes ds-page-header-arrive {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.995);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes ds-page-header-sheen {
  0%, 42% { background-position: 120% 50%; }
  58%, 100% { background-position: -120% 50%; }
}

}
@layer rottay-engines {
/**
 * Modern WorkbenchHeader skin (WO-SKIN-06 CK-B).
 *
 * LAYER: imported by `facade/entrypoints/base.css` and
 * `facade/entrypoints/styles.css` into `layer(rottay-engines)` (the old
 * "unlayered" note predates the wiring). Caller inline styles still win.
 *
 * SCOPE ROOT is the header's outer `<div>`, carrying the pair
 * `ds-pattern-workbench-header ds-engine-modern` + `data-part='root'`; both the
 * loading early-return and the main render use that same root. Every painted
 * element is a descendant with its own `data-part`.
 *
 * SPECIFICITY (P-48): the Platform-only Rottay artifact ships an unlayered
 * `html[data-tenant]:not([data-theme]):not(.light) *` at (0,3,1) setting
 * `border-color` on every element. A rule painting `border` / `border-color`
 * with a real color (including `transparent`, which is NOT a reset) must reach
 * (0,4,0). Repeating an attribute on one element is forbidden: descendant
 * rules buy the fourth unit from the always-stamped root `data-part`
 * ancestor, and the rule ON the root buys it from `data-loading`, which the
 * engine always stamps ('true'|'false'). `border: none` resets are exempt.
 *
 * Interaction paint that the removed React hover/focus state used to own now
 * lives here: hovers ride the `@media (hover: hover)` guard (house hover
 * law) with unguarded `:active` twins; keyboard focus keeps its unguarded
 * `:focus` rules. QuickActionButton merged `vs.hover` over `vs.base` when
 * `(hovered||focused) && !disabled`; the button is natively `disabled`, so
 * `:hover:not(:disabled), :focus:not(:disabled)` reproduces that gate. SavedViewTab
 * tracks `onFocus`/`onBlur` in addition to hover (a keyboard-focus affordance the
 * page-shell tab deliberately lacks), so it keys on `:hover` AND `:focus`.
 *
 * GLASS: `backdrop-filter` is opt-in through the
 * `--ds-workbench-header-actions-backdrop` channel (default `none`) — a
 * default-ON blur taxes every scroll frame and is not the sanctioned glass
 * contract (same fix as cockpit-header PT29; Sheet glass precedent).
 *
 * OWNERSHIP (R2+R3): the engine stamps anatomy + state only; this file owns
 * 100% of layout and paint — typography, tab geometry, skeleton geometry and
 * the pulse animation included. The skeleton blocks share one `data-part` but
 * differ in geometry, so each block carries a `data-size` attribute and, where
 * it deviates from the default, its radius on the sanctioned inline
 * `--ds-workbench-header-skeleton-radius` custom-property data channel
 * (uncounted). The only remaining inline style in the engine is the caller's
 * own `style` prop on the root.
 */

/* ---- root: card surface + bottom border (both loading and main roots) ---- */
.ds-pattern-workbench-header.ds-engine-modern[data-part='root'] {
  --ds-workbench-header-padding: clamp(var(--ds-spacing-4, 16px), 2vw, var(--ds-spacing-6, 24px));
  --ds-workbench-header-section-gap: var(--ds-spacing-4, 16px);
  --ds-workbench-header-item-gap: var(--ds-workspace-card-gap, var(--ds-spacing-3, 12px));
  --ds-workbench-header-action-gap: var(--ds-spacing-2, 8px);
  overflow: hidden;
  background: var(
    --ds-workbench-header-bg,
    var(
      --ds-card-header-bg,
      linear-gradient(
        112deg,
        color-mix(in srgb, var(--ds-color-primary) 7%, var(--ds-surface-card)),
        var(--ds-surface-card) 56%,
        var(--ds-surface-panel)
      )
    )
  );
  background-position: 0% 50%;
  background-size: 180% 180%;
  border-radius: var(--ds-workspace-card-radius, var(--ds-radius-lg));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--ds-color-bg-elevated) 88%, transparent),
    var(--ds-workspace-card-shadow, var(--ds-elevation-1));
  transition:
    background-position var(--ds-motion-slow, 320ms) var(--ds-motion-ease-out, ease-out),
    border-color var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out),
    box-shadow var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out);
  animation: ds-workbench-header-arrive var(--ds-motion-calm)
    var(--ds-motion-ease-out, ease-out) both;
  container-type: inline-size;
  container-name: ds-workbench-header;
  /* Layout migrated from the engine (R2+R3). */
  padding: var(--ds-workbench-header-padding);
}
.ds-pattern-workbench-header.ds-engine-modern[data-part='root'][data-loading] {
  border: 1px solid var(--ds-workspace-card-border, var(--ds-color-border));
}
.ds-pattern-workbench-header.ds-engine-modern[data-part='root']:active {
  background-position: 100% 50%;
  border-color: var(--ds-workspace-card-border-hover, var(--ds-workspace-card-border, var(--ds-color-border)));
  box-shadow: var(--ds-workspace-card-shadow-hover, var(--ds-elevation-2));
}

.ds-pattern-workbench-header.ds-engine-modern[data-part='root'] [data-part='header-icon'] {
  display: inline-grid;
  flex: 0 0 auto;
  width: var(--ds-workbench-header-icon-size, 40px);
  height: var(--ds-workbench-header-icon-size, 40px);
  place-items: center;
  border: 1px solid var(--ds-workspace-card-icon-border, var(--ds-color-border-primary));
  border-radius: var(--ds-radius-lg);
  background: var(--ds-workspace-card-icon-bg, var(--ds-surface-card));
  color: var(--ds-workspace-card-icon-color, var(--ds-color-primary));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--ds-color-bg-elevated) 90%, transparent),
    0 8px 18px -14px color-mix(in srgb, currentColor 58%, transparent);
  transition: transform var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out);
}
.ds-pattern-workbench-header.ds-engine-modern[data-part='root']:active [data-part='header-icon'] {
  transform: translateY(-1px) scale(1.025);
}

.ds-pattern-workbench-header.ds-engine-modern [data-part='eyebrow'] {
  margin-bottom: 4px;
  color: var(--ds-color-text-muted);
