@keyframes ds-workbench-header-arrive {
  from { opacity: 0; transform: translateY(8px) scale(0.995); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

/* ---- hover is pointer-fine only; every treatment keeps an unguarded
        `:active` twin beside its base rule (touch press feedback matches),
        and keyboard focus keeps its own unguarded `:focus` rules. ---- */
@media (hover: hover) {
  .ds-pattern-workbench-header.ds-engine-modern[data-part='root']:hover {
    background-position: 100% 50%;
    border-color: var(--ds-workspace-card-border-hover, var(--ds-workspace-card-border, var(--ds-color-border)));
    box-shadow: var(--ds-workspace-card-shadow-hover, var(--ds-elevation-2));
  }

  .ds-pattern-workbench-header.ds-engine-modern[data-part='root']:hover [data-part='header-icon'] {
    transform: translateY(-1px) scale(1.025);
  }

  .ds-pattern-workbench-header.ds-engine-modern [data-part='action'][data-variant='primary'] > .rottay-button:hover:not(:disabled) {
    background: var(--ds-color-primary-600);
    border-color: var(--ds-color-primary-600);
    box-shadow: var(--ds-elevation-2);
  }

  .ds-pattern-workbench-header.ds-engine-modern [data-part='action'][data-variant='danger'] > .rottay-button:hover:not(:disabled) {
    background: var(--ds-color-error-50);
    border-color: var(--ds-color-error-300);
  }

  .ds-pattern-workbench-header.ds-engine-modern [data-part='action'][data-variant='default'] > .rottay-button:hover:not(:disabled) {
    background: var(--ds-color-neutral-50);
    color: var(--ds-color-text-primary);
    border-color: var(--ds-color-neutral-300);
  }

  .ds-pattern-workbench-header.ds-engine-modern [data-part='tab']:hover:not([data-active='true']) {
    color: var(--ds-tab-color-hover, var(--ds-color-text-primary));
    background: var(--ds-tab-bg-hover, var(--ds-color-neutral-50));
    border-color: color-mix(in srgb, var(--ds-tabs-list-border, var(--ds-color-border)) 72%, transparent);
  }
}

/* ---- forced colors: the pattern-owned frames read as ButtonText; the
        keyboard-focused tab gets a Highlight outline; the active tab already
        reads by shape (frame + weight + lift), the exception badge by
        icon + count. ---- */
@media (forced-colors: active) {
  .ds-pattern-workbench-header.ds-engine-modern[data-part='root'][data-loading],
  .ds-pattern-workbench-header.ds-engine-modern[data-part='root'] [data-part='header-icon'],
  .ds-pattern-workbench-header.ds-engine-modern[data-part='root'] [data-part='actions'],
  .ds-pattern-workbench-header.ds-engine-modern[data-part='root'] [data-part='tabs'],
  .ds-pattern-workbench-header.ds-engine-modern [data-part='exception'],
  .ds-pattern-workbench-header.ds-engine-modern [data-part='tab'][data-active='true'] {
    border-color: ButtonText;
  }

  .ds-pattern-workbench-header.ds-engine-modern [data-part='tab']:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 1px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-pattern-workbench-header.ds-engine-modern[data-part='root'],
  .ds-pattern-workbench-header.ds-engine-modern [data-part='header-icon'],
  .ds-pattern-workbench-header.ds-engine-modern [data-part='tab'],
  .ds-pattern-workbench-header.ds-engine-modern [data-part='skeleton'] {
    animation: none;
    transition: none;
  }
}

}
@layer rottay-engines {
/**
 * Modern CommandPalette skin.
 *
 * LAYERING: imported by `facade/entrypoints/base.css` into `layer(
 * rottay-engines)` — this file does not control its own layering (the older
 * "deliberately unlayered" note predates that wiring). Caller inline `style`
 * still wins over every rule here.
 *
 * SCOPE ROOT: the palette's outer `<div>` carries
 * `ds-pattern-command-palette ds-engine-modern` + `data-part='root'` (two
 * distinct classes + one attribute, (0,3,0); repetition is prohibited — the
 * old P-48 border-color floor is bought from this scope + a single target
 * part, never a repeated attribute). NOT portaled: the dialog is a
 * `position:fixed` DOM descendant of the tenant-scoped root, so descendant
 * selectors reach it.
 *
 * COMPOSITION: the search box is the certified Input primitive, shortcut
 * hints are the certified Kbd, the argument chip wraps the certified Tag and
 * the empty state wraps the certified Empty — those primitives own their
 * paint (the pre-composition kbd/chip/empty color rules were deleted with
 * the raw elements). This file owns the overlay chrome: root/backdrop/
 * dialog geometry, the listbox scroll frame, row layout + keyboard/pointer
 * states, section labels, the argument panel and the footer hairline.
 *
 * Z-INDEX: the arbitrary Tailwind `z-50` is re-mapped to the sanctioned
 * `--ds-z-modal` rung — a command palette stacks with modal overlays, not
 * below them.
 *
 * INTERACTION: the keyboard-active row keys on `[data-active='true']`;
 * pointer hover is hover-capable-only (`@media (hover: hover)`) AND keyed on
 * `:not([data-active='true'])` so it never repaints the keyboard-selected
 * row — the exact `activeIndex !== idx` guard the removed onMouseEnter/Leave
 * writes had. In forced colors the active row re-expresses as
 * Highlight/HighlightText so the keyboard cursor stays visible.
 */

/* ---- root: fixed top-anchored overlay frame (was Tailwind
        `fixed inset-0 z-50 flex items-start justify-center pt-[15vh]`) ---- */
.ds-pattern-command-palette.ds-engine-modern[data-part='root'] {
  position: fixed;
  inset: 0;
  z-index: var(--ds-z-modal, 1500);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-block-start: 15vh;
  padding-inline: var(--ds-spacing-3, 12px);
  container-type: inline-size;
}

/* backdrop: scrim + sanctioned glass layer. Frost tint + backdrop blur scale
   with --ds-effect-intensity, collapsing to a plain scrim at 0; glass is
   sanctioned on overlay backdrops only (spec section 5). */
.ds-pattern-command-palette.ds-engine-modern [data-part='backdrop'] {
  position: absolute;
  inset: 0;
  background-color: var(--ds-color-bg-overlay);
  background-image: linear-gradient(var(--ds-glass-scrim-tint), var(--ds-glass-scrim-tint));
  backdrop-filter: var(--ds-glass-backdrop-filter);
  -webkit-backdrop-filter: var(--ds-glass-backdrop-filter);
}

/* ---- dialog card (was `relative rounded-xl w-full max-w-lg
        overflow-hidden`) ---- */
.ds-pattern-command-palette.ds-engine-modern [data-part='dialog'] {
  position: relative;
  inline-size: 100%;
  max-inline-size: 32rem;
  overflow: hidden;
  border-radius: var(--ds-radius-xl);
  background: var(--ds-surface-card);
  box-shadow: var(--ds-elevation-2);
  color: var(--ds-color-text-primary);
}

/* ---- search row: always a flex line so the argument chip can sit beside
        the composed Input (which owns its own paint). ---- */
.ds-pattern-command-palette.ds-engine-modern[data-part='root'] [data-part='search'] {
  display: flex;
  align-items: center;
  gap: var(--ds-spacing-2, 8px);
  padding: var(--ds-spacing-3, 12px);
  border-bottom: 1px solid var(--ds-color-border);
}
.ds-pattern-command-palette.ds-engine-modern [data-part='search'] > :last-child {
  flex: 1 1 auto;
  min-inline-size: 0;
}

/* ---- listbox: internal scroll with the lane's thin, ink-derived bar
        (ScrollArea is not composed — see the engine header). ---- */
.ds-pattern-command-palette.ds-engine-modern [data-part='list'] {
  overflow-y: auto;
  padding-block: var(--ds-spacing-2, 8px);
  scrollbar-color: color-mix(in srgb, var(--ds-color-primary) 24%, var(--ds-color-border)) transparent;
  scrollbar-width: thin;
}

/* ---- sections: recent block + group labels (geometry transcribed from the
        retired menuSectionTitleStyle spread) ---- */
.ds-pattern-command-palette.ds-engine-modern [data-part='recent'] {
  padding-inline: var(--ds-spacing-3, 12px);
  padding-block-end: var(--ds-spacing-2, 8px);
}
.ds-pattern-command-palette.ds-engine-modern [data-part='section-label'],
.ds-pattern-command-palette.ds-engine-modern [data-part='group-label'] {
  padding-block: 6px 4px;
  padding-inline: var(--ds-spacing-3, 12px);
  margin-block-end: var(--ds-spacing-1, 4px);
  color: var(--ds-color-text-muted);
  font-size: var(--ds-font-size-xs, 12px);
  font-weight: 500;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.ds-pattern-command-palette.ds-engine-modern [data-part='group-label'] {
  padding-block: var(--ds-spacing-3, 12px) var(--ds-spacing-1, 4px);
  padding-inline: var(--ds-spacing-5, 20px);
  margin-block-end: 0;
  /* a live per-tenant override channel (fallback: muted) */
  color: var(--ds-search-category-color, var(--ds-color-text-muted));
}

/* ---- option rows: keyboard-active and pointer-hover-while-not-active both
        resolve to the inset surface; hover is hover-capable-only and the
        `:not([data-active='true'])` guard keeps a hovered pointer off the
        keyboard-selected row (a plain :hover would light two rows at once). ---- */
.ds-pattern-command-palette.ds-engine-modern [data-part='item'] {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ds-spacing-2, 8px);
  padding-block: var(--ds-spacing-2, 8px);
  padding-inline: var(--ds-spacing-3, 12px);
  border-radius: var(--ds-radius-lg);
  cursor: pointer;
}
.ds-pattern-command-palette.ds-engine-modern [data-part='recent'] [data-part='item'] {
  padding-inline: var(--ds-spacing-3, 12px);
}
.ds-pattern-command-palette.ds-engine-modern [data-part='item'][aria-disabled='true'] {
  cursor: not-allowed;
  opacity: 0.5;
}
.ds-pattern-command-palette.ds-engine-modern [data-part='item'][data-active='true'] {
  background: var(--ds-surface-inset);
}
@media (hover: hover) {
  .ds-pattern-command-palette.ds-engine-modern [data-part='item']:hover:not([data-active='true']) {
    background: var(--ds-surface-inset);
  }
}

/* ---- row content: icon + text column, ellipsis-safe ---- */
.ds-pattern-command-palette.ds-engine-modern [data-part='item-main'] {
  display: flex;
  align-items: center;
  gap: var(--ds-spacing-2, 8px);
