.ds-pattern-workspace-switcher.ds-engine-modern[data-part='root'] [data-part='search'] {
  border-bottom: 1px solid var(--ds-color-border);
}
.ds-pattern-workspace-switcher.ds-engine-modern [data-part='empty'] {
  display: flex;
  justify-content: center;
  padding-block: var(--ds-spacing-4, 16px);
}

/* ---- panel + positioning (logical: sidebar opens inline-end, topbar below) ---- */
.ds-pattern-workspace-switcher.ds-engine-modern [data-part='panel'] {
  position: absolute;
  z-index: 50;
  inline-size: var(--ds-workspace-switcher-panel-width, 18rem);
  overflow: hidden;
}

.ds-pattern-workspace-switcher.ds-engine-modern[data-part='root'][data-position='sidebar'] [data-part='panel'] {
  inset-block-start: 0;
  inset-inline-start: 100%;
  margin-inline-start: var(--ds-workspace-switcher-panel-gap, 8px);
}

.ds-pattern-workspace-switcher.ds-engine-modern[data-part='root']:not([data-position='sidebar']) [data-part='panel'] {
  inset-block-start: 100%;
  inset-inline-start: 0;
  margin-block-start: var(--ds-workspace-switcher-panel-gap-block, 4px);
}

.ds-pattern-workspace-switcher.ds-engine-modern [data-part='header'] {
  padding-block: 6px;
  padding-inline: 12px;
}

/* ---- list + option rows ---- */
.ds-pattern-workspace-switcher.ds-engine-modern [data-part='list'] {
  max-block-size: var(--ds-workspace-switcher-list-max-height, 16rem);
  padding-block: 4px;
  overflow-y: auto;
}

.ds-pattern-workspace-switcher.ds-engine-modern [data-part='item'] {
  display: flex;
  align-items: center;
  gap: var(--ds-workspace-switcher-item-gap, 12px);
  padding-block: 8px;
  padding-inline: 12px;
  cursor: pointer;
  transition: background var(--ds-motion-fast) var(--ds-motion-ease-out);
}

/* Hover reveals only where hovering is a real input mode (hover law); touch
   gets the persistent gear via the (hover: none) block below. The keyboard
   reveals (virtual focus + own focus ring) are NEVER hover-gated. */
@media (hover: hover) {
  .ds-pattern-workspace-switcher.ds-engine-modern [data-part='item']:hover:not([data-active='true']) {
    background: var(--ds-workspace-switcher-item-bg-hover, var(--ds-surface-highlight));
  }

  .ds-pattern-workspace-switcher.ds-engine-modern [data-part='item']:hover [data-part='settings'] {
    opacity: 1;
  }
}

.ds-pattern-workspace-switcher.ds-engine-modern [data-part='item-copy'] {
  display: flex;
  flex: 1 1 auto;
  min-inline-size: 0;
  flex-direction: column;
}

.ds-pattern-workspace-switcher.ds-engine-modern [data-part='item-title-row'] {
  display: flex;
  align-items: center;
  gap: 6px;
}

.ds-pattern-workspace-switcher.ds-engine-modern [data-part='item-name'] {
  overflow: hidden;
  font-size: var(--ds-font-size-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ds-pattern-workspace-switcher.ds-engine-modern [data-part='item-name'][data-active='true'] {
  font-weight: var(--ds-font-weight-semibold, 600);
}

/* Secondary metadata keeps a LEGIBLE muted ink instead of the drained
   `opacity-50` composite (the steps family's axe color-contrast law). */
.ds-pattern-workspace-switcher.ds-engine-modern [data-part='item-meta'] {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--ds-workspace-switcher-meta-color, var(--ds-color-text-muted));
  font-size: var(--ds-font-size-xs);
}

.ds-pattern-workspace-switcher.ds-engine-modern [data-part='item-plan'] {
  text-transform: capitalize;
}

.ds-pattern-workspace-switcher.ds-engine-modern [data-part='item-online'] {
  display: flex;
  align-items: center;
  gap: 4px;
  font-variant-numeric: var(--ds-workspace-switcher-meta-numeric, tabular-nums);
}

.ds-pattern-workspace-switcher.ds-engine-modern [data-part='online-dot'] {
  display: inline-block;
  inline-size: 6px;
  block-size: 6px;
  border-radius: var(--ds-radius-full, 9999px);
}

.ds-pattern-workspace-switcher.ds-engine-modern [data-part='item-controls'] {
  display: flex;
  align-items: center;
  gap: 6px;
}

/* ---- settings gear: 24px box, revealed on row hover / virtual focus / own
        focus (the reveal was an inline opacity ternary). ---- */
.ds-pattern-workspace-switcher.ds-engine-modern [data-part='settings'] {
  inline-size: 24px;
  block-size: 24px;
  padding: 0;
  font-size: var(--ds-font-size-xs);
  cursor: pointer;
  opacity: 0;
  transition: opacity var(--ds-motion-fast) var(--ds-motion-ease-out);
}

/* Keyboard reveals (virtual focus + own focus ring) -- never hover-gated. */
.ds-pattern-workspace-switcher.ds-engine-modern [data-part='settings'][data-focused='true'],
.ds-pattern-workspace-switcher.ds-engine-modern [data-part='settings']:focus-visible {
  opacity: 1;
}

/* ---- create row + current user ---- */
.ds-pattern-workspace-switcher.ds-engine-modern [data-part='create-row'] {
  padding-block: 8px;
  padding-inline: 12px;
}

.ds-pattern-workspace-switcher.ds-engine-modern [data-part='create'] {
  gap: 4px;
  inline-size: 100%;
  block-size: 32px;
  padding-block: 0;
  padding-inline: 12px;
  font-size: var(--ds-font-size-sm);
  cursor: pointer;
}

.ds-pattern-workspace-switcher.ds-engine-modern [data-part='current-user'] {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-block: 8px;
  padding-inline: 12px;
}

.ds-pattern-workspace-switcher.ds-engine-modern [data-part='current-user-copy'] {
  display: flex;
  flex: 1 1 auto;
  min-inline-size: 0;
  flex-direction: column;
}

.ds-pattern-workspace-switcher.ds-engine-modern [data-part='current-user-name'] {
  overflow: hidden;
  font-size: var(--ds-font-size-xs);
  font-weight: var(--ds-font-weight-medium, 500);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ds-pattern-workspace-switcher.ds-engine-modern [data-part='current-user-email'] {
  overflow: hidden;
  color: var(--ds-workspace-switcher-meta-color, var(--ds-color-text-muted));
  font-size: var(--ds-font-size-xs);
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---- focus rings for the three composed buttons ---- */
.ds-pattern-workspace-switcher.ds-engine-modern [data-part='trigger']:focus-visible,
.ds-pattern-workspace-switcher.ds-engine-modern [data-part='settings']:focus-visible,
.ds-pattern-workspace-switcher.ds-engine-modern [data-part='create']:focus-visible {
  outline: var(--ds-focus-ring-width, 2px) solid var(--ds-focus-ring-color, var(--ds-color-primary));
  outline-offset: var(--ds-focus-ring-offset, 2px);
}

/* ---- coarse pointers: 44px floors; the gear grows a transparent hit area
        (and is always visible on touch, where there is no hover). ---- */
@media (hover: none), (pointer: coarse) {
  .ds-pattern-workspace-switcher.ds-engine-modern [data-part='trigger'],
  .ds-pattern-workspace-switcher.ds-engine-modern [data-part='item'],
  .ds-pattern-workspace-switcher.ds-engine-modern [data-part='create'] {
    min-block-size: var(--ds-workspace-switcher-touch-target-min, 44px);
  }

  .ds-pattern-workspace-switcher.ds-engine-modern [data-part='settings'] {
    position: relative;
    opacity: 1;
  }

  .ds-pattern-workspace-switcher.ds-engine-modern [data-part='settings']::after {
    content: '';
    position: absolute;
    inset: -10px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-pattern-workspace-switcher.ds-engine-modern [data-part='item'],
  .ds-pattern-workspace-switcher.ds-engine-modern [data-part='settings'] {
    transition: none;
  }
}

/* forced-colors: shadows, tints and the reveal opacity are forced away. The
   panel re-frames in system colors; hairlines degrade to ButtonText; the
   ACTIVE row keeps the system Highlight outline (selection never reads as
   colour alone -- the check icon and the semibold name also survive); the
   virtually-focused row keeps a ButtonText outline; the settings gear is
   always visible (its hover reveal is meaningless under forced colours);
   the online dot keeps a system mark (the count carries the info).
   Composed primitives (Button, Badge, Avatar, Input, Empty) own their own
   forced-colors contracts. */
@media (forced-colors: active) {
  .ds-pattern-workspace-switcher.ds-engine-modern[data-part='root'] [data-part='panel'] {
    border-color: ButtonText;
    background: Canvas;
    box-shadow: none;
  }
  .ds-pattern-workspace-switcher.ds-engine-modern[data-part='root'] [data-part='header'],
  .ds-pattern-workspace-switcher.ds-engine-modern[data-part='root'] [data-part='search'],
  .ds-pattern-workspace-switcher.ds-engine-modern[data-part='root'] [data-part='divider'] {
    border-color: ButtonText;
  }
  .ds-pattern-workspace-switcher.ds-engine-modern [data-part='item'][data-active='true'] {
    outline: 2px solid Highlight;
    outline-offset: -2px;
    background: Canvas;
    box-shadow: none;
  }
  .ds-pattern-workspace-switcher.ds-engine-modern [data-part='item'][data-focused='true'] {
    outline: 1px solid ButtonText;
    outline-offset: -1px;
    background: Canvas;
  }
  .ds-pattern-workspace-switcher.ds-engine-modern [data-part='check'] {
    color: CanvasText;
  }
  .ds-pattern-workspace-switcher.ds-engine-modern [data-part='online-dot'] {
    background: ButtonText;
  }
  .ds-pattern-workspace-switcher.ds-engine-modern [data-part='settings'] {
    opacity: 1;
  }
  .ds-pattern-workspace-switcher.ds-engine-modern[data-part='root'] [data-part='create'] {
    border-color: ButtonText;
  }
}

}
@layer rottay-engines {
/**
 * Modern ShortcutsOverlay skin.
 *
 * LAYERING: imported by `facade/entrypoints/base.css` into `layer(
 * rottay-engines)` — this file does not control its own layering (the older
 * "deliberately unlayered" note predates that wiring). Caller inline `style`
 * still wins over every rule here.
 *
 * SCOPE ROOT: the overlay's outer `<div>` carries
 * `ds-pattern-shortcuts-overlay ds-engine-modern` + `data-part='root'` (two
 * distinct classes + one attribute, (0,3,0); repetition is prohibited — the
 * old P-48 border-color floor is bought from this scope + a single target
 * part, never a repeated attribute). NOT portaled: the dialog is a
 * `position:fixed` DOM descendant of the tenant-scoped root.
 *
 * COMPOSITION: the close control is the certified Button, the search box
 * the certified Input, key caps the certified Kbd, the scroll frame the
 * certified ScrollArea (its own skin owns the scrollbar), and the empty
 * state the certified Empty — those primitives own their paint (the
 * pre-composition kbd/close/input/empty color rules were deleted with the
 * raw elements). This file owns only the overlay chrome: root/backdrop/
 * dialog geometry, header/search/footer rhythm + hairlines, category
 * hierarchy and row layout.
 *
 * Z-INDEX: the arbitrary Tailwind `z-50` is re-mapped to the sanctioned
 * `--ds-z-modal` rung — an overlay stacks with modal layers, not below them.
 */

/* ---- root: fixed top-anchored overlay frame (was Tailwind
        `fixed inset-0 z-50 flex items-start justify-center pt-[10vh]`) ---- */
.ds-pattern-shortcuts-overlay.ds-engine-modern[data-part='root'] {
  position: fixed;
  inset: 0;
  z-index: var(--ds-z-modal, 1500);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-block-start: 10vh;
  padding-inline: var(--ds-spacing-3, 12px);
  container-type: inline-size;
}

.ds-pattern-shortcuts-overlay.ds-engine-modern [data-part='backdrop'] {
  position: absolute;
  inset: 0;
  background: var(--ds-color-bg-overlay);
}

/* ---- dialog card (was `relative rounded-xl w-full max-w-lg
        overflow-hidden`) ---- */
.ds-pattern-shortcuts-overlay.ds-engine-modern [data-part='dialog'] {
  position: relative;
  inline-size: 100%;
  max-inline-size: 32rem;
  overflow: hidden;
  border-radius: var(--ds-radius-xl);
  background: var(--ds-surface-card);
  box-shadow: var(--ds-elevation-3);
  color: var(--ds-color-text-primary);
}

/* ---- header: title + composed close Button over a quiet hairline ---- */
.ds-pattern-shortcuts-overlay.ds-engine-modern[data-part='root'] [data-part='header'] {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ds-spacing-3, 12px);
  padding-block: var(--ds-spacing-3, 12px);
  padding-inline: var(--ds-spacing-5, 20px);
  border-bottom: 1px solid var(--ds-color-border);
}
.ds-pattern-shortcuts-overlay.ds-engine-modern [data-part='title'] {
  margin: 0;
  color: var(--ds-color-text-primary);
  font-size: var(--ds-font-size-base, 16px);
  font-weight: var(--ds-font-weight-semibold, 600);
}

/* ---- search row (the composed Input owns its paint + focus ring) ---- */
.ds-pattern-shortcuts-overlay.ds-engine-modern[data-part='root'] [data-part='search'] {
  padding-block: var(--ds-spacing-2, 8px);
  padding-inline: var(--ds-spacing-5, 20px);
  border-bottom: 1px solid var(--ds-color-border);
}

/* ---- list rhythm (the certified ScrollArea owns the scroll frame) ---- */
.ds-pattern-shortcuts-overlay.ds-engine-modern [data-part='list'] {
  padding-block: var(--ds-spacing-2, 8px);
}

/* ---- category groups: quiet uppercase label, hairline-free ---- */
.ds-pattern-shortcuts-overlay.ds-engine-modern [data-part='group'] {
  padding-block: var(--ds-spacing-1, 4px);
}
.ds-pattern-shortcuts-overlay.ds-engine-modern [data-part='category-row'] {
  padding-block: var(--ds-spacing-1, 4px);
  padding-inline: var(--ds-spacing-5, 20px);
}
.ds-pattern-shortcuts-overlay.ds-engine-modern [data-part='category-label'] {
  color: var(--ds-color-text-secondary);
  font-size: var(--ds-font-size-xs, 12px);
  font-weight: var(--ds-font-weight-semibold, 600);
  letter-spacing: var(--ds-letter-spacing-wide, 0.025em);
  text-transform: uppercase;
}

/* ---- shortcut rows: description left, chord right ---- */
.ds-pattern-shortcuts-overlay.ds-engine-modern [data-part='item'] {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ds-spacing-3, 12px);
  padding-block: 6px;
  padding-inline: var(--ds-spacing-5, 20px);
}
.ds-pattern-shortcuts-overlay.ds-engine-modern [data-part='description'] {
  min-inline-size: 0;
  color: var(--ds-color-text-primary);
  font-size: var(--ds-font-size-sm, 14px);
}

/* ---- chord: caps separated by a consistent gap (dir="ltr" is stamped by
        the engine — key names never translate nor reorder). The composed
        Kbd owns the key-cap paint; the wrapper keeps only geometry. ---- */
.ds-pattern-shortcuts-overlay.ds-engine-modern [data-part='chord'] {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: var(--ds-spacing-1, 4px);
}
.ds-pattern-shortcuts-overlay.ds-engine-modern [data-part='kbd'] {
  display: inline-flex;
}

/* ---- empty state: rhythm only — the composed Empty owns its paint ---- */
.ds-pattern-shortcuts-overlay.ds-engine-modern [data-part='empty'] {
  padding-block: var(--ds-spacing-8, 32px);
}

/* ---- footer (caller slot; the pattern owns rhythm + hairline) ---- */
.ds-pattern-shortcuts-overlay.ds-engine-modern [data-part='footer'] {
  padding-block: var(--ds-spacing-2, 8px);
  padding-inline: var(--ds-spacing-5, 20px);
  color: var(--ds-color-text-secondary);
  font-size: var(--ds-font-size-xs, 12px);
}
.ds-pattern-shortcuts-overlay.ds-engine-modern[data-part='root'] [data-part='footer'] {
  border-top: 1px solid var(--ds-color-border);
}

/* ---- narrow overlay: full-width top sheet with a smaller top offset ---- */
@container (inline-size < 40rem) {
  .ds-pattern-shortcuts-overlay.ds-engine-modern[data-part='root'] {
    padding-block-start: var(--ds-spacing-8, 32px);
  }
  .ds-pattern-shortcuts-overlay.ds-engine-modern [data-part='dialog'] {
    max-inline-size: 100%;
  }
}

/* ---- coarse pointers: the close control meets the physical 44px floor ---- */
@media (pointer: coarse) {
  .ds-pattern-shortcuts-overlay.ds-engine-modern [data-part='close'] {
    min-inline-size: 44px;
    min-block-size: 44px;
  }
}

/* ---- forced colors: system colors only. The dialog gains a real frame
        (elevation dies in forced colors), hairlines re-express as
        ButtonText, and the category hierarchy flattens to GrayText. The
        composed Button/Input/Kbd/ScrollArea/Empty own their own
        forced-colors behavior — no opt-out anywhere. ---- */
@media (forced-colors: active) {
  .ds-pattern-shortcuts-overlay.ds-engine-modern [data-part='dialog'] {
    border: 1px solid ButtonText;
    box-shadow: none;
  }

  .ds-pattern-shortcuts-overlay.ds-engine-modern[data-part='root'] [data-part='header'],
  .ds-pattern-shortcuts-overlay.ds-engine-modern[data-part='root'] [data-part='search'],
  .ds-pattern-shortcuts-overlay.ds-engine-modern[data-part='root'] [data-part='footer'] {
    border-color: ButtonText;
  }

  .ds-pattern-shortcuts-overlay.ds-engine-modern [data-part='category-label'],
  .ds-pattern-shortcuts-overlay.ds-engine-modern [data-part='footer'] {
    color: GrayText;
  }
}

}
@layer rottay-engines {
/**
 * LocaleSwitcher — Modern engine skin.
 *
 * LAYER: imported by `facade/entrypoints/base.css` and
 * `facade/entrypoints/styles.css` into `layer(rottay-engines)` (the old
 * "unlayered" note predates the wiring). Caller inline styles still win.
 *
 * SCOPE ROOT is the outer `<div>` carrying `ds-pattern-locale-switcher
 * ds-engine-modern` + `data-part='root'` (+ `data-loading`). The engine
 * stamps data-parts only; ALL geometry and paint live here (the old inline
 * size maps, the panel's popup object and the per-option style literals are
 * drained into the rules below, values transcribed verbatim; z-index moved
 * from an arbitrary 50 to the token scale).
 *
 * SPECIFICITY (P-48): a rule that paints a border COLOR must reach (0,4,0)
 * to beat the tenant's unlayered `…*` border-color floor at (0,3,1) — here
 * through the always-stamped root `data-part` ancestor; repeating an
 * attribute on one element is forbidden. `border: none` resets carry no
 * color and stay at (0,3,0). Non-border paint wins at (0,3,0).
 *
 * KEYBOARD / HOVER: the option's focus model is APG activedescendant — the
 * engine moves `data-focused` with both pointer and keys, so the background
 * rule keyed on it already serves every input mode (no `:hover` selector is
 * needed on options). The trigger is a plain button: its hover rides the
 * (hover: hover) guard with an unguarded `:active` twin.
 *
 * The option's three-way background was `isFocused ? hoverBg : isActive ?
 * insetBg : transparent`, so focus outranks active: the [data-focused] rule is
 * ordered AFTER [data-active] so it wins at equal specificity when a row is
 * both. Modern's focus/active values genuinely differ (hoverBg carries a
 * fallback, insetBg does not) — the divergence is preserved, not normalized
 * (rustic collapses both to one token; that asymmetry is intentional).
 */

/* ---- root geometry (drained from the engine's inline wrapper) ---- */
.ds-pattern-locale-switcher.ds-engine-modern[data-part='root'] {
  position: relative;
  display: inline-block;
}
.ds-pattern-locale-switcher.ds-engine-modern[data-part='root'][data-loading='true'] {
  cursor: progress;
}

/* ---- trigger ---- */
.ds-pattern-locale-switcher.ds-engine-modern [data-part='trigger'] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding-block: 0;
  padding-inline: var(--ds-spacing-2, 8px);
  border-radius: var(--ds-radius-md);
  background: transparent;
  color: var(--ds-color-text-primary);
  font-family: inherit;
  font-size: var(--ds-font-size-sm, 14px);
  line-height: 1;
  block-size: 32px;
  cursor: pointer;
  transition: border-color var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out),
    background var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out);
}
.ds-pattern-locale-switcher.ds-engine-modern [data-part='trigger'][data-size='sm'] {
  padding-inline: var(--ds-spacing-2, 8px);
  block-size: 28px;
  font-size: var(--ds-font-size-sm);
}
.ds-pattern-locale-switcher.ds-engine-modern[data-part='root'] [data-part='trigger'] {
  border: 1px solid var(--ds-color-border-subtle, var(--ds-color-border));
}
.ds-pattern-locale-switcher.ds-engine-modern [data-part='trigger']:focus-visible {
  outline: none;
  box-shadow: var(
    --ds-shadow-focus-ring,
    0 0 0 3px color-mix(in srgb, var(--ds-color-primary) 24%, transparent)
  );
}
.ds-pattern-locale-switcher.ds-engine-modern [data-part='trigger']:active {
  background: var(--ds-surface-highlight);
}
@media (hover: hover) {
  .ds-pattern-locale-switcher.ds-engine-modern [data-part='trigger']:hover {
    background: var(--ds-surface-highlight);
  }
}
.ds-pattern-locale-switcher.ds-engine-modern [data-part='trigger'] > svg {
  opacity: 0.5;
  flex-shrink: 0;
}

/* ---- flag glyph (emoji; geometry only) ---- */
.ds-pattern-locale-switcher.ds-engine-modern [data-part='flag'] {
  font-size: var(--ds-font-size-lg);
  line-height: 1;
  flex-shrink: 0;
}
.ds-pattern-locale-switcher.ds-engine-modern [data-part='trigger'][data-size='sm'] [data-part='flag'] {
  font-size: var(--ds-font-size-sm);
}

/* ---- panel (the old inline popup object, re-anchored logically so it
        opens from the inline-start edge under RTL) ---- */
.ds-pattern-locale-switcher.ds-engine-modern[data-part='root'] [data-part='panel'] {
  position: absolute;
  inset-block-start: 100%;
  inset-inline-start: 0;
  z-index: var(--ds-z-index-dropdown, 1000);
