.ds-pattern-activity-log.ds-engine-modern [data-part='item-body'][data-interactive='true'] {
  cursor: pointer;
}
@media (hover: hover) {
  .ds-pattern-activity-log.ds-engine-modern [data-part='item-body'][data-interactive='true']:hover {
    background: var(--ds-surface-highlight);
  }
}
.ds-pattern-activity-log.ds-engine-modern [data-part='item-body'][data-interactive='true']:active {
  background: var(--ds-surface-inset);
}
.ds-pattern-activity-log.ds-engine-modern [data-part='item-body'][data-interactive='true']:focus-visible {
  outline: 2px solid var(--ds-focus-ring-color, var(--ds-color-primary));
  outline-offset: 2px;
