  margin-block-start: var(--ds-spacing-1, 0.25rem);
  color: var(--ds-color-text-muted);
  font-size: var(--ds-font-size-xs, 0.75rem);
}

/* ---- diff: geometry drained + paint preserved ---- */
.ds-pattern-activity-log.ds-engine-modern [data-part='diff'] {
  margin-block-start: var(--ds-spacing-2);
  padding: var(--ds-spacing-2) var(--ds-spacing-3);
  background: var(--ds-surface-inset);
  border-radius: var(--ds-radius-md);
  font-size: var(--ds-font-size-xs, 0.75rem);
  line-height: 1.6;
