.ds-pattern-activity-log.ds-engine-modern [data-part='diff-row'] {
  display: flex;
  align-items: baseline;
  gap: var(--ds-spacing-1, 0.375rem);
  color: var(--ds-color-text-secondary);
}
.ds-pattern-activity-log.ds-engine-modern [data-part='diff-cell'][data-diff-role='label'] {
  min-inline-size: 60px;
  color: var(--ds-color-text-primary);
  font-weight: var(--ds-font-weight-semibold, 600);
}
.ds-pattern-activity-log.ds-engine-modern [data-part='diff-cell'][data-diff-role='from'] {
  color: var(--ds-color-text-muted);
  text-decoration: line-through;
}
.ds-pattern-activity-log.ds-engine-modern [data-part='diff-cell'][data-diff-role='arrow'] {
  display: inline-flex;
  color: var(--ds-color-text-muted);
}
.ds-pattern-activity-log.ds-engine-modern [data-part='diff-cell'][data-diff-role='to'] {
  color: var(--ds-color-text-primary);
  font-weight: var(--ds-font-weight-medium, 500);
}

/* ---- skeleton list frame (the composed Skeleton primitives own the bars) ---- */
.ds-pattern-activity-log.ds-engine-modern [data-part='skeleton-list'] {
  display: flex;
  flex-direction: column;
  gap: var(--ds-spacing-5, 1.25rem);
  padding-block: var(--ds-spacing-4);
}

/* ---- empty frame (the composed Empty primitive owns visual + copy paint) ---- */
.ds-pattern-activity-log.ds-engine-modern [data-part='empty'] {
  display: flex;
  justify-content: center;
  padding-block: var(--ds-spacing-12, 3rem);
  color: var(--ds-color-text-muted);
