.ds-pattern-live-feed.ds-engine-modern [data-part='skeleton'] {
  border-radius: var(--ds-radius-sm);
  background: var(--ds-surface-panel);
  margin-block-end: var(--ds-live-feed-skeleton-row-gap, 8px);
