.ds-pattern-live-feed.ds-engine-modern [data-part='refresh'] {
  inline-size: var(--ds-live-feed-refresh-size, 32px);
  block-size: var(--ds-live-feed-refresh-size, 32px);
  padding: 0;
  background: transparent;
  color: var(--ds-color-text-primary);
  border-radius: var(--ds-radius-md);
  border: none;
  font-size: var(--ds-live-feed-control-font-size, 13px);
}

/* new-items banner: solid info surface with shape + text + count — the
   former glow shadow is removed (no-glow law). Geometry was inline. */
.ds-pattern-live-feed.ds-engine-modern [data-part='banner'] {
  inline-size: 100%;
  block-size: var(--ds-live-feed-banner-height, 32px);
  gap: var(--ds-live-feed-banner-gap, 8px);
  padding-block: 0;
  padding-inline: var(--ds-live-feed-banner-padding-inline, 12px);
  margin-block-end: var(--ds-live-feed-banner-margin-block-end, 12px);
  background: var(--ds-color-info);
  color: var(--ds-color-text-on-primary);
  border-radius: var(--ds-radius-md);
  border: none;
  font-size: var(--ds-live-feed-control-font-size, 13px);
}

/* banner count badge: pill geometry transcribed from pillBadgeSmStyle,
