.ds-pattern-live-feed.ds-engine-modern [data-part='load-more'] {
  gap: var(--ds-live-feed-load-more-gap, 6px);
  block-size: var(--ds-live-feed-control-height, 32px);
  padding-block: 0;
  padding-inline: var(--ds-live-feed-control-padding-inline, 12px);
  background: transparent;
  color: var(--ds-color-text-primary);
  border-radius: var(--ds-radius-md);
  border: none;
  font-size: var(--ds-live-feed-control-font-size, 13px);
