  .ds-pattern-live-feed.ds-engine-modern [data-part='skeleton'] {
    background: GrayText;
  }

  .ds-pattern-live-feed.ds-engine-modern [data-part='refresh']:focus-visible,
  .ds-pattern-live-feed.ds-engine-modern [data-part='banner']:focus-visible,
  .ds-pattern-live-feed.ds-engine-modern [data-part='load-more']:focus-visible {
    outline-color: Highlight;
  }
}

