}
@layer rottay-engines {
/**
 * Rustic (Vanilla / CSS-variable) LiveFeed skin (WO-SKIN-06 CK-F).
 *
 * DELIBERATELY UNLAYERED (P-47), same rationale as the modern skin: a layered
 * rule loses to Tailwind preflight on layer order whatever its specificity;
 * unlayered outranks preflight + DaisyUI and still yields to a caller's inline
 * `style`.
 *
 * SCOPE ROOT: the outer `<div>` carries `ds-pattern-live-feed ds-engine-rustic`
 * + `data-part='root'`, identical in the loading-skeleton and loaded branches.
 *
 * SPECIFICITY (P-48): root and banner both paint a border COLOR and have no
 * second contract attribute to spend, so both reach (0,4,0) by repeating their
 * own `data-part`. refresh/load-more borders are `none` (no color) and are
 * exempt. Non-border paint wins unlayered at (0,3,0).
 *
 * TOKENS: this is the ONE engine of the three that consumes the
 * `--ds-live-feed-*` component-scoped hatch (11 of 11 tokens, declared in
 * `foundation/themes/default.css` and overridden per-tenant in the first-party
 * artifacts) -- modern has no equivalent hatch to preserve (§0). Keep consuming
 * these names; do not point them at modern's generic tokens.
 *
 * KEYFRAMES (§3 trap 1, orchestrator ruling): the local `@keyframes pulse` this
 * file used to inject (`1 -> 0.4 -> 1`) is NOT a duplicate of the global
 * `@keyframes pulse` (`1 -> 0.5 -> 1`, `foundation/animations/keyframes.css`) --
 * the local `<style>` was injected after the global bundle, so the local 0.4 was
 * the value actually rendering. Renamed `ds-live-feed-pulse`, value carried
 * verbatim, per the `detail-panel` precedent
 * (`tests/PatternDetailPanel.real-engines.test.tsx:196`): rename the local copy,
 * never redefine the global name. `feedPulse` has no global equivalent at all;
 * renamed `ds-live-feed-feed-pulse`, value carried verbatim. Both `animation`
 * references in `engines/rustic.tsx` were updated to the new names.
 *
 * Values transcribed verbatim from `engines/rustic.tsx`.
 */

@keyframes ds-live-feed-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: .4; }
}

@keyframes ds-live-feed-feed-pulse {
  0% { background: var(--ds-live-feed-new-bg, var(--ds-color-info-bg)); }
  100% { background: transparent; }
}

/* root: color/background/border/radius identical across both branches */
.ds-pattern-live-feed.ds-engine-rustic[data-part='root'][data-part='root'] {
  color: var(--ds-color-neutral-900);
  background: var(--ds-live-feed-bg, var(--ds-color-bg-elevated));
  border: 1px solid var(--ds-live-feed-border, var(--ds-color-border));
  border-radius: var(--ds-radius-lg);
}

/* refresh button */
.ds-pattern-live-feed.ds-engine-rustic [data-part='refresh'] {
  background: none;
  border: none;
  color: var(--ds-live-feed-refresh-color, var(--ds-color-text-secondary));
  border-radius: var(--ds-radius-sm);
}

/* new-items bar */
.ds-pattern-live-feed.ds-engine-rustic [data-part='banner'][data-part='banner'] {
  background: var(--ds-live-feed-new-bg, var(--ds-color-info-bg));
  border-radius: var(--ds-radius-md);
  color: var(--ds-live-feed-new-color, var(--ds-color-info));
  border: 1px solid var(--ds-live-feed-new-border, var(--ds-color-info-border));
}

/* new-items count badge */
.ds-pattern-live-feed.ds-engine-rustic [data-part='badge'] {
  border-radius: var(--ds-radius-full, 9999px);
  background: var(--ds-live-feed-badge-bg, var(--ds-color-primary));
  color: var(--ds-live-feed-badge-color, var(--ds-color-text-on-primary));
}

/* empty state */
.ds-pattern-live-feed.ds-engine-rustic [data-part='empty'] {
  color: var(--ds-live-feed-empty-color, var(--ds-color-text-muted));
}

/* load more */
.ds-pattern-live-feed.ds-engine-rustic [data-part='load-more'] {
  background: none;
  border: none;
  color: var(--ds-live-feed-load-more-color, var(--ds-color-primary));
  border-radius: var(--ds-radius-md);
}

/* skeleton factory (title bar + row blocks) */
.ds-pattern-live-feed.ds-engine-rustic [data-part='skeleton'] {
  border-radius: var(--ds-radius-md);
  background: var(--ds-live-feed-skeleton-bg, var(--ds-color-bg-tertiary));
}

}
@layer rottay-components {
/**
 * Avatar compound skin — Avatar.Badge + Avatar.Group (WO-SKIN-05 checkpoint D1).
 *
 * DELIBERATELY UNLAYERED (P-47): every `rottay-*` cascade layer sorts before
 * Tailwind's base layer, so a layered rule cannot paint these elements at all.
 * Unlayered outranks preflight and still yields to the caller's inline `style`.
 *
 * ENGINE-AGNOSTIC: both compounds have a single render tree shared by every engine,
 * so they share one file rather than an engine pair.
 *
 * SPECIFICITY (P-48): each `border` shorthand carries a real colour and must clear
 * the tenant's unlayered `*` border-color floor at (0,3,1); the repeated `data-part`
 * (and, for the surplus tile, its group ancestor) buys the fourth unit. They stay
 * SHORTHANDS because preflight zeroes `border-width` on every element — these 2px
 * frames are the cut-out that separates each circle from the one it overlaps, so a
 * longhand colour over a zeroed width would erase the effect entirely.
 *
 * Avatar.Group's rules use a CHILD combinator: its `item` wrappers hold whole
 * Avatars, which stamp `data-part` names of their own.
 *
 * The surplus tile inherits the item's frame (its object spread `childStyle` first),
 * so it takes the same border rule and adds its own fill and ink. `maxStyle` is a
 * caller's value and stays inline, outranking both.
 *
 * Values transcribed verbatim from `compound/Badge/index.tsx` and
 * `compound/Group/index.tsx`.
 */

/* ---- Avatar.Badge: the presence dot ---- */
.rottay-avatar-badge-dot[data-part='dot'][data-part='dot'] {
  border-radius: 50%;
  border: 2px solid var(--ds-avatar-badge-border, var(--ds-color-bg-primary));
}
.rottay-avatar-badge-dot[data-part='dot'][data-status='online'] {
  background-color: var(--ds-color-success);
}
.rottay-avatar-badge-dot[data-part='dot'][data-status='offline'] {
  background-color: var(--ds-color-border-secondary);
}
.rottay-avatar-badge-dot[data-part='dot'][data-status='busy'] {
  background-color: var(--ds-color-error);
}
.rottay-avatar-badge-dot[data-part='dot'][data-status='away'] {
  background-color: var(--ds-color-warning);
}

/* ---- Avatar.Group: the overlap cut-out, worn by every tile including surplus ---- */
.rottay-avatar-group[data-part='root'] > [data-part='item'][data-part='item'],
.rottay-avatar-group[data-part='root'] > [data-part='surplus'][data-part='surplus'] {
  border: 2px solid var(--ds-avatar-group-border, var(--ds-color-bg-base));
}
.rottay-avatar-group[data-part='root'] > [data-part='surplus'] {
  background-color: var(--ds-avatar-surplus-bg, var(--ds-color-bg-secondary));
  color: var(--ds-avatar-surplus-color, var(--ds-color-text-secondary));
}

/* ---- forced colors: presence hues and surface-matched cut-outs strip away.
        The cut-out frame re-expresses against Canvas (the forced page
        background) so overlapping circles stay separated, and the badge dot
        keeps a guaranteed-visible system fill (its status is also exposed
        through its own role=img label). ---- */
@media (forced-colors: active) {
  .rottay-avatar-badge-dot[data-part='dot'][data-part='dot'] {
    border-color: Canvas;
    background-color: CanvasText;
    forced-color-adjust: auto;
  }
  .rottay-avatar-group[data-part='root'] > [data-part='item'][data-part='item'],
  .rottay-avatar-group[data-part='root'] > [data-part='surplus'][data-part='surplus'] {
    border-color: Canvas;
  }
  .rottay-avatar-group[data-part='root'] > [data-part='surplus'] {
    background-color: Canvas;
    color: CanvasText;
  }
}

}
@layer rottay-components {
/**
 * Card compound skin — Card.Header, Card.Footer, Card.Image (WO-SKIN-05 D1).
 *
 * Imported by the canonical engine bundle. Compounds expose stable anatomy;
 * this file owns their paint through public `--ds-card-*` channels.
 *
 * ENGINE-AGNOSTIC: each compound has one render tree shared by every engine, so they
 * share one file rather than an engine pair.
 *
 * THE CLASSNAME IS THE OWNERSHIP BOUNDARY, not the `data-part`. Both Card engines
 * render their OWN `data-part='header'`, `'title'`, `'actions'` and `'cover'`
 * elements with different token fallback chains, and a compound dropped into a
 * Card's `children` sits right beside them in the tree. Every selector here is
 * anchored on the compound's own classname, which no engine element wears; the
 * engines' skins carry the mirror-image guard (`:not(.rottay-card-header)`).
 *
 * SPECIFICITY (P-48): each rule carrying a border colour must clear the tenant's
 * unlayered `*` border-color floor at (0,3,1); the repeated `data-part` buys the
 * fourth unit. The `none` resets are colour-free and exempt. The frames stay
 * SHORTHANDS because preflight zeroes `border-width` on every element.
 *
 * `--ds-card-image-radius` is the hatch for `RADIUS_MAP[radius] || radius`, whose
 * else-branch passes the caller's raw string through — an open value no rule can
 * enumerate. The per-position corner longhands override it, which is the order the
 * object's spreads had.
 *
 * KEYFRAME: Card.Image's per-mount `<style>` injected `rottay-card-image-spin`; the
 * copy here is renamed into the `ds-` vocabulary the skins share.
 *
 * Values transcribed verbatim from `compound/{Header,Footer,Image}/index.tsx`.
 */

/* ---- Card.Header ---- */
.rottay-card-header[data-part='header'][data-part='header'] {
  position: relative;
  /* layout moved from the compound's inline styles (P2): the skin owns the
     row composition and the gap; the padding axis is keyed on data-padding
     below so every engine renders the identical geometry. */
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--ds-card-header-gap);
  min-inline-size: 0;
  min-height: var(--ds-card-header-min-height);
  border-bottom: none;
  background: var(--ds-card-header-bg);
  background-position: 0% 50%;
  background-size: 180% 180%;
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--ds-color-bg-elevated) 72%, transparent);
  transition:
    background-position var(--ds-motion-deliberate) var(--ds-motion-ease-enter),
    border-color var(--ds-motion-feedback) var(--ds-motion-ease-enter);
}

.rottay-card-header[data-padding='none'] {
  padding: 0;
}
.rottay-card-header[data-padding='sm'] {
  padding: var(--ds-card-header-padding-sm);
}
.rottay-card-header[data-padding='md'] {
  padding: var(--ds-card-header-padding);
}
.rottay-card-header[data-padding='lg'] {
  padding: var(--ds-card-header-padding-lg);
}

.rottay-card-header > .rottay-card-header-content {
  display: flex;
  align-items: center;
  gap: var(--ds-card-header-gap);
  flex: 1;
  min-inline-size: 0;
}
.rottay-card-header > .rottay-card-header-content > .rottay-card-header-text {
  display: flex;
  flex-direction: column;
  gap: var(--ds-spacing-1);
  flex: 1;
  min-inline-size: 0;
}
.rottay-card-header > .rottay-card-header-content > .rottay-card-header-avatar {
  flex-shrink: 0;
}
.rottay-card-header > .rottay-card-header-extra {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  gap: var(--ds-card-header-actions-gap);
}

/* Hover paint is gated to hover-capable pointers: on touch the behavior core
