@media (hover: hover) {
  .ds-card[data-interactive='true'][data-state~='hovered']:not([data-disabled='true']) .rottay-card-header[data-part='header'][data-part='header'] {
    background-position: 100% 50%;
  }
}
.rottay-card-header[data-part='header'][data-part='header'][data-divider='true'] {
