  font-size: var(--ds-card-title-font-size);
  font-weight: var(--ds-card-title-font-weight);
  line-height: var(--ds-card-title-line-height);
  letter-spacing: var(--ds-card-title-letter-spacing, var(--ds-letter-spacing-heading));
  margin: 0;
  overflow-wrap: anywhere;
  text-wrap: balance;
}
.rottay-card-header > .rottay-card-header-content > .rottay-card-header-text > [data-part='subtitle'] {
  color: var(--ds-card-subtitle-color, var(--ds-color-text-secondary));
  font-size: var(--ds-card-subtitle-font-size);
  line-height: var(--ds-card-body-line-height);
  margin: var(--ds-card-subtitle-margin-top) 0 0;
  max-inline-size: var(--ds-card-header-copy-max-width);
  overflow-wrap: anywhere;
  text-wrap: pretty;
}
.rottay-card-header > .rottay-card-header-content > .rottay-card-header-text > [data-part='eyebrow'] {
  color: var(--ds-card-header-color, var(--ds-color-text-muted));
  font-family: var(--ds-font-family-mono);
  font-size: var(--ds-card-header-eyebrow-size);
  font-weight: var(--ds-font-weight-semibold);
  letter-spacing: var(--ds-card-header-eyebrow-tracking);
  line-height: 1.2;
  text-transform: uppercase;
}
.rottay-card-header > .rottay-card-header-content > [data-part='icon'][data-part='icon'] {
