}

.rottay-card-header > .rottay-card-header-content,
.rottay-card-header > .rottay-card-header-content > .rottay-card-header-text,
.rottay-card-footer[data-part='footer'][data-part='footer'],
.rottay-card-body[data-part='body'][data-part='body'] {
  min-inline-size: 0;
  overflow-wrap: anywhere;
}

.rottay-card-body[data-part='body'][data-part='body'] {
  color: var(--ds-card-body-color, var(--ds-color-text-primary));
  font-size: var(--ds-card-body-font-size, var(--ds-font-size-base));
  line-height: var(--ds-card-body-line-height, var(--ds-line-height-normal));
