.rottay-card-image[data-part='image'][data-part='image'] {
  /* layout moved from the compound's inline styles (P2). The aspect ratio
     reads the per-instance hook the compound stamps from its contract value;
     unset, the declaration is inert and the ratio stays at the UA initial. */
  position: relative;
  inline-size: 100%;
  overflow: hidden;
  aspect-ratio: var(--ds-card-image-aspect-ratio);
  border-radius: var(--ds-card-image-radius);
  --_ds-card-image-corner: var(--_ds-card-radius-current, var(--ds-card-radius));
}
.rottay-card-image[data-part='image'][data-part='image'][data-position='cover'] {
  position: absolute;
  inset: 0;
  block-size: 100%;
  z-index: 0;
}
.rottay-card-image[data-part='image'][data-part='image'][data-position='top'] {
  border-top-left-radius: var(--_ds-card-image-corner);
  border-top-right-radius: var(--_ds-card-image-corner);
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}
.rottay-card-image[data-part='image'][data-part='image'][data-position='bottom'] {
  border-top-left-radius: 0;
  border-top-right-radius: 0;
  border-bottom-left-radius: var(--_ds-card-image-corner);
  border-bottom-right-radius: var(--_ds-card-image-corner);
}
.rottay-card-image[data-part='image'][data-part='image'][data-position='start'] {
  border-start-start-radius: var(--_ds-card-image-corner);
  border-end-start-radius: var(--_ds-card-image-corner);
  border-start-end-radius: 0;
  border-end-end-radius: 0;
}
