/* keyboard focus: the back button is a Flex inside an <a>, so the ring lands
   on the chip when the anchor is focus-visible */
.ds-structure.ds-detail-header a:focus-visible [data-part='back-button'] {
  box-shadow: var(--ds-detail-header-focus-ring, var(--ds-focus-ring, 0 0 0 3px color-mix(in srgb, var(--ds-color-primary) 24%, transparent)));
}

/* ─── avatar (image + initials variants) ───────────────────────────────────── */

.ds-structure.ds-detail-header [data-part='avatar'] {
  inline-size: var(--ds-detail-header-avatar-size, 68px);
  block-size: var(--ds-detail-header-avatar-size, 68px);
  overflow: hidden;
  flex-shrink: 0;
  border-radius: 18px;
  box-shadow:
    0 0 0 4px color-mix(in srgb, var(--ds-surface-card) 78%, transparent),
    0 12px 30px -18px color-mix(in srgb, var(--ds-color-text-primary) 42%, transparent);
  transition: transform var(--ds-motion-normal) var(--ds-motion-ease-spring, ease-out);
}
.ds-structure.ds-detail-header [data-part='avatar'][data-variant='initials'] {
  display: flex;
