.ds-structure.ds-detail-header [data-part='avatar'][data-variant='image'],
.ds-structure.ds-detail-header [data-part='avatar'][data-variant='initials'] {
  border: 1px solid var(--ds-color-border-secondary);
}
.ds-structure.ds-detail-header [data-part='avatar'] img {
  inline-size: 100%;
  block-size: 100%;
  object-fit: cover;
}
.ds-structure.ds-detail-header [data-part='avatar-initials'][data-part='avatar-initials'][data-part='avatar-initials'] {
  font-size: var(--ds-detail-header-avatar-initials-size, 24px);
  font-weight: 700;
}

/* ─── hero copy: eyebrow / title (Box as h1) / subtitle ────────────────────── */

.ds-structure.ds-detail-header [data-part='eyebrow'][data-part='eyebrow'][data-part='eyebrow'] {
  color: var(--ds-color-text-muted);
  font-family: var(--ds-font-family-mono, monospace);
  letter-spacing: var(--ds-detail-header-eyebrow-tracking, 0.14em);
  text-transform: uppercase;
}
/* the title is a `Box as="h1"` (NOT typography), so its display type lives here
   and wins unlayered at (0,3,0); the per-archetype size keys on the stamped
   data-archetype (editorial 34 / technical 30 / control+governance 32). */
.ds-structure.ds-detail-header [data-part='title'] {
  margin: 0;
  color: var(--ds-color-text-primary);
  font-family: var(--ds-font-family-heading, var(--ds-font-family-base));
  font-size: var(--ds-detail-header-title-size, 32px);
  font-weight: var(--ds-detail-header-title-weight, 720);
  letter-spacing: var(--ds-detail-header-title-tracking, -0.04em);
  line-height: var(--ds-detail-header-title-leading, 1.02);
  text-wrap: balance;
}
.ds-structure.ds-detail-header [data-part='title'][data-archetype='editorial'] {
  font-size: var(--ds-detail-header-title-size-editorial, 34px);
}
.ds-structure.ds-detail-header [data-part='title'][data-archetype='technical'] {
  font-size: var(--ds-detail-header-title-size-technical, 30px);
}
.ds-structure.ds-detail-header [data-part='subtitle'][data-part='subtitle'][data-part='subtitle'] {
  color: var(--ds-color-text-secondary);
  line-height: var(--ds-detail-header-subtitle-leading, 1.65);
  max-inline-size: var(--ds-detail-header-subtitle-max-inline-size, 780px);
}

.ds-structure.ds-detail-header [data-part='context-rail'] {
  margin-block-start: var(--ds-detail-header-context-rail-margin-block-start, 2px);
}

.ds-structure.ds-detail-header [data-part='hero-panel'] {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  padding: var(--ds-detail-header-hero-panel-padding, 28px);
}

.ds-structure.ds-detail-header[data-part='root']:hover [data-part='avatar'] {
  transform: translateY(-2px) scale(1.015);
}

/* ─── metadata card + chips ────────────────────────────────────────────────── */

/* the inline object set `background` (a linear-gradient) THEN `backgroundImage`
   (a 5-layer stack); the later key silently overwrote the earlier, so only the
