    radial-gradient(circle at 12% 16%, color-mix(in srgb, var(--ds-color-text-muted) 22%, transparent) 0%, transparent 48%),
    radial-gradient(circle at 84% 2%, color-mix(in srgb, var(--ds-color-text-primary) 10%, transparent) 0%, transparent 34%),
    radial-gradient(circle at 74% 100%, color-mix(in srgb, var(--ds-color-text-primary) 6%, transparent) 0%, transparent 42%),
