  line-height: 1;
}
.ds-stats-header[data-part='root'] [data-part='change-row'][data-change='increase'],
.ds-stats-header[data-part='root'] [data-part='stat-card'][data-accent] [data-part='change-value'][data-change='increase'] {
  color: var(--ds-color-success);
}
.ds-stats-header[data-part='root'] [data-part='change-row'][data-change='decrease'],
.ds-stats-header[data-part='root'] [data-part='stat-card'][data-accent] [data-part='change-value'][data-change='decrease'] {
  color: var(--ds-color-error);
}
.ds-stats-header[data-part='root'] [data-part='change-row'][data-change='neutral'],
.ds-stats-header[data-part='root'] [data-part='stat-card'][data-accent] [data-part='change-value'][data-change='neutral'] {
  color: var(--ds-color-text-muted);
}
.ds-stats-header[data-part='root'] [data-part='stat-card'][data-accent] [data-part='change-period'] {
  color: var(--ds-color-text-muted);
  font-size: var(--ds-stats-header-kicker-font-size, var(--ds-font-size-2xs));
