  .ds-stats-header[data-part='root'] [data-part='stat-card']:hover [data-part='spark-dot'][data-dot-index='1'] { animation-delay: calc(var(--ds-stats-header-ping-duration, 400ms) / 8); }
  .ds-stats-header[data-part='root'] [data-part='stat-card']:hover [data-part='spark-dot'][data-dot-index='2'] { animation-delay: calc(var(--ds-stats-header-ping-duration, 400ms) / 8 * 2); }
  .ds-stats-header[data-part='root'] [data-part='stat-card']:hover [data-part='spark-dot'][data-dot-index='3'] { animation-delay: calc(var(--ds-stats-header-ping-duration, 400ms) / 8 * 3); }
  .ds-stats-header[data-part='root'] [data-part='stat-card']:hover [data-part='spark-dot'][data-dot-index='4'] { animation-delay: calc(var(--ds-stats-header-ping-duration, 400ms) / 8 * 4); }
  .ds-stats-header[data-part='root'] [data-part='stat-card']:hover [data-part='spark-dot'][data-dot-index='5'] { animation-delay: calc(var(--ds-stats-header-ping-duration, 400ms) / 8 * 5); }
  .ds-stats-header[data-part='root'] [data-part='stat-card']:hover [data-part='spark-dot'][data-dot-index='6'] { animation-delay: calc(var(--ds-stats-header-ping-duration, 400ms) / 8 * 6); }
}
.ds-stats-header[data-part='root'] [data-part='spark-dot'][data-accent='primary'] { background: var(--ds-color-primary); }
.ds-stats-header[data-part='root'] [data-part='spark-dot'][data-accent='success'] { background: var(--ds-color-success); }
