.ds-stats-header[data-part='root'] [data-part='spark-dot'][data-accent='info']    { background: var(--ds-color-info); }

/* ---- progress meter slot (the composed Progress owns track + fill) ---- */
.ds-stats-header[data-part='root'] [data-part='stat-progress'] {
