.ds-assistant-tool-call-card [data-part='tool-card'][data-part='tool-card'][data-part='tool-card'][data-part='tool-card'][data-tone='warning'] {
  color: var(--ds-color-warning);
}
.ds-assistant-tool-call-card [data-part='tool-card'][data-part='tool-card'][data-part='tool-card'][data-part='tool-card'][data-tone='danger'] {
