  .ds-pattern-saved-views.ds-engine-modern
    .ds-saved-views__menu-trigger[data-part='menu-trigger'],
  .ds-pattern-saved-views.ds-engine-modern
    .ds-saved-views__create-button[data-part='create-button'],
  .ds-pattern-saved-views.ds-engine-modern
    .ds-saved-views__input[data-part='field'] .rottay-input,
