@layer rottay-components {
/**
 * ExportButton skin — engine-agnostic and deliberately unlayered so it beats
 * layered base/preflight paint (P-47).
 * The dropdown is portaled under document.body and therefore owns a standalone
 * two-class panel scope.
 *
 * COMPOSITION LAW (S19): the trigger and the menu items are the Button
 * primitive (the interim menu while Dropdown P88 is blocked), so every item
 * chrome rule (background, hover wash, focus ring, borders) is retired —
 * each primitive's own skin owns its paint, including forced-colors. What
 * this file owns: the root anchor geometry, the copied-toast frame and its
 * fade vocabulary (the one semaphore accent), the portaled panel's frame
 * and z/layer channels, and the full-width menu-item layout.
 *
 * SPECIFICITY (P-48): border paint reaches the tenant floor from the two
 * scope classes + two DISTINCT attributes (`data-part` + `data-open`, or the
 * descendant toast chain) — never an identical attribute repeated
 * (4th-tanda law; the former `panel×2`, `menu-item×2`, `toast-label×3` and
 * `menu-label×3` selectors are retired). Color fallbacks are token-only:
 * the retired `#16a34a` / `#fff` / `#e2e2e2` / `#1a1a1a` / `#666` literals
 * violated the zero-literals law.
 *
 * RTL: the end-aligned panel flip is mirrored via :dir(rtl).
 */

/* ---- root: the trigger's anchor (geometry drained from inline) ---- */
.ds-structure.ds-export-button[data-part='root'] {
  position: relative;
  display: inline-flex;
}

/* ---- trigger-side toast (geometry drained from inline; success accent with
        icon + text, announced via role=status in the engine) ---- */
.ds-structure.ds-export-button[data-part='root'] [data-part='toast'] {
  position: absolute;
  inset-block-start: -32px;
  inset-inline-start: 50%;
  z-index: var(--ds-export-button-toast-z, 9999);
  padding-block: 4px;
  padding-inline: 10px;
  border-radius: 6px;
  background: var(--ds-color-bg-success);
  color: var(--ds-color-text-on-success);
  font-size: var(--ds-font-size-xs);
  font-weight: 600;
  white-space: nowrap;
  pointer-events: none;
  transform: translateX(-50%);
  animation: ds-export-toast-fade var(--ds-export-button-toast-duration, 1.8s) ease forwards;
}

.ds-structure.ds-export-button[data-part='root'] [data-part='toast'] [data-part='toast-label'] {
  color: inherit;
  font-size: var(--ds-font-size-xs);
  font-weight: 600;
}

/* ---- standalone portaled dropdown (measured top/left stay inline) ---- */

.ds-structure.ds-export-button-panel[data-part='panel'] {
  z-index: var(--ds-export-button-panel-z, 9998);
  min-inline-size: var(--ds-export-button-panel-min-width, 200px);
  padding: 4px;
  border-radius: 8px;
  background: var(--ds-color-bg-elevated);
  box-shadow: 0 4px 12px color-mix(in srgb, var(--ds-color-primary) 10%, transparent), 0 1px 3px color-mix(in srgb, var(--ds-color-primary) 8%, transparent);
  transform: translateX(-100%);
}
.ds-structure.ds-export-button-panel[data-part='panel']:dir(rtl) {
  transform: translateX(100%);
}

.ds-structure.ds-export-button-panel[data-part='panel'][data-open='true'] {
  border: 1px solid var(--ds-color-border);
}

/* ---- menu items: the composed ghost Buttons stretch to full rows (their
        chrome, hover wash and focus ring are button.css-owned) ---- */
.ds-structure.ds-export-button-panel[data-part='panel'] [data-part='menu-item'] {
  inline-size: 100%;
  justify-content: flex-start;
}

@keyframes ds-export-toast-fade {
  0% { opacity: 0; transform: translateX(-50%) translateY(4px); }
  10% { opacity: 1; transform: translateX(-50%) translateY(0); }
  80% { opacity: 1; transform: translateX(-50%) translateY(0); }
  100% { opacity: 0; transform: translateX(-50%) translateY(-4px); }
}

/* Reduced motion: the toast appears/disappears instantly. */
@media (prefers-reduced-motion: reduce) {
  .ds-structure.ds-export-button[data-part='root'] [data-part='toast'] {
    animation: none;
  }
}

/* forced-colors: the panel's ambient shadow and the toast's success fill are
   forced away, so both re-frame in system colors. The toast stays readable
   as feedback through its icon + text (never colour alone); the portaled
   panel keeps a system boundary; the composed Buttons (trigger and items)
   own their own forced-colors contracts. */
@media (forced-colors: active) {
  .ds-structure.ds-export-button[data-part='root'] [data-part='toast'] {
    border: 1px solid ButtonText;
    background: Canvas;
    color: CanvasText;
  }
  .ds-structure.ds-export-button-panel[data-part='panel'],
  .ds-structure.ds-export-button-panel[data-part='panel'][data-open='true'] {
    border: 1px solid ButtonText;
    background: Canvas;
    box-shadow: none;
  }
}

}
@layer rottay-components {
/**
 * SavedViewsMenu skin — engine-agnostic.
 * LAYERING: imported by `facade/entrypoints/base.css` into
 * `layer(rottay-components)` — this file does not control its own layering
 * (the older "deliberately unlayered" note predates that wiring).
 *
 * The document.body portal uses its own standalone two-class panel scope;
 * nothing in this file assumes trigger-to-panel ancestry. Class/attribute
 * repetition is prohibited, so the border floor (P-48) is bought from
 * ALWAYS-PRESENT attributes instead (fragility documented): the trigger and
 * the panel both stamp `data-open` on every render, and every panel rule
 * chains the two scope classes + `data-part='panel'` (+ `data-open` for the
 * (0,5,0) Text tier) + the target part.
 *
 * HOVER LAW: every hover is hover-capable-only (`@media (hover: hover)`);
 * actionable parts keep their `:active` and `:focus-visible` states beside
 * it. In forced colors the box-shadow focus rings would vanish, so the
 * focusables re-express the ring as a Highlight outline.
 *
 * INK DERIVATION: the surface brightening mixes resolve against
 * `--ds-color-bg-elevated` — never a hard `white` literal.
 */

/* trigger ----------------------------------------------------------------- */

.ds-structure.ds-saved-views-menu[data-part='trigger'] {
  border-radius: 12px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--ds-surface-card) 92%, var(--ds-color-bg-elevated) 8%), color-mix(in srgb, var(--ds-surface-card) 88%, var(--ds-color-bg-primary) 12%));
  color: var(--ds-color-text-primary);
  transition:
    background-color var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out),
    border-color var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out),
    box-shadow var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out),
    color var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out);
}

.ds-structure.ds-saved-views-menu[data-part='trigger'][data-open] {
  border: 1px solid color-mix(in srgb, var(--ds-color-border-secondary) 84%, transparent);
}

@media (hover: hover) {
  .ds-structure.ds-saved-views-menu[data-part='trigger'][data-open]:hover:not([data-open='true']) {
    border-color: color-mix(in srgb, var(--ds-color-text-secondary) 30%, transparent);
    background: linear-gradient(180deg, color-mix(in srgb, var(--ds-surface-card) 96%, var(--ds-color-bg-elevated) 4%), color-mix(in srgb, var(--ds-surface-card) 92%, var(--ds-color-bg-primary) 8%));
  }
}

.ds-structure.ds-saved-views-menu[data-part='trigger']:focus-visible {
  outline: none;
  box-shadow: 0 0 0 var(--ds-focus-ring-width, 2px) var(--ds-focus-ring-color, color-mix(in srgb, var(--ds-color-primary) 55%, transparent));
}

.ds-structure.ds-saved-views-menu[data-part='trigger'][data-open='true'] {
  background: linear-gradient(180deg, color-mix(in srgb, var(--ds-color-primary) 12%, var(--ds-surface-card)), color-mix(in srgb, var(--ds-color-primary) 8%, var(--ds-surface-card)));
  border-color: color-mix(in srgb, var(--ds-color-primary) 34%, transparent);
}

.ds-structure.ds-saved-views-menu [data-part='trigger-icon'] {
  border-radius: 10px;
  background: color-mix(in srgb, var(--ds-color-bg-primary) 56%, transparent);
  color: var(--ds-color-text-secondary);
}

.ds-structure.ds-saved-views-menu [data-part='trigger-icon'][data-open='true'] {
  background: color-mix(in srgb, var(--ds-color-primary) 16%, transparent);
  color: var(--ds-color-primary);
}

/* standalone portaled panel ---------------------------------------------- */

.ds-structure.ds-saved-views-menu-panel[data-part='panel'] {
  border-radius: 18px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--ds-surface-card) 98%, var(--ds-color-bg-elevated) 2%), color-mix(in srgb, var(--ds-color-bg-primary) 28%, var(--ds-surface-card)));
  box-shadow: 0 24px 60px color-mix(in srgb, var(--ds-color-primary) 16%, transparent);
}

.ds-structure.ds-saved-views-menu-panel[data-part='panel'][data-open] {
  border: 1px solid color-mix(in srgb, var(--ds-color-border-secondary) 78%, transparent);
}

.ds-structure.ds-saved-views-menu-panel [data-part='header'] {
  background: linear-gradient(180deg, color-mix(in srgb, var(--ds-color-primary) 8%, transparent), transparent);
}

.ds-structure.ds-saved-views-menu-panel[data-part='panel'] [data-part='header'] {
  border-bottom: 1px solid color-mix(in srgb, var(--ds-color-border-subtle) 82%, transparent);
}

.ds-structure.ds-saved-views-menu-panel[data-part='panel'][data-open] [data-part='header-description'] {
  color: var(--ds-color-text-muted);
}

.ds-structure.ds-saved-views-menu-panel [data-part='count-pill'] {
  border-radius: 999px;
  background: color-mix(in srgb, var(--ds-color-bg-primary) 72%, transparent);
  color: var(--ds-color-text-secondary);
}

/* active card stays at 8%; StatusPill primary stays at 12% ---------------- */

.ds-structure.ds-saved-views-menu-panel [data-part='active-card'] {
  border-radius: 14px;
