/* ---------------------------------------------------------------------------
   WAVE R2+R3 — typography + microinteractions (skin-owned, never inline).
   Quiet Premium: the section headers are tracked uppercase eyebrows, counts
   are tabular-nums pills, and every actionable part earns a deliberate
   hover/focus/active state on the --ds-motion-* channels.
--------------------------------------------------------------------------- */

/* header + section eyebrows */
.ds-structure.ds-saved-views-menu-panel[data-part='panel'][data-open] [data-part='header-title'] {
  font-size: var(--ds-font-size-sm);
}
.ds-structure.ds-saved-views-menu-panel[data-part='panel'][data-open] [data-part='header-description'],
.ds-structure.ds-saved-views-menu-panel[data-part='panel'][data-open] [data-part='active-card-description'],
.ds-structure.ds-saved-views-menu-panel[data-part='panel'][data-open] [data-part='view-item-description'] {
  font-size: var(--ds-font-size-xs);
}
.ds-structure.ds-saved-views-menu-panel[data-part='panel'][data-open] [data-part='section-header'] {
  font-size: var(--ds-font-size-2xs, var(--ds-font-size-xs));
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* count + status pills: tabular-nums so tallies never jitter */
.ds-structure.ds-saved-views-menu-panel [data-part='count-pill'] {
  font-size: var(--ds-font-size-2xs, var(--ds-font-size-xs));
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.ds-structure.ds-saved-views-menu-panel [data-part='status-pill'] {
  font-size: var(--ds-font-size-2xs, var(--ds-font-size-xs));
  font-weight: 600;
}

/* action buttons: type per tone + deliberate hover/focus/active */
.ds-structure.ds-saved-views-menu-panel [data-part='action-button'] {
  font-size: var(--ds-font-size-xs);
  font-weight: 600;
  transition:
    background-color var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out),
    border-color var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out),
    box-shadow var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out),
    color var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out);
}
.ds-structure.ds-saved-views-menu-panel [data-part='action-button'][data-tone='primary'] {
  font-weight: 700;
}
@media (hover: hover) {
  .ds-structure.ds-saved-views-menu-panel [data-part='action-button'][data-tone='neutral']:hover {
    background: color-mix(in srgb, var(--ds-surface-card) 70%, var(--ds-color-bg-primary) 30%);
    color: var(--ds-color-text-primary);
  }
  .ds-structure.ds-saved-views-menu-panel[data-part='panel'] [data-part='action-button'][data-tone='neutral']:hover {
    border-color: color-mix(in srgb, var(--ds-color-text-secondary) 30%, transparent);
  }
  .ds-structure.ds-saved-views-menu-panel [data-part='action-button'][data-tone='primary']:hover {
    background: color-mix(in srgb, var(--ds-color-primary) 14%, transparent);
  }
  .ds-structure.ds-saved-views-menu-panel[data-part='panel'] [data-part='action-button'][data-tone='primary']:hover {
    border-color: color-mix(in srgb, var(--ds-color-primary) 38%, transparent);
  }
}
.ds-structure.ds-saved-views-menu-panel [data-part='action-button']:focus-visible {
  outline: none;
  box-shadow: 0 0 0 var(--ds-focus-ring-width, 2px) var(--ds-focus-ring-color, color-mix(in srgb, var(--ds-color-primary) 55%, transparent));
}
.ds-structure.ds-saved-views-menu-panel [data-part='action-button'][data-tone='neutral']:active {
  background: color-mix(in srgb, var(--ds-color-bg-primary) 60%, var(--ds-surface-card));
}
.ds-structure.ds-saved-views-menu-panel [data-part='action-button'][data-tone='primary']:active {
  background: color-mix(in srgb, var(--ds-color-primary) 18%, transparent);
}

/* view items: the whole card lifts on hover; the select button keeps the
   inset focus ring it already owns */
.ds-structure.ds-saved-views-menu-panel [data-part='view-item'] {
  transition:
    background-color var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out),
    border-color var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out),
    box-shadow var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out);
}
@media (hover: hover) {
  .ds-structure.ds-saved-views-menu-panel [data-part='view-item']:hover:not([data-active='true']) {
    background: color-mix(in srgb, var(--ds-surface-card) 96%, var(--ds-color-bg-primary) 4%);
    box-shadow: 0 4px 14px color-mix(in srgb, var(--ds-color-text-primary) 4%, transparent);
  }
  .ds-structure.ds-saved-views-menu-panel[data-part='panel'] [data-part='view-item']:hover:not([data-active='true']) {
    border-color: color-mix(in srgb, var(--ds-color-border-secondary) 88%, transparent);
  }
}

/* delete affordance: quiet until asked, then a measured danger whisper */
.ds-structure.ds-saved-views-menu-panel [data-part='delete'] {
  transition:
    background-color var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out),
    border-color var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out),
    color var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out);
}
@media (hover: hover) {
  .ds-structure.ds-saved-views-menu-panel [data-part='delete']:hover {
    background: color-mix(in srgb, var(--ds-color-danger) 8%, transparent);
    color: var(--ds-color-danger);
  }
  .ds-structure.ds-saved-views-menu-panel[data-part='panel'] [data-part='delete']:hover {
    border-color: color-mix(in srgb, var(--ds-color-danger) 34%, transparent);
  }
}
.ds-structure.ds-saved-views-menu-panel [data-part='delete']:focus-visible {
  outline: none;
  box-shadow: 0 0 0 var(--ds-focus-ring-width, 2px) var(--ds-focus-ring-color, color-mix(in srgb, var(--ds-color-danger) 50%, transparent));
}

/* Reduced motion: every state change on the trigger and panel is a
 * cross-fade; all of them go silent together. */
@media (prefers-reduced-motion: reduce) {
  .ds-structure.ds-saved-views-menu[data-part='trigger'],
  .ds-structure.ds-saved-views-menu-panel [data-part='action-button'],
  .ds-structure.ds-saved-views-menu-panel [data-part='view-item'],
  .ds-structure.ds-saved-views-menu-panel [data-part='delete'] {
    transition: none;
  }
}

/* Forced colors: system colors only. Frames re-express as ButtonText; the
   active/current marks read by the checkmark shape and the pill text (never
   tint); the box-shadow focus rings would vanish, so the focusables get a
   real Highlight outline; the dashed empty-state frame survives as ButtonText. */
@media (forced-colors: active) {
  .ds-structure.ds-saved-views-menu[data-part='trigger'][data-open],
  .ds-structure.ds-saved-views-menu-panel[data-part='panel'][data-open],
  .ds-structure.ds-saved-views-menu-panel[data-part='panel'] [data-part='header'],
  .ds-structure.ds-saved-views-menu-panel[data-part='panel'] [data-part='active-card'],
  .ds-structure.ds-saved-views-menu-panel[data-part='panel'] [data-part='action-button'],
  .ds-structure.ds-saved-views-menu-panel[data-part='panel'] [data-part='view-item'],
  .ds-structure.ds-saved-views-menu-panel[data-part='panel'] [data-part='delete'],
  .ds-structure.ds-saved-views-menu-panel[data-part='panel'] [data-part='empty-state'] {
    border-color: ButtonText;
  }

  .ds-structure.ds-saved-views-menu-panel[data-part='panel'] [data-part='view-item'][data-active='true'] {
    border-color: Highlight;
  }

  .ds-structure.ds-saved-views-menu [data-part='trigger-icon'],
  .ds-structure.ds-saved-views-menu-panel [data-part='glyph'],
  .ds-structure.ds-saved-views-menu-panel [data-part='checkmark'],
  .ds-structure.ds-saved-views-menu-panel [data-part='status-pill'],
  .ds-structure.ds-saved-views-menu-panel [data-part='count-pill'] {
    color: CanvasText;
  }

  .ds-structure.ds-saved-views-menu-panel[data-part='panel'] [data-part='status-pill'],
  .ds-structure.ds-saved-views-menu-panel[data-part='panel'] [data-part='count-pill'] {
    border: 1px solid ButtonText;
    background: transparent;
  }

  .ds-structure.ds-saved-views-menu[data-part='trigger']:focus-visible,
  .ds-structure.ds-saved-views-menu-panel [data-part='action-button']:focus-visible,
  .ds-structure.ds-saved-views-menu-panel [data-part='view-item-select']:focus-visible,
  .ds-structure.ds-saved-views-menu-panel [data-part='delete']:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
    box-shadow: none;
  }
}

}
@layer rottay-components {
/**
 * ScopeSwitcher skin — engine-agnostic and deliberately unlayered.
 *
 * COMPOSITION LAW (S22): the scope switcher is the certified Segmented
 * primitive (radiogroup semantics, roving keyboard, option chrome and the
 * active fill all belong to `segmented.css`) — the retired hand-rolled
 * pills took with them every pill rule (resting gradient, hover, focus,
 * active tint) and the repeated-selector budget they were bought with.
 * What this file owns: the root frame (section strip vs inline
 * transparent), the count badge paint INSIDE the composed option label
 * (tabular figures, active tint by data-active), the scroll region for
 * narrow compositions, and the forced-colors contract for those owned
 * pieces.
 *
 * SPECIFICITY (P-48): the root's hairline reaches the tenant floor from the
 * two scope classes + the root's own `data-part` + `data-inline` — two
 * DISTINCT attributes, never an identical one repeated (4th-tanda law; the
 * former `[data-part='root']×2`, `pill×2` ×6 and `pill-label×3` selectors
 * are retired). The `white` color-mix literals of the retired pill gradients
 * violated the zero-literals law and are gone with them.
 */

/* ---- root: quiet hairline strip (padding drained from the engine's inline
        styles, keyed on the inline variant; scroll region for narrow
        compositions) ---- */
.ds-structure.ds-scope-switcher[data-part='root'] {
  padding-block: 8px;
  padding-inline: 16px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}
.ds-structure.ds-scope-switcher[data-part='root'][data-inline='false'] {
  border-bottom: 1px solid color-mix(in srgb, var(--ds-color-border-subtle) 88%, transparent);
  background: linear-gradient(180deg, color-mix(in srgb, var(--ds-surface-card) 95%, var(--ds-color-bg-primary) 5%), color-mix(in srgb, var(--ds-surface-card) 92%, var(--ds-color-bg-primary) 8%));
}
.ds-structure.ds-scope-switcher[data-part='root'][data-inline='true'] {
  padding-block: 0;
  padding-inline: 0;
}

/* ---- count badge INSIDE the composed Segmented option label: the pattern's
        own mini-pill (the primitive owns the option chrome; the count scans
        tabular and reads through number + tint, never tint alone) ---- */
.ds-structure.ds-scope-switcher[data-part='root'] [data-part='count-badge'] {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  min-inline-size: 18px;
  block-size: 18px;
  margin-inline-start: var(--ds-spacing-1, 4px);
  padding-block: 0;
  padding-inline: 6px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--ds-color-bg-primary) 60%, transparent);
  color: var(--ds-color-text-muted);
  font-size: var(--ds-font-size-2xs, var(--ds-font-size-xs));
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.ds-structure.ds-scope-switcher[data-part='root'] [data-part='count-badge'][data-active='true'] {
  background: color-mix(in srgb, var(--ds-color-primary) 18%, transparent);
  color: var(--ds-color-primary);
}

/* forced-colors: the root's gradient hairline is forced away, so the strip
   re-asserts in system colors and the count badge keeps a framed neutral
   boundary (its number carries the information). The composed Segmented
   keeps its own forced-colors contract (active option by system state). */
@media (forced-colors: active) {
  .ds-structure.ds-scope-switcher[data-part='root'][data-inline='false'] {
    border-bottom-color: ButtonText;
    background: Canvas;
  }
  .ds-structure.ds-scope-switcher[data-part='root'] [data-part='count-badge'] {
    outline: 1px solid ButtonText;
    background: Canvas;
    color: CanvasText;
  }
}

}
@layer rottay-components {
/**
 * SearchCommandBar skin — engine-agnostic and deliberately unlayered.
 * Border rules clear the tenant floor at (0,4,0) or higher; composed Text
 * colors clear the Typography engine skin at (0,5,0). Input paint preserves
 * the caller-style landing per engine: wrapper in modern, shell in rustic;
