  color: var(--ds-filter-pill-color, var(--ds-color-text-secondary));
}

.ds-pattern-status-filter-pills
  .ds-status-filter-pills__pill-label[data-part='pill-label'][data-part='pill-label'][data-part='pill-label'][data-part='pill-label'][data-selected='true'] {
