@layer rottay-components {
/**
 * TableToolbar skin — engine-agnostic.
 * LAYERING: imported by `facade/entrypoints/base.css` into
 * `layer(rottay-components)` — this file does not control its own layering
 * (the older "deliberately unlayered" note predates that wiring).
 *
 * Search paint lands where caller style landed: the modern Input wrapper and
 * the rustic Input shell (the P-79/Input landing the contract tests pin).
 * The rustic arm NO LONGER repeats `[data-part='root']` six times — class/
 * attribute repetition is prohibited; the honest selector is the class triple
 * + one part, and the cascade order between `rottay-components` (this file)
 * and `rottay-engines` (the rustic input skin) decides the rest, exactly as
 * it did before (the repetitions never changed layer order).
 *
 * SPECIFICITY: the root border reaches the (0,4,0) tenant floor from the two
 * scope classes + `data-part='root'` + the always-present
 * `data-structure='table-toolbar'` hook the engine stamps (the record/PT10
 * precedent — never a repeated attribute).
 *
 * WAVE R2+R3 (Quiet Premium editorial): a hairline-separated chrome row.
 * The divider is a soft vertical hairline with a paper highlight (token
 * color-mix, never a raw literal); the search icon stays muted and deepens
 * when its field gains focus. Search typography uses the supporting step of
 * the system scale on the exact per-engine paint node.
 */

/* ---- root: hairline-bottomed chrome row + named container ---- */
.ds-structure.ds-table-toolbar[data-part='root'] {
  padding-block: 10px;
  padding-inline: 16px;
  container-type: inline-size;
}
.ds-structure.ds-table-toolbar[data-part='root'][data-structure='table-toolbar'] {
  border-bottom: 1px solid var(--ds-color-border);
}

/* ---- row sections (geometry drained from inline flex styles) ---- */
.ds-structure.ds-table-toolbar [data-part='root'] .ds-table-toolbar__left {
  flex-shrink: 0;
  min-inline-size: 0;
  padding-inline-end: 12px;
}
.ds-structure.ds-table-toolbar [data-part='root'] .ds-table-toolbar__spacer {
  flex: 1;
}
.ds-structure.ds-table-toolbar [data-part='root'] .ds-table-toolbar__right {
  flex-shrink: 0;
  min-inline-size: 0;
}
.ds-structure.ds-table-toolbar [data-part='root'] .ds-table-toolbar__filters {
  padding-inline-end: 12px;
}
.ds-structure.ds-table-toolbar [data-part='root'] .ds-table-toolbar__actions {
  padding-inline-start: 12px;
}

/* ---- divider: soft vertical hairline with a paper highlight ---- */
.ds-structure.ds-table-toolbar .ds-table-toolbar__divider[data-part='divider'] {
  inline-size: 2px;
  block-size: 28px;
  flex-shrink: 0;
  margin-inline: 4px;
  border-radius: 1px;
  background: linear-gradient(180deg, transparent 0%, var(--ds-color-border) 20%, var(--ds-color-border) 80%, transparent 100%);
  box-shadow: 1px 0 0 color-mix(in srgb, var(--ds-color-bg-elevated) 4%, transparent);
}

/* ---- search field: fluid with a 476px cap, ceding before the actions ---- */
.ds-structure.ds-table-toolbar [data-part='root'] .ds-table-toolbar__search-field {
  position: relative;
  flex: 0 1 auto;
  inline-size: 100%;
  max-inline-size: 476px;
  min-inline-size: 160px;
}

.ds-structure.ds-table-toolbar
  .ds-table-toolbar__search-field
  > .ds-table-toolbar__search-icon[data-part='search-icon'] {
  position: absolute;
  inset-inline-start: 10px;
  top: 50%;
  inline-size: 15px;
  block-size: 15px;
  pointer-events: none;
  transform: translateY(-50%);
  color: var(--ds-color-text-muted);
  transition: color var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out);
}
.ds-structure.ds-table-toolbar
  .ds-table-toolbar__search-field:focus-within
  > .ds-table-toolbar__search-icon[data-part='search-icon'] {
  color: var(--ds-color-text-secondary);
}

/* Search typography: the supporting step of the system scale, on the exact
 * paint node per engine — the native input inside the modern wrapper, and
 * the rustic shell which IS the input root. */
.ds-structure.ds-table-toolbar
  .ds-table-toolbar__search-field
  .ds-table-toolbar__search-input
  .rottay-input,
.ds-structure.ds-table-toolbar
  .ds-table-toolbar__search-field
  .ds-table-toolbar__search-input.rottay-input {
  font-size: var(--ds-type-supporting-font-size, 0.8125rem);
}

/* Search field surface + the icon's inline-start inset (drained from the
 * engine's inline paddingInlineStart) on the same per-engine paint nodes. */
.ds-structure.ds-table-toolbar
  .ds-table-toolbar__search-field
  > .ds-table-toolbar__search-icon[data-part='search-icon']
  + .ds-table-toolbar__search-input:has(> .rottay-input.rottay-input--modern[data-part='root']),
.ds-structure.ds-table-toolbar
  .ds-table-toolbar__search-field
  > .ds-table-toolbar__search-icon[data-part='search-icon']
  + div
  > .ds-table-toolbar__search-input.rottay-input.rottay-input--rustic[data-part='root'] {
  padding-inline-start: 32px;
  background: var(--ds-color-bg-secondary);
  border: 1px solid var(--ds-color-border);
}

/* ---- narrow containers: the row wraps and search takes the full width ---- */
@container (max-width: 40rem) {
  .ds-structure.ds-table-toolbar [data-part='root'] .ds-table-toolbar__row {
    flex-wrap: wrap;
    row-gap: 8px;
  }
  .ds-structure.ds-table-toolbar [data-part='root'] .ds-table-toolbar__search-field {
    flex: 1 1 100%;
    max-inline-size: 100%;
  }
}

/* ---- forced colors: system colors only — the hairlines re-express as
        ButtonText and the search icon follows the field ink. ---- */
@media (forced-colors: active) {
  .ds-structure.ds-table-toolbar[data-part='root'][data-structure='table-toolbar'] {
    border-color: ButtonText;
  }
  .ds-structure.ds-table-toolbar .ds-table-toolbar__divider[data-part='divider'] {
    background: ButtonText;
    box-shadow: none;
  }
  .ds-structure.ds-table-toolbar
    .ds-table-toolbar__search-field
    > .ds-table-toolbar__search-icon[data-part='search-icon'] {
    color: CanvasText;
  }
}

/* Reduced motion: the only animated channel is the icon color cross-fade. */
@media (prefers-reduced-motion: reduce) {
  .ds-structure.ds-table-toolbar
    .ds-table-toolbar__search-field
    > .ds-table-toolbar__search-icon[data-part='search-icon'] {
    transition: none;
  }
}

}
@layer rottay-components {
/**
 * ViewModeSwitcher skin — engine-agnostic and deliberately unlayered.
 *
 * COMPOSITION LAW (S25): the switcher is the certified Segmented primitive
 * (scope-switcher S22 precedent — no per-option paint channel exists here).
 * The retired hand-rolled icon-buttons took with them every segment rule
 * (resting/hover/focus/selected/disabled paints) and the repeated-selector
 * budget; `segmented.css` owns option chrome, the selected state and its
 * own forced-colors contract. What this file owns: the root's recessed
 * frame (geometry drained from the engine's inline styles) and the
 * forced-colors boundary for it.
 *
 * SPECIFICITY (P-48): the root's border reaches the tenant floor (0,3,1)
 * from the two scope classes + two DISTINCT attributes (the engine stamps
 * `data-structure` for exactly this budget, headers/form S10 idiom) —
 * never a repeated `[data-part]` (4th-tanda law; the former
 * `[data-part='root']×2` is retired).
 */

/* ---- root: recessed strip frame (padding/gap drained from inline) ---- */
.ds-structure.ds-view-mode-switcher[data-part='root'] {
  display: inline-flex;
  align-items: center;
  padding: 2px;
  border-radius: 8px;
  background: var(--ds-color-bg-primary);
}
.ds-structure.ds-view-mode-switcher[data-part='root'][data-structure='view-mode-switcher'] {
  border: 1px solid var(--ds-color-border-secondary);
}

/* forced-colors: the recessed fill is forced away, so the strip keeps a
   system boundary; the composed Segmented owns the selected segment's
   forced-colors state. */
@media (forced-colors: active) {
  .ds-structure.ds-view-mode-switcher[data-part='root'] {
    border-color: ButtonText;
    background: Canvas;
  }
}

}

/* WO-SKIN-06 CK-H2: misc patterns paint from layered skins. */
@layer rottay-engines {
/**
 * Modern FileManager skin (WO-SKIN-06 checkpoint CK-H2; Lote-2 composition uplift).
 *
 * DELIBERATELY UNLAYERED (P-47): layered component rules sort before
 * Tailwind's base layer. Real border colours use the two scope classes plus
 * a private ownership class and repeated part, clearing the tenant border
 * floor at (0,3,1).
 *
 * COMPOSITION LAW (Lote 2): the pattern COMPOSES public DS primitives —
 * Button (toolbar / view-toggle / item actions), Checkbox (row selection),
 * Spinner (loading), Empty (empty state) and Breadcrumb (navigation trail,
 * PT12: the hand-rolled ul/li and its `li + li::before` separator are
 * retired — the primitive owns the nav landmark, separator icon, crumb
 * interaction and aria-current) — which own their own chrome, density,
 * states and skins. This stylesheet paints only what the PATTERN owns:
 * layout geometry, the breadcrumb slot, the folder-link affordance, the
 * per-kind icon colours, the list table, the grid cards and the drop-zone
 * feedback. The former button fills, checkbox sizing and spinner ring are
 * retired (duplication).
 *
 * The normal root keeps `background`, `borderRadius`, and `boxShadow` inline.
 * Its local defaults follow the caller's style spread and intentionally win;
 * moving them to CSS would reverse that public precedence contract.
 *
 * The list row's DaisyUI `active` class remains the sole owner of its
 * class-driven behavior. SVG fill and stroke presentation attributes also
 * remain on their original elements.
 *
 * RESPONSIVE: the root is the named container `ds-file-manager`; the grid
 * column cuts are container queries (the composition defines the cut, not
 * viewport breakpoints — spec section 13).
 */

/* ---- root: named container (the composition defines the cut) ---- */
.ds-pattern-file-manager.ds-engine-modern[data-part='root'] {
  container: ds-file-manager / inline-size;
}

/* ---- loading root: centered Spinner frame (Spinner owns ring + cadence) ---- */
.ds-pattern-file-manager.ds-engine-modern[data-part='root'][data-loading='true'] {
  display: flex;
  align-items: center;
  justify-content: center;
  padding-block: var(--ds-spacing-12, 3rem);
}

/* ---- body ---- */
.ds-pattern-file-manager.ds-engine-modern [data-part='body'] {
  padding: var(--ds-spacing-4);
}

/* ---- toolbar ---- */
.ds-pattern-file-manager.ds-engine-modern [data-part='toolbar'] {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ds-spacing-3);
  margin-block-end: var(--ds-spacing-4);
}
.ds-pattern-file-manager.ds-engine-modern [data-part='toolbar-actions'] {
  display: flex;
  align-items: center;
  gap: var(--ds-spacing-2);
}

/* ---- breadcrumb slot: the composed Breadcrumb primitive (P76) owns the
        nav landmark, separator, crumb paint and aria-current; the pattern
        keeps only the flex slot so the trail can shrink inside the toolbar
        instead of crushing the actions. ---- */
.ds-pattern-file-manager.ds-engine-modern [data-part='breadcrumb'] {
  min-inline-size: 0;
}

/* ---- behavior-only file input (the pinned testid chrome): never visible ---- */
.ds-pattern-file-manager.ds-engine-modern [data-part='file-input'] {
  display: none;
}

/* ---- name cell + row actions: geometry drained from the retired Tailwind
        utilities (flex items-center gap-2 / flex gap-1) ---- */
.ds-pattern-file-manager.ds-engine-modern [data-part='name-cell'] {
  display: flex;
  align-items: center;
  gap: var(--ds-spacing-2);
  min-inline-size: 0;
}
.ds-pattern-file-manager.ds-engine-modern [data-part='item-actions'] {
  display: flex;
  gap: var(--ds-spacing-1);
}
.ds-pattern-file-manager.ds-engine-modern [data-part='file-name'] {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---- folder anchor: the retired `link link-hover` affordance, owned here.
        The anchor carries no `href`, so the resting colour must be declared --
        preflight leaves a hrefless <a> at `inherit`. The colour resolves
        through `--ds-color-link`, the same token the bridge's
        `--ds-link-color` fed from, so tenant white-labelling is unchanged. ---- */
.ds-pattern-file-manager.ds-engine-modern .ds-file-manager__folder-link[data-part='folder-link'] {
  cursor: pointer;
  color: var(--ds-file-manager-link-color, var(--ds-color-link, var(--ds-color-primary)));
  text-decoration-line: none;
  text-decoration-thickness: var(--ds-link-underline-thickness, 1px);
  text-underline-offset: var(--ds-link-underline-offset, 2px);
  transition: color var(--ds-motion-fast) var(--ds-motion-ease-out);
}

/* Underline reveals only where hovering is a real input mode. */
@media (hover: hover) {
  .ds-pattern-file-manager.ds-engine-modern
    .ds-file-manager__folder-link[data-part='folder-link']:hover {
    color: var(--ds-file-manager-link-hover-color, var(--ds-color-link-hover, var(--ds-color-primary-hover)));
    text-decoration-line: underline;
  }
}

.ds-pattern-file-manager.ds-engine-modern .ds-file-manager__folder-link[data-part='folder-link']:focus {
  outline-style: none;
}

.ds-pattern-file-manager.ds-engine-modern .ds-file-manager__folder-link[data-part='folder-link']:focus-visible {
  outline: none;
  box-shadow: var(--ds-shadow-focus-ring);
}

/* ---- item-action tones: the composed ghost Buttons keep their chrome; the
        pattern owns only the semantic tone of each action label. ---- */
.ds-pattern-file-manager.ds-engine-modern [data-part='item-action'][data-action='rename'] {
  color: var(--ds-color-text-primary);
}
.ds-pattern-file-manager.ds-engine-modern [data-part='item-action'][data-action='delete'] {
  color: var(--ds-color-error);
}

/* ---- per-kind icon colours + sizes (moved off the retired h-* utilities) ---- */
.ds-pattern-file-manager.ds-engine-modern .ds-file-manager__folder-icon[data-part='folder-icon'],
.ds-pattern-file-manager.ds-engine-modern .ds-file-manager__file-icon[data-part='file-icon'] {
  display: inline-flex;
  flex-shrink: 0;
  inline-size: 1.25rem;
  block-size: 1.25rem;
}
.ds-pattern-file-manager.ds-engine-modern .ds-file-manager__folder-icon[data-part='folder-icon'] > svg,
.ds-pattern-file-manager.ds-engine-modern .ds-file-manager__file-icon[data-part='file-icon'] > svg {
  inline-size: 100%;
  block-size: 100%;
}
.ds-pattern-file-manager.ds-engine-modern .ds-file-manager__folder-icon[data-part='folder-icon'][data-file-kind='folder'] {
  color: var(--ds-color-warning);
}
.ds-pattern-file-manager.ds-engine-modern .ds-file-manager__file-icon[data-part='file-icon'][data-file-kind='image'] {
  color: var(--ds-color-info);
}
.ds-pattern-file-manager.ds-engine-modern .ds-file-manager__file-icon[data-part='file-icon'][data-file-kind='pdf'] {
  color: var(--ds-color-error);
}
.ds-pattern-file-manager.ds-engine-modern .ds-file-manager__file-icon[data-part='file-icon'][data-file-kind='text'] {
  color: var(--ds-color-success);
}
.ds-pattern-file-manager.ds-engine-modern .ds-file-manager__file-icon[data-part='file-icon'][data-file-kind='other'] {
  color: var(--ds-color-text-secondary);
}

/* ---- drop zone: quiet drag-over affordance (fill tint + hairline, no
        dashed chrome) gated on having an upload handler at all ---- */
.ds-pattern-file-manager.ds-engine-modern [data-part='content'] {
  min-block-size: var(--ds-file-manager-content-min-height, 12.5rem);
  border-radius: var(--ds-radius-md);
  transition:
    background-color var(--ds-motion-fast) var(--ds-motion-ease-out),
    box-shadow var(--ds-motion-fast) var(--ds-motion-ease-out);
}
.ds-pattern-file-manager.ds-engine-modern [data-part='content'][data-drag-over='true'] {
  background: color-mix(in srgb, var(--ds-color-primary) 6%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ds-color-primary) 45%, transparent);
}

/* ---- empty state: the composed Empty primitive owns visual + copy paint ---- */
.ds-pattern-file-manager.ds-engine-modern [data-part='empty'] {
  display: flex;
  justify-content: center;
  padding-block: var(--ds-spacing-12, 3rem);
}

/* ---- list view ---- */
.ds-pattern-file-manager.ds-engine-modern [data-part='list-scroll'] {
  overflow-x: auto;
}
.ds-pattern-file-manager.ds-engine-modern [data-part='list-table'] {
  inline-size: 100%;
  border-collapse: collapse;
  font-size: var(--ds-font-size-sm);
}
.ds-pattern-file-manager.ds-engine-modern [data-part='list-table'] th {
  padding-block: var(--ds-spacing-2);
  padding-inline: var(--ds-spacing-2);
  color: var(--ds-color-text-secondary);
  font-weight: var(--ds-font-weight-semibold);
  text-align: start;
}
.ds-pattern-file-manager.ds-engine-modern [data-part='list-table'] td {
  padding-block: var(--ds-spacing-2);
  padding-inline: var(--ds-spacing-2);
}
.ds-pattern-file-manager.ds-engine-modern [data-part='list-table'] [data-part='column-select'] {
  inline-size: 2.5rem;
}
.ds-pattern-file-manager.ds-engine-modern [data-part='checkbox'] {
  display: inline-flex;
}

/* ---- grid view: 2 columns, widening by container cut (was viewport
        sm:/md: utilities). ---- */
.ds-pattern-file-manager.ds-engine-modern [data-part='grid'] {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--ds-spacing-3);
}
@container ds-file-manager (min-width: 40rem) {
  .ds-pattern-file-manager.ds-engine-modern [data-part='grid'] {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
@container ds-file-manager (min-width: 48rem) {
  .ds-pattern-file-manager.ds-engine-modern [data-part='grid'] {
    grid-template-columns: repeat(6, minmax(0, 1fr));
  }
}
/* Narrow containers: cards go full-width so names and the press target
   never crush (mobile law — actions stay visible, nothing hover-gated). */
@container ds-file-manager (max-width: 22rem) {
