      color-mix(in srgb, var(--ds-color-primary) 6%, transparent);
  }
}
.ds-collection-page-size-control:focus-within {
  border-color: color-mix(
    in srgb,
    var(--ds-color-primary) 42%,
    var(--ds-color-border-secondary)
  );
