      color-mix(in srgb, var(--ds-color-primary) 12%, transparent),
    0 8px 18px color-mix(in srgb, var(--ds-color-primary) 7%, transparent);
}
.ds-collection-page-size-control__picker {
  transition: border-color var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out),
