  font-weight: var(--ds-font-weight-bold, 700);
  letter-spacing: 0.03em;
  line-height: 1;
  white-space: nowrap;
  color: color-mix(in srgb, var(--ds-color-text-muted) 88%, white 12%);
}

/* -------------------------------------------------------------------------
   Context + stats slots (collapsible). Collapse motion uses the slow/normal
   channels; the geometry lives entirely here (never inline).
   ------------------------------------------------------------------------- */
.ds-surface.ds-collection-workspace
  .ds-collection-workspace__context-slot[data-part="context-slot"] {
  background: var(--ds-surface-card);
  border-bottom: 1px solid var(--ds-color-border-subtle);
  transition: max-height var(--ds-motion-normal, 200ms) var(--ds-motion-ease-out, ease-out),
    opacity var(--ds-motion-normal, 200ms) var(--ds-motion-ease-out, ease-out),
    padding var(--ds-motion-normal, 200ms) var(--ds-motion-ease-out, ease-out);
}

.ds-surface.ds-collection-workspace.ds-collection-shell
  .ds-collection-workspace__context-slot[data-part="context-slot"] {
  background: transparent;
  border-bottom: none;
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__context-slot[data-part="context-slot"][data-collapsed="false"] {
  padding-block-end: var(--ds-spacing-3, 12px);
  padding-inline: var(--ds-spacing-4, 16px);
  margin-block-start: calc(var(--ds-spacing-1, 4px) * 0.5);
  max-block-size: calc(var(--ds-spacing-20, 80px) * 4);
  overflow: visible;
  pointer-events: auto;
  opacity: 1;
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__context-slot[data-part="context-slot"][data-collapsed="false"][data-masthead="true"] {
  padding-inline: var(--ds-spacing-5, 20px);
  margin-block-start: 0;
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__context-slot[data-part="context-slot"][data-collapsed="true"] {
  padding: 0;
  margin-block-start: 0;
  max-block-size: 0;
  overflow: hidden;
  pointer-events: none;
  opacity: 0;
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__stats-slot[data-part="stats-slot"] {
  transition: max-height var(--ds-motion-slow, 320ms) var(--ds-motion-ease-in-out, ease-in-out),
    opacity var(--ds-motion-slow, 320ms) var(--ds-motion-ease-in-out, ease-in-out),
    padding var(--ds-motion-slow, 320ms) var(--ds-motion-ease-in-out, ease-in-out);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__stats-slot[data-part="stats-slot"][data-collapsed="false"] {
  padding: 14px 16px 10px;
  max-height: none;
  overflow: visible;
  pointer-events: auto;
  opacity: 1;
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__stats-slot[data-part="stats-slot"][data-collapsed="true"] {
  padding: 0;
  max-height: 0;
  overflow: hidden;
  pointer-events: none;
  opacity: 0;
}

/* -------------------------------------------------------------------------
   Toolbar row + controls rail (strip swap choreography).
   ------------------------------------------------------------------------- */
.ds-surface.ds-collection-workspace
  .ds-collection-workspace__toolbar-row[data-part="toolbar-row"] {
  position: relative;
  isolation: isolate;
  z-index: 4;
  overflow: visible;
  padding-block-start: calc(var(--ds-spacing-1, 4px) * 1.5);
  padding-inline: var(--ds-spacing-4, 16px);
  container: ds-collection-toolbar / inline-size;
  border-top: 1px solid
    color-mix(in srgb, var(--ds-color-border-subtle) 30%, transparent);
}

.ds-surface.ds-collection-workspace.ds-collection-shell
  .ds-collection-workspace__toolbar-row[data-part="toolbar-row"] {
  border-top: 1px solid
    color-mix(in srgb, var(--ds-color-border-subtle) 16%, transparent);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__controls-row[data-part="controls-row"] {
  min-block-size: var(--ds-spacing-9, 36px);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__controls-rail[data-part="controls-rail"] {
  position: relative;
  z-index: 1;
  min-inline-size: 0;
  overflow: hidden;
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__controls-rail[data-part="controls-rail"][data-filters-expanded="true"] {
  z-index: 2;
  overflow: visible;
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__strip-host[data-part="strip-host"] {
  position: relative;
  min-block-size: var(--ds-spacing-11, 44px);
  overflow: visible;
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__views-strip[data-part="views-strip"] {
  overflow: hidden;
  transition: max-height var(--ds-motion-normal, 200ms) var(--ds-motion-ease-out, ease-out),
    opacity var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out),
    transform var(--ds-motion-normal, 200ms) var(--ds-motion-ease-out, ease-out);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__views-strip[data-part="views-strip"][data-active="true"] {
  max-block-size: var(--ds-spacing-12, 48px);
  opacity: 1;
  transform: translateY(0);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__views-strip[data-part="views-strip"][data-active="false"] {
  max-block-size: 0;
  opacity: 0;
  transform: translateY(-8px);
  pointer-events: none;
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__views-strip-row {
  min-inline-size: 0;
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__divider[data-part="divider"] {
  inline-size: 1px;
  block-size: var(--ds-spacing-5, 20px);
  flex-shrink: 0;
  background: var(--ds-color-border-subtle);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__saved-views-host[data-part="saved-views-host"] {
  flex: 1;
  min-inline-size: 0;
  overflow: hidden;
}

/* A phone-width workspace gives scopes and saved views independent rows.
   Keeping both in one nowrap rail could collapse the saved-views host to
   almost zero while still passing document-level overflow checks. */
@container ds-collection-toolbar (max-width: 480px) {
  .ds-surface.ds-collection-workspace
    .ds-collection-workspace__views-strip[data-part="views-strip"][data-active="true"] {
    max-block-size: calc(var(--ds-spacing-12, 48px) * 2);
  }

  .ds-surface.ds-collection-workspace
    .ds-collection-workspace__saved-views-host[data-part="saved-views-host"] {
    flex: 1 1 100%;
    inline-size: 100%;
  }

  .ds-surface.ds-collection-workspace
    .ds-collection-workspace__saved-views-host[data-part="saved-views-host"]
    > .ds-pattern-saved-views[data-part="root"] {
    inline-size: 100%;
  }
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__filters-strip[data-part="filters-strip"] {
  position: relative;
  z-index: 1;
  overflow: hidden;
  transition: max-height var(--ds-motion-normal, 200ms) var(--ds-motion-ease-out, ease-out),
    opacity var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out),
    transform var(--ds-motion-normal, 200ms) var(--ds-motion-ease-out, ease-out);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__filters-strip[data-part="filters-strip"][data-active="true"] {
  z-index: 2;
  max-block-size: var(--ds-spacing-12, 48px);
  overflow: visible;
  opacity: 1;
  transform: translateY(0);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__filters-strip[data-part="filters-strip"][data-active="true"][data-phone="true"] {
  max-block-size: calc(var(--ds-spacing-12, 48px) * 2);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__filters-strip[data-part="filters-strip"][data-active="false"] {
  max-block-size: 0;
  opacity: 0;
  transform: translateY(8px);
  pointer-events: none;
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__filters-strip-row {
  min-inline-size: 0;
  padding-block: calc(var(--ds-spacing-1, 4px) * 0.5);
  overflow: visible;
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__filters-eyebrow {
  flex-shrink: 0;
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__muted-text[data-part="filters-eyebrow-text"],
.ds-surface.ds-collection-workspace
  .ds-collection-workspace__muted-text[data-part="smart-sets-label"] {
  font-size: var(--ds-font-size-xs, 12px);
  font-weight: var(--ds-font-weight-bold, 700);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  white-space: nowrap;
  color: var(--ds-color-text-muted);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__filter-count[data-part="filter-count"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-inline-size: var(--ds-spacing-5, 20px);
  block-size: var(--ds-spacing-5, 20px);
  padding-inline: var(--ds-spacing-1, 4px);
  font-size: var(--ds-font-size-xs, 12px);
  font-weight: var(--ds-font-weight-bold, 700);
  border-radius: var(--ds-radius-md, 8px);
  background: var(--ds-color-primary);
  color: var(--ds-color-text-on-primary);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__strip-scroller {
  flex: 1 1 auto;
  min-inline-size: 0;
  overflow-x: auto;
  overflow-y: visible;
  scrollbar-width: thin;
  padding-block-end: calc(var(--ds-spacing-1, 4px) * 0.5);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__filters-strip[data-phone="true"]
  .ds-collection-workspace__strip-scroller {
  overflow-x: visible;
  padding-block-end: 0;
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__muted-text[data-part="root"] {
  color: var(--ds-color-text-muted);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__filter-reset[data-part="filter-reset"] {
  flex-shrink: 0;
  color: var(--ds-color-text-muted);
}

/* -------------------------------------------------------------------------
   Smart-selection bar + selection count pill.
   ------------------------------------------------------------------------- */
.ds-surface.ds-collection-workspace
  .ds-collection-workspace__smart-selection[data-part="smart-selection"] {
  padding-block: calc(var(--ds-spacing-1, 4px) * 1.5);
  padding-inline: var(--ds-spacing-4, 16px);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__selection-count[data-part="selection-count"] {
  display: inline-flex;
  align-items: center;
  gap: var(--ds-spacing-2, 8px);
  padding-block: var(--ds-spacing-1, 4px);
  padding-inline: calc(var(--ds-spacing-2, 8px) * 1.25);
  font-size: var(--ds-font-size-xs, 12px);
  font-weight: var(--ds-font-weight-bold, 700);
  font-variant-numeric: tabular-nums;
  border-radius: 999px;
  background: color-mix(in srgb, var(--ds-color-primary) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--ds-color-primary) 20%, transparent);
  color: var(--ds-color-primary);
}

/* -------------------------------------------------------------------------
   Body region (table + preview rail host).
   ------------------------------------------------------------------------- */
.ds-surface.ds-collection-workspace
  .ds-collection-workspace__body[data-part="body"] {
  inline-size: 100%;
  padding-block-start: var(--ds-spacing-1, 4px);
  padding-block-end: var(--ds-spacing-4, 16px);
  padding-inline: var(--ds-spacing-4, 16px);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__body[data-part="body"][data-phone="true"] {
  padding-block-end: var(--ds-spacing-3, 12px);
  padding-inline: calc(var(--ds-spacing-2, 8px) * 1.25);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__content[data-surface-mode="embed"]
  .ds-collection-workspace__body[data-part="body"] {
  flex: 1 1 auto;
  min-block-size: 0;
}

/* -------------------------------------------------------------------------
   Sheets / accordion / compact actions (content wrappers only — the overlay
   chrome belongs to AdaptiveOverlay).
   ------------------------------------------------------------------------- */
.ds-surface.ds-collection-workspace
  .ds-collection-workspace__filter-sheet-content[data-part="filter-sheet-content"],
.ds-surface.ds-collection-workspace
  .ds-collection-workspace__preview-sheet-content[data-part="preview-sheet-content"],
.ds-collection-workspace__filter-dropdown-content[data-part="filter-dropdown-content"] {
  min-inline-size: 0;
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__filter-dropdown-actions[data-part="filter-dropdown-actions"] {
  margin-block-start: var(--ds-spacing-md, 16px);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__preview-accordion[data-part="preview-accordion"] {
  inline-size: 100%;
  min-inline-size: 0;
  overflow: clip;
  border: 1px solid var(--ds-color-border-secondary);
  border-radius: var(--ds-radius-lg);
  background: var(--ds-surface-card);
}

.ds-surface.ds-collection-workspace
  [data-part="preview-accordion"]
  > [data-part="trigger"] {
  min-block-size: var(--ds-size-touch-target, 44px);
  border-radius: 0;
  text-align: start;
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__preview-accordion-trigger {
  inline-size: 100%;
}

.ds-surface.ds-collection-workspace [data-part="preview-accordion-icon"] {
  flex: 0 0 auto;
  transition: transform var(--ds-motion-fast) var(--ds-motion-ease-out);
}

.ds-surface.ds-collection-workspace
  [data-part="preview-accordion"]
  > [data-part="trigger"][data-expanded="true"]
  [data-part="preview-accordion-icon"] {
  transform: rotate(180deg);
}

.ds-surface.ds-collection-workspace [data-part="preview-accordion-content"] {
  min-inline-size: 0;
  padding: 0 var(--ds-spacing-md, 16px) var(--ds-spacing-md, 16px);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__compact-action {
  min-block-size: var(--ds-size-touch-target, 44px);
  justify-content: flex-start;
}

/* -------------------------------------------------------------------------
   Sticky action dock (phone posture) — surface overrides on ActionDock.
   ------------------------------------------------------------------------- */
.ds-surface.ds-collection-workspace.ds-collection-workspace__sticky-action-bar.rottay-action-dock[data-mode="sticky"] {
  background: var(--ds-color-bg-primary);
  border-top: 1px solid var(--ds-color-border-secondary);
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__muted-text[data-part="dock-selection-count"] {
  flex-shrink: 1;
  white-space: nowrap;
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__dock-more {
  min-block-size: var(--ds-size-touch-target, 44px);
  flex: 0 0 auto;
}

.ds-surface.ds-collection-workspace
  .ds-collection-workspace__toolbar-primary-action[data-part="toolbar-primary-action"] {
  flex: 0 0 auto;
  min-inline-size: max-content;
  white-space: nowrap;
}

.ds-surface.ds-collection-workspace
  .rottay-button.ds-collection-workspace__sticky-primary-action {
  min-inline-size: 0;
  min-block-size: var(--ds-size-touch-target, 44px);
  flex: 1 1 auto;
  justify-content: center;
  background: var(--ds-color-primary);
  color: var(--ds-color-text-on-primary, #fff);
  border: none;
  border-radius: var(--ds-radius-sm, 6px);
}

/* Fixed, in-tree filter disclosure. Its standalone scope is intentional: the
   panel is a sibling of the clipped workspace shell rather than its child. */
.ds-collection-workspace__filter-dropdown[data-part="filter-dropdown-surface"][data-open="true"] {
  box-sizing: border-box;
  /* Stay on the dropdown tier so Select/DatePicker portals (mounted later on
     the same or a higher tier) can paint above this parent disclosure. */
  z-index: var(--ds-z-dropdown, var(--ds-z-index-dropdown, 1000));
  inline-size: min(
    var(--ds-collection-filter-dropdown-width, 22.5rem),
    calc(100vw - (var(--ds-spacing-3, 0.75rem) * 2))
  );
  min-inline-size: 0;
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
  padding: var(
    --ds-collection-filter-dropdown-padding,
    var(--ds-popover-padding, var(--ds-spacing-md, 1rem))
  );
  color: var(--ds-popover-content-color, var(--ds-color-text-primary));
  background: var(--ds-popover-bg, var(--ds-surface-card));
  border: 1px solid var(--ds-popover-border, var(--ds-color-border-secondary));
  border-radius: var(--ds-popover-radius, var(--ds-radius-lg));
  box-shadow: var(--ds-popover-shadow, var(--ds-elevation-3));
  -webkit-overflow-scrolling: touch;
}

.ds-collection-workspace__filter-dropdown[data-part="filter-dropdown-surface"][data-positioned="false"] {
  pointer-events: none;
  opacity: 0;
}

.ds-collection-workspace__filter-dropdown[data-part="filter-dropdown-surface"]:focus-visible {
  outline: var(--ds-focus-ring-width, 2px) solid
    var(--ds-focus-ring-color, var(--ds-color-primary));
  outline-offset: var(--ds-focus-ring-offset, 2px);
}

@supports (inline-size: 100dvw) {
  .ds-collection-workspace__filter-dropdown[data-part="filter-dropdown-surface"][data-open="true"] {
    max-inline-size: calc(100dvw - (var(--ds-spacing-3, 0.75rem) * 2));
  }
}

/* -------------------------------------------------------------------------
   Forced colors: re-key surface-owned accents with system colors (UA owns
   the palette; composed primitives already handle their own).
   ------------------------------------------------------------------------- */
@media (forced-colors: active) {
  .ds-surface.ds-collection-workspace
    .ds-collection-workspace__filter-count[data-part="filter-count"] {
    background: ButtonFace;
    color: ButtonText;
    border: 1px solid ButtonText;
  }

  .ds-surface.ds-collection-workspace
    .ds-collection-workspace__selection-count[data-part="selection-count"] {
    background: ButtonFace;
    color: ButtonText;
    border-color: ButtonText;
  }

  .ds-surface.ds-collection-workspace
    .ds-collection-workspace__utility-icon-toggle[data-part="utility-icon-toggle"][data-active="true"] {
    border-color: Highlight;
    color: Highlight;
    background: Canvas;
  }

  .ds-surface.ds-collection-workspace
    .ds-collection-preview-rail__resize-bar[data-part="preview-rail-resize-bar"] {
    background: ButtonText;
    box-shadow: none;
  }

  .ds-surface.ds-collection-workspace
    .ds-collection-preview-rail__resize[data-part="preview-rail-resize"]:focus-visible {
    outline: 2px solid Highlight;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-collection-workspace__filter-dropdown[data-part="filter-dropdown-surface"] {
    animation: none !important;
    scroll-behavior: auto;
    transition: none !important;
  }

  .ds-surface.ds-collection-workspace [data-part="preview-accordion-icon"] {
    transition: none;
  }
}

}
@layer rottay-components {
/**
 * CollectionRenderDispatch skin (WO-SKIN-06 / CK-I, SU32 pass 2026-07-30).
 *
 * LAYER: imported by the facade entrypoints into `layer(rottay-components)`
 * (sibling of collection-workspace.css).
 *
 * SCOPE: paints ONLY what the dispatch owns — the cards grid (the one view
 * mode without a pattern), its skeleton/empty frames, the fallback card, the
 * shared pagination footers and the error anatomy. Kanban and calendar are
 * composed patterns (PatternKanbanBoard / PatternCalendarView) and keep
 * their own chrome; the old hand-rolled kanban/calendar rules are gone with
 * the hand-rolled markup.
 *
 * SPECIFICITY: single class + single attribute hooks; no repetition, no
 * !important. LAYER TRUTH: typography.css sorts in `rottay-engines` (after
 * this file), so `.ds-collection-render-dispatch__muted-text` is the color
 * source only where Typography leaves the part unpainted.
 *
 * The pagination footer is intentionally preserved (replacing it with the
 * Pagination primitive is a later, contract-level refactor); its controls
 * are DS Button/Select primitives skinned here through the preserved hooks.
 */

/* Cards grid — display/padding live here; the column template, gap and
   min-card-width stay inline (instance geometry pinned by tests). */
.ds-surface.ds-collection-render-dispatch[data-part="root"][data-view-mode="cards"][data-state="ready"],
.ds-surface.ds-collection-render-dispatch[data-part="root"][data-view-mode="cards"][data-state="loading"] {
  display: grid;
  box-sizing: border-box;
  align-items: stretch;
  padding: 1px 1px var(--ds-spacing-2, 8px);
}

.ds-surface.ds-collection-render-dispatch[data-part="root"][data-view-mode="cards"][data-state="loading"] {
  padding-block: var(--ds-spacing-8, 32px);
  padding-inline: var(--ds-spacing-5, 20px);
}

.ds-surface.ds-collection-render-dispatch[data-part="root"][data-view-mode="cards"][data-state="empty"] {
  overflow: hidden;
}

.ds-surface.ds-collection-render-dispatch[data-part="root"][data-view-mode="cards"][data-state="loading"],
.ds-surface.ds-collection-render-dispatch[data-part="root"][data-view-mode="cards"][data-state="empty"] {
  border-radius: var(--ds-collection-card-radius, var(--ds-radius-xl, 16px));
  border: 1px solid var(--ds-listing-grid-empty-border, var(--ds-collection-card-border, var(--ds-color-border)));
  background: var(--ds-listing-grid-empty-bg, var(--ds-collection-card-bg, var(--ds-card-bg, var(--ds-surface-card))));
}

/* Loading skeleton mirrors the real grid (same inline template) so the swap
   does not shift layout; the Skeleton primitive owns the shimmer + RM. */
.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__skeleton-card[data-part="skeleton-card"] {
  min-block-size: calc(var(--ds-spacing-40, 160px) + var(--ds-spacing-3, 12px));
  padding: calc(var(--ds-spacing-3, 12px) + calc(var(--ds-spacing-1, 4px) * 0.5));
  border-radius: var(--ds-collection-card-radius, var(--ds-radius-lg, 12px));
  border: 1px solid var(--ds-collection-card-border, var(--ds-color-border-secondary, var(--ds-color-border)));
  background: var(--ds-collection-card-bg, var(--ds-surface-card, var(--ds-color-bg-primary)));
}

/* Visually-hidden loading announcement (aria-busy companion). */
.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__loading-label[data-part="loading-label"] {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* Error anatomy (capability inventory beside the caller-provided error). */
.ds-surface.ds-collection-render-dispatch[data-part="root"][data-state="error"] {
  display: grid;
  gap: var(--ds-spacing-4, 16px);
}

/* Card item: geometry drained from inline; state hooks already stamped. */
.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__card-item[data-part="card-item"] {
  position: relative;
  min-inline-size: 0;
  block-size: 100%;
}

.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__card-item[data-part="card-item"][data-activatable="true"] {
  cursor: pointer;
}

.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__card-item[data-part="card-item"][data-lone-final="true"] {
  grid-column: 1 / -1;
}

/* Fallback card (no app renderer provided). */
.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__fallback-card[data-part="fallback-card"] {
  display: flex;
  flex-direction: column;
  gap: var(--ds-spacing-3, 12px);
  min-block-size: calc(var(--ds-spacing-40, 160px) + var(--ds-spacing-3, 12px));
  block-size: 100%;
  box-sizing: border-box;
  overflow: hidden;
  padding: calc(var(--ds-spacing-3, 12px) + calc(var(--ds-spacing-1, 4px) * 0.5));
  border-radius: var(--ds-collection-card-radius, var(--ds-radius-lg, 12px));
  border: 1px solid var(--ds-collection-card-border, var(--ds-color-border-secondary, var(--ds-color-border)));
  background: var(--ds-collection-card-bg, var(--ds-surface-card, var(--ds-color-bg-primary)));
  box-shadow: var(--ds-collection-card-shadow, 0 10px 24px color-mix(in srgb, var(--ds-color-text-primary) 5%, transparent));
}

.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__muted-text {
  color: var(--ds-color-text-muted);
}

.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__fallback-heading {
  min-inline-size: 0;
}

.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__muted-text[data-part="fallback-label"] {
  display: block;
  margin-block-end: var(--ds-spacing-1, 4px);
  font-size: var(--ds-font-size-xs, 12px);
  font-weight: var(--ds-font-weight-extrabold, 800);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__fallback-grid[data-part="fallback-grid"]
  .ds-collection-render-dispatch__muted-text[data-part="fallback-label"] {
  font-weight: var(--ds-font-weight-bold, 700);
  letter-spacing: 0.04em;
  margin-block-end: calc(var(--ds-spacing-1, 4px) * 0.75);
}

.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__fallback-title[data-part="title"] {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--ds-color-text-primary);
}

.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__fallback-grid[data-part="fallback-grid"] {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: calc(var(--ds-spacing-2, 8px) * 1.25)
    calc(var(--ds-spacing-3, 12px) + calc(var(--ds-spacing-1, 4px) * 0.5));
  min-inline-size: 0;
}

.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__fallback-field {
  min-inline-size: 0;
}

.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__fallback-value[data-part="fallback-value"] {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--ds-color-text-secondary, var(--ds-color-text-primary));
}

.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__fallback-actions[data-part="fallback-actions"] {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ds-spacing-2, 8px);
  flex-wrap: wrap;
  margin-block-start: auto;
  padding-block-start: calc(var(--ds-spacing-2, 8px) * 1.25);
  border-top: 1px solid var(--ds-color-border-subtle, var(--ds-color-border-secondary));
}

/* Screen-reader activation overlay on activatable cards (anchor or button;
   the button variant is test-pinned and stays a native element for now). */
.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__card-item[data-part="card-item"]:has(.ds-collection-render-dispatch__card-activation[data-part="card-activation"]:focus-visible) {
  outline: var(--ds-focus-ring-width, 2px) solid var(--ds-focus-ring-color, var(--ds-color-primary));
  outline-offset: var(--ds-focus-ring-offset, 2px);
}

.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__card-activation[data-part="card-activation"] {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
  pointer-events: none;
}

/* Quiet activation feedback on activatable fallback cards: a one-pixel lift
   on hover (transform-only, motion channels) with press as the touch
   equivalent. App-rendered cards own their own chrome. */
.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__card-item[data-part="card-item"][data-activatable="true"]
  .ds-collection-render-dispatch__fallback-card[data-part="fallback-card"] {
  transition: transform var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out),
    box-shadow var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out),
    border-color var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out);
}

@media (hover: hover) {
  .ds-surface.ds-collection-render-dispatch
    .ds-collection-render-dispatch__card-item[data-part="card-item"][data-activatable="true"]:hover
    .ds-collection-render-dispatch__fallback-card[data-part="fallback-card"] {
    transform: translateY(-1px);
    border-color: color-mix(in srgb, var(--ds-color-primary) 22%, var(--ds-color-border-secondary, var(--ds-color-border)));
    box-shadow: var(--ds-collection-card-shadow-hover, 0 14px 28px color-mix(in srgb, var(--ds-color-text-primary) 7%, transparent));
  }
}

.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__card-item[data-part="card-item"][data-activatable="true"]:active
  .ds-collection-render-dispatch__fallback-card[data-part="fallback-card"] {
  transform: translateY(0);
}

/* Fallback "Open details" affordance: skinned identically whether it renders
   as the native anchor or as the DS Button replacement. */.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__fallback-open-link[data-part="fallback-open-link"] {
  display: inline-flex;
  align-items: center;
  min-block-size: var(--ds-size-touch-target, 44px);
  padding-inline: var(--ds-spacing-sm, 8px);
  color: var(--ds-color-primary);
  font-family: inherit;
  font-size: var(--ds-font-size-sm, 0.875rem);
  font-weight: var(--ds-font-weight-semibold, 600);
  text-decoration: none;
  background: transparent;
  border: 0;
  border-radius: var(--ds-radius-sm, 6px);
  cursor: pointer;
}

.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__fallback-open-link[data-part="fallback-open-link"]:focus-visible {
  outline: var(--ds-focus-ring-width, 2px) solid var(--ds-focus-ring-color, var(--ds-color-primary));
  outline-offset: var(--ds-focus-ring-offset, 2px);
}

/* Pagination footer (hand-rolled, preserved; controls are DS primitives). */
.ds-surface.ds-collection-render-dispatch.ds-collection-render-dispatch__pagination[data-part="pagination"] {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ds-spacing-3, 12px);
  flex-wrap: wrap;
  padding: var(--ds-spacing-3, 12px) var(--ds-spacing-4, 16px);
  margin-block-start: var(--ds-spacing-4, 16px);
  border-radius: var(--ds-radius-lg, 12px);
  border: 1px solid var(--ds-color-border, var(--ds-color-border-secondary));
  background: var(--ds-color-bg-primary, var(--ds-surface-card));
}

.ds-surface.ds-collection-render-dispatch
  .ds-collection-render-dispatch__pagination-controls[data-part="pagination-controls"] {
  display: flex;
  align-items: center;
  gap: var(--ds-spacing-2, 8px);
  flex-wrap: wrap;
}

.ds-surface.ds-collection-render-dispatch.ds-collection-render-dispatch__pagination[data-part="pagination"]
  :is(.ds-collection-render-dispatch__pagination-prev, .ds-collection-render-dispatch__pagination-next) {
  border-radius: var(--ds-radius-md, 8px);
}

.ds-surface.ds-collection-render-dispatch.ds-collection-render-dispatch__pagination[data-part="pagination"]
  :is(.ds-collection-render-dispatch__pagination-prev, .ds-collection-render-dispatch__pagination-next)[data-disabled="true"] {
  opacity: 0.45;
}

.ds-surface.ds-collection-render-dispatch.ds-collection-render-dispatch__pagination[data-part="pagination"]
  .ds-collection-render-dispatch__page-size[data-part="page-size"] {
  display: flex;
  align-items: center;
  gap: var(--ds-spacing-2, 8px);
  font-size: var(--ds-font-size-sm, 0.875rem);
  color: var(--ds-color-text-muted);
}

.ds-surface.ds-collection-render-dispatch.ds-collection-render-dispatch__pagination[data-part="pagination"]
  .ds-collection-render-dispatch__page-size-select {
  display: inline-flex;
}

/* Incremental footer (cards load-more sentinel). */
.ds-surface.ds-collection-render-dispatch.ds-collection-render-dispatch__incremental-footer[data-part="incremental-footer"] {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: calc(var(--ds-spacing-2, 8px) * 1.25);
  min-block-size: calc(var(--ds-spacing-12, 48px) + calc(var(--ds-spacing-1, 4px) * 1.5));
  margin-block-start: var(--ds-spacing-4, 16px);
  font-size: var(--ds-font-size-xs, 12px);
  font-weight: var(--ds-font-weight-semibold, 600);
  color: var(--ds-color-text-muted);
}

.ds-surface.ds-collection-render-dispatch.ds-collection-render-dispatch__incremental-footer[data-part="incremental-footer"]
  .ds-collection-render-dispatch__incremental-count[data-part="incremental-count"],
.ds-surface.ds-collection-render-dispatch.ds-collection-render-dispatch__incremental-footer[data-part="incremental-footer"]
  .ds-collection-render-dispatch__incremental-end[data-part="incremental-end"] {
  font-size: var(--ds-font-size-xs, 12px);
  color: inherit;
}

.ds-surface.ds-collection-render-dispatch.ds-collection-render-dispatch__incremental-footer[data-part="incremental-footer"]
  .ds-collection-render-dispatch__incremental-count[data-part="incremental-count"] {
  font-variant-numeric: tabular-nums;
}

.ds-surface.ds-collection-render-dispatch.ds-collection-render-dispatch__incremental-footer[data-part="incremental-footer"]
  .ds-collection-render-dispatch__load-more[data-part="load-more"] {
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--ds-color-primary) 24%, var(--ds-color-border-secondary));
  background: color-mix(in srgb, var(--ds-color-primary) 8%, var(--ds-surface-card-bg, var(--ds-surface-card)));
  color: var(--ds-color-primary);
}

/* Forced colors: surface-owned affordances re-keyed to system colors. */
@media (forced-colors: active) {
  .ds-surface.ds-collection-render-dispatch
    .ds-collection-render-dispatch__card-item[data-part="card-item"]:has(.ds-collection-render-dispatch__card-activation[data-part="card-activation"]:focus-visible) {
    outline: 2px solid Highlight;
  }

  .ds-surface.ds-collection-render-dispatch
    .ds-collection-render-dispatch__fallback-open-link[data-part="fallback-open-link"] {
    color: LinkText;
  }

  .ds-surface.ds-collection-render-dispatch
    .ds-collection-render-dispatch__skeleton-card[data-part="skeleton-card"] {
    border-color: ButtonText;
  }
}

}
@layer rottay-components {
/**
 * CommandCenterSurface skin (WO-SKIN-06 / CK-I).
 *
 * LAYER: imported by `facade/entrypoints/base.css` and
 * `facade/entrypoints/styles.css` into `layer(rottay-components)` (the old
 * "deliberately unlayered" note predates the wiring).
 *
 * SCOPE: the surface composes Card, PatternStatsGrid, PatternActivityLog,
 * NavLink, Heading/Text and the surface state kits — each owns its chrome,
 * interaction states, focus ring and forced-colors treatment (the actionable
 * quick-action Card already paints cursor, hover lift and its transition
 * through its own `data-interactive` recipe, so this file adds none of it).
 * What remains surface-owned and is painted here: header rhythm, the
 * quick-action icon tile geometry/tint, the two layout grids and section
 * spans, the recent-activity header row, the view-all touch target, the
 * skeleton mirror's spacing, and the forced-colors re-key of the one tinted
 * part. No motion is declared in this file: entrance choreography arrives via
 * the `collection.insert` recipe (`.ds-collection-stagger`) and every other
 * transition belongs to the composed components.
 *
 * SPECIFICITY: single class (optionally + one always-stamped data attr) under
 * the surface root; no repeated classes/attributes. Logical properties only,
 * so RTL mirrors without extra rules.
 */

/* Header rhythm ------------------------------------------------------------ */

/* Text renders an inline span; block display makes the rhythm margin real
   (the inline-style margin this replaces was inert on an inline box). */
.ds-surface.ds-command-center .ds-command-center__greeting {
  display: block;
  margin-block-end: var(--ds-spacing-1, 4px);
}

/* UA heading margins are neutralized; the surface stack owns the rhythm. */
.ds-surface.ds-command-center .ds-command-center__title {
  margin-block: 0;
}

.ds-surface.ds-command-center .ds-command-center__section-heading,
.ds-surface.ds-command-center .ds-command-center__section-title {
  margin-block: 0 var(--ds-spacing-2, 8px);
}

/* Insight + quick-action tiles ---------------------------------------------- */

.ds-surface.ds-command-center .ds-command-center__insight-body,
.ds-surface.ds-command-center .ds-command-center__quick-action-body {
  flex: 1 1 0%;
  min-inline-size: 0;
}

.ds-surface.ds-command-center .ds-command-center__insight-description,
.ds-surface.ds-command-center .ds-command-center__quick-action-description {
  display: block;
  margin-block-start: var(--ds-spacing-1, 4px);
}

/* Icon tile: the one tinted part the surface owns. The 36px size is part
   geometry (4px-scale aligned), deliberately density-stable like an avatar. */
.ds-surface.ds-command-center .ds-command-center__quick-action-icon[data-part='quick-action-icon'] {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  inline-size: 36px;
  block-size: 36px;
  border-radius: var(--ds-radius-md, 8px);
  background: var(--ds-color-bg-tertiary, var(--ds-color-bg-secondary));
  color: var(--ds-color-text-secondary);
}

/* Layout grids ---------------------------------------------------------------- */

.ds-surface.ds-command-center .ds-command-center__quick-actions-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(220px, 100%), 1fr));
  gap: var(--ds-spacing-sm, 8px);
}

.ds-surface.ds-command-center .ds-command-center__sections-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(280px, 100%), 1fr));
  gap: var(--ds-spacing-md, 16px);
}

/* Spans apply only where the viewport can fit multiple columns; below the
   guard a span would create implicit tracks and overflow narrow screens. */
@media (min-width: 40em) {
  .ds-surface.ds-command-center .ds-command-center__section-card[data-span='2'] {
    grid-column: span 2;
  }

  .ds-surface.ds-command-center .ds-command-center__section-card[data-span='3'] {
    grid-column: span 3;
  }
}

/* Recent activity header row ---------------------------------------------------- */

.ds-surface.ds-command-center .ds-command-center__recent-activity-header {
  margin-block-end: var(--ds-spacing-sm, 8px);
}

.ds-surface.ds-command-center .ds-command-center__recent-activity-title {
  flex: 1 1 0%;
  min-inline-size: 0;
  margin-block: 0;
}

/* Touch: the quiet view-all link reaches the 44px coarse-pointer hit area via
   box growth, never by inflating its visual size. */
@media (pointer: coarse) {
  .ds-surface.ds-command-center .ds-command-center__view-all {
    display: inline-flex;
    align-items: center;
    min-block-size: 44px;
  }
}

/* Skeleton mirror -------------------------------------------------------------- */

.ds-surface.ds-command-center .ds-command-center__skeleton-grow {
  flex: 1 1 0%;
  min-inline-size: 0;
}

.ds-surface.ds-command-center .ds-command-center__skeleton-greeting {
  margin-block-end: var(--ds-spacing-2, 8px);
}

.ds-surface.ds-command-center .ds-command-center__skeleton-heading {
  margin-block-end: var(--ds-spacing-3, 12px);
}

.ds-surface.ds-command-center .ds-command-center__skeleton-line {
  margin-block-start: var(--ds-spacing-2, 8px);
}

.ds-surface.ds-command-center .ds-command-center__skeleton-body {
  margin-block-start: var(--ds-spacing-3, 12px);
}

/* Forced colors ------------------------------------------------------------------ */

/* Re-key the only surface-owned tint to system colors; every composed part
   (Card, NavLink, Button, StatsGrid, ActivityLog) already handles its own. */
@media (forced-colors: active) {
  .ds-surface.ds-command-center .ds-command-center__quick-action-icon[data-part='quick-action-icon'] {
    background: ButtonFace;
    color: ButtonText;
  }
}

}
@layer rottay-components {
/**
 * DecisionInboxSurface skin (WO-SKIN-06 / CK-I, SU34 pass 2026-07-30).
 *
 * LAYER: imported by `facade/entrypoints/base.css` and
 * `facade/entrypoints/styles.css` into `layer(rottay-components)`.
 *
 * SCOPE: paints ONLY what the surface owns — the queue header spacing, the
 * selection (batch) bar accent, the drained skeleton geometry, the
 * content/rail layout switch (mobile column vs desktop row + sticky review
 * card), the reason-field geometry and the divider hairlines. Composed
 * primitives/patterns (PatternDataTable, PatternFilterPanel, Card, Button,
 * Textarea, Badge, Skeleton, SurfaceEmptyState) keep their own chrome.
 *
 * SPECIFICITY: single class + single attribute hooks; no repetition, no
 * !important. LAYER TRUTH (same as list.css): typography.css sorts in
 * `rottay-engines` (after this file), so wherever the Typography skin paints
 * a color it governs regardless of selector weight here; the
 * `__muted-text` rule is the color source only where Typography leaves the
 * part unpainted.
 *
 * MOTION: no motion owned by this surface (mount/dismount only; the motion
 * authority owns cadence through the composed primitives).
 */

/* -------------------------------------------------------------------------- */
/* Queue header                                                                */
/* -------------------------------------------------------------------------- */

.ds-surface.ds-decision-inbox .ds-decision-inbox__muted-text[data-part='root'] {
  color: var(--ds-color-text-muted);
}

.ds-surface.ds-decision-inbox .ds-decision-inbox__subtitle[data-part='root'] {
  display: block;
  margin-block-start: var(--ds-spacing-xs, 4px);
}

/* -------------------------------------------------------------------------- */
/* Loading skeleton (geometry drained from inline styles)                      */
/* -------------------------------------------------------------------------- */

/* Visually-hidden live label beside aria-busy (sr-only idiom, same as
   collection-workspace-render-dispatch.css). */
.ds-surface.ds-decision-inbox .ds-decision-inbox__loading-label[data-part='loading-label'] {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.ds-surface.ds-decision-inbox .ds-decision-inbox__skeleton-subtitle {
  display: block;
  margin-block-start: var(--ds-spacing-2, 8px);
}

.ds-surface.ds-decision-inbox .ds-decision-inbox__divider[data-part='divider'][data-divider-kind='skeleton-header'] {
  padding-block-end: var(--ds-spacing-sm, 8px);
  border-block-end: 1px solid var(--ds-color-border-secondary);
}

.ds-surface.ds-decision-inbox .ds-decision-inbox__divider[data-part='divider'][data-divider-kind='skeleton-row'] {
  padding-block: var(--ds-spacing-sm, 8px);
  border-block-end: 1px solid var(--ds-color-border-subtle, var(--ds-color-border-secondary));
}

/* -------------------------------------------------------------------------- */
/* Selection (batch) bar                                                       */
/* -------------------------------------------------------------------------- */

.ds-surface.ds-decision-inbox .ds-decision-inbox__selection-bar[data-part='root'] {
  border-color: var(--ds-color-primary);
  background: var(--ds-color-primary-bg, var(--ds-color-bg-tertiary));
}

.ds-surface.ds-decision-inbox .ds-decision-inbox__selection-spacer {
  flex: 1 1 auto;
}

.ds-surface.ds-decision-inbox .ds-decision-inbox__batch-reason {
  min-inline-size: 200px;
  max-inline-size: 320px;
  inline-size: 100%;
}

/* -------------------------------------------------------------------------- */
/* Content layout: column on mobile, row + review rail on desktop              */
/* -------------------------------------------------------------------------- */

.ds-surface.ds-decision-inbox .ds-decision-inbox__content[data-part='content'] {
  flex-direction: column;
  align-items: stretch;
}

.ds-surface.ds-decision-inbox[data-mobile='false'] .ds-decision-inbox__content[data-part='content'] {
  flex-direction: row;
}

.ds-surface.ds-decision-inbox .ds-decision-inbox__queue[data-part='queue'] {
  flex: 1 1 0%;
  min-inline-size: 0;
}

.ds-surface.ds-decision-inbox .ds-decision-inbox__review-rail[data-part='review-rail'] {
  inline-size: 100%;
  flex-shrink: 0;
}

/* The caller-supplied rail width arrives through a private runtime-instance
   bridge for the existing `reviewRail.width` prop. It is not a public hook. */
.ds-surface.ds-decision-inbox[data-mobile='false'] .ds-decision-inbox__review-rail[data-part='review-rail'] {
  inline-size: var(--_ds-instance-decision-inbox-rail-width, 380px);
}

.ds-surface.ds-decision-inbox .ds-decision-inbox__review-card {
  position: relative;
}

.ds-surface.ds-decision-inbox[data-mobile='false'] .ds-decision-inbox__review-card {
  position: sticky;
  inset-block-start: var(--ds-spacing-md, 16px);
}

/* -------------------------------------------------------------------------- */
/* Review rail parts                                                           */
/* -------------------------------------------------------------------------- */

.ds-surface.ds-decision-inbox .ds-decision-inbox__divider[data-part='divider'][data-divider-kind='review-rail'] {
  block-size: 1px;
  background: var(--ds-color-border-secondary);
}

.ds-surface.ds-decision-inbox .ds-decision-inbox__reason-label[data-part='root'] {
  display: block;
  margin-block-end: var(--ds-spacing-xs, 4px);
}

.ds-surface.ds-decision-inbox .ds-decision-inbox__review-reason {
  inline-size: 100%;
}

.ds-surface.ds-decision-inbox .ds-decision-inbox__decision-action {
  flex: 1 1 0%;
}

/* Touch law: decision actions reach the 44px hit floor on coarse pointers
   without inflating the visual size on fine pointers. */
@media (pointer: coarse) {
  .ds-surface.ds-decision-inbox .ds-decision-inbox__decision-action {
    min-block-size: 44px;
  }
}

/* -------------------------------------------------------------------------- */
/* Forced colors: re-key the surface-owned paint onto system colors            */
/* -------------------------------------------------------------------------- */

@media (forced-colors: active) {
  .ds-surface.ds-decision-inbox .ds-decision-inbox__selection-bar[data-part='root'] {
    border-color: Highlight;
    background: Canvas;
  }

  .ds-surface.ds-decision-inbox .ds-decision-inbox__divider[data-part='divider'] {
    background: ButtonBorder;
    border-color: ButtonBorder;
  }
}

