  flex: 1 1 0%;
  min-inline-size: 0;
}

.ds-surface.ds-record-workbench .ds-record-workbench__identity-text {
  flex: 1 1 0%;
  min-inline-size: 0;
}

.ds-surface.ds-record-workbench .ds-record-workbench__avatar {
  flex-shrink: 0;
}

.ds-surface.ds-record-workbench .ds-record-workbench__skeleton-subtitle {
  display: block;
  margin-block-start: var(--ds-spacing-2, 8px);
}

/* -------------------------------------------------------------------------- */
/* Status badge (surface-owned pill; not a composed Badge — pinned anatomy)    */
/* -------------------------------------------------------------------------- */

.ds-surface.ds-record-workbench .ds-record-workbench__status-badge[data-part='status-badge'] {
  padding-block: var(--ds-spacing-1, 4px);
  padding-inline: var(--ds-spacing-3, 12px);
