  border-radius: var(--ds-radius-full, 9999px);
  font-size: var(--ds-font-size-xs, 12px);
  font-weight: var(--ds-font-weight-medium, 500);
  line-height: 1.2;
  white-space: nowrap;
  color: var(--ds-color-text-muted);
  transition:
    color var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, cubic-bezier(0.16, 1, 0.3, 1)),
    background-color var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, cubic-bezier(0.16, 1, 0.3, 1)),
    border-color var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, cubic-bezier(0.16, 1, 0.3, 1));
