/* -------------------------------------------------------------------------- */

.ds-surface.ds-record-workbench .ds-record-workbench__content[data-part='content'] {
  flex-direction: column;
  align-items: stretch;
}

.ds-surface.ds-record-workbench[data-mobile='false'] .ds-record-workbench__content[data-part='content'] {
  flex-direction: row;
}

.ds-surface.ds-record-workbench .ds-record-workbench__tabpanel[data-part='tabpanel'] {
