/* The caller-supplied width arrives through a private runtime-instance bridge
   for the existing `sidebarWidth` prop. It is not a public hook. */
.ds-surface.ds-record-workbench[data-mobile='false'] .ds-record-workbench__sidebar[data-part='sidebar'] {
  inline-size: var(--_ds-instance-record-workbench-sidebar-width, 280px);
  padding-block-start: 0;
  padding-inline-start: var(--ds-spacing-5, 20px);
  border-block-start: none;
  border-inline-start: 1px solid var(--ds-color-border-secondary);
}

.ds-surface.ds-record-workbench .ds-record-workbench__sidebar-title[data-part='sidebar-title'] {
  display: block;
  margin-block-end: var(--ds-spacing-md, 16px);
}

.ds-surface.ds-record-workbench .ds-record-workbench__field-value {
  margin-block-start: var(--ds-spacing-1, 4px);
}

/* -------------------------------------------------------------------------- */
/* Loading: visually-hidden live label beside aria-busy (sr-only idiom, same   */
/* as decision-inbox.css)                                                      */
/* -------------------------------------------------------------------------- */

.ds-surface.ds-record-workbench .ds-record-workbench__loading-label[data-part='loading-label'] {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* -------------------------------------------------------------------------- */
/* Touch law: tabs and header actions reach the 44px hit floor on coarse       */
/* pointers without inflating the visual size on fine pointers.                */
/* -------------------------------------------------------------------------- */

@media (pointer: coarse) {
  .ds-surface.ds-record-workbench .ds-record-workbench__tab[data-active],
  .ds-surface.ds-record-workbench .ds-record-workbench__action[data-action-variant] {
    min-block-size: 44px;
  }
}

/* -------------------------------------------------------------------------- */
/* Forced colors: re-key the surface-owned paint onto system colors            */
/* -------------------------------------------------------------------------- */

@media (forced-colors: active) {
  .ds-surface.ds-record-workbench .ds-record-workbench__tab[data-active='true'] .ds-record-workbench__tab-underline[data-part='tab-underline'] {
    background: Highlight;
  }

  .ds-surface.ds-record-workbench .ds-record-workbench__tab-list[data-part='tab-list'],
  .ds-surface.ds-record-workbench .ds-record-workbench__sidebar[data-part='sidebar'] {
    border-color: ButtonBorder;
  }

  .ds-surface.ds-record-workbench .ds-record-workbench__status-badge[data-part='status-badge'] {
    border-color: ButtonBorder;
  }

  .ds-surface.ds-record-workbench .ds-record-workbench__tab-badge[data-part='tab-badge'] {
    border: 1px solid ButtonBorder;
    background: Canvas;
  }
}

