.ds-visual-excellence__signal-strip > button {
  flex: 0 0 auto;
  margin-inline-start: auto;
  margin-inline-end: var(--ds-spacing-2, 8px);
}

.ds-visual-excellence__navigation-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ds-spacing-4, 16px);
  min-height: 58px;
  padding: var(--ds-spacing-2, 8px) var(--ds-spacing-5, 20px);
  border-bottom: 1px solid var(--ds-surface-card-border, var(--ds-color-border-primary));
  background: color-mix(
    in srgb,
    var(--ds-surface-panel-bg, var(--ds-color-bg-secondary)) 46%,
    var(--ds-surface-card-bg, var(--ds-color-bg-elevated))
  );
}

.ds-visual-excellence__hero-actions {
  width: min(100%, 420px);
}

.ds-visual-excellence__tabs > [data-part="tab-panel"] {
  padding: var(--ds-spacing-4, 16px);
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--ds-layout-bg, var(--ds-color-bg-primary)) 84%, white 16%),
    var(--ds-layout-bg, var(--ds-color-bg-primary)) 320px
  );
}

.ds-visual-excellence__tabs > [data-part="tab-list"] {
  border-inline: 0 !important;
  border-radius: 0 !important;
  padding: 7px var(--ds-spacing-5, 20px) !important;
  background: color-mix(
    in srgb,
    var(--ds-surface-panel-bg, var(--ds-color-bg-secondary)) 58%,
    var(--ds-surface-card-bg, var(--ds-color-bg-elevated))
  ) !important;
  box-shadow: inset 0 -1px 0 var(--ds-surface-card-border, var(--ds-color-border-primary)) !important;
}

.ds-visual-excellence__signal-icon {
  display: inline-grid;
  place-items: center;
  font-size: var(--ds-text-body-xs-size, var(--ds-font-size-xs));
  font-style: normal;
  line-height: 1;
}

.ds-visual-excellence__stage-progress {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 4px;
}

.ds-visual-excellence__stage-progress > span {
  height: 5px;
  border-radius: 999px;
  background: var(--ds-color-border-primary);
}

.ds-visual-excellence__stage-progress > span[data-state='done'] {
  background: color-mix(in srgb, var(--ds-color-primary) 52%, var(--ds-color-border-primary));
}

.ds-visual-excellence__stage-progress > span[data-state='current'] {
  background: var(--ds-color-primary);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--ds-color-primary) 9%, transparent);
}

.ds-visual-excellence__stage-progress > small {
  grid-column: 1 / -1;
  margin-top: 4px;
  color: var(--ds-color-text-muted);
  font-size: var(--ds-text-detail-size, var(--ds-font-size-xs));
  text-align: center;
}

.ds-visual-excellence__decision-meta {
  display: grid;
  gap: 4px;
}

.ds-visual-excellence__decision-meta strong {
  color: var(--ds-color-text-primary);
  font-size: var(--ds-font-size-sm, 14px);
}

.ds-visual-excellence__journey,
.ds-visual-excellence__placeholder {
  overflow: hidden;
  border: 1px solid
    var(--ds-surface-card-border, var(--ds-color-border-primary));
  border-radius: var(--ds-radius-xl, 16px);
  background: var(--ds-surface-card-bg, var(--ds-color-bg-elevated));
  box-shadow: var(--ds-shadow-sm, 0 1px 3px color-mix(in srgb, var(--ds-color-text-primary) 8%, transparent));
}

.ds-visual-excellence__section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ds-spacing-4, 16px);
  padding: var(--ds-spacing-4, 16px) var(--ds-spacing-5, 20px);
  border-bottom: 1px solid
    var(--ds-surface-card-border, var(--ds-color-border-primary));
  background: linear-gradient(
    110deg,
    color-mix(in srgb, var(--ds-color-primary) 7%, var(--ds-surface-card-bg, white)),
    var(--ds-surface-card-bg, var(--ds-color-bg-elevated)) 52%,
    color-mix(in srgb, var(--ds-surface-panel-bg, var(--ds-color-bg-secondary)) 72%, white)
  );
  box-shadow: inset 0 1px 0 color-mix(in srgb, white 72%, transparent);
}

.ds-visual-excellence__journey-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.ds-visual-excellence__journey-stage {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: var(--ds-spacing-3, 12px);
  min-width: 0;
  padding: var(--ds-spacing-4, 16px) var(--ds-spacing-5, 20px);
  border-inline-end: 1px solid
    var(--ds-surface-card-border, var(--ds-color-border-primary));
}

.ds-visual-excellence__journey-stage:last-child {
  border-inline-end: 0;
}

.ds-visual-excellence__journey-stage[data-state="current"] {
  background: color-mix(
    in srgb,
    var(--ds-color-primary) 8%,
    var(--ds-surface-card-bg, var(--ds-color-bg-elevated))
  );
  box-shadow: inset 0 3px 0 var(--ds-color-primary);
}

.ds-visual-excellence__journey-index {
  display: grid;
  width: 24px;
  height: 24px;
  place-items: center;
  border: 1px solid
    var(--ds-surface-card-border-strong, var(--ds-color-border-secondary));
  border-radius: 999px;
  background: var(--ds-surface-card-bg, var(--ds-color-bg-elevated));
  color: var(--ds-color-text-secondary);
  font-size: var(--ds-font-size-xs, 12px);
  font-weight: var(--ds-font-weight-semibold, 600);
}

.ds-visual-excellence__journey-stage[data-state="current"]
  .ds-visual-excellence__journey-index {
  border-color: var(--ds-color-primary);
  background: var(--ds-color-primary);
  color: var(--ds-button-primary-color, #fff);
  box-shadow: 0 0 0 4px
    color-mix(in srgb, var(--ds-color-primary) 14%, transparent);
}

.ds-visual-excellence__widget {
  min-height: 100%;
  padding: var(--ds-spacing-5, 20px);
}

.ds-visual-excellence__metric {
  justify-content: center;
}

.ds-visual-excellence__metric[data-tone="positive"] {
  background: radial-gradient(
      circle at 100% 0%,
      color-mix(in srgb, var(--ds-color-success) 9%, transparent),
      transparent 42%
    ),
    var(--ds-surface-card-bg, var(--ds-color-bg-elevated));
}

.ds-visual-excellence__metric[data-tone="warning"] {
  background: radial-gradient(
      circle at 100% 0%,
      color-mix(in srgb, var(--ds-color-warning) 10%, transparent),
      transparent 42%
    ),
    var(--ds-surface-card-bg, var(--ds-color-bg-elevated));
}

.ds-visual-excellence__intelligence {
  background: radial-gradient(
      circle at 100% 0%,
      color-mix(in srgb, var(--ds-color-primary) 8%, transparent),
      transparent 42%
    ),
    var(--ds-surface-card-bg, var(--ds-color-bg-elevated));
}

.ds-visual-excellence__recommendation {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ds-spacing-4, 16px);
  margin: auto calc(var(--ds-spacing-5, 20px) * -1)
    calc(var(--ds-spacing-5, 20px) * -1);
  padding: var(--ds-spacing-4, 16px) var(--ds-spacing-5, 20px);
  border-top: 1px solid
    var(--ds-surface-card-border, var(--ds-color-border-primary));
  background: color-mix(
    in srgb,
    var(--ds-color-success) 7%,
    var(--ds-surface-card-bg, var(--ds-color-bg-elevated))
  );
}

.ds-visual-excellence__signal-row,
.ds-visual-excellence__action-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ds-spacing-3, 12px);
  min-width: 0;
}

.ds-visual-excellence__signal-state {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 24px;
  padding-inline: 8px;
  border: 1px solid color-mix(in srgb, currentColor 18%, transparent);
  border-radius: var(--ds-radius-full);
  background: color-mix(in srgb, currentColor 7%, transparent);
  font-family: var(--ds-font-family-mono, ui-monospace, monospace);
  font-size: var(--ds-text-detail-size, var(--ds-font-size-xs));
  font-weight: var(--ds-font-weight-semibold, 600);
  white-space: nowrap;
}

.ds-visual-excellence__signal-state[data-tone='success'] {
  color: var(--ds-color-success);
}

.ds-visual-excellence__signal-state[data-tone='warning'] {
  color: var(--ds-color-warning);
}

.ds-visual-excellence__source-list {
  overflow: hidden;
  border: 1px solid var(--ds-surface-card-border, var(--ds-color-border-primary));
  border-radius: var(--ds-radius-lg, 12px);
  background: color-mix(
    in srgb,
    var(--ds-surface-panel-bg, var(--ds-color-bg-secondary)) 34%,
    var(--ds-surface-card-bg, var(--ds-color-bg-elevated))
  );
}

.ds-visual-excellence__source-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ds-spacing-3, 12px);
  padding: var(--ds-spacing-2, 8px) var(--ds-spacing-3, 12px);
  border-bottom: 1px solid var(--ds-surface-card-border, var(--ds-color-border-primary));
}

.ds-visual-excellence__source-row:last-child {
  border-bottom: 0;
}

.ds-visual-excellence__source-row > span {
  display: inline-flex;
  align-items: center;
  gap: var(--ds-spacing-2, 8px);
  color: var(--ds-color-text-primary);
  font-size: var(--ds-font-size-sm, 14px);
  font-weight: var(--ds-font-weight-medium, 500);
}

.ds-visual-excellence__source-row > span > svg {
  color: var(--ds-color-success);
}

.ds-visual-excellence__signal-row {
  padding-block: var(--ds-spacing-2, 8px);
  border-bottom: 1px solid
    var(--ds-surface-card-border, var(--ds-color-border-primary));
}

.ds-visual-excellence__signal-row:last-child,
.ds-visual-excellence__action-row:last-child {
  border-bottom: 0;
}

.ds-visual-excellence__action-list {
  overflow: hidden;
  border: 1px solid
    var(--ds-surface-card-border, var(--ds-color-border-primary));
  border-radius: var(--ds-radius-lg, 12px);
}

.ds-visual-excellence__action-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  padding: var(--ds-spacing-3, 12px) var(--ds-spacing-4, 16px);
  border-bottom: 1px solid
    var(--ds-surface-card-border, var(--ds-color-border-primary));
  background: color-mix(
    in srgb,
    var(--ds-surface-panel-bg, var(--ds-color-bg-secondary)) 34%,
    var(--ds-surface-card-bg, var(--ds-color-bg-elevated))
  );
  transition: background-color var(--ds-motion-fast, 120ms)
      var(--ds-motion-ease-out, ease-out),
    transform var(--ds-motion-fast, 120ms) var(--ds-motion-ease-out, ease-out);
}

.ds-visual-excellence__action-icon {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--ds-color-primary) 18%, var(--ds-color-border-primary));
  border-radius: var(--ds-radius-md, 8px);
  background: color-mix(in srgb, var(--ds-color-primary) 7%, var(--ds-surface-card-bg));
  color: var(--ds-color-primary);
  transition:
    transform var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out),
    background-color var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out);
}

.ds-visual-excellence__action-row:hover {
  background: color-mix(
    in srgb,
    var(--ds-color-primary) 7%,
    var(--ds-surface-card-bg, var(--ds-color-bg-elevated))
  );
  transform: translateX(2px);
}

.ds-visual-excellence__action-row:hover .ds-visual-excellence__action-icon {
  transform: translateY(-1px) scale(1.04);
  background: color-mix(in srgb, var(--ds-color-primary) 12%, var(--ds-surface-card-bg));
}

.ds-visual-excellence__source-row:hover {
  background: color-mix(
    in srgb,
    var(--ds-color-primary) 5%,
    var(--ds-surface-card-bg, var(--ds-color-bg-elevated))
  );
}

[dir="rtl"] .ds-visual-excellence__action-row:hover {
  transform: translateX(-2px);
}

@keyframes ds-visual-excellence-arrive {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes ds-visual-excellence-header-shift {
  from { background-position: 0% 50%; }
  to { background-position: 100% 50%; }
}

.ds-visual-excellence__placeholder {
  display: grid;
  min-height: 180px;
  place-items: center;
  padding: var(--ds-spacing-6, 24px);
  text-align: center;
}

@container (max-width: 860px) {
  .ds-visual-excellence__command-bar {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .ds-visual-excellence__command-search {
    grid-column: 1 / -1;
    grid-row: 2;
  }

  .ds-visual-excellence__command-account {
    grid-column: 2;
    grid-row: 1;
  }

  .ds-visual-excellence__journey-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .ds-visual-excellence__journey-stage:nth-child(2) {
    border-inline-end: 0;
  }

  .ds-visual-excellence__journey-stage:nth-child(-n + 2) {
    border-bottom: 1px solid
      var(--ds-surface-card-border, var(--ds-color-border-primary));
  }
}

@container (max-width: 560px) {
  .ds-visual-excellence {
    border-inline: 0;
    border-radius: 0;
  }

  .ds-visual-excellence__tabs > [data-part="tab-panel"] {
    padding: var(--ds-spacing-3, 12px);
  }

  .ds-visual-excellence__command-bar {
    gap: var(--ds-spacing-2, 8px);
    min-height: 0;
    padding: var(--ds-spacing-3, 12px);
  }

  .ds-visual-excellence__command-context > button {
    padding-inline: 0;
  }

  .ds-visual-excellence__command-account > .rottay-badge {
    display: none !important;
  }

  .ds-visual-excellence__signal-strip {
    min-height: 38px;
  }

  .ds-visual-excellence__signal-strip > button {
    display: none;
  }

  .ds-visual-excellence__navigation-row {
    align-items: stretch;
    flex-direction: column;
    padding: var(--ds-spacing-3, 12px);
  }

  .ds-visual-excellence__hero-actions {
    width: 100%;
  }

  .ds-visual-excellence__section-header,
  .ds-visual-excellence__recommendation,
  .ds-visual-excellence__signal-row,
  .ds-visual-excellence__action-row {
    align-items: stretch;
    flex-direction: column;
  }

  .ds-visual-excellence__section-header > button,
  .ds-visual-excellence__recommendation > button,
  .ds-visual-excellence__widget > button {
    width: 100%;
  }

  .ds-visual-excellence__journey-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .ds-visual-excellence__journey-stage,
  .ds-visual-excellence__journey-stage:nth-child(2) {
    border-inline-end: 0;
    border-bottom: 1px solid
      var(--ds-surface-card-border, var(--ds-color-border-primary));
  }

  .ds-visual-excellence__journey-stage:last-child {
    border-bottom: 0;
  }

  .ds-visual-excellence__action-row:hover,
  [dir="rtl"] .ds-visual-excellence__action-row:hover {
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-visual-excellence,
  .ds-visual-excellence__command-bar {
    animation: none;
  }

  .ds-visual-excellence__action-row {
    transition: none;
  }
}

}

/* WO-SKIN-06 CK-E: chart and visualization paint from layered skins. */
@layer rottay-components {
/*
 * WO-SKIN-06 CK-E — shared chart foundation paint.
 *
 * Every rule is anchored to the production scope that owns the element. The
 * repeated scope class gives paint declarations specificity (0,4,0) where the
 * Platform-only Rottay artifact floor would otherwise win. Geometry and runtime series
 * colours remain in React/D3.
 */

.ds-chart-scaffold.ds-chart-scaffold[data-part='chart-scaffold'] > [data-part='loading'] {
  color: var(--ds-color-text-secondary);
}

.ds-chart-scaffold.ds-chart-scaffold[data-part='chart-scaffold'] > [data-part='heading'] > [data-part='title'] {
  color: var(--ds-color-text-primary);
}

.ds-chart-scaffold.ds-chart-scaffold[data-part='chart-scaffold'] > [data-part='heading'] > [data-part='subtitle'] {
  color: var(--ds-color-text-secondary);
}

.ds-chart-scaffold.ds-chart-scaffold[data-part='chart-scaffold'] > [data-part='accessible-summary'] {
  border: 0;
}

.ds-chart-brush.ds-chart-brush[data-part='chart-brush'] > [data-part='brush-background'] {
  fill: var(--ds-color-bg-secondary, #f5f5f5);
  stroke: var(--ds-color-border-subtle);
}

.ds-chart-brush.ds-chart-brush[data-part='chart-brush'] > [data-part='brush-separator'] {
  stroke: var(--ds-color-border-subtle);
}

.ds-chart-brush.ds-chart-brush[data-part='chart-brush'] > [data-part='brush-dim'] {
  fill: var(--ds-color-bg-primary);
}

.ds-chart-brush.ds-chart-brush[data-part='chart-brush'] > [data-part='brush-selection'] {
  fill: var(--ds-color-primary);
}

.ds-chart-brush.ds-chart-brush[data-part='chart-brush'] > [data-part='brush-selection-border'] {
  fill: none;
  stroke: var(--ds-color-primary);
}

.ds-chart-brush.ds-chart-brush[data-part='chart-brush'] > [data-part='brush-handle'] {
  fill: var(--ds-color-primary);
}

.ds-chart-brush.ds-chart-brush[data-part='chart-brush'] > [data-part='brush-interaction'] {
  fill: transparent;
}

.ds-chart-tooltip.ds-chart-tooltip[data-part='chart-tooltip'][data-state] {
  background: var(--ds-color-bg-elevated);
  border: 1px solid var(--ds-color-border);
  color: var(--ds-color-text-primary);
  font-size: 12px;
  max-width: 280px;
}

.ds-chart-tooltip.ds-chart-tooltip[data-part='chart-tooltip'][data-variant='minimal'] {
  padding: 4px 8px;
  max-width: 220px;
  border-color: var(--ds-color-border-subtle);
  border-radius: var(--ds-radius-sm);
  box-shadow: none;
}

.ds-chart-tooltip.ds-chart-tooltip[data-part='chart-tooltip'][data-variant='detailed'] {
  padding: 8px 12px;
  border-radius: var(--ds-radius-md);
  box-shadow: var(--ds-shadow-lg);
}

.ds-chart-tooltip.ds-chart-tooltip[data-part='chart-tooltip'][data-variant='glass'] {
  padding: 8px 12px;
  max-width: 300px;
  background: color-mix(in srgb, var(--ds-color-bg-elevated) 78%, transparent);
  border-color: color-mix(in srgb, var(--ds-color-border) 72%, transparent);
  border-radius: var(--ds-radius-lg);
  box-shadow: var(--ds-shadow-lg);
  backdrop-filter: var(--ds-glass-backdrop-filter, blur(12px));
  -webkit-backdrop-filter: var(--ds-glass-backdrop-filter, blur(12px));
}

.ds-chart-tooltip-value.ds-chart-tooltip-value[data-part='tooltip-value'] > [data-part='swatch'],
.ds-chart-tooltip-series.ds-chart-tooltip-series[data-part='tooltip-series'] [data-part='swatch'] {
  border-radius: 50%;
}

.ds-chart-tooltip-value.ds-chart-tooltip-value[data-part='tooltip-value'] > [data-part='label'],
.ds-chart-tooltip-series.ds-chart-tooltip-series[data-part='tooltip-series'] [data-part='label'] {
  color: var(--ds-color-text-secondary);
}

.ds-chart-tooltip-series.ds-chart-tooltip-series[data-part='tooltip-series'] > [data-part='title'] {
  color: var(--ds-color-text-primary);
}

.ds-chart-scaffold.ds-chart-scaffold[data-part='chart-scaffold'] [data-part='crosshair-line'] {
  stroke: var(--ds-color-border);
}

.ds-chart-scaffold.ds-chart-scaffold[data-part='chart-scaffold'] [data-part='crosshair-dot'] {
  stroke: var(--ds-color-bg-primary);
}

/* VIZ-01 — renderer-neutral ChartFrame anatomy. The frame owns chrome and
 * semantic states only; projected renderers retain ownership of their marks. */
.ds-chart-frame.ds-chart-frame[data-part='chart-frame'] {
  display: grid;
  gap: var(--ds-spacing-4);
  inline-size: 100%;
  min-inline-size: 0;
  color: var(--ds-color-text-primary);
}

.ds-chart-frame.ds-chart-frame[data-part='chart-frame'] > [data-part='header'] {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--ds-spacing-4);
  min-inline-size: 0;
}

.ds-chart-frame.ds-chart-frame[data-part='chart-frame'] > [data-part='header'] > [data-part='copy'] {
  display: grid;
  gap: var(--ds-spacing-1);
  min-inline-size: 0;
}

.ds-chart-frame.ds-chart-frame[data-part='chart-frame'] [data-part='title'] {
  margin: 0;
  color: var(--ds-color-text-primary);
  font-size: var(--ds-font-size-lg);
  line-height: var(--ds-line-height-heading);
}

.ds-chart-frame.ds-chart-frame[data-part='chart-frame'] [data-part='question'] {
  margin: 0;
  color: var(--ds-color-text-primary);
  font-size: var(--ds-font-size-sm);
  font-weight: 600;
  line-height: var(--ds-line-height-body);
}

.ds-chart-frame.ds-chart-frame[data-part='chart-frame'] [data-part='description'],
.ds-chart-frame.ds-chart-frame[data-part='chart-frame'] [data-part='state-description'],
.ds-chart-frame.ds-chart-frame[data-part='chart-frame'] [data-part='metadata'] {
  color: var(--ds-color-text-secondary);
  font-size: var(--ds-font-size-sm);
  line-height: var(--ds-line-height-body);
}

.ds-chart-frame.ds-chart-frame[data-part='chart-frame'] [data-part='toolbar'] {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: wrap;
  align-items: center;
