  .ds-pattern-timeline.ds-engine-modern[data-part='root'] .ds-timeline-modern__type-badge[data-part='type-badge'],
  .ds-pattern-timeline.ds-engine-modern[data-part='root'] .ds-timeline-modern__type-badge[data-part='type-badge'][data-type='default'],
  .ds-pattern-timeline.ds-engine-modern[data-part='root'] .ds-timeline-modern__type-badge[data-part='type-badge'][data-type='info'],
  .ds-pattern-timeline.ds-engine-modern[data-part='root'] .ds-timeline-modern__type-badge[data-part='type-badge'][data-type='success'],
  .ds-pattern-timeline.ds-engine-modern[data-part='root'] .ds-timeline-modern__type-badge[data-part='type-badge'][data-type='warning'],
  .ds-pattern-timeline.ds-engine-modern[data-part='root'] .ds-timeline-modern__type-badge[data-part='type-badge'][data-type='error'] {
    border: 1px solid ButtonText;
    background: transparent;
    color: CanvasText;
  }

  .ds-pattern-timeline.ds-engine-modern[data-part='root'] .ds-timeline-modern__timestamp[data-part='timestamp'],
  .ds-pattern-timeline.ds-engine-modern[data-part='root'] .ds-timeline-modern__date-heading[data-part='date-heading'],
  .ds-pattern-timeline.ds-engine-modern[data-part='root'] .ds-timeline-modern__empty[data-part='empty'] {
    color: GrayText;
  }

  .ds-pattern-timeline.ds-engine-modern[data-part='root'] .ds-timeline-modern__item-card[data-part='item-card'][data-clickable='true']:focus-visible {
    outline-color: Highlight;
  }

  .ds-pattern-timeline.ds-engine-modern[data-part='root'][data-loading='true']
    > .ds-timeline-modern__spinner[data-part='spinner'] {
    border-color: ButtonText;
    border-block-start-color: Highlight;
  }
}

