/* ========================================================================
   SMOOTH SCROLL
   Enables smooth scrolling with reduced-motion respect.
   ======================================================================== */

html {
  scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  /* Disable all personality animations when reduced-motion is preferred */
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-delay: 0ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    transition-delay: 0ms !important;
  }

  /* DS motion primitives opt into choreography suppression without replacing
     caller-owned opacity or transforms. Their SSR render already emits the
     final visible state through the runtime reduced-motion snapshot. */
  [data-ds-motion-primitive][data-ds-motion-state='entrance'],
  [data-ds-motion-primitive][data-ds-motion-state='entrance']::before,
  [data-ds-motion-primitive][data-ds-motion-state='entrance']::after {
    animation: none !important;
    transition: none !important;
  }
}

/* MotionProvider's additive runtime override for app/document policy. The OS
   media-query block above remains the no-JS authority; this seam extends the
   same choreography suppression to CSS-only effects when React forces reduced
   motion. */
html[data-ds-motion='reduced'] {
  scroll-behavior: auto;

  /* Runtime policy mirrors the OS media-query authority in transitions.css.
     Important is deliberate: accessibility must beat static and DB-authored
     tenant cadence, including inline custom-property hydration. */
  --ds-motion-instant: 0s !important;
  --ds-motion-calm: 0s !important;
  --ds-motion-deliberate: 0s !important;
  --ds-motion-fast: 0s !important;
  --ds-motion-normal: 0s !important;
  --ds-motion-slow: 0s !important;
  --ds-motion-glacial: 0s !important;
  --ds-motion-feedback: 0s !important;
  --ds-motion-reveal: 0s !important;
  --ds-motion-disclosure: 0s !important;
  --ds-motion-resize: 0s !important;
  --ds-motion-rearrange: 0s !important;
  --ds-motion-attention: 0s !important;
}

html[data-ds-motion='reduced'] *,
html[data-ds-motion='reduced'] *::before,
html[data-ds-motion='reduced'] *::after {
  animation-duration: 0.01ms !important;
  animation-delay: 0ms !important;
  animation-iteration-count: 1 !important;
  transition-duration: 0.01ms !important;
  transition-delay: 0ms !important;
}

html[data-ds-motion='reduced'] [data-ds-motion-primitive][data-ds-motion-state='entrance'],
html[data-ds-motion='reduced'] [data-ds-motion-primitive][data-ds-motion-state='entrance']::before,
html[data-ds-motion='reduced'] [data-ds-motion-primitive][data-ds-motion-state='entrance']::after {
  animation: none !important;
  transition: none !important;
}

}

/* Layer 6: Responsive overrides */
@layer rottay-responsive {
/**
 * Responsive Tokens Index - Rottay Design System
 *
 * Central import file for adjustments conditioned on the rendering
 * environment: screen size, and the language the text is written in. Both
 * entrypoints import this file as `layer(rottay-responsive)`, the last
 * design-system layer, so these adjustments outrank every token, skin, and
 * tenant artifact they correct.
 */

/**
 * Avatar Responsive Tokens - Rottay Design System
 *
 * Responsive overrides for Avatar component tokens.
 * Adjusts sizes and spacing for different screen sizes.
 */

/* ========================================================================
   MOBILE (< 640px)
   Smaller avatars and compact spacing on mobile
   ======================================================================== */
