    --ds-avatar-active-scale: 1;

    /* Instant transitions */
    --ds-avatar-transition-duration: 0.01s;
    --ds-avatar-transition: none;

    /* Disable loading animation */
    --ds-avatar-loading-animation: none;
  }
}

/* ========================================================================
   LANDSCAPE ORIENTATION
   Specific adjustments for landscape mode on mobile
   ======================================================================== */
@media (max-width: 1023px) and (orientation: landscape) {
  :root {
    /* Slightly smaller avatars in landscape to save vertical space */
    --ds-avatar-default-size: var(--ds-avatar-sm-size);

    /* Compact group spacing */
    --ds-avatar-group-default-spacing: var(--ds-avatar-group-compact-spacing);
  }
}

/* ========================================================================
   PRINT
   Adjustments for print media
   ======================================================================== */
@media print {
  :root {
    /* Remove shadows for print */
    --ds-avatar-default-shadow: none;
    --ds-avatar-primary-shadow: none;
    --ds-avatar-secondary-shadow: none;
    --ds-avatar-hover-shadow: none;

    /* Ensure borders are visible in print */
    --ds-avatar-default-border-width: 1px;
    --ds-avatar-default-border-color: var(--ds-color-neutral-400);

    /* Disable status indicators in print (save ink) */
    --ds-avatar-status-online-color: transparent;
    --ds-avatar-status-offline-color: transparent;
    --ds-avatar-status-away-color: transparent;
    --ds-avatar-status-busy-color: transparent;
  }
}

