/* === Declared artifact extension (authored source, mechanically scoped) === */
/* ============================================
   ROTTAY DARK THEME (default for tenant)
   rottayBrandTheme.chrome (sidebar/layout/table/controls) is single-valued
   and dark-authored; it cannot represent both themes, so palette and chrome
   for this state are declared in this governed extension.
   ============================================ */
/* @ds-exception kind=capability-gap
   owner=claude
   purpose="flat channels the BrandTheme contract cannot express at this granularity"
   reachability=shipped
   retire="BrandTheme gains per-step ramp overrides (or the OKLCH-derived steps are accepted as a sighted visual change) and per-channel card/input/shadow fields" */
:is(html[data-tenant='rottay'], :where([data-ds-root][data-vertical='platform'])):not([data-theme='light']):not(.light) {
  color: var(--ds-color-text-primary, #F0F0F0);

  /* -- Primary - White/light scale for dark mode -- */
  --ds-color-primary-hover: #E0E0E0;
  --ds-color-primary-subtle: rgba(255, 255, 255, 0.08);
  --ds-color-primary-foreground: #0C0C0E;
  --ds-color-primary-rgb: 255, 255, 255;

  /* -- Secondary - Neutral gray for dark ---------- */
  --ds-color-secondary-hover: #C0C0C4;
  --ds-color-secondary-rgb: 160, 160, 165;

  /* -- Accent - Neutral gray -------------------- */
  --ds-color-accent-hover: #C0C0C4;

  /* -- Neutral - Cool dark scale ----------------- */
  --ds-color-neutral-0: #0C0C0E;
  --ds-color-neutral-50: #101012;
  --ds-color-neutral-100: #131316;
  --ds-color-neutral-200: #1A1A1E;
  --ds-color-neutral-300: #2A2A2F;
  --ds-color-neutral-400: #6B6B72;
  --ds-color-neutral-500: #A0A0A5;
  --ds-color-neutral-600: #C0C0C4;
  --ds-color-neutral-700: #D4D4D8;
  --ds-color-neutral-800: #E4E4E8;
  --ds-color-neutral-900: #ECECEC;

  /* -- Alpha semantic aliases ------------------- */
  --ds-color-alpha-primary-10: rgba(255, 255, 255, 0.08);
  --ds-color-alpha-primary-20: rgba(255, 255, 255, 0.14);
  --ds-color-alpha-secondary-10: rgba(160, 160, 165, 0.08);
  --ds-color-alpha-secondary-20: rgba(160, 160, 165, 0.14);
  --ds-color-alpha-success-10: rgba(34, 197, 94, 0.10);
  --ds-color-alpha-success-20: rgba(34, 197, 94, 0.18);
  --ds-color-alpha-warning-10: rgba(245, 158, 11, 0.10);
  --ds-color-alpha-warning-20: rgba(245, 158, 11, 0.18);
  --ds-color-alpha-error-10: rgba(239, 68, 68, 0.10);
  --ds-color-alpha-error-20: rgba(239, 68, 68, 0.18);
  --ds-color-alpha-info-10: rgba(59, 130, 246, 0.10);
  --ds-color-alpha-info-20: rgba(59, 130, 246, 0.18);

  /* -- Backgrounds - Tight dark hierarchy (Vercel/Linear) ------- */
  --ds-color-bg-primary: #0A0A0C;
  --ds-color-bg-subtle: #0D0D10;
  --ds-color-bg-hover: #18181C;
  --ds-color-bg-canvas: #0A0A0C;
  --ds-color-bg-input: #0F0F12;
  --ds-color-bg-info: rgba(59, 130, 246, 0.10);
  --ds-color-bg-overlay: rgba(0, 0, 0, 0.64);
  --ds-color-bg-surface: #18181B;
  --ds-color-bg: #0C0C0E;
  --ds-color-background: #0C0C0E;

  /* -- Text - Light text on dark surfaces --------- */
  --ds-color-text-primary: #F0F0F0;
  --ds-color-text-secondary: #B0B0B5;
  /* Ladder re-leveled (W8): muted must clear APCA |Lc| 45 on the page ground
     (#808088 measured 34.9); tertiary rises with it so the
     secondary > tertiary > muted ordering is preserved. */
  --ds-color-text-tertiary: #9A9AA2;
  --ds-color-text-muted: #96969E;
  --ds-color-text-disabled: #555560;
  --ds-color-text: #ECECEC;
  --ds-color-text-inverse: #0C0C0E;

  /* -- Borders - Nearly invisible on dark (Vercel style) ------- */
  --ds-color-border: #1C1C20;
  --ds-color-border-primary: #1C1C20;
  --ds-color-border-secondary: #252529;
  --ds-color-border-subtle: #161619;
  --ds-color-border-tertiary: #161619;
  --ds-color-border-focus: rgba(255, 255, 255, 0.20);

  /* -- Surfaces --------------------------------- */
  --ds-color-surface: #18181B;
  --ds-color-surface-secondary: #1A1A1E;
  --ds-color-surface-muted: #222226;
  --ds-color-shadow: rgba(0, 0, 0, 0.40);

  /* -- Links ------------------------------------ */
  --ds-color-link: #ECECEC;
  --ds-color-link-hover: #FFFFFF;
  --ds-color-link-visited: #A0A0A5;

  /* Success - Green */
  --ds-color-success-bg: rgba(34, 197, 94, 0.10);
  --ds-color-success-border: rgba(34, 197, 94, 0.22);

  /* Warning - Amber */
  --ds-color-warning-bg: rgba(245, 158, 11, 0.10);
  --ds-color-warning-border: rgba(245, 158, 11, 0.22);
  /* Dark surface: the semantic channel doubles as status text on the page
     ground, so it sits on the 400 step (APCA |Lc| 48.9 on --ds-color-bg-primary;
     #EF4444 measured 37.7 — W8). Solid fills (buttons, inputs) keep their own
     500-step literals from chrome.controls. */
  --ds-color-error: var(--ds-color-error-400);
  --ds-color-error-bg: rgba(239, 68, 68, 0.10);
  --ds-color-error-border: rgba(239, 68, 68, 0.22);
  --ds-color-danger: var(--ds-color-error-400);
  /* Same W8 dark-surface re-leveling as error: 400 step clears APCA |Lc| 45
     (#3B82F6 measured 37.6; #60A5FA measures 52.1). */
  --ds-color-info: var(--ds-color-info-400);
  --ds-color-info-bg: rgba(59, 130, 246, 0.10);
  --ds-color-info-border: rgba(59, 130, 246, 0.22);

  /* Live/Online indicators */
  --ds-color-accent-live: #22C55E;
  --ds-color-accent-live-bg: rgba(34, 197, 94, 0.08);

  /* -- Alpha overlays --------------------------- */
  --ds-color-alpha-black-50: rgba(0, 0, 0, 0.12);
  --ds-color-alpha-black-100: rgba(0, 0, 0, 0.20);
  --ds-color-alpha-black-200: rgba(0, 0, 0, 0.30);
  --ds-color-alpha-black-300: rgba(0, 0, 0, 0.40);
  --ds-color-alpha-black-400: rgba(0, 0, 0, 0.50);
  --ds-color-alpha-black-500: rgba(0, 0, 0, 0.60);
  --ds-color-alpha-white-50: rgba(255, 255, 255, 0.04);
  --ds-color-alpha-white-100: rgba(255, 255, 255, 0.08);
  --ds-color-alpha-white-200: rgba(255, 255, 255, 0.14);
  --ds-color-alpha-white-300: rgba(255, 255, 255, 0.20);
  --ds-color-alpha-white-400: rgba(255, 255, 255, 0.28);
  --ds-color-alpha-white-500: rgba(255, 255, 255, 0.40);

  /* -- Interactive states ----------------------- */
  --ds-color-interactive-border: rgba(255, 255, 255, 0.12);
  --ds-color-interactive-bg-hover: rgba(255, 255, 255, 0.04);
  --ds-color-interactive-bg-active: #2A2A2F;
