  /* ============================================
     4. TYPOGRAPHY
     ============================================ */

  --ds-font-family-base: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --ds-font-family-heading: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --ds-font-family-display: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;

  /* ============================================
     5. BORDERS & RADIUS
     ============================================ */
  --ds-radius-full: 9999px;

  /* ============================================
     6. DEPTH - Dark-aware elevation
     Dark-surface treatment of the foundation --ds-elevation-0..5 ramp: a top
     hairline highlight (inset white) + deeper ambient shadow render depth on the
     #0A0A0C canvas where pure-black shadows are invisible; elevation 4-5 add a
     low-alpha primary glow. Values mirror buildElevationScale() for a dark canvas.
     ============================================ */

  --ds-elevation-0: none;
  --ds-elevation-1: inset 0 1px 0 rgba(255, 255, 255, 0.04), 0 1px 2px rgba(0, 0, 0, 0.40), 0 2px 6px rgba(0, 0, 0, 0.28);
  --ds-elevation-2: inset 0 1px 0 rgba(255, 255, 255, 0.05), 0 2px 4px rgba(0, 0, 0, 0.44), 0 6px 16px rgba(0, 0, 0, 0.34);
  --ds-elevation-3: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 6px 12px rgba(0, 0, 0, 0.46), 0 12px 28px rgba(0, 0, 0, 0.40);
  --ds-elevation-4: inset 0 1px 0 rgba(255, 255, 255, 0.07), 0 12px 24px rgba(0, 0, 0, 0.50), 0 20px 44px rgba(0, 0, 0, 0.44), 0 0 24px color-mix(in srgb, var(--ds-color-primary, #ffffff) 8%, transparent);
  --ds-elevation-5: inset 0 1px 0 rgba(255, 255, 255, 0.08), 0 20px 40px rgba(0, 0, 0, 0.56), 0 32px 64px rgba(0, 0, 0, 0.48), 0 0 32px color-mix(in srgb, var(--ds-color-primary, #ffffff) 10%, transparent);

  /* Shadow names alias the dark elevation ramp so every --ds-shadow-* consumer
     inherits the top hairline highlight; pure-black shadows are invisible on #0A0A0C. */
  --ds-shadow-xs: var(--ds-elevation-1);
  --ds-shadow-2xl: var(--ds-elevation-5);
  --ds-shadow-inner: inset 0 2px 4px 0 rgba(0, 0, 0, 0.30);

  --ds-shadow-primary: 0 4px 14px rgba(255, 255, 255, 0.05), 0 8px 24px rgba(0, 0, 0, 0.20);
  --ds-shadow-success: 0 4px 14px rgba(34, 197, 94, 0.12), 0 8px 24px rgba(0, 0, 0, 0.20);
  --ds-shadow-warning: 0 4px 14px rgba(245, 158, 11, 0.12), 0 8px 24px rgba(0, 0, 0, 0.20);
  --ds-shadow-error: 0 4px 14px rgba(239, 68, 68, 0.12), 0 8px 24px rgba(0, 0, 0, 0.20);

  --ds-shadow-focus-ring: 0 0 0 3px rgba(255, 255, 255, 0.12);
